ref_dict.thm:shiu:
\begin{theorem}[Uniform Shiu bound]\label{thm:shiu} Let $q \geq 2$ be a prime power and $N \geq 1$ be an integer. Let $g : \mathcal{M} \to [0,\infty)$ be a non-negative multiplicative function on $\mathcal{M}$ satisfying $\log g(P^{\ell}) \ll \ell $  for every integer $\ell$ and monic irreducible $P$, and $g(F) \ll_{\epsilon} 2^{\epsilon \deg F}$ for every $\epsilon > 0$ and any $F \in \mathcal{M}$.  If  $A \in \mathcal{M}_N$,  $0< \beta < 1/2$, $\beta N < h \leq N-1$, and $N$ is sufficiently large depending only on $\beta$, then  
    \begin{align*}
        \sum_{\substack{F\in \mathcal{I}(A,h)}}g(F)\ll_{\beta} \frac{q^{h+1}}{N}\exp\Big(\sum_{\substack{P\in\mathcal{P}_{\leq N}}}\frac{g(P)}{q^{\deg P}}\Big). 
    \end{align*}
\end{theorem}

ref_dict.thm:CLT-rough:
\begin{theorem}\label{thm:CLT-rough}
    Let $q \geq 2$ be a prime power and $N\geq 1$ an integer. Assume $N^{1/2} \leq z \leq N-1$ is an integer satisfying $N^{1/2} = o(z)$  as $N \to \infty$. If $f$ is a Steinhaus random multiplicative function over $\mathbb{F}_q[t]$, then \eqref{eqn:CLT} holds  for
    \[
    \mathcal{A} = \{ F \in \mathcal{M}_N : P^-(F) > z \}
    \]
    as $N \to \infty$. 
\end{theorem}

ref_dict.thm:CLT-intervals:
\begin{theorem}\label{thm:CLT-intervals}
    Let $q \geq 2$ be a prime power and let $N\geq 3$ be an integer. Let $K \in \mathcal{M}_N$  and $1 \leq h \leq N-2$. If $f$ is a Steinhaus random multiplicative function over $\mathbb{F}_q[t]$, then \eqref{eqn:CLT} holds for 
    \[
    \mathcal{A} = \mathcal{I}(K,h) := \{ F \in \mathcal{M}_N : \deg(F-K) \leq h\}
    \]
    in both of the following cases:
    \begin{enumerate}[label=(\alph*)]
    	\item As $q^{h} \to \infty$ provided $q^{h+1} = o(q^N/N)$. 
    	\item As $h \to \infty$ provided $q^{h+1} = o(q^N/N^c)$ for some fixed $c > 2\log 2-1$. 
    \end{enumerate}

\end{theorem}

