\begin{definition}[Eventually positive function]    \label{def:eventually positive functions}
    Let $g \colon X \mapping X$ be a map on a set $X$, and $\varphi \colon X \mapping \real$ be a real-valued function on $X$.
    Then $\varphi$ is \emph{eventually positive} if there exists $N \in \n$ such that $S_n \varphi(x) > 0$ for each $x \in X$ and each $n \in \n$ with $n \geqslant N$. 
\end{definition}

ref_dict.rem:chordal metric visual metric qs equi:
\begin{remark}\label{rem:chordal metric visual metric qs equiv}
    If $f \colon \ccx \mapping \ccx$ is a rational expanding Thurston map, then a visual metric is quasisymmetrically equivalent to the chordal metric on the Riemann sphere $\ccx$ (see \cite[Theorem~18.1~(ii)]{bonk2017expanding}). 
    Here the chordal metric $\sigma$ on $\ccx$ is given by $\sigma (z, w) \define \frac{2\abs{z - w}}{\sqrt{1 + \abs{z}^2} \sqrt{1 + \abs{w}^2}}$ for all $\juxtapose{z}{w} \in \cx$, and $\sigma(\infty, z) = \sigma(z, \infty) \define \frac{2}{\sqrt{1 + \abs{z}^2}}$ for all $z \in \cx$. 
    Quasisymmetric embeddings of bounded connected metric spaces are \holder continuous (see \cite[Section~11.1 and Corollary~11.5]{heinonen2001lectures}). 
    Accordingly, the classes of \holder continuous functions on $\ccx$ equipped with the chordal metric and on $S^2 = \ccx$ equipped with any visual metric for $f$ are the same (up to a change of the \holder exponent).
\end{remark}

