\begin{align}\label{Stopping-times}
    &\sigma_i = \inf \left\{ k > \tau_i : S_k \in [N_{\tau_i - 1}, M_{\tau_i - 1}] \right\}, \nonumber\\
    &\tau_{i+1} = \inf \left\{ k > \sigma_i : S_k \notin [N_{\sigma_i}, M_{\sigma_i}] \right\}.
