\end{equation}
\begin{lemma}\label{lem4.2}
 For any $0<N_1<N_2$ such that $\p\left(\max\limits_{1\leq s\leq N_2}g(s)\geq M\right)\leq 0.1$, we have
 \begin{equation}
 \p\left(\max\limits_{1\leq s\leq N_2}g(s)\geq M\right)\geq \frac{N_2-N_1}{8N_1(\log N_1+1)}\p\left(\max\limits_{1\leq s\leq N_1}g(s)\geq M\right).\label{eq:lem4.2}
 \end{equation}
\end{lemma}
Suppose
\begin{equation}\label{eq:3.1}
 \Theta:=\limsup_{M\to\infty} \frac{\log\left(\p\left(\max\limits_{1\leq m\leq \sigma-1}\curvevisitonenumber{m}\geq M\right)\right)}{2\sqrt{M}}.
\end{equation}
\begin{lemma}\label{lem4.3}
 For any $0<c<-2\Theta+\frac{(1+\Theta)^{2}}{2}$,
 \footnote{The motivation for writing the expression as $-2\Theta+\frac{(1+\Theta)^2}{2}$ is to clearly show that it exceeds $-2\Theta$ by precisely $\frac{(1+\Theta)^2}{2}$. The same logic applies to the analogous expressions that follow.}
 \begin{equation}
 h(c)\leq \frac{c}{2}+\Theta-\frac{(1+\Theta)^2}{4}.\label{eq:lem4.3}
 \end{equation}
\end{lemma}
\begin{lemma}\label{lem4.4}
 If \eqref{eq:lem4.3} holds for $c\leq c_1$, then it holds for any
 $$c=c_2<\min\left(1+\frac{1-\Theta}{4}c_1,-2\Theta+\frac{(1+\Theta)^{2}}{2}\right).$$
