	\section{Preliminaries on weak-connections}
	\label{preli}
	We work in the context of weak-connection introduce by Petrache-Rivière \cite{PR14}, see also the introduction and the appendix of the work of the first and second author \cite{GL24}. Here, we just have to extend the theory to $W^{2,2}$-bundles with $W^{1,p}$-connection with $p>2$, which is mostly obvious since every thing which is true for $W^{1,2}$-connection will be automatically true for $W^{1,p}$-connections. 
	Let $(M^4, h)$ be an arbitrary Riemannian manifold, $G$ a compact Lie subgroup of $\mathrm{SU}(n)$ with Lie algebra $\mathfrak{g}$, $p\geq 2$, a weak $W^{1,p}$-connection is a $\mathfrak{g}$-valued 1-form $A$ (called the connection form) such that 
	\begin{itemize}
		\item $A\in \mathrm{L}^{4,\infty}(M,T^*M\otimes \mathfrak{g})$\footnote{See \cite{Grafakos1} for a complete introduction to Lorentz spaces.},
		\item $F_A= \diff A + A \wedge A$ (defined as a distribution) is in $\mathrm{L}^p$,
		\item locally, there exists a $\mathrm{W}^{1,(4,\infty)}$-gauge $g$ satisfying $A^g\in \mathrm{W}^{1,p}$, where $ A^g := g^{-1} A g+g^{-1}\diff g$ is the expression of $A$ after the gauge change $g$,
	\end{itemize}  
	We denote by $\mathfrak A^p_G(M^4)$ the space of such connections. The main advantage of this formulation, is that the connection form is globally defined, which includes the classical case, since by \cite[theorem A]{PR14}, every $\mathrm{W}^{2,2}$-bundle is a trivial $\mathrm{W}^{1,(4,\infty)}$-bundle, see also the appendix of \cite{GL24}. Moreover, we can also define an associated notion of convergence, i.e. smooth convergence in local good gauge, we denote it by $\mathfrak{C}_{G,loc}^\infty$- convergence , see Proposition-definition A.8 of \cite{GL24} for a precise definition.

	\section{Second variation : computation and finiteness of the Morse index}
	We start by reminding the expression of the first variation of the $p$-Yang-Mills functional in our framework.

	\begin{proposition}[Section 2 of \cite{HS}] For every connection $A\in\mathfrak U_G^p(M)$,  for all $a\in \mathrm{W}^{1,p}(M, T^*M\otimes \mathfrak{g})$, 
		\begin{equation} \frac{\diff}{\diff t}_{|t=0}  \mathcal{YM}_p(A + ta) = p\int_{M}(1+|F_A|_h^2)^{\frac{p}{2}-1} \langle F_{A}, \diff_{A} a
			\rangle_h \mathrm{vol}_h. \label{variationpremiere}
		\end{equation}
		Hence $A\in\mathfrak U_G^p(M)$ is a $p$-Yang-Mills connections, if it satisfies in the distributional sense the following equation
		\begin{equation} \label{equationdepYMdiv}
			\diff_A^* \left((1+|F_A|_h^2)^{p/2-1}F_A\right) =0 .
		\end{equation}
	\end{proposition}

	\begin{remark}
		Recall that  the Bianchi identity is satisfies by any connection, i.e. \begin{equation}
			\label{equationdeBianchi} \diff_A F_A =0.
		\end{equation}
	\end{remark}

	It turns out, as already proved in \cite{HS}, that solution of the $p$-Yang-Mills equation is smooth in Coulomb gauge and satisfies so-called $\varepsilon$-regularity estimates under a small energy assumption. But for sake of completeness, we give new proofs of those results  in the appendix. In particular, knowing solutions are regular, the $p$-Yang-Mills equation \eqref{equationdepYMdiv} rewrites as 

	\begin{equation} \label{equationdepYM}
		\diff_A^* F_A = \frac{p-2}{2} \star \frac{\diff |F_A|_h^2\wedge \star F_A}{1+|F_A|_h^2}.
	\end{equation}
	Let us now consider the second variation.
	\begin{proposition}
		If $(A_t)_{t\in(-\varepsilon, \varepsilon)}\in \mathfrak A_G^p(M)$ is a one parameter  family of weak connections where $A:=A_0$ is a $p$-Yang-Mills connection and $a:=\displaystyle {\frac{\diff}{\diff t}}_{|t=0} A_t\in   \mathrm{W}^{1,p}(M, T^*M\otimes \mathfrak{g})$ then \begin{equation} 
			\frac{\diff^2}{\diff t^2}_{|t=0}\mathcal{YM}_p(A_t) =p  \int_{M}(1+|F_A|_h^2)^{\frac{p}{2}-1} \left( |\diff_{A} a|_h^2 + \langle F_{A}, [a, a] \rangle_h + (p-2) \frac{\langle F_A, \diff_A a \rangle_h^2}{1+|F_A|_h^2} \right)\mathrm{vol}_h.  \label{variationseconde}
		\end{equation}
	\end{proposition} 

	\begin{proof}
		From \[ \diff_{A + a} b = \diff_{A} b + [a, b], \] \[ F_{A + a} - F_{A} = \diff_{A} a + a \wedge a, \] and the embedding $\mathrm{W}^{1, 2} \hookrightarrow \mathrm{L}^{4,2}$, we deduce, by substituting in \eqref{variationpremiere} : 
		\begin{align*}
			\mathrm{D} \mathcal{YM}_{A + a} (b) & =p\langle  (1+|F_A+d_Aa+a\wedge a|_h^2)^{\frac{p}{2}-1}( F_{A} + \diff_{A}
			a + a \wedge a), \diff_{A} b + [a, b] \rangle_h\\
			& = \mathrm{D} \mathcal{YM}_{A} (b) +p(p-2)\langle \left(1+\vert F_A\vert^2_h\right)^{\frac{p}{2}-2}\langle F_A, d_Aa\rangle_h F_A, d_Ab\rangle_h  \\
			&+p \langle  \left(1+\vert F_A\vert^2_h\right)^{\frac{p}{2}-1}F_{A}, [a, b] \rangle_h +p
			\langle  \left(1+\vert F_A\vert^2_h\right)^{\frac{p}{2}-1}\diff_{A} a, \diff_{A} b \rangle_h \\
			&+ \gdo{ \| a
				\|^2_{\mathrm{W}^{1, 2}} \| b\|_{\mathrm{W}^{1, 2}}}
		\end{align*}
		which implies the result.

	\end{proof}

	\begin{definition} $ Q_{p,A}$ is the quadratic form defined by the right hand side of \eqref{variationseconde}.
	\end{definition}

	A consequence of the gauge invariance is that $Q_{p,A}$ has a huge kernel, as shown in the following result :
	\begin{proposition}
		\[ \Imag{\diff_{A}} \subset \ker Q_{p,A}\]
	\end{proposition}

	\begin{proof} 
		Identical to proposition 2.3 of \cite{GL24}.
	\end{proof}

	\noindent Recall the index of a quadratic form $q$ is the non-negative integer $\ind q$ defined as \[ \ind q = \sup \left\{ \dim W \mid q_{|W} < 0\right\}.\]

	\begin{proposition} Let $\mathfrak{Q}_{p,A}(a) = Q_{p,A}(a) +\int_{M}(1+|F_A|_h^2)^{\frac{p}{2}-1}|\diff^*_A  a|_h^2 \,\mathrm{vol}_h$. The index and kernel of $Q_{p,A}$ can be expressed from those of $\mathfrak{Q}_{p,A}$ as follows : \begin{align*}
			\ind Q_{p,A} &= \ind {\mathfrak{Q}_{p,A}}\\ 
			\ker Q_{p,A} &=  \ker {\mathfrak{Q}_{p,A}} \oplus  \Imag \diff_{A}  
		\end{align*}
	\end{proposition}

	\begin{proof} 
		Identical to proposition 2.4 of \cite{GL24}.
	\end{proof}

	\begin{propdef} \label{finitudeindice} $\ind^0\mathfrak{Q}_{p,A}:= \ind {\mathfrak{Q}_{p,A}} + \dim  \ker {\mathfrak{Q}_{p,A}}$ is finite and \[\ind^0 \mathfrak{Q}_{p,A} = \ind {Q_{p,A}} + \dim \left( \ker {Q_{p,A}}\cap {\ker \diff_{A}^*}\right).\] We call this quantity the extended index of the quadratic form $Q_{p,A}$.
	\end{propdef} 

	\begin{proof} 
		The equality comes from the previous proposition. We shall then prove the finiteness of $\ind^0\mathfrak{Q}_{p,A}$. Let $\mathcal{E}(\lambda)$ be the (possibly trivial) eigenspace associated with the eigenvalue $\lambda$ of the non-negative elliptic operator $\diff_{A}^* \diff_{A} + \diff_{A} \diff_{A}^*$ . For all $\Lambda\in\R$, we denote \[ \mathcal{E}^{\Lambda} = \bigoplus_{\lambda \leq \Lambda} \mathcal{E}(\lambda).
		\]
		For all $\Lambda \in \R$, $\dim \mathcal{E}^\Lambda < +\infty$. We choose $\Lambda > C \Vert F_{A} \Vert_{\mathrm{L}^\infty(M)}$ where $C$ is such that \[\left| \int_M \langle F_{A}, [a, a] \rangle_h \mathrm{vol}_h \right| \leq C  \int_M |F_{A}|_h\, |a|^2_h \mathrm{vol}_h.\]

		\noindent If $a\in  \left(\mathcal{E}^\Lambda\right)^\perp$, then
		\begin{align*}
			\mathfrak{Q}_{p,A}(a) &\geq  \int_M (1+|F_A|_h^2)^{\frac{p}{2}-1}\left( \vert d^*_Aa\vert_h^2+\vert d_Aa\vert^2_h +\langle F_A, [a,a]\rangle_h\right) \mathrm{vol}_h\\
			&\geq  \int_M \vert d^*_Aa\vert^2_h+\vert d_Aa\vert^2_h +\langle F_A, [a,a]\rangle_h \mathrm{vol}_h\\
			&\geq \Lambda \int_M  |a|^2_h \mathrm{vol}_h + \int_M \langle F_{A}, a\wedge a \rangle_h \mathrm{vol}_h\\
			&\geq \int_M \left(\Lambda - C|F_{A}|_h\right) |a|^2_h \mathrm{vol}_h.
		\end{align*} We conclude that if $W$ a subspace on which $\mathfrak{Q}_{p, A}$ is negative-definite, $W\cap \left(\mathcal{E}^\Lambda\right)^\perp = \{0\}$. Consequently, $\dim W \leq \mathrm{codim}\left(\mathcal{E}^\Lambda\right)^\perp = \dim \mathcal{E}^\Lambda <+\infty$ so $\ind \mathfrak{Q}_{p,A} < +\infty$. A similar argument can be applied to prove that $\ker \mathfrak{Q}_{p,A}$ is also finite dimensional. 
	\end{proof}

	\section{$\varepsilon$-regularity, $\mathrm{L}^2$ and $\mathrm{L}^{2,1}$ quantization}
	We state here the $\varepsilon$-regularity pointwise estimate, the proof of which is to be found in the appendix. Then we give the $L^2$ quantization, also proved in \cite{HS}, but we do it in a different setting which permits us to improve it to the stronger $L^{2,1}$ quantization.
	\subsection{$\varepsilon$-regularity}
	\begin{theorem}[\cref{epsregcurvaturepointwiseproof}] \label{epsregbis}
		Let $G$ be a compact Lie group. There exist $\varepsilon_{G}>0$ and constants $C_{G},p_G>0$ such that for all $p\in[2,2+p_G]$, for all $R\in]0,1]$ and for all $1$-form $A$ in  $\mathrm{W}^{1,2}\left(\mathrm{B}_R,\Lambda^1 \R^4\otimes  \mathfrak{g}\right)$ satisfying the small energy condition:
		$$\int_{ \mathrm{B}_R}\left|F_A\right|^2 \diff x <\varepsilon_{G},
		$$ and the $p$-Yang-Mills equation \eqref{equationdepYM}, then the following estimate holds: \begin{equation}
			R^4\left\|F\right\|_{\mathrm{L}^{\infty}\left(\mathrm{B}_{R/2}\right)}^2 \leq C_{G} \int_{\mathrm{B}_R}\left|F_A\right|^2 \diff x. 
		\end{equation}
	\end{theorem}

	\subsection{$\mathrm{L}^{2,\infty}$ bound on the curvature}
	Once one has $\varepsilon$-regularity, it is classical to derive the weak-$L^2$ quantization.

	\begin{lemma} There exists $ C_G> 0$ and $p_G>0$ such that for all $p\in[2,2+p_G]$ and for all $p$-Yang-Mills connection $A$ in $\mathrm{B}_R\backslash \overline{\mathrm{B}_r} $ with $0<4r<R<1$, if $A$ satisfies
		\[ \sup_{r \leq \rho \leq R /2} \| F_A \|_{\mathrm{L}^2(\mathrm{B}_{2\rho} \backslash \mathrm{B}_\rho)} \leq \varepsilon_{G},\] then \[ \|F_A\|_{\mathrm{L}^{2,\infty}(\mathrm{B}_{R}\backslash \mathrm{B}_{r})} \leq C_G \sup_{r \leq \rho \leq R/2} \| F_A \|_{\mathrm{L}^2(\mathrm{B}_{2\rho}\backslash \mathrm{B}_\rho)}.\]
	\end{lemma}
	It is well known that the dyadic energy goes to zero in the neck, in fact it is a direct consequence of the bubble-neck  decomposition, see section 3.1 of \cite{HS} or proof of theorem VII.3 of \cite{rivière2015variations} for the classical case. Then we obtain the weak-$L^2$ quantization as a corollary.\\

	\begin{proof} Denote $\varepsilon =\displaystyle \sup_{r \leq \rho \leq R/2} \| F_A \|_{\mathrm{L}^2(\mathrm{B}_{2\rho}\backslash \mathrm{B}_\rho)} $ and apply the $\varepsilon$-regularity result \eqref{epsregbis} on balls $\mathrm{B}(x,|x|/3)$ for $x\in \mathrm{B}_{R/2}\backslash \mathrm{B}_{2r}$: there exists $C>0$ such that for all $x\in \mathrm{B}_{R/2}\backslash \mathrm{B}_{2r}$, \[|x|^2|F_A|(x) \leq C \| F_A
		\|_{\mathrm{L}^2(\mathrm{B}(x,|x|/3)}\leq C \| F_A
		\|_{\mathrm{L}^2(\mathrm{B}_{4|x|/3}\backslash\mathrm{B}_{2|x|/3})}\leq C\varepsilon. \] Therefore \begin{align*}
			\|F_A\|_{\mathrm{L}^{2,\infty}(\mathrm{B}_{R/2}\backslash \mathrm{B}_{2r})} &\leq  \|C\varepsilon |x|^{-2}\|_{\mathrm{L}^{2,\infty}(\mathrm{B}_{R/2}\backslash \mathrm{B}_{2r})} \\
			&\leq C\varepsilon\||x|^{-1}\|_{\mathrm{L}^{4,\infty}(\mathrm{B}_{R/2}\backslash \mathrm{B}_{2r})} ^2 \\
			& \leq C\varepsilon\||x|^{-1}\|_{\mathrm{L}^{4,\infty}(\R^4)}^2\\
			&  \leq C|\mathrm{B}_1|^{1/2}\varepsilon.
		\end{align*}
	\end{proof}

	\subsection{$\mathrm{L}^{2,1}$ bound on the curvature}

	To have $\mathrm{L}^{2,1}$ curvature bound, we need to use a refined version of Uhlenbeck \cite[Corollary 2.2]{UhlenbeckKarenK1982CwLb} with an hypothesis of small curvature in $\mathrm{L}^{2,\infty}$ in the neck region, which is due to Rivière \cite{rivière2015variations, riviere2002interpolation}. 
	\begin{theorem} There exist $\varepsilon_G, C_G> 0$ with the following property: for all $R,
		r $ with $0<2r < R <1$, if $A \in \mathrm{W}^{1, 2} (\mathrm{B}_R \backslash
		\overline{\mathrm{B}_r}, \Lambda^1 \R^4 \otimes \mathfrak{g})$
		satisfies \[\| F_A \|_{\mathrm{L}^{2, \infty}
			(\mathrm{B}_R \backslash \overline{\mathrm{B}_r})} + \| F_A \|_{\mathrm{L}^2 (\mathrm{B}_{2 r} \backslash
			\overline{\mathrm{B}_{r}})} \leq \varepsilon_G\] then there exists $g
		\in \mathrm{W}^{2, 2} (\mathrm{B}_R \backslash \overline{\mathrm{B}_r}, G)$
		such that $\diff^* A^g = 0$ and
		\[ \int_{\mathrm{B}_R\backslash
			\overline{\mathrm{B}_r}}  \left( | \nabla A^g |^2 + \frac{ | A^g |^2}{|x|^2}  \right) \diff x
		\leq C_G \int_{\mathrm{B}_R \backslash \overline{\mathrm{B}_r}} | F_A
		|^2 \diff x. \]
		\label{recollementjauge}
	\end{theorem}
	\begin{proof}
		Combine \cite[Lemma 4.4]{uhlenbeck_chern_1985} to extend the connection up to gauge in the whole ball $\mathrm{B}_R$ with curvature $\mathrm{L}^2$-small in the ball $\mathrm{B}_r$. This implies that the curvature is small in $\mathrm{L}^{2,\infty}$ in the whole ball $\mathrm{B}_R$ and \cite[Theorem IV.4]{rivière2015variations} applies.
	\end{proof}

	\begin{remark}
		In the limiting case $r=R/2$, the hypothesis reduces to \[\| F_A \|_{\mathrm{L}^2 (\mathrm{B}_{R} \backslash
			\overline{\mathrm{B}_{R/2}})} \leq \varepsilon_0\] and the conclusion is a form of Uhlenbeck theorem which applies on the dyadic annulus $\mathrm{B}_R \backslash \overline{\mathrm{B}_{R/2}}$.
	\end{remark}

	\

	\noindent We are now able to prove the crucial part of this section:

	\begin{proposition} There exists $\varepsilon_G,p_G, C_G> 0$ such that, for all $p\in[2,2+p_G]$ and all $p$-Yang-Mills connection $A\in W^{1,2} (\mathrm{B}_R\backslash \overline{\mathrm{B}_r} ,  \Lambda^1 \R^4 \otimes \mathfrak{g})$, for all $R,r$ with $0<r<4r<R<1$, if $A$ satisfies
		\[ \sup_{r \leq \rho \leq R /2} \| F_A \|_{\mathrm{L}^2(\mathrm{B}_{2\rho} \backslash \mathrm{B}_\rho)} \leq \varepsilon, \] then
		\[ \|  F_{A} \|_{\mathrm{L}^{2,1} (\mathrm{B}_{R/2} \backslash \mathrm{B}_{  2r})} \leq C \|  F_{A} \|_{\mathrm{L}^2 (\mathrm{B}_{R} \backslash \mathrm{B}_{ r})}.\]
		\label{inegalitequantificationYM}
	\end{proposition}

	\begin{proof}		The proof is inspired by \cite[lemma III.2]{riviere2002interpolation} on $\mathrm{L}^2$-quantization for Yang-Mills connections. Let's use the same notations as in \eqref{recollementjauge}, up to a gauge transformation, we can assume that the conclusion of this theorem is satisfied by $A$. 

		\noindent Let $\chi \in \mathcal{C}^{\infty}_c (\R^4, [0 ; 1])$ such that $\supp \chi \subset \text{B}_{R} \backslash \text{B}_{r}$, $\chi \equiv 1$ in $\text{B}_{R/2} \backslash
		\text{B}_{2r}$ and $\| | x | \nabla \chi
		\|_{\text{L}^{\infty}} \leq C$, with $C$ independent of $R,r$. 

		\noindent From Bianchi identity \eqref{equationdeBianchi}, we have $\diff (\chi F_A) = - \chi [A, F_A] + \diff
		\chi \wedge F_A$. Using Hölder inequality (Lorentz spaces version, see \cite[theorem 4.5]{Hunt1966}) and the improved Sobolev-embedding $\dot{\mathrm{W}}^{1,2}(\R^4) \hookrightarrow \mathrm{L}^{4,2}(\R^4)$ (\cite[theorem 8.1]{peetrelorentzsobolev}): 

		\begin{equation}
			\label{majorationL4/3}
			\begin{split}
				\| \chi [A, F_A] \|_{\text{L}^{4 / 3, 1} (\R^4)} & = 
				\| [\chi A, F_A] \|_{\text{L}^{4 / 3, 1}
					(\R^4)}\\
				& \leq C\| \chi A \|_{\text{L}^{4, 2} (\R^4)}  \|
				F_A \|_{\mathrm{L}^2 (\mathrm{B}_R \backslash \mathrm{B}_r)}\\
				& \leq C  \| \nabla(\chi A) \|_{\text{L}^{2} (\R^4)} \|
				F_A \|_{\mathrm{L}^2 (\mathrm{B}_R \backslash \mathrm{B}_r)}. 
			\end{split}
		\end{equation}
		We can use the fact we choose a good gauge to prove the following estimate \begin{equation}
			\label{gradientcutoff}
			\begin{split}
				\| \nabla(\chi A) \|_{\text{L}^{2} (\R^4)}^2 &\leq C \int_{\R^4} |\chi \nabla A|^2 + |\nabla \chi|^2| A |^2 \diff x \\
				&\leq C \int_{\text{B}_{R} \backslash \text{B}_{r}} |\nabla A|^2 + 				\frac{1}{|x|^2} | A |^2 \diff x \\
				&\leq C \int_{\mathrm{B}_R \backslash
					\mathrm{B}_{r}} | F_A |^2 \diff x.
			\end{split}
		\end{equation} 

		\noindent Since $\diff \chi$ has support in the annuli 
		$(\mathrm{B}_{R} \backslash \mathrm{B}_{R/2})\cup (\mathrm{B}_{2r} \backslash \mathrm{B}_{r})$, using Hölder inequality we obtain
		\begin{align}    
			\| \diff \chi \wedge F_A \|_{\text{L}^{4 / 3, 1}
				(\R^4)}& = \| \diff \chi \wedge F_A \|_{\text{L}^{4 / 3, 1}
				(\mathrm{B}_{R} \backslash \mathrm{B}_{r})}\\ &\leq C {\| F_A \|_{\mathrm{L}^2 (\mathrm{B}_R \backslash \mathrm{B}_{r})}}  \| \diff \chi \|_{\text{L}^{4, 2}\left(\R^4 \right)} \notag \\
			& \leq C {\| F_A \|_{\mathrm{L}^2 (\mathrm{B}_R \backslash \mathrm{B}_{r})}} \left( \| |x|^{-1}\|_{\text{L}^{4, 2}(\mathrm{B}_{R} \backslash \mathrm{B}_{R/2})} +  \| |x|^{-1}\|_{\text{L}^{4, 2}(\mathrm{B}_{2r} \backslash \mathrm{B}_{r})}\right)\notag \\
			&\leq C {\| F_A \|_{\mathrm{L}^2 (\mathrm{B}_R \backslash \mathrm{B}_{r})}} \| |x|^{-1}\|_{\text{L}^{4, 2}\left(\mathrm{B}_{1} \backslash \mathrm{B}_{1/2}\right)} \label{scalintL42}\\ &\leq C {\| F_A \|_{\mathrm{L}^2 (\mathrm{B}_R \backslash \mathrm{B}_{r})}}. \label{cutoffcourbureestimate}     
		\end{align}

ref_dict.bubbletree:
\begin{theorem} 
		\label{bubbletree}(See also Theorem 2 of \cite{HS}) 	Let $ (M^4,h)$ be a closed four-dimensional Riemannian manifold and  $A_k\in\mathfrak {U}_G^{p_k}(M^4)$ a sequence of $p_k$-Yang-Mills connection with uniformly bounded energy\footnote{It means that $\mathcal{YM}_{p_k}(A_k)$ is uniformly bounded.} and such that $p_k \underset{k\to+\infty}{\rightarrow} 2^+$. Then we have, up to a sub-sequence,
		\begin{enumerate}
			\item There exists finitely many points $\{p_1,\dots, p_N\}$ and a Yang-Mills connection $A_\infty\in \mathfrak U_G(M^4)$ such that $A_k$ converges to $A_\infty$ in $\mathfrak C^\infty_{G,\mathrm{loc}}(M\setminus \{p_1,\dots, p_N\})$.
			\item For each $i\in \{1, \dots, N\}$, there exists $N_i\in \N$ sequences of points $(p_k^{i,j})_k$ converging to $p_i$,  $N_i$ sequences of scalars $(\lambda_k^{i,j})_k$ converging to zero, $N_i$ non-trivial Yang-Mills connections, called bubbles,  $A_\infty^{i,j} \in\mathfrak{U}_G(S^4)$ such that,
			$$(\phi_{k}^{i,j})^*(A_k) \rightarrow \widehat{A}_\infty^{i,j}=\pi_*A_\infty^{i,j}  \text{ into } \mathfrak C^\infty_{G,\mathrm{loc}}(\R^4 \setminus \{\text{ finitely many points}\}),$$
			where $\phi_{k}^{i,j} (x)= p_k^{i,j} +\lambda _k^{i,j} x$ in local coordinates and $\pi$ is the stereographic projection.
			\item Moreover there is no loss of energy, i.e
			$$ \lim_{k\rightarrow +\infty}\int_{M^4} \vert F_{A_k}\vert^2_h\, \mathrm{vol}_h  = \int_{M^4} \vert F_{A_\infty}\vert^2_h\, \mathrm{vol}_h +\sum_{i=1}^N \sum_{j=1}^{N_i} \int_{S^4} \vert F_{A_\infty^{i,j}}\vert^2\, \mathrm{vol}. $$
		\end{enumerate}
	\end{theorem}

