\label{main_thm}
    Let $\alpha>0$, and assume \begin{enumerate}[label= {\rm  (H\arabic*)}]
    \item\label{H1} {\bf Periodicity:} $W(\cdot, F, \nu)$ is $Y$-periodic for any $F \in \R^{3 \times 3}$ and for any $\nu \in \R^3$.

    \item\label{H2} {\bf Coercivity:} there exists a constant $C > 0$ such that 
    \begin{equation*}
        W(y, F, \nu) \ge C \, \left[\dist^2(F; SO(3)) \vee \dist^p(F; SO(3)) \right],
    \end{equation*}
    for some $p > 3$ and for any $F \in \R^{3 \times 3}$, $\nu \in \R^3$ and a.e. $y \in \R^3$. Moreover we assume
    \begin{equation*}
        W(y, F, \nu) \ge h(\det F)
    \end{equation*}
    for any $F \in \R^{3 \times 3}$, $\nu \in \R^3$ and a.e. $y \in \R^3$, where $h : (0, +\infty) \to [0, +\infty)$ is a Borel function satisfying
    \begin{equation}
    \label{grwt-h}
        \lim_{t \to 0^+} t h(t) = +\infty.
    \end{equation}
    In particular, we choose $h(t) = t^{-s}$ where $s > \frac{p}{p-2}$.

    \item\label{H3} {\bf Frame indifference:} $W(y, RF, R\nu) = W(y, F, \nu)$ for any $R \in SO(3)$, for any $F \in \R^{3 \times 3}$, for any $\nu \in \R^3$ and for a.e. $y \in \R^3$.

    \item\label{H4} {\bf Normalization:} $W(y, \Id, \nu) = 0$ for any $\nu \in \R^3$ and for a.e. $y \in \R^3$.

    \item\label{H5} {\bf Taylor expansion:} $W$ has a second--order Taylor expansion centered at the identity, namely
    \begin{equation*}
        W(y, \Id + F, \nu) = \frac{1}{2} \, Q(y, F, \nu) + r(y, F, \nu),
    \end{equation*}
    for any $F \in \R^{3 \times 3}$, for any $\nu \in \R^3$ and for a.e. $y \in \R^3$. Here $Q: \R^3 \times \R^{3 \times 3} \times \R^3 \to [0, +\infty)$ is a non-negative Carath\u00e9odory function which is $Y$-periodic in $y$ and quadratic in $F$. Moreover, we require that $Q$ is bounded in the following sense: for any $F \in \R^{3 \times 3}$ and for any $\nu \in \R^3$,
        \begin{equation}
            \notag
            \underset{y \in \R^3}{\esssup} \ Q(y, F, \nu) \le C \, |F|^2,
        \end{equation}
    for some constant $C > 0$. We further require that for any $\nu \in \R^3$ and for a.e. $y \in \R^3$, $r(y, F, \nu) \le \tilde{r}(|F|)|F|^2$ as $|F| \to 0$, for a suitable continuous function $\tilde{r}$.
\end{enumerate}.
    Then, the family of magnetoelastic energies $(F_\varepsilon)_\varepsilon$, given by \begin{equation}
\label{resc-en}
\begin{aligned}
    F_{\e}(u,m)
    := \ &\frac{1}{\e^{2\alpha}} \int_\Omega W \left(\frac{x}{\e}, \Id + \e^\alpha \nabla u(x), m(x + \e^\alpha u(x)) \right) \dx \\
    + &\int_\Omega a \left(\frac{x}{\e}\right) |\nabla m(x + \e^\alpha u(x))|^2 |\det(\Id+\e^\alpha\nabla u)| \dx + \frac{\mu_0}{2} \int_{\R^3} |\nabla \psi_m|^2 \dx,
\end{aligned}
\end{equation}, $\Gamma$-converges with respect to the convergence in the following proposition.

We first prove the following theorem. \begin{prop}
\label{compact}
    Let $\alpha > 0$, and assume \ref{H1}--\ref{H5}. Let $(u_\e, m_\e) \in \A_\e$ be such that 
    \begin{equation}
    \label{suplim}
        \sup_{\e > 0} F_\e(u_\e, m_\e) < + \infty,
    \end{equation}
    where the energy $F_\e$ is defined as in \eqref{resc-en}. Then, there exists $(u,m) \in \A_0$ such that, up to subsequences, setting $w_\e := id + \e^\alpha u_\e$, there holds
    \begin{alignat*}{3}
        w_\e &\to id &&\qquad \textnormal{strongly in } W^{1,p}(\Omega; \R^3), \\
        u_\e &\rightharpoonup u &&\qquad \textnormal{weakly in } W^{1,2}(\Omega; \R^3), \\
        \det\nabla w_\e &\to 1 &&\qquad \textnormal{strongly in } L^\frac{p}{3}(\Omega), \\ 
        |\det\nabla w_\e|^{-1} &\to 1 &&\qquad \textnormal{strongly in } L^1(\Omega), \\     
        m_\e \circ w_\e &\rightharpoonup m  &&\qquad \textnormal{weakly in } W^{1,q}(\Omega; \R^3), \\
        m_\e \circ w_\e &\to m  &&\qquad \textnormal{strongly in } L^r(\Omega; \R^3) \quad \textnormal{for any } r \in [1,+\infty), \\
        \chi_{w_\e(\Omega)} m_\e &\to \chi_\Omega m &&\qquad \textnormal{strongly in } L^r(\R^3; \R^3) \quad \textnormal{for any } r \in [1,+\infty), \\
        \chi_{w_\e(\Omega)} \nabla m_\e &\rightharpoonup \chi_\Omega \nabla m &&\qquad \textnormal{weakly in } L^2(\R^3; \R^{3 \times 3}),
    \end{alignat*}
    where $q := \frac{2ps}{p+s(p+2)} \in (1, \tfrac{2p}{p+2})$, and $s$ is the exponent in \eqref{5.15a}.
\end{prop}

We next prove the following theorem. \begin{prop}
\label{prop:two_scale}
    Let $\alpha > 0$. Let $(u_\e, m_\e) \in \A_\e$ be such that $w_\e := id + \e^\alpha u_\e \in \Y$, and let
    \begin{equation*}
        \sup_{\e > 0} F_\e(u_\e, m_\e) < + \infty,
    \end{equation*}
    where the energy $F_\e$ is defined as in \eqref{resc-en}. Then we have up to a subsequence that
    \begin{equation}
    \label{5.10}
		\nabla m_\e \circ w_\e |\det\nabla w_\e|^\frac{1}{2} \wts \nabla m(x) + \nabla_y \phi(x,y) \quad \textnormal{ weakly two-scale in } L^2(\Omega \times Y; \R^3),
    \end{equation}
    where $\phi \in L^2(\Omega; H^1_\per(Y; \R^3))$.
    \qed
\end{prop}

The $\Gamma$-limit is the homogenized functional $F_{\textnormal{hom}}$ defined by
\begin{equation}
\label{hommagnetoel}
\begin{aligned}
    F_{\hom}(u, m)
    := & \ \frac{1}{2} \int_\Omega Q_\hom(\nabla u(x), m(x)) \dx + \int_\Omega T_\hom(\nabla m(x)) \dx \\
    + & \ \frac{\mu_0}{2} \int_{\Omega}| \nabla\psi_m(x)|^2 \dx,
\end{aligned}
\end{equation}.
    \qed,

ref_dict.subsec: hyp:
\begin{equation}\label{eq: cp_zero}
c'(0)=-\f{\phi_f'(c_f)}\left\lbrace 2\theta-\f{c_f}\integ{x}{-\infty}[0]<|x|\left(e^{\f{x}{c_f}}+1\right)K(x)>\right\rbrace,
\end{equation}
where $\phi_f$ is the speed index function for the front that satisfies $\phi_f'(c_f)<0$.
\end{corollary}
\subsection{Hypotheses} \label{subsec: hyp}
We state our main hypotheses and then offer some remarks as to why they are necessary.
\begin{itemize}
\item[(H1)] The parameters satisfy $0<\theta<\min\{\f{2},\int_{-\infty}^0 K\}$, \, $\f{\gamma}{1+\gamma}<\theta,\,$ and $\epsilon \ll 1$.
\item[(H2)] When $\epsilon=0$, there exists a traveling front solution $u(x,t)=U_f(x+c_ft)$ to \eqref{eq: intro_scalar} with $U_f(\cdot)<\theta$ on $(-\infty,0)$, $U_f(\cdot)>\theta$ on $(0,\infty)$, $U_f(-\infty)=0$, and $U_f(\infty)=1$. The solution is translation invariant, but we will assume $U_f(0)=\theta$ unless stated otherwise.
\item[(H3)] There exists $\alpha>0$ and $\rho>0$ such that $|K(x)|\leq \alpha e^{-\rho|x|}$. Moreover, assume $K$ is continuous and $\int_\R K = 1$.
\end{itemize}
We require $0<\theta<\int_{-\infty}^0 K$ because it is necessary in order for the front to exist, while $\theta <\f{2}$ is required for the pulse. Often $K$ is symmetrical so these conditions are equivalent. To conclude remarks on (H1), we note that the assumption $\frac{\gamma}{1+\gamma}<\theta$ ensures that the line $Q=\frac{U}{\gamma}$ does not intersect $Q=-U+H(U-\theta)$ when $U>\theta$, which would lead to a second fixed point, and the homoclinic orbit would be replaced by a heteroclinic orbit. Hypothesis (H2) ensures we have a leading order inner solution. Finally, hypothesis (H3) is a common assumption in nonlocal problems. Biologically, long-range synaptic interaction strengths decay sharply, while mathematically, exponential decay ensures that terms of order $O\left(\epsilon^{-k}e^{-\f{|C|}{\epsilon}}\right)$ vanish. 
\section{Singular Solution,  Previous Results, and Outline}
We review the Heaviside version of the $\epsilon=0$ singular homoclinic orbit construction from \cite{PintoandErmentrout-SpatiallyStructuredActivityinSynapticallyCoupledI.TravelingWaves}, which proves the leading orders of inner and outer solutions can be matched at boundary points. We then highlight how our result advances nonlocal geometric singular perturbation theory approaches.
\subsection{Construction of Singular Homoclinic Orbit}
\subsubsection*{Fast Inner Solutions at $\epsilon=0$}
Writing \eqref{eq: intro_system_1}--\eqref{eq: intro_system_2}, in terms of the traveling coordinate, we obtain the fast inner system
\begin{align}
c\begin{pmatrix} U' \\ Q' \end{pmatrix}
+\begin{pmatrix}
1 & 1\\
-\epsilon & \epsilon\gamma
\end{pmatrix}
\begin{pmatrix} U \\ Q \end{pmatrix}
= \begin{pmatrix} \integ{y}{\R}[]<K(z-y)H(U(y)-\theta)> \\ 0 \end{pmatrix}. \label{eq: fast_null}
\end{align}
When $\epsilon=0$, from the second equation, we have $Q'=0$ so $Q\equiv Q_0$ for some constant $Q_0$. Plugging into the first equation, we recall from \cite{ExistenceandUniqueness-ErmMcLeod} that there may (guaranteed when $K\geq 0$) exist a front with wave speed $c_f>0$ that solves
\begin{equation}
c_f U_f' + U_f=\integ{y}{\R}[]<K(z-y)H(U_f(y)-\theta)>.
\label{eq: front_ODE}
\end{equation}

pre_theorem_intro_text:
\label{Section: Intro}
In mammals, cortical waves are an intriguing and observable pattern, both in normal function and pathology. For example, wave propagation is a prominent phenomena seen in higher order sensory and motor cortical processing, believed to encode plasticity and other hierarchical sequencing \cite{sato2022cortical}. This occurs in the visual cortex via feedforward and feedback traveling waves \cite{aggarwal2022v}. By combining high-resolution imaging techniques like fMRI and MEG-EEG, a synergistic approach can provide insight into the connection between retinotopic directional mappings, hemodynamics, and vision-related motor tasks \cite{zanos2015sensorimotor,aquino2012hemodynamic,grabot2025traveling}.
Traveling waves have also been proven to play a pivotal role in cortical organization such as in working memory \cite{luo2025traveling}. In vitro, neural slices have also shown evidence of recorded propagation, often with techniques to block inhibition \cite{avoli2016models,pavan2022vitro}. Sensory processing pathologies such as migraines \cite{o2021migraine} and epilepsy \cite{martinet2017human} are also known to be related to pulse propagation.

Due to a tractability challenge in neuroscience, neural fields are a well-studied macroscopic model that portray the spatial and temporal interactions between patches of neurons as nonlocal integro-differential equations. Originally, the neural field equations were modeled by Wilson and Cowan \cite{WilsonCowan1972} with separate excitatory and inhibitory network populations. Amari \cite{Amari1977} justified a scalar equation of mixed populations with firing rates encoded within integrals of synaptic interactions. Models with one spatial dimension are justified, based on the layering structure of the cortex and practical recording methods. Voltage activity is then measured as spatial and temporal averages with spike times neglected. Efforts have been made to fit Wilson-Cowan and Amari models to data \cite{freestone2011data,rule2019neural,kofinas2023latent}.

With further simplification, Amari introduced the so-called ``Heaviside" activation approach that supplements the usual sigmoidal models with a more tractable alternative. By exploiting the Heaviside structure, Amari showed bumps, oscillations, and traveling waves exist when synaptic coupling kernels take on Mexican hat shapes. Since then, there have been many follow-ups based on Amari's Heaviside assumption. 

As a scalar equation, the model takes on the form \cite{Amari1977,ExistenceandUniqueness-ErmMcLeod} 
\begin{equation} \label{eq:	 intro_scalar}
u_t=-u+\integ{y}{\R}[]<K(x-y)H(u(y,t)-\theta)>.
\end{equation}
In \eqref{eq: intro_scalar}, $u=u(x,t)$ represents average voltage at position $x$ and time $t$; $K$ is a synaptic coupling kernel, representing homogeneous spatial connectivity strength between presynaptic neural patches at position $y$ with postsynaptic neural patches at position $x$. The parameter $\theta>0$ is the threshold for neurons at $y$ to fire. We ignore previously studied spatial and feedback delays \cite{HuttZhang-TravelingWave,LijZhangSolo,Atay2004} for technical reasons, though there's no obvious reason why they would alter our approach. There are a variety of other modifications of \eqref{eq: intro_scalar} in the literature, but \eqref{eq: intro_scalar} can be categorized as the standard nonlocal Heaviside model without external currents, synaptic depression, stochastic noise, or other nonlinearities.

Due to a Heaviside firing rate, neural patches communicate in an all-or-none manner, justified statistically (and mathematically \cite{Burlakov_etal2025}) as an average of sigmoidals or the limit of steep sigmoidals. While sigmoidal firing rates are more physically appropriate, the Heaviside function provides a favorable mathematical trade-off.

Incorporating more realistic linear feedback such as spike frequency adaptation, Pinto and Ermentrout also studied traveling and standing waves in the singularly perturbed system \cite{pinto2001spatially,PintoandErmentrout-SpatiallyStructuredActivityinSynapticallyCoupledI.TravelingWaves}
\begin{align}
u_t&=-u-q+ \integ{y}{\R}[]<K(x-y)H(u(y,t)-\theta)>, \label{eq: intro_system_1}\\
q_t &=\epsilon (u-\gamma q). \label{eq: intro_system_2}
\end{align}
Here, $0<\epsilon \ll 1$, the function $q$ is a slow linear term, and $\gamma>0$ is a decay constant. Equation \eqref{eq: intro_scalar}, system \eqref{eq: intro_system_1}--\eqref{eq: intro_system_2}, and variations have been studied extensively, leading to vast dynamical systems findings. See \cite{cowan2014personal,ermentrout2010mathematical, bressloff2014waves_wholebook,coombes2014neural,cook2022neural} for background and more historical context.

With traveling waves as our focus, we introduce the traveling coordinate $z=x+c t$ and look for solutions to \eqref{eq: intro_system_1}--\eqref{eq: intro_system_2} of the form $\allowbreak (u(x,t),q(x,t))=(U(z),Q(z))$. Moreover, this solution is defined as a fast traveling pulse if there exists $a=O\left(\f{\epsilon}\right)$ such that $U(z)<\theta$ on $(-\infty,0)\cup (a,\infty)$ and $U(z)>\theta$ on $(0,a)$. Plugging in this ansatz into \eqref{eq: intro_system_1}--\eqref{eq: intro_system_2}, we arrive at the system
\begin{align}
c\begin{pmatrix} U' \\ Q' \end{pmatrix}
+A
\begin{pmatrix} U \\ Q \end{pmatrix}
= \begin{pmatrix} \integ{x}{z-a}[z]<K(x)> \\ 0 \end{pmatrix}, \label{eq: ansatz}
\end{align}
where $A:=\begin{pmatrix}
1 & 1\\
-\epsilon & \epsilon\gamma
\end{pmatrix}$. The matrix $A$ has eigenvalues and eigenvectors given by \begin{align}
\omega_1(\epsilon)&=\frac{1+\gamma\epsilon+\sqrt{(1-\gamma\epsilon)^2-4\epsilon}}{2},\qquad v_1=\begin{pmatrix}1\\\omega_1-1\end{pmatrix}, \\
\omega_2(\epsilon)&=\frac{1+\gamma\epsilon-\sqrt{(1-\gamma\epsilon)^2-4\epsilon}}{2},\qquad v_2=\begin{pmatrix}1\\\omega_2-1\end{pmatrix}.
\end{align}
Under the assumption of fixed $\gamma>0$ and $\epsilon \ll 1$, both $\omega_1$ and $\omega_2$ are positive with
\begin{equation}\label{eq: limits_eig}
\omega_1(0)=1,\qquad \omega_2(0)=0,\qquad \omega_1'(0)=-1, \qquad \omega_2'(0)=1+\gamma.
\end{equation}
Note that 
\begin{equation}\label{eq: omega_calcs}
\omega_1 \omega_2 =\det(A)=\epsilon(1 + \gamma), \qquad \omega_1 + \omega_2 = tr(A) = 1+\epsilon \gamma,
\end{equation}
