\begin{theorem}\label{theorem on resonance method}
	Let $q \ge 3$ and for every $\beta > 0$, define $\tau_{\beta, n}
	= e^{\gamma}\!\left(\log n + \log_2 n + C_2(q) - \beta\right),$ where
	\[
