ref_dict.dir-neu-lp:
\begin{lem}
\label{dir-neu-lp}
Let $O\subseteq \mathbb{R}^d$ be an open set and consider the sesquilinear forms $h^N_{A, O}(\cdot, \cdot)$ and $h^D_{A, O}(\cdot, \cdot)$ as defined in (\ref{ses-neu}) and (\ref{ses-dir}),  respectively.
\begin{enumerate}
\item[(i)] These two sesquilinear forms are positive, symmetric, and closed. Therefore, they each uniquely define a positive self-adjoint operator denoted $H^N_{A, O}$ and $H^D_{A, O}$, respectively.
\item[(ii)] The restricted Neumann magnetic Laplacian $H^N_{A, O}$ is given by
 \begin{equation}
\label{neu-lapla}
h^N_{A,O}(\psi, u)=\big\langle \psi, H^N_{A, O}u\big\rangle,~\forall~\psi\in W^{1,2}_A(O),~u\in 
D(H^N_{A,O}).
\end{equation}
Here the domain of the operator $H^N_{A,O}$ is described by
\begin{align}
\label{neu-dom}
D(H^N_{A,O})&=\bigg\{u\in W^{1,2}_A(O): \text{there~exists}~\tilde{u}\in L^2(O),~\text{such that}\nonumber\\
&\qquad \qquad \qquad h^N_{A, O}(\psi,u)=\langle \psi, \tilde{u}\rangle~\forall~\psi\in W^{1,2}_A(O)  \bigg\},
\end{align}
and for $u\in D(H^N_{A, O})$ we write $H^N_{A, O}u=\tilde{u}$.
\item[(iii)] The restricted Dirichlet magnetic Laplacian $H^D_{A, O}$ is given by
 \begin{equation}
\label{dir-lapla}
h^D_{A,O}(\psi, u)=\big\langle \psi, H^D_{A, O}u\big\rangle,~\forall~\psi\in W^{1,2}_{A,cl}(O),~u\in 
D(H^D_{A,O}).
\end{equation}
Here the domain of the operator $H^D_{A,O}$ is described by
\begin{align}
\label{dir-dom}
D(H^D_{A,O})&=\bigg\{u\in W^{1,2}_{A,cl}(O): \text{there~exists}~\tilde{u}\in L^2(O),~\text{such that}\nonumber\\
&\qquad \qquad \qquad h^D_{A, O}(\psi,u)=\langle \psi, \tilde{u}\rangle~\forall~\psi\in W^{1,2}_{A,cl}(O)  \bigg\},
\end{align}
and for $u\in D(H^D_{A, O})$ we write $H^D_{A, O}u=\tilde{u}$.
\end{enumerate}
\end{lem}

