pre_theorem_intro_text:
In this work, we consider the random Schr\"{o}dinger operator \( H^\omega \) on the Hilbert space \( L^2(\mathbb{R}^d) \) in the presence of a magnetic field, defined by
\begin{equation}
\label{model}
H^\omega = H_A + V^\omega, \quad \omega \in \Omega, \quad \text{where} \quad H_A := (i\nabla + A)^2.
\end{equation}
Here, \( A \in \big(L^2_{\mathrm{loc}}(\mathbb{R}^d)\big)^d \) denotes the vector potential of a constant magnetic field. The operator \( H_A\), known as the \emph{free magnetic Laplacian}, is a positive, unbounded, self-adjoint operator on \( L^2(\mathbb{R}^d) \), defined via an associated quadratic form. A detailed description of the operator \( H_A \) and its domain is provided in Remark~\ref{fl-d-lp}.
We consider the alloy-type random potential $V^\omega$ defined as the bounded multiplication operator
\begin{equation}
\label{pntal}
\big(V^\omega \varphi\big)(x) = \sum_{n \in \mathbb{Z}^d} \omega_n u(x - n)\varphi(x), \quad \forall \, \varphi \in L^2(\mathbb{R}^d),
\end{equation}
where the single site potential \( u \in L^\infty(\mathbb{R}^d) \) is real-valued and compactly supported. The coefficients \( \{\omega_n\}_{n \in \mathbb{Z}^d} \) are independent and identically distributed (i.i.d.), bounded, real-valued random variables with a common distribution \( \mu \), referred to as the \emph{single site distribution} (SSD).
The underlying probability space is the product measure space \( (\Omega, \mathcal{B}_\Omega, \mathbb{P}) := \big(\mathbb{R}^{\mathbb{Z}^d}, \mathcal{B}_{\mathbb{R}^{\mathbb{Z}^d}}, \mathbb{P} \big) \), where \( \mathbb{P} = \bigotimes_{n \in \mathbb{Z}^d} \mu \) is constructed via Kolmogorov’s extension theorem. We denote elements by \( \omega = (\omega_n)_{n \in \mathbb{Z}^d} \in \Omega \).
It follows from \cite{WF} and \cite{TLMS} that \( H^\omega \) is self-adjoint on \( L^2(\mathbb{R}^d) \) for almost every \( \omega \in \Omega \). Since \( V^\omega \) is a bounded operator, we have $D(H^\omega) = D(H_A),$ for a.e. $\omega \in \Omega$.
Moreover, the mapping \( \omega \mapsto H^\omega \) is measurable with respect to
the product $\sigma$-algebra \( \mathcal{B}_\Omega \), so that \( \{H^\omega\}_{\omega \in \Omega} \) forms a measurable family of random operators. For further details, we refer to \cite{Wernr} and \cite{CL}. 
 \\
Let $O\subset \mathbb{R}^d$ be a bounded open set. We denote
$H^\omega_{O, N}$ and $H^\omega_{O, D}$ as the finite-volume restriction of $H^\omega$ to the Hilbert space $L^2(O)$ with the Neumann and Dirichlet boundary conditions, respectively.   The finite-volume restriction of $H^\omega$ is defined by
\begin{equation}
\label{NDrst}
H^\omega_{O, X}=H^X_{A,O}+V^\omega_O~~\text{on}~~L^2(O),~\omega\in\Omega~~\text{and}~~X=D,N.
\end{equation}
In the above, $H^X_{A,O},~X=D, N$ denotes the finite-volume restriction of the free magnetic Laplacian $H_A$ to the Hilbert space $L^2(O)$ with Dirichlet and Neumann boundary conditions.  
The operators $H^D_{A,O}$ and $H^N_{A,O}$ are unbounded, positive, self-adjoint on $L^2(O)$, a detailed description is given in Lemma \ref{dir-neu-lp}. The bounded operator $V^\omega_O$ is the restriction of $V^\omega$ to the Hilbert space $L^2(O)$, defined by $\big(V^\omega_O\varphi\big)(x)=\big(V^\omega \varphi\big)(x)~\forall~x\in O$ where $\varphi\in L^2(O)$.   Also $\{H^\omega_{O,X}\}_{\omega\in\Omega}$ forms a measurable collection of random operators,  \big(see \cite{KMcre},  \cite{TLMS} and \cite{CL}\big).
Since $V^\omega_O$ is a bounded operator, therefore $H^\omega_{O,X}$ is an unbounded self-adjoint operator on $L^2(O)$ with $D\big( H^\omega_{O,X} \big)=D\big( H^X_{A,O} \big)$ for a.e. $\omega$,  here $X=D,N$.\\
Before describing our result, we formally make assumptions on the vector potential $A$, single site potential $u$,  and the single site distribution (SSD) $\mu$.
\begin{hyp}\indent
\label{hypo}
\begin{enumerate}
\item The single site distribution (SSD) $\mu$ is compactly supported.
\item The single site potential $u\in L^\infty(\mathbb{R}^d)$ is real-valued and compactly supported and denote $u_n(x)=u(x-n)$, $n\in\mathbb{Z}^d$.
\item  The vector potential $A(x)=\big(A_1(x),A_2(x),\cdots,A_d(x)\big):\mathbb{R}^d\to\mathbb{R}^d$ is Borel-measurable and it is given by 
$$A(x)=\frac{1}{2}Bx,~x=(x_1,x_2,\cdots,x_d)\in\mathbb{R}^d.$$
Here $B=\big[ B_{i,j} \big]_{1\leq i,j\leq d}$ is a real skew-symmetric $d\times d$ matrix
representing the constant magnetic field.
\end{enumerate}
\end{hyp}
\begin{rem}
\label{bnd-f-pnt}
\noindent Under Hypothesis~\ref{hypo}, there exists a deterministic constant $\|V\|_\infty$ such that $\|V^\omega_O\| \leq \|V\|_\infty~\text{for a.e.}~\omega$ and every open set $O \subseteq \mathbb{R}^d$.
\end{rem}
\begin{rem}
Under Hypothesis~\ref{hypo}, it is clear that each component $A_k$ of the vector potential $A$ can be written as 
$A_k(x_1,x_2,\cdots, x_d)=\frac{1}{2}\displaystyle\sum_{j=1}^dx_jB_{k,j}$, for $k=1,2,\cdots, d$.  Now $A_k\in L^2_{\mathrm{loc}}(\mathbb{R}^d)$ is immediate.
\end{rem}
\noindent Denote $m=(m_1,m_2,\cdots,m_d)\in\mathbb{Z}^d$. We define a family of the unitary operators $\{U_m\}_{m\in\mathbb{Z}^d}$ on $L^2(\mathbb{R}^d)$ as
\begin{equation}
\label{unop}
\big(U_m\varphi\big)(x)=e^{i\Psi_m(x)}\varphi(x-m)~~\forall~~\varphi\in L^2(\mathbb{R}^d),~\text{here}~i=\sqrt{-1},
\end{equation}
here $\Psi_m(x)=\displaystyle\frac{1}{2}\sum_{j,k=1}^d(m_j-x_j)B_{k,j}m_k,~x=(x_1,x_2,\cdots,x_d)\in\mathbb{R}^d$.  We also define an ergodic family $\{T_m\}_{m\in\mathbb{Z}^d}$ of measure-preserving transformations on the product probability space $\big(\Omega, \mathcal{B}_\Omega, \mathbb{P} \big)$ as
\begin{equation}
\label{mpt}
\big(T_m\omega\big)_n=\omega_{n-m},~~\omega=(\omega_n)_{n\in\mathbb{Z}^d}\in\Omega=\mathbb{R}^{\mathbb{Z}^d}
\end{equation}
$\{H^\omega\}_{\omega\in\Omega}$ is an ergodic family of random self-adjoint operators (unbounded) on $L^2(\mathbb{R}^d)$,  in the sense that $U_mH^\omega U_m^*=H^{T_m\omega}~~\forall~~\omega\in\Omega$ and $m\in\mathbb{Z}^d$.  We refer to \cite{Wernr} for details about ergodic operators (self-adjoint); see also \cite{CL}.   Since $H^\omega$ is an ergodic operator (self-adjoint), its spectral components are non-random subsets of the real line for a.e $\omega$, and the discrete spectrum of $H^\omega$ is empty for a.e. $\omega$, details can be found in \cite{Wernr},  \cite{CL} and \cite{ U}.  The spectrum of the finite-volume restriction $H^\omega_{O, X}$ \big(of $H^\omega$\big) is always purely discrete for a.e. $\omega$, $X=D,N,$  see \cite{TLMS} and \cite{RS4} for details.\\
First, we set a few notations to define the integrated density of states (IDS) of the ergodic operator $H^\omega$.  Let $\Lambda_L\subseteq\mathbb{R}^d$ be the cube (open) of side length $L$ centered at the origin i.e. 
\begin{equation}
\label{cbL}
\Lambda_L=\bigg\{x=(x_1,x_2,\cdots, x_d)\in\mathbb{R}^d:|x_i|< \frac{L}{2}  \bigg\},~~L\in\mathbb{N}.
\end{equation}
Now the integrated density of states (IDS) of $H^\omega$ can be described by the limit
\begin{equation}
\label{ids}
\lim_{L\to\infty}\frac{1}{\big|\Lambda_L  \big|}\operatorname{Tr}\!\big( f\big(H^\omega_{\Lambda_L,X}  \big) \big)=
\mathbb{E}\left[\operatorname{Tr}\!\left(\chi_{\Lambda_1}f\big( H^\omega\big)\chi_{\Lambda_1} \right)\right]~~a.e.~\omega,~~\forall~f\in C_c(\mathbb{R}).
\end{equation}
In the above, $C_c(\mathbb{R})$ denotes the set of all continuous functions defined on $\mathbb{R}$ with compact support. The existence of the limit in $(\ref{ids})$ is independent of the choice of boundary condition $X=D,N$. The distribution function $\mathcal{N}(\cdot)$ defined by $\mathcal{N}(x)=\mathbb{E}\left[\operatorname{Tr}\!\left(\chi_{\Lambda_1} E_{ H^\omega}(-\infty,x]\chi_{\Lambda_1}\right) \right],~x\in\mathbb{R}$ is known as the integrated density of states (IDS) of $H^\omega$.  \\
The existence of the limit $(\ref{ids})$ is a well-studied topic in the literature.
A proof of the existence of IDS in the sense of vague convergence (a.e. $\omega$) of random measures can be found in \cite{TLMS1},  the generalisation of \cite{PF}, which deals with the case when the magnetic field is absent. Use of the functional-analytic argument is given in \cite{MH}; it is first presented in \cite{KM} without a magnetic field. A different approach using Feynman-Kac(-It\^{o}) functional-integral representation of Schr\"{o}dinger semigroups can be found in \cite{U, BHL} and it goes back to \cite{pasl,  Nas} for $A=0$.    For the uniqueness of the limit $(\ref{ids})$,  \big(its independence of the boundary condition $X=D,N$\big), we refer to \cite{TLMS1,  DIM,  Na} for non-zero magnetic field and \cite{Wernr,  CL} for zero magnetic field. More details about IDS and, in general, random Schr\"{o}dinger operator is well documented in \cite{KB, His, CFKS, ves}.\\
Let us regard the limit in \((\ref{ids})\) as the analogue of the law of large numbers (LLN) for the trace functional $\operatorname{Tr}\!\big(f(H^\omega_{\Lambda_L,X})\big)$.
Our main goal is to establish an analogue of the central limit theorem (CLT) for \((\ref{ids})\) and to demonstrate its independence from the choice of boundary conditions \(X = D, N\). More explicitly, we aim to study the fluctuations of the trace functional $\operatorname{Tr}\!\big(f(H^\omega_{\Lambda_L,X})\big)$ around its mean as \(L \to \infty\).
\begin{rem}
\label{lbs}
In view of Remark~\ref{bnd-f-pnt}, we have  
$\sigma(H^\omega_{O,X}) \subseteq \big[-\|V\|_\infty,\infty\big)$,  and
$\sigma(H^\omega) \subseteq \big[-\|V\|_\infty,\infty\big)$ a.e. $\omega$,
where $O \subset \mathbb{R}^d$ and $X \in \{D,N\}$.
\end{rem}
\noindent We now define the class of test functions $C^1_{d,0}[-\|V\|_\infty,\infty)$, for which we will establish an analogue of the central limit theorem for the limit (\ref{ids}).
\begin{defin}
\label{defcl}
We say $f\in C^1_{d, 0}\big[-\|V\|_\infty,\infty\big)$ if both $f$ and $f'$ are real-valued continuous functions on $\big[-\|V\|_\infty,\infty\big)$ and $|f(x)|=O(x^{-{m_1}})$, $|f'(x)|=O(x^{-{m_2}})$ as $x\to\infty$ for some $m_1>d+1$,  $m_2>d+1$.
\end{defin}
\noindent Now for any real-valued Borel measurable function $f$ on $\mathbb{R}$ we define the random variable $Y_{f,X,L}(\omega)$ as
\begin{equation}
\label{rv}
Y_{f,X,L}(\omega)=\bigg(\operatorname{Tr}\!\big( f\big(H^\omega_{\Lambda_L,X}  \big) \big)-\mathbb{E}
\big[\operatorname{Tr}\!\big( f\big(H^\omega_{L,X}  \big) \big) \big]\bigg),~~X=D,N.
\end{equation}
\noindent We denote $\sigma^2_{f,X}$as the limiting variance of the random variable $Y_{f,X,L}$, as $L\to\infty$ and it is given by
\begin{align}
\label{lim-vr}
\sigma^2_{f,X}&=\lim_{L\to\infty}\frac{1}{|\Lambda_L|} \mathrm{Var}\big(Y_{f,X,L}  \big),~~~~X=D,N\nonumber\\
&=\lim_{L\to\infty}\frac{1}{|\Lambda_L|}\mathbb{E}\bigg[\operatorname{Tr}\!\big( f\big(H^\omega_{\Lambda_L,X}  \big) \big)-\mathbb{E}\big[\operatorname{Tr}\!\big( f\big(H^\omega_{\Lambda_L,X}  \big) \big) \big]\bigg]^2.
\end{align}
\begin{rem}
We will show that for \( f \in C^1_{d, 0}\big[-\|V\|_\infty,\infty\big) \), the limit~\eqref{lim-vr} exists, and the limiting variance \(\sigma^2_{f,X}\) is independent of the choice of boundary conditions \(X = D, N\).
\end{rem}
\noindent To express the limiting variance $\sigma^2_{f,X}$ explicitly, we introduce a family of subsets of $\mathbb{Z}^d$ together with the corresponding $\sigma$-algebras. For $n = (n_1, n_2,\ldots, n_d) \in \mathbb{Z}^d$, define
\[
\begin{aligned}
A_0^1 &= \{\, n \in \mathbb{Z}^d : n_1 \le 0 \,\}, \\
A_1^1 &= \{\, n \in \mathbb{Z}^d : n_1 \le 1 \,\}, \\
