A_{1,1,0}^3 &= A_{1,0}^2 \,\cup\, \{\, n \in \mathbb{Z}^d : n_1 \le 1,\, n_2 \le 1,\, n_3 \le 0 \,\}, \\
A_{1,1,1}^3 &= A_{1,0}^2 \,\cup\, \{\, n \in \mathbb{Z}^d : n_1 \le 1,\, n_2 \le 1,\, n_3 \le 1 \,\}.
\end{aligned}
\]
Now successively we can define
\begin{equation*}
\label{sgmalg}
\begin{split}
& A^d_{\underbrace{\scriptstyle 1,1, \cdots,1,0}_{\scriptstyle d}}=A^{d-1}_{\underbrace{\scriptstyle 1,1,\cdots,1,0}_{\scriptstyle d-1}}
