\mathcal{F}^d_{\vec{1}_{d-1,0}}&=
\sigma\bigg(\omega_n:n\in A^d_{\underbrace{\scriptstyle 1,1,\cdots,1,0}_{\scriptstyle d}}  \bigg),~~\vec{1}_{d-1,0}= ( \underbrace { 1,1,\cdots,1,1}_{\scriptstyle d-1},0)\in\mathbb{Z}^d.
\end{split}
\end{align}
For each \( k \in \mathbb{Z}^d \) and \( t \in [0,1] \), we define the modified random operator
\[
H^\omega\big|_{(\omega_k \to t\omega_k)}
= H_A + t\omega_k\,u(\cdot - k)
+ \sum_{\substack{n \in \mathbb{Z}^d \\ n \ne k}} \omega_n\,u(\cdot - n).
