    Let $H\in \mathscr{H}$ such that $G p_{H}$ is closed. 
    Suppose that 
    \[  S_{H} = \{\mathbf{x} \in \R^{ \Sigma_{i=1}^k (n_i-1)}: u(\mathbf{x}) p_{H} \in V^{0-}_L(A) \}
    \]is nonempty. 
        Then there exists $\xi_0 \in G$ and a reductive subgroup $F$ of $G$ containing $A$ such that the following conditions are satisfied.
    \begin{enumerate}
        \item $F = N_G^1\big(\xi_0H\xi_0^{-1}\big)$. In particular, if $G$ does not fix $p_H$, then $F$ is a proper reductive subgroup of $G$.
        \item $F$ is an almost direct product $S_0\cdot S_1 \cdots S_p$ for some $1 \leq p \leq k$, where $S_0$ is the largest compact normal subgroup of $F$, and for $1 \leq j \leq p$, each $S_{j}$ is of the form $\Delta_{\mathcal{J}_j}\mathrm{SO}(m_{\mathcal{J}_j},1)$ for some partition $ \mathscr{P} = \{\mathcal{J}_1, \mathcal{J}_2, \cdots, \mathcal{J}_p\}$ of $\{1, 2, \cdots, k\}$ such that for each $\mathcal{J}\in \mathscr{P}$, we have $\zeta_{j_1} = \zeta_{j_2}$ for all $j_1, j_2 \in \mathcal{J}$.
        \item \begin{equation} \label{equation: 4. in the sphere}
        S_{H} = \{\mathbf{x} \in \R^{\Sigma_{i=1}^k (n_i-1)}: \mathcal{I}\circ u(\mathbf{x}) \in \mathcal{I}(F\xi_0) \},
    \end{equation}
    which is an embedding of a product of subspheres or of subspaces of $\R^{n_i-1}$ into $\R^{ \Sigma_{i=1}^k (n_i-1)}.$
    \end{enumerate}

\end{prop}

