\begin{remark}\label{rem: compute v(F(gamma))}
    Define the \textbf{depth} of $\mathfrak{s}$ by $d_\mathfrak{s} \coloneqq \min_{\alpha, \alpha'} \val(\alpha - \alpha')$.  When $|{\mathfrak{s}}| > 1$ and $\gamma_{\mathfrak{s}} \in X_{\mathfrak{s}}$, we have that $\val(\gamma_{\mathfrak{s}} - \alpha_j) = d_{\mathfrak{s}}$, and hence $\val(F(\gamma_{\mathfrak{s}})) = |\mathfrak{s}| d_{\mathfrak{s}} +c_{\mathfrak{s}}$.
\end{remark}

ref_dict.defn: cluster:
\begin{definition}\label{defn: cluster}
    A \textbf{cluster} is a nonempty subset $\mathfrak{s} \subseteq \{\alpha_i\}$ of the form $\mathfrak{s} = D \cap \{\alpha_i\}$ for some disk $D_{z,\, d} = \{x \in \overline{K}\mid |x - z|\leq d\}$ for some $z \in \overline{K}$ and $d \in \mathbb{R}$.  Let $\mathcal{O}(\mathfrak{s})$ denote the orbit of $\mathfrak{s}$ as a set under $\text{Gal}(K^{\text{\rm sep}}/K)$, and let $\mathfrak{s}^c$ denote the complement of $\mathfrak{s}$ in $\{\alpha_i\}$.
\end{definition}

