ref_dict.lem: congruence conditions imply N>r:
\begin{lem}\label{lem: congruence conditions imply N>r}
    Suppose that the residue field of $K$ is algebraically closed and that every root of $F(x)$ is tamely ramified. Fix a Galois-invariant cluster $\mathfrak{s}$. If one of the following holds:
    \begin{enumerate}[label=$(\roman*)$]
        \item\label{condition: bS not 0 mod q} $|\mathfrak{s}| \not \equiv 0 \pmod{q}$, or
        \item\label{condition: bS and cS both 0 mod q} $|\mathfrak{s}| \equiv 0 \pmod q$ and $c_{\mathfrak{s}} \equiv 0 \pmod{q}$, or
        \item\label{condition: constant term 0 mod q} $0 \in X_{\mathfrak{s}}$ and $\val(F(0)) \equiv 0 \pmod{q}$, or
        \item\label{condition: gamma term 0 mod q} $\gamma_{\mathfrak{s}} \in X_{\mathfrak{s}}$ and $\val(F(\gamma_{\mathfrak{s}})) \equiv 0 \pmod{q}$,
    \end{enumerate}
    then there exists $r_0 \in \mathbb{N}$ such that for all $r \geq r_0$ with $\gcd(r,q) = 1$, there exists a point $P \in U(\overline{K})$ of degree $r$ with $x(P) \in X_{\mathfrak{s}}$.
\end{lem}

ref_dict.lem: valuation of polynomial:
\begin{lem}\label{lem: valuation of polynomial}
    Fix a cluster $\mathfrak{s}$. There exists $c_{\mathfrak{s}} \in \mathbb{Q}$ such that for all $x_0 \in X_{\mathfrak{s}}$ and any $\alpha \in {\mathfrak{s}}$,
    $$
    \val(F(x_0)) = |\mathfrak{s}|\cdot\val(x_0 - \alpha) + c_{\mathfrak{s}},
    $$
    where $c_{\mathfrak{s}}$ is given by
    \begin{align*}
        c_{\mathfrak{s}} &= \val(a_d) + \sum_{\beta \in {\mathfrak{s}^c}} \val(\alpha - \beta)
    \end{align*}
    and all expressions above are independent of the choice of $\alpha \in {\mathfrak{s}}$.
\end{lem}

ref_dict.lem: no points not zero mod q:
\begin{lem}\label{lem: no points not zero mod q}
    Suppose that the residue field of $K$ is algebraically closed and that every root of $F(x)$ is tamely ramified. Fix a Galois-invariant cluster $\mathfrak{s}$. Let $\gamma_{\mathfrak{s}}$ be constructed from $\mathfrak{s}$ as in \Cref{lem: shifting argument}. Let $r$ be a natural number not divisible by $q$. If there exists $P \in U(\overline{K})$ of degree $r$ with $x(P) \in X_{\mathfrak{s}}$, then one of the following holds:
    \begin{enumerate}[label=$(\roman*)$]
        \item\label{condition: bS not 0 mod q first lemma} $|\mathfrak{s}| \not \equiv 0 \pmod{q}$, or
        \item\label{condition: bS and cS both 0 mod q first lemma} $|\mathfrak{s}| \equiv 0 \pmod q$ and $c_{\mathfrak{s}} \equiv 0 \pmod{q}$, or
        \item\label{condition: constant term 0 mod q first lemma} $0 \in X_{\mathfrak{s}}$ and $\val(F(0)) \equiv 0 \pmod{q}$, or
        \item\label{condition: F(gamma) mod q first lemma} $\gamma_{\mathfrak{s}} \in X_{\mathfrak{s}}$ and $\val(F(\gamma_{\mathfrak{s}})) \equiv 0 \pmod{q}$.
    \end{enumerate}
\end{lem}

