\begin{definition}\label{defn: cluster}
    A \textbf{cluster} is a nonempty subset $\mathfrak{s} \subseteq \{\alpha_i\}$ of the form $\mathfrak{s} = D \cap \{\alpha_i\}$ for some disk $D_{z,\, d} = \{x \in \overline{K}\mid |x - z|\leq d\}$ for some $z \in \overline{K}$ and $d \in \mathbb{R}$.  Let $\mathcal{O}(\mathfrak{s})$ denote the orbit of $\mathfrak{s}$ as a set under $\text{Gal}(K^{\text{\rm sep}}/K)$, and let $\mathfrak{s}^c$ denote the complement of $\mathfrak{s}$ in $\{\alpha_i\}$.
\end{definition}

\begin{example}\label{ex: computed degree set}
    Let $\alpha = 7^{\frac{1}{2}} + 7^{\frac{3}{5}}$, $\beta = 2\cdot7^{\frac{1}{2}} + 7^{\frac{3}{5}}$, and $\gamma = 3 \cdot 7^{\frac{1}{2}} + 7^{\frac{3}{5}}$ as elements of $\overline{\mathbb{Q}_7}$, and let $f_1(x)$, $f_2(x)$, and $f_3(x)$ be the minimal polynomials of $\alpha$, $\beta$, and $\gamma$ respectively over $\mathbb{Q}_7$. Let $F(x) = 7 f_1(x)f_2(x)f_3(x)$, and let $C/\mathbb{Q}_7$ be the curve given by $y^3 = F(x)$. Then, we have
    \begin{align*}
        \mathcal{D}(C/\mathbb{Q}_7) = 3\mathbb{N} \cup 2\left( \{8,11,13,14\} \cup \mathbb{N}_{>15}\right) \cup 10\mathbb{N} \subseteq 3\mathbb{N} \cup 2 \mathbb{N}.
    \end{align*}
\end{example}

\begin{lem}\label{lem: shifting argument}
    Suppose that the residue field of $K$ is algebraically closed and that the roots of $F(x)$ are tamely ramified. Let $\mathfrak{s}$ be a Galois-invariant cluster. There exists $\gamma_{\mathfrak{s}} \in K$ and $\alpha_{\min} \in {\mathfrak{s}}$ such that ${\mathfrak{s}} = \{ \alpha \mid \val(\alpha - \gamma_{\mathfrak{s}}) \geq \val(\alpha_{\min} - \gamma_{\mathfrak{s}}) \}$.
\end{lem}

\begin{lem}\label{lem: valuation of polynomial}
    Fix a cluster $\mathfrak{s}$. There exists $c_{\mathfrak{s}} \in \mathbb{Q}$ such that for all $x_0 \in X_{\mathfrak{s}}$ and any $\alpha \in {\mathfrak{s}}$,
    $$
    \val(F(x_0)) = |\mathfrak{s}|\cdot\val(x_0 - \alpha) + c_{\mathfrak{s}},
    $$
    where $c_{\mathfrak{s}}$ is given by
    \begin{align*}
        c_{\mathfrak{s}} &= \val(a_d) + \sum_{\beta \in {\mathfrak{s}^c}} \val(\alpha - \beta)
    \end{align*}
    and all expressions above are independent of the choice of $\alpha \in {\mathfrak{s}}$.
\end{lem}

