Following \cite{cluster-diagrams}, we give an answer in terms of clusters. A \textbf{cluster} is a subset of the roots of $F(x)$ contained in an open disk. As the absolute Galois group $\text{Gal}(K^{\text{sep}}/K)$ acts on the roots of $F(x)$, there is a natural action of $\text{Gal}(K^{\text{sep}}/K)$ on clusters (see \Cref{defn: cluster}). Let $\mathcal{O}(\mathfrak{s})$ denote the orbit of a cluster $\mathfrak{s}$ under $\text{Gal}(K^{\text{sep}}/K)$, let $c_\mathfrak{s}$ be the integer defined in \Cref{lem: valuation of polynomial}, and let $\gamma_\mathfrak{s} \in K$ be defined as in \Cref{lem: shifting argument}. Note that $c_\mathfrak{s}$ and $\gamma_\mathfrak{s}$ are computable by hand from the roots of $F(x)$, see \Cref{ex: computed degree set}.

The two main tools used in the proof of \Cref{thm: main thm} are \Cref{lem: valuation of polynomial} and \Cref{lem: no points not zero mod q}. \Cref{lem: valuation of polynomial} provides a formula to compute $\val(F(x_0))$ as a function of $x_0 \in \overline{K}$ and the nearest cluster, and may be of independent interest. \Cref{lem: no points not zero mod q} shows that there is an obstruction arising from the valuation to points of arbitrary degree.

\begin{lem}\label{lem: cS integer}
 Suppose that the residue field of $K$ is algebraically closed and that the roots of $F(x)$ are tamely ramified. Let $\mathfrak{s}$ be a Galois-invariant cluster. Then $c_{\mathfrak{s}} \in \mathbb{Z}$.
\end{lem}
\begin{proof}
 Note that we can apply a rational change of coordinates: if $\gamma \in K$, consider $F(x + \gamma)$. The set ${\mathfrak{s}}_\gamma=\{ \alpha - \gamma \mid \alpha \in {\mathfrak{s}}\}$ is a Galois-invariant cluster for $F(x+ \gamma)$ and $c_{{\mathfrak{s}}_\gamma} = c_{\mathfrak{s}}$. By \Cref{lem: shifting argument}, we can assume that there exists $\alpha_\text{min}$ such that ${\mathfrak{s}} = \{ \alpha \mid \val(\alpha) \geq \val(\alpha_\text{min})\}$.

\begin{lem}\label{lem: no points not zero mod q}
 Suppose that the residue field of $K$ is algebraically closed and that every root of $F(x)$ is tamely ramified. Fix a Galois-invariant cluster $\mathfrak{s}$. Let $\gamma_{\mathfrak{s}}$ be constructed from $\mathfrak{s}$ as in \Cref{lem: shifting argument}. Let $r$ be a natural number not divisible by $q$. If there exists $P \in U(\overline{K})$ of degree $r$ with $x(P) \in X_{\mathfrak{s}}$, then one of the following holds:
 \begin{enumerate}[label=$(\roman*)$]
 \item\label{condition: bS not 0 mod q first lemma} $|\mathfrak{s}| \not \equiv 0 \pmod{q}$, or
 \item\label{condition: bS and cS both 0 mod q first lemma} $|\mathfrak{s}| \equiv 0 \pmod q$ and $c_{\mathfrak{s}} \equiv 0 \pmod{q}$, or
 \item\label{condition: constant term 0 mod q first lemma} $0 \in X_{\mathfrak{s}}$ and $\val(F(0)) \equiv 0 \pmod{q}$, or
 \item\label{condition: F(gamma) mod q first lemma} $\gamma_{\mathfrak{s}} \in X_{\mathfrak{s}}$ and $\val(F(\gamma_{\mathfrak{s}})) \equiv 0 \pmod{q}$.
 \end{enumerate}
\end{lem}

\begin{lem}\label{lem: congruence conditions imply N>r}
 Suppose that the residue field of $K$ is algebraically closed and that every root of $F(x)$ is tamely ramified. Fix a Galois-invariant cluster $\mathfrak{s}$. If one of the following holds:
 \begin{enumerate}[label=$(\roman*)$]
 \item\label{condition: bS not 0 mod q} $|\mathfrak{s}| \not \equiv 0 \pmod{q}$, or
 \item\label{condition: bS and cS both 0 mod q} $|\mathfrak{s}| \equiv 0 \pmod q$ and $c_{\mathfrak{s}} \equiv 0 \pmod{q}$, or
 \item\label{condition: constant term 0 mod q} $0 \in X_{\mathfrak{s}}$ and $\val(F(0)) \equiv 0 \pmod{q}$, or
 \item\label{condition: gamma term 0 mod q} $\gamma_{\mathfrak{s}} \in X_{\mathfrak{s}}$ and $\val(F(\gamma_{\mathfrak{s}})) \equiv 0 \pmod{q}$,
 \end{enumerate}
 then there exists $r_0 \in \mathbb{N}$ such that for all $r \geq r_0$ with $\gcd(r,q) = 1$, there exists a point $P \in U(\overline{K})$ of degree $r$ with $x(P) \in X_{\mathfrak{s}}$.
\end{lem}
\begin{proof}
 Following the argument in the proof of case \ref{case: close to root} of \Cref{lem: no points not zero mod q}, without loss of generality we can take $\gamma_{\mathfrak{s}} = 0$, so condition \ref{condition: gamma term 0 mod q} reduces to condition \ref{condition: constant term 0 mod q}.
 Suppose that condition \ref{condition: constant term 0 mod q} holds, so that $0 \in X_{\mathfrak{s}}$ and hence ${\mathfrak{s}}$ is the set of roots of maximal valuation. We let $r_0 = 1$ and construct points of all degrees $r \geq r_0$. Let $N$ be an integer greater than $\max\{\val(\alpha)\}$, and let $x_0 = \pi^{N + \frac{1}{r}}$. By construction, $x_0 \in X_{\mathfrak{s}}$, and hence by \Cref{lem: valuation of polynomial}, for any $\alpha \in \mathfrak{s}$,
 \begin{align*}
 \val(F(x_0)) = |\mathfrak{s}| \val(x_0 - \alpha) + c_{\mathfrak{s}} = |\mathfrak{s}|\val(\alpha) + c_{\mathfrak{s}} = \val(F(0)) \equiv 0 \pmod q.
 \end{align*}
 Thus, $(x_0,\sqrt[q]{F(x_0)})$ is a $\overline{K}$-point of degree $r$ over $K$.

\begin{proof}
 We begin with the case where $q$ is odd. Define $m_k = \{ n_k \mid n_k >1\}$, and reorder so that both $n_k$ and $m_k$ are weakly increasing. We construct a superelliptic curve $C/K$ with equation $y^q = F(x)$ such that
 \begin{align*}
 \mathcal{D}(C/K) = q\mathbb{N} \cup \bigcup_{n_k> 1} n_k \mathbb{N} = q\mathbb{N} \cup \bigcup_{k} m_k \mathbb{N}.
 \end{align*}
 Define $c \coloneqq D - q\sum_{k}m_k$ and let $a$ be relatively prime to $c$, congruent to $1 \pmod q$, and less than $-c$. As $D$ is a multiple of $q$, so is $c$. Define $F(x)$ by
 \begin{align}\label{eq: definition of F(x)}
 F(x) \coloneqq \pi (x^c - \pi^a)\prod_{n_k>1} \prod_{i=1}^q (x^{n_k} - \pi)
 \end{align}
 and consider the curve $C/K$ defined by $y^q = F(x)$. By \Cref{lem: contains qN} and \Cref{lem: degree of root}, we have that $q\mathbb{N} \cup \bigcup_{n_k > 1} n_k \mathbb{N} \subseteq \mathcal{D}(C/K)$. We show that $\mathcal{D}(C/K) \subseteq q\mathbb{N} \cup \bigcup_{n_k > 1} n_k \mathbb{N}$. Let $P \in U(\overline{K})$ and let $\mathfrak{s}$ be such that $x(P) \in X_{\mathfrak{s}}$. By \Cref{lem: types of S}, $X_{\mathfrak{s}} \subseteq B_{|\alpha|}(\alpha)$ or there exists $\alpha_\text{min}$ such that ${\mathfrak{s}}$ indexes the set $\{ \alpha \mid \val(\alpha) \geq \val(\alpha_\text{min}) \}$.

Suppose $|\mathfrak{s}| = 5$. We detail only the case where $\mathfrak{s} = \{7^{\frac{1}{2}} + \zeta_5^i7^{\frac{3}{5}}\}_{i = 1}^{5}$, as the other cases are similar. We have that $c_{\mathfrak{s}} = \frac{27}{2}$. Fix $\alpha \in \mathfrak{s}$.
 By \Cref{lem: types of S}, we have that $X_{\mathfrak{s}} \subseteq B_{|\alpha|}(\alpha)$, and applying \Cref{lem: tamely ramified generalized krasners}, we find that for all $\eta \in B_{|\alpha|}(\alpha)$, $K(7^{\frac{1}{2}}) \subseteq K(\eta)$, so that if $x(P) \in X_{\mathfrak{s}}$, then $K(7^{\frac{1}{2}}) \subseteq \textbf{k}(x(P))$. We extend to $K(7^{\frac{1}{2}})$ and renormalize the valuation, remembering that we have divided the degree of our point by 2. 
 Following \Cref{lem: congruence conditions imply N>r} over $K(7^{\frac{1}{2}})$, we have that $\gamma_\mathfrak{s} = 7^{\frac{1}{2}}$ and $(M, N) = (1, \frac{6}{5})$. If $\val(x(P) - \gamma_\mathfrak{s}) = \frac{a}{r}$, then
 \begin{align*}
 \val(y(P)) = \frac{5}{3} \cdot \frac{a}{r} + \frac{27}{3} = \frac{5a + 27r}{3r}
 \end{align*}
 and so 3 divides the denominator of $\val(y(P))$ unless $5a + 27r \equiv 0 \pmod{3}$, which occurs if and only if $a \equiv 0 \pmod{3}$. We search for $r \in \mathbb{N}$ that produce $\frac{a}{r} \in (1, \frac{6}{5})$ such that $a \equiv 0 \pmod 3$. For $r$ large enough, by \Cref{lem: sol in interval}, this condition is always satisfied, and a computer finds the condition is satisfied for $8$, $11$, $13$, $14$, and all integers greater than $15$. 
\end{proof}

post_theorem_intro_text:
The two main tools used in the proof of \Cref{thm: main thm} are \Cref{lem: valuation of polynomial} and \Cref{lem: no points not zero mod q}.  \Cref{lem: valuation of polynomial} provides a formula to compute $v(F(x_0))$ as a function of $x_0 \in \overline{K}$ and the nearest cluster, and may be of independent interest.  \Cref{lem: no points not zero mod q} shows that there is an obstruction arising from the valuation to points of arbitrary degree.

The results of \cite{Degrees-on-Varieties} show that \Cref{thm: main thm} must relate to the multiplicities of the components of the special fiber of a regular model with strict normal crossings. Following the construction of \cite{Regular-Models}, for many Galois invariant clusters $\mathfrak{s}$ (specifically, for those that fall in case \ref{case: annulus type} of \Cref{lem: types of S}), there exists a $v$-edge $L_\mathfrak{s}$, and that $\delta_{L_\mathfrak{s}}$ equals 1 if and only if the conditions of \Cref{thm: main thm} are not satisfied. When $\delta_{L_\mathfrak{s}}$ equals 1, there are intersecting copies of $\mathbb{P}^1$ with coprime multiplicity, and thus \cite{Degrees-on-Varieties}*{Theorem 1.1} shows that for some $r$, $\mathbb{N}_{>r} \subseteq \mathcal{D}(C/K)$. We compute the degrees of all points reducing to the $\mathbb{P}^1$'s arising from $L_\mathfrak{s}$ simultaneously in \Cref{lem: congruence conditions imply N>r}. When $C/K$ is not $\Delta_v$-regular, the methods of \cite{Regular-Models} do not give a regular model, see \Cref{rem: dokchitser}. As in \Cref{ex: computed degree set}, we can often compute the degree set even when $C/K$ is not $\Delta_v$-regular.

Restricting briefly to the case of hyperelliptic curves, \cite{models-of-hyperelliptic-curves}*{Theorem 1.2} shows that, if the curve has potential semistable reduction (which is equivalent to every root of $F(x)$ being tamely ramified), the special fiber can be computed from a \textit{cluster diagram} (see \cite{original-cluster-diagrams} or the overview \cite{cluster-diagrams-users-guide}) and thus the degree set depends only on the cluster diagram.  Using an additional quantity $c_{\mathfrak{s}}$, both $|\mathfrak{s}|$ and $v(F(\gamma_{\mathfrak{s}}))$ can be computed from the cluster diagram (see \Cref{rem: compute v(F(gamma))}). We do not know how $c_\mathfrak{s}$ relates to the cluster diagram.

\begin{thm}\label{thm: nice generate examples theorem}
    Let $K$ be a discretely valued Henselian field with algebraically closed residue field of characteristic $p$. Let $q$ be a prime not equal to $p$, and let $n_1, \ldots, n_\ell$ be positive integers. Then, there exists a superelliptic curve $C/K$ such that
    \begin{align*}
        \mathcal{D}(C/K) = q\mathbb{N} \cup n_1\mathbb{N} \cup \ldots \cup n_\ell \mathbb{N}.
    \end{align*}
\end{thm}

As a special case of \Cref{thm: nice generate examples theorem}, we find that for every pair of odd primes $p$ and $q$, there exists a curve $C/K$ such that $\mathcal{D}(C/K) = p \mathbb{N} \cup q\mathbb{N}$. Thus, the density of $\mathcal{D}(C/K)$ in $\ind(C/K)\mathbb{N}$ can be arbitrarily small.

The authors would like to thank Bianca Viray, Paul Fili, and Carlos Rivera. The first author was supported in part by NSF grant DGE-2140004.

