\begin{Theorem}\label{thm:ideseq:3}
Let  $\sigma \in \mathfrak{S}_j$ and $\tau\in \mathfrak{S}_k$
be two permutations with 
$\ides(\sigma)=j'$ and $\ides(\tau)=k'$. Then  
\begin{align} \label{eqn:ideseq:pfc}
\sum_{\mu \in \sigma \lozenge \tau} t^{\ides(\mu)}&=\sum_{i\geq 1} \binom{k-k'+j'+1}{i+j'-k'} \binom{j-j'+k'-1}{i-1} t^{i+j'},\\[5pt]
\sum_{\mu \in \sigma \vartriangle \tau} t^{\ides(\mu)}&=\sum_{i\geq 1} \binom{k-k'+j'}{i+j'-k'} \binom{j-j'+k'-1}{i-1} t^{i+j'}, \label{eqn:ideseq:pfccc} \\[5pt]
\sum_{\mu \in \sigma \triangledown \tau} t^{\ides(\mu)}&=\sum_{i\geq 1} \binom{k-k'+j'}{i+j'-k'} \binom{j-j'+k'-1}{i-1} t^{i+j'}. \label{eqn:ideseq:pfcc}
\end{align} 

\end{Theorem}

