\begin{proof}
		Recall that we have endowed $\la x \ra$ with graded lexicographic order. If $\ad\ge |v|$ and  $v>w$, then  
		\[
		\langle  A^{w} \Omega, e_{v} \rangle \ =\  0 
		\]
		by Lemma~\ref{lem:faithful}. Hence, $\ME_\ad$ is upper triangular.
		Moreover, each diagonal entry is $1$ by Lemma~\ref{lem:faithful}. Thus, $\ME_{\ad}$ is invertible.
	\end{proof}

	\subsection{Extraction formula for coefficients}\label{ssec:coeff}
	Let $q = \sum Q_{w} w \in \cA_{\ad}.$ For $v\in \la x\ra_{\ad}$ 	define the linear functional
	$\Omega_{v} : \cB(\Ftgd) \to \mathbb{C}$ 	by
	\[
	\Omega_{{v}}(T) = \langle  T \Omega, e_{v} \rangle. 
	\]
	The operator coefficients \(Q_v\) are obtained from $q(A)$  by solving the linear system
	\begin{align*} 
		Z_{v}(q) \ :=&\ (\mathrm{id}_{\cB(\cH)} \otimes \Omega_{v}) q(A) \ =\   \sum\limits_{w} Q_{w} \otimes \Omega_{v} (A^{w}) \\
		\ =&\   \sum\limits_{w} \langle  A^{w} \Omega , e_{v} \rangle \, Q_{w} \ =\   \sum\limits_{w} [\ME_{\ad}]_{v,w} Q_{w},
	\end{align*}
	where $[\ME_{\ad}]_{v,w}$ is the $(v,w)$ entry of the matrix $\ME_{\ad}.$ In short, \index{$[\ME_d]$}
	\begin{equation}\label{eq:coeff2}
		Z(q) \ =\  \ME_{\ad} Q,
	\end{equation}
	where $Z(q)$ and $Q$ are column vectors with $Z_{v}(q)$ and $Q_{v}$  as the $v^{\rm th}$ entry of $Z$ and $Q,$ respectively. 
	Since,  by Lemma~\ref{lem:invertible M}, $\ME_d$ is invertible, 
	\begin{equation} \label{eq:coeff}
		Q \ =\  \ME_{\ad}^{-1} Z(q).
	\end{equation} 
	{We refer to $\ME$ as the \df{extraction matrix}, and equation~\eqref{eq:coeff} as the \df{extraction formula} for the coefficients of $q.$ Note 
		that this formula depends only upon $q(A);$ that is, the coefficients of $q$ are determined uniquely
		by $q(A).$}

	It follows from equation~\eqref{eq:coeff}  that  there exists a positive constant $\lambda_{\ad}$ (independent of $q$) such that 
	\begin{equation} \label{eq:Coeff bound}
		\|Q_{w}\| \ \leq\  \lambda_{\ad} \, \|q(A)\| \quad \text{ for all $w \in \la x\ra_{\ad}$.}
	\end{equation}

	\begin{prop} \label{prop:bounded}
		If  $p \in \cC_{d},$ then the set 
		\[
		\Gamma_p \ =\  \{\, \SG \in \cB(\cH)^{N(d)\times N(d)} \ : \quad \SG \succeq 0, \quad   V_d^* \SG V_d = p \,\}
		\]
		is norm bounded $($with respect to the operator norm on $\cB(\cH^{N(d)})$$)$. More precisely, 
		there exists a constant $\mu_{d}$ $($depending only on $d$ and $\vg$ and not on $p$$)$ such that,
		for all $\SG\in\Gamma_p,$ 
		\[ 
		\|\SG\| \ \leq\  \mu_{d} \; \|p(A)\| ,
		\]
		where the tuple $A=A^{(\ad)}$ is defined in \eqref{eq:symcreate}
		for any $\ad\geq 2d$. 
	\end{prop}

	\begin{proof}
		Fix $p \in \cC_{d}$ and $\SG \in \Gamma_p.$ Thus $p=V_d^* \SG V_d.$ By
		Proposition~\ref{prop:closed under addition}, there exists $Q_j: \cH\to \oplus_{w\in\la x\ra_d} \cH$ such that
		\begin{equation}
			\label{e:bound:1}
			p \ =\  \sum\limits_{j=1}^{N(d)} q_{j}^{*}q_{j} \ =\  V_d^* \left [ \sum\limits_{j=1}^{N(d)} Q_{j} Q_{j}^* \right ] V_d,
		\end{equation}
		where
		\[
		q_j \ =\   Q_j^* V_d = \sum_{w\in\la x\ra_d} Q_{j,w} w.
		\]
		By equation~\eqref{eq:Coeff bound}, for $v\in\la x \ra_d,$
		\[
		\| Q_{j,v}\| \ \le\  \lambda_d\; \|q_j(A)\|.
		\]
		From equation~\eqref{e:bound:1}, 
		\[
		\|q_j(A)\|^2 \ =\  \|q_j(A)^* q_j(A)\| \ \le\  \|p(A)\|.
		\]
		Thus, again using equation~\eqref{e:bound:1},
		\[
		\sum_{u,v\in \la x \ra_d} \|\SG_{u,v}\| \ \le\   \sum_{u,v\in \la x \ra_d} \, \sum_{j=1}^{N(d)} \|Q_{j,u}Q_{j,v}^*\| 
		\ \le\  N(d)^3 \lambda_d^{2} \; \|p(A)\|.
		\]
		It follows that 
		$\|\SG\|\le \mu_d \, \|p(A)\|$ for $\mu_d = N(d)^3 \lambda_d^{2}.$
	\end{proof}

