\begin{equation*}
 \Gamma(\frac{n+1}{m}) = \sqrt{\frac{2 \pi m}{n+1}}(\frac{n+1}{me})^{(n+1)/m}\big(1+ O(\frac{m}{n+1})\big).
\end{equation*}
and 
\begin{equation*}
