\label{MainTheorem}
    Let $g \in L^2(\mathbb{R})$ with Fourier transform satisfies the super-exponential decay condition:
    \begin{equation*}
        |\hat{g}(\xi)| \leq C e^{-a|\xi|^m}
    \end{equation*}
    for some constants $m>1$, $C>0$, $a \in (1,\infty)$. Let $\tau_1, \tau_2 \in \mathbb{R}^+$ satisfy
    \begin{equation*}
        \tau_1 < \big(\frac{2}{(2\pi)^{m/(m-1)}(ma)^{-1/(m-1)}e}\big)^{\frac{m-1}{m}}, \quad \quad \quad \tau_2< (\frac{2}{ame})^{\frac{1}{m}}.
    \end{equation*}
    Define the set $\Lambda$ such that: 
    \begin{equation*}
        \Lambda =  \{(\pm\tau_1n^{\frac{m-1}{m}},\pm\tau_2n^{\frac{1}{m}}),n \in \mathbb{N}\}
    \end{equation*} 
    Then the following statements are equivalent for every $f, h \in L^2(\mathbb{R}):$
    \begin{enumerate}
