\begin{thm}\label{thm:intro-keller}
    Let $X$ be a quasi-compact separated scheme over a base field $\bbK$. Then there exist canonical isomorphisms 
    \begin{align*}
        & HH_\bullet\big(\Perf(X)\big) \to HH_\bullet(X),\\
        & HC_\bullet\big(\Perf(X)\big) \to HC_\bullet(X).
    \end{align*} 
