 \sqrt{-\varepsilon \mu} \left(k_1 e^{\sqrt{-\varepsilon \mu} x_1}-k_2 e^{-\sqrt{-\varepsilon \mu} x_1} \right) ={\mu^2} \left( \mu \pa2 f-\pa3 f-\frac{\mu}{2}\right).
\end{array}
\right.
\end{equation}
Integrating the first equation in \eqref{GRS} we get
\begin{equation}\label{effe}
\begin{array}{l}
f(x_1,x_2,x_3) = \frac{1}{\mu} \left( k_1 e^{\sqrt{-\varepsilon \mu} x_1}+k_2 e^{-\sqrt{-\varepsilon \mu} x_1}+k_3 \right)x_2 +Q(x_1,x_3) ,
\end{array}
\end{equation}
where $Q$ denotes an arbitrary smooth function. We substitute from \eqref{effe} into the third equation of \eqref{GRS} and we obtain
\begin{equation}\label{GRSIII}
\begin{array}{l}
k_1 (\mu^2 x_2+ \sqrt{-\varepsilon \mu}) e^{\sqrt{-\varepsilon \mu} x_1} +k_2 (\mu^2 x_2 -\sqrt{-\varepsilon \mu}) e^{-\sqrt{-\varepsilon \mu} x_1}\\[3pt]
+{\mu^2} \left(k_3 x_2 -\pa3 Q - \frac{\mu}{2} \right)=0.
\end{array}
\end{equation}
As the above equation must be satisfied for all values of $x_1$ and $x_2$, it yields at once $k_1=k_2=k_3=0$ and $\pa3 Q = \frac{\mu}{2}$, whence, by integration, we find
\begin{equation}\label{qu}
\begin{array}{l}
Q(x_1,x_3)= -\frac{1}{2} \mu x_3 +R(x_1) ,
\end{array}
\end{equation}
for some smooth function $R$. Using \eqref{qu} and $k_1=k_2=k_3=0$, the second equation of \eqref{GRS} reduces to
\begin{equation}\label{GRSII}
\begin{array}{l}
R'(x_1)+\frac{1}{2}\mu^2 x_2=0,
\end{array}
\end{equation}
which cannot hold for all values of $x_2$, as $\mu \neq 0$. Therefore, the Ricci soliton is never gradient.

