pre_theorem_intro_text:
For some \(\alpha>0\), \(p>0\) and \(dV\) the standard volume measure on \(\mathbb{C}^n\), let \(L^{p}_{\alpha}(\mathbb{C}^n,dV)\) be the Lebesgue space of measurable functions \(f\) on \(\mathbb{C}^n\) such that 
	\begin{equation}\label{Fnorm1}
		\left\lVert f \right\rVert^{p}_{\alpha} := \left(\frac{p\alpha}{2\pi}\right)^{n} \int_{\mathbb{C}^n} |f(z)e^{-\frac{\alpha}{2}|z|^2}|^{p} dV(z) < \infty~.
	\end{equation}
	Similarly, for \(\alpha>0\) and \(p=\infty\), we denoted by \(L^{\infty}_{\alpha}\) the space of Lebesgue measurable function \(f\) on \(\mathbb{C}^n\) such that 
	\begin{equation*}
		\left\lVert f \right\rVert_{\infty,\alpha} := \text{esssup}\{|f(z)|e^{-\frac{\alpha|z|^2}{2}} : ~z \in \mathbb{C}^n\}< \infty ~.
	\end{equation*}
	The classical Fock space \(F^{p}_{\alpha}\) is the space of entire functions on \(\mathbb{C}^n\) which belong to \( L^{p}_{\alpha}(\mathbb{C}^n, dV)\). Similarly, the Fock space \(F^{\infty}_{\alpha}\) is the space of entire functions on \(\mathbb{C}^n\) which belong to \(L^{\infty}_{\alpha}\).

	Let \(d\mu\) be the Gaussian measure on \(\mathbb{C}^n\), \(n\ge 1\). In terms of the standard volume measure \(dV\) on \(\mathbb{C}^n\), it is given by
	\begin{equation*}
		d\mu(z) = \pi^{-n} e^{-|z|^2} dV(z)~.
	\end{equation*}

	 The Fock space \(H^{2}(\mathbb{C}^n,d\mu)\) is defined to be the subspace of the (Hilbert-) Lebesgue space \(L^{2}(\mathbb{C}^n,d\mu)\) consisting of entire functions. Notice that \(H^{2}(\mathbb{C}^n,d\mu) = F^{2}_{1} \). The symbol \(K_z\) denotes the reproducing kernel and the symbol \(k_z\) denotes the normalized reproducing kernel for \(H^{2}(\mathbb{C}^n,d\mu)\). That is, 
	\begin{equation*}
		K_z(\zeta) = e^{\langle \zeta, z \rangle}, \quad k_{z}(\zeta) = e^{\langle \zeta, z\rangle}e^{-\frac{|z|^2}{2}}~, \quad z,\zeta \in \mathbb{C}^n.
	\end{equation*}

	In \cite{xia2015localization}, J. Xia showed in the case of the Bergman space on the unit ball of \(\mathbb{C}^n\) that the norm closure of \(\{T_{f}: f \in L^{\infty}(B,dv) \}\) coincides with the \(C^{*}\)-algebra of weakly localized operators. Also, he stated in \cite[Section 4 ]{xia2015localization}  that  the analogue of \cite[Theorem 1.5]{xia2015localization} on the Fock space \(H^{2}(\mathbb{C}^n, d\mu)\) was true. In this paper, we define the notion of weakly localized operators, state Xia's theorem for the Fock space \(H^{2}(\mathbb{C}^n, d\mu)\) and provide details of its proof. Further, we present a consequence of this theorem on the compactness of operators on \(H^{2}(\mathbb{C}^n,d\mu)\).  We begin with the following definitions and we state the main theorem, the proof of which will retain our attention in the following sections.

	\begin{defn}
		For \(f \in L^{\infty}(\mathbb{C}^n,dV) \), the \textbf{Toeplitz operator} \(T_{f}\) is defined by the formula
		\begin{equation*}
			T_{f}h = P(fh)~,\quad h \in H^{2}(\mathbb{C}^n,d\mu)~,
		\end{equation*}
		where \(P \colon L^{2}(\mathbb{C}^n,d\mu) \rightarrow H^{2}(\mathbb{C}^n,d\mu)\) is the orthogonal projection.
	\end{defn}

	The \textbf{standard lattice} in \(\mathbb{C}^n\) is denoted by 
	\begin{equation*}
		\mathbb{Z}^{2n} = \{(m_{1}+il_{1}, \dots, m_{n}+il_{n}): m_{1}, l_{1}, \dots, m_{n},l_{n} \in \mathbb{Z}\}~.
	\end{equation*}
	We fix an orthonormal set \(\{e_{u}: u \in \mathbb{Z}^{2n}\}\) in \(H^{2}(\mathbb{C}^n,d\mu)\). We let \(S\) denote the \textbf{fundamental unit cube in }\(\mathbb{C}^{n}\). That is,
	\begin{equation*}
		S = \{(x_{1}+iy_{1}, \dots, x_{n}+iy_{n}) : x_{1},y_{1}, \dots , x_{n},y_{n} \in [0,1)\}.
	\end{equation*}
	With \(\mathbb{Z}^{2n}\) and \(S\), we have 
	\begin{equation*}
		\cup_{u \in \mathbb{Z}^{2n}} \{S+u\} = \mathbb{C}^{n} = \cup_{u \in \mathbb{Z}^{2n}} \{u-S\} ~,
	\end{equation*}
	which is a tiling of the space, meaning that there is no overlap between \(S+u\) and \(S+v\) for \(u \neq v\) in \(\mathbb{Z}^{2n}\) (resp. between \(u-S\) and \(v-S\) for \(u \neq v \in \mathbb{Z}^{2n}\) ).

	\begin{defn}
		Let \(\mathcal{T}^{(1)}\) denote the norm closure of \(\{T_{f}: f\in L^{\infty}(\mathbb{C}^n,dV)\}\) in \(\mathcal{B}(H^2(\mathbb{C}^n,d\mu))\) with respect to the operator norm. That is 
		\begin{equation*}
			\mathcal{T}^{(1)} = \{B : \lim_{k \to \infty } \norm{B-T_{b_{k}}}=0 , b_{k} \in L^{\infty}(\mathbb{C}^{n},dV)\}.
		\end{equation*}
	\end{defn}

	\begin{defn}
		We denote by \(\mathcal{S}\) the linear span of the normalized reproducing kernels \(k_z\). A linear operator \(B : \mathcal{S} \rightarrow H^{2}(\mathbb{C}^n,d\mu) \) is said to be \textbf{admissible} on \( H^{2}(\mathbb{C}^n,d\mu) \) if there exists a linear operator \( B^{*} : \mathcal{S} \rightarrow H^{2}(\mathbb{C}^n,d\mu) \) such that the duality relation 
		\begin{equation}\label{R1}
			\langle Bk_{z}, k_{w} \rangle = \langle k_{z}, B^{*}k_w \rangle
		\end{equation}
		holds for all \(z,w \in \mathbb{C}^n\).	
	\end{defn}
	The inner product here is with respect to \(d\mu\).

	We define below sufficiently localized operators following J. Xia and D. Zheng (XZ) in \cite{xia2013localization}.
	\begin{defn}
		A bounded linear operator \(B\) on \(H^{2}(\mathbb{C}^n,d\mu)\) is said to be XZ-\textbf{sufficiently localized} if there exist constants \(2n<\beta<\infty\) and \(0<C<\infty\) such that
		\begin{equation}\label{SL1}
			|\langle Bk_{z},k_{w}\rangle| \le \frac{C}{(1+|z-w|)^{\beta}}
		\end{equation}
		for all \(z,w\in \mathbb{C}^n\).
	\end{defn}

		\begin{defn}
		An admissible operator \(B\) on \(H^{2}(\mathbb{C}^n,d\mu)\) is said to be \textbf{weakly localized} if it satisfies the following four conditions
		\begin{equation*} 
			\sup_{z\in \mathbb{C}^n}\int_{\mathbb{C}^n} |\langle Bk_{z}, k_{w} \rangle| dV(w) <\infty, \quad \sup_{z\in \mathbb{C}^n}\int_{\mathbb{C}^n} |\langle B^{*} k_{z}, k_{w} \rangle| dV(w) <\infty
		\end{equation*}

		and 
		\begin{equation*}
			\lim_{r\to\infty}\sup_{z\in \mathbb{C}^n}\int_{|z-w|\ge r} |\langle Bk_{z}, k_{w} \rangle| dV(w) =0, \quad \lim_{r\to\infty}\sup_{z\in \mathbb{C}^n}\int_{|z-w|\ge r} |\langle B^{*} k_{z}, k_{w} \rangle| dV(w) =0~.
		\end{equation*}
	\end{defn}

	\begin{exa}\label{Ex1}
		If \(f\) is a \textbf{bounded measurable function} on \(\mathbb{C}^n\), then there is a positive constant \(0<C=C(f)<\infty\) such that 
		\begin{equation*}
			|\langle T_{f}k_{z}, k_{w}\rangle| \le C e^{-(1/8) |z-w|^2}
		\end{equation*}
		for all \(z,w \in \mathbb{C}^n\). That is, \(T_{f} \in \text{XZ-}\mathcal{SL}\). Also, \(T_{f} \in \mathcal{L}_{p}\) for \(2<p<\frac{8}{3}\).
	\end{exa}

	\begin{proof}
		For each \(z, w, \xi \in \mathbb{C}^n\), we have 
		\begin{equation*}
			|k_{z}(\xi)k_{w}(\xi)|e^{-|\xi|^2} = |e^{\langle \xi , z \rangle - \frac{|z|^2}{2} } e^{\langle \xi, w \rangle - \frac{|w|^2}{2}} | e^{-|\xi|^2} = e^{-\frac{1}{2}\left(|z-\xi|^2 + |w-\xi|^2\right)} ~.
		\end{equation*}
		By the triangular inequality we have 
		\begin{equation*}
			|z-w|^2 \le |z-\xi + \xi -w|^2 \le (|z-\xi| + |w-\xi|)^2 \le 2 (|z-\xi|^2 + |w-\xi|^2)~.
		\end{equation*}
		It follows that
		\begin{eqnarray}\label{kzw}
			|k_{z}(\xi)k_{w}(\xi)|e^{-|\xi|^2} = e^{-\frac{1}{4}\left(|z-\xi|^2 + |w-\xi|^2\right)}e^{-\frac{1}{4}\left(|z-\xi|^2 + |w-\xi|^2\right)} \le e^{-\frac{1}{4}\left(|z-\xi|^2 + |w-\xi|^2\right)} e^{-\frac{1}{8}|z-w|^2}~.
		\end{eqnarray}
		Let \(f\) be a bounded measurable function on \(\mathbb{C}^n\), then for all \(g,h\in H^{2}(\mathbb{C}^n,d\mu)\), it holds
		\begin{equation}\label{Toepfgh}
			\langle T_{f}g, h \rangle = \int_{\mathbb{C}^{n}} f(\xi)g(\xi)\overline{h(\xi)} d\mu(\xi)~.
		\end{equation}
		In fact, 
		\begin{eqnarray*}
			\langle T_{f}g, h \rangle &=&  \int_{\mathbb{C}^{n}} T_{f}g(w)\overline{h(w)} d\mu(w) \\
			&=& \int_{\mathbb{C}^{n}}\int_{\mathbb{C}^{n}} K(w,\xi) f(\xi)g(\xi) d\mu(\xi) \overline{h(w)} d\mu(w) \\
			&=& \int_{\mathbb{C}^{n}} f(\xi)g(\xi) \int_{\mathbb{C}^{n}} K_{\xi}(w) \overline{h(w)} d\mu(w) d\mu(\xi) \\
			&=& \int_{\mathbb{C}^{n}} f(\xi)g(\xi) \langle K_{\xi} , h \rangle d\mu(\xi) = \int_{\mathbb{C}^{n}} f(\xi)g(\xi) \overline{\langle  h, K_{\xi}  \rangle} d\mu(\xi) \\
			&=& \int_{\mathbb{C}^{n}} f(\xi)g(\xi)\overline{h(\xi)} d\mu(\xi)~.
		\end{eqnarray*}
		Therefore,
		\begin{eqnarray*}
			|\langle T_{f}k_{z}, k_{w} \rangle| &=& \left|\int_{\mathbb{C}^n} 
			f(\xi)k_{z}(\xi) \overline{k_{w}(\xi)} d\mu(\xi)\right|  \\
			&\le & \frac{\left\lVert f \right\rVert_{\infty}}{\pi^n} \int_{\mathbb{C}^n} |k_{z}(\xi) k_{w}(\xi)| e^{-|\xi|^2} dV(\xi) \\
			& \le & \frac{\left\lVert f \right\rVert_{\infty}}{\pi^n}  e^{-\frac{1}{8}|z-w|^2} \int_{\mathbb{C}^n} e^{-\frac{1}{4}\left(|z-\xi|^2 + |w-\xi|^2\right)}  dV(\xi) \\
			& \le & \frac{\left\lVert f \right\rVert_{\infty}}{\pi^n}  e^{-\frac{1}{8}|z-w|^2} \left(\int_{\mathbb{C}^n} e^{-\frac{1}{2}|z-\xi|^2} dV(\xi) \right)^{\frac{1}{2}} \left(\int_{\mathbb{C}^n} e^{-\frac{1}{2}|w-\xi|^2}dV(\xi) \right)^{\frac{1}{2}} \\
			&=& \frac{\left\lVert f \right\rVert_{\infty}}{\pi^n}  e^{-\frac{1}{8}|z-w|^2} \int_{\mathbb{C}^n} e^{-\frac{1}{2}|\zeta|^2} dV(\zeta) \\
			&=& (\sqrt{2})^n \left\lVert f \right\rVert_{\infty} e^{-\frac{1}{8}|z-w|^2}~.
		\end{eqnarray*}	
		This completes the proof.
	\end{proof}

	 \begin{pro}
	 	Any XZ-sufficiently localized operator is weakly localized.
	 \end{pro} 
	\begin{proof}
	Let \(B\) be a XZ-sufficiently localized operator, then  for all \(z\in \mathbb{C}^n\), we have
	\begin{eqnarray*}
		\int_{\mathbb{C}^n} |\langle Bk_z, k_w \rangle| dV(w) &\le& \frac{C}{\pi^n} \int_{\mathbb{C}^n} \frac{1}{(1+|\zeta|)^{\beta}} dV(\zeta) \\
		&=& \frac{Cc_n}{\pi^n} \int_{0}^{\infty} \frac{r^{2n-1}}{(1+r)^{\beta}} dr \\
		&=& C_n \left[ \int_{0}^{1} \frac{r^{2n-1}}{(1+r)^{\beta}} dr  + \int_{1}^{\infty } \frac{r^{2n-1}}{(1+r)^{\beta}} dr\right] \\
		&\le & C_n \left[ \int_{0}^{1} \frac{1}{(1+r)^{\beta}} dr +  \int_{1}^{\infty } \frac{r^{2n-1}}{r^{\beta}} dr\right] \\
		&=& C_n \left\{\frac{1}{\beta-1}\left(1-\frac{1}{2^{\beta}-1}\right) + \frac{1}{\beta-2n}\right\} \\
		&:=& C(n,\beta)~,
	\end{eqnarray*}
	which does not depend on \(z\). Therefore,
	\begin{equation*}
		\sup_{z\in \mathbb{C}^n}\int_{\mathbb{C}^n} |\langle Bk_z, k_w \rangle| dV(w) \le C(n,\beta)  <\infty~.
	\end{equation*}
	And in the same way, we also have
	\begin{equation*}
		\sup_{z\in \mathbb{C}^n}\int_{\mathbb{C}^n} |\langle B^*k_z, k_w \rangle| dV(w) \le C(n,\beta) <\infty~.
	\end{equation*}
	We now show that \(B\) satisfies the third condition of weakly localized operator.

	Let \(z\in \mathbb{C}^n\), using the change of variables \(\zeta=z-w\) and the spherical coordinates, it holds
	\begin{eqnarray*}
		\int_{|z-w|\ge r} |\langle Bk_z, k_w \rangle dV(w) &\le& C \int_{|z-w|\ge r} \frac{1}{(1+|z-w|)^{\beta}} dV(w) \\
		&=& C \int_{|\zeta|\ge r} \frac{1}{(1+|\zeta|)^{\beta}} dV(\zeta) \\
		&=& C c_n \int_{\rho\ge r} \frac{\rho^{2n-1}}{(1+\rho)^{\beta}} d \rho \\
		&\le& C c_n \int_{\rho\ge r} \frac{\rho^{2n-1}}{\rho^{\beta}} d \rho =  C c_n \int_{\rho\ge r} \frac{1}{\rho^{\beta-2n+1}} d \rho \\
		&=& \frac{Cc_n}{\beta-2n}\frac{1}{r^{\beta-2n}}~.
	\end{eqnarray*}
	It follows that,
	\begin{equation*}
		\lim_{r\to\infty} \sup_{z\in \mathbb{C}^n} \int_{|z-w|\ge r} |\langle Bk_z, k_w \rangle dV(w) \le \frac{Cc_n}{\beta-2n} \lim_{r\to\infty} \frac{1}{r^{\beta-2n}} =0~.
	\end{equation*}
	Using the duality relation (\ref{R1}) of an admissible operator and similarly like with \(B\), we also have:
	\begin{equation*}
		\lim_{r\to\infty} \sup_{z\in \mathbb{C}^n} \int_{|z-w|\ge r} |\langle B^*k_z, k_w \rangle dV(w) \le \frac{Cc_n}{\beta-2n} \lim_{r\to\infty} \frac{1}{r^{\beta-2n}} =0~.
	\end{equation*}
\end{proof}

	We denote by \(\mathcal{WL}\) the collection of weakly localized operators on \(H^{2}(\mathbb{C}^n,d\mu)\). We recall the following definition from \cite{zhu2007}.

		\begin{defn}
		A \textbf{Banach algebra} is a complex algebra together with a complete norm satisfying the condition \(\left\lVert xy \right\rVert \le \left\lVert x \right\rVert\left\lVert y \right\rVert\).
		A \(C^{*}\)\textbf{-algebra} is a Banach algebra \(\mathcal{A}\) with an involution \(x \mapsto x^{*}\) on it satisfying the following conditions:
		\begin{enumerate}[label=$\blacktriangleright$]
			\item \(x^{**}=x\) for all vectors \(x \in \mathcal{A} \).
			\item \((ax + by)^{*} = \bar{a}x^{*} + \bar{b}y^{*} \) for all vectors \(x,y \in \mathcal{A}\) and \(a,b \in \mathbb{C}\).
			\item \((xy)^{*}=y^{*}x^{*}\) for all vectors \(x,y \in \mathcal{A}\).
			\item \(\norm{xx^{*}} = \left\lVert x \right\rVert^{2}\) for all vector \(x \in \mathcal{A}\).
		\end{enumerate}
	\end{defn}

	\begin{defn}
		A Banach algebra \(\mathcal{A}\) is called a \textbf{\(\star\)-algebra} if for every \(A\in \mathcal{A}\), we have \(A^{*} \in \mathcal{A} \).
	\end{defn}

	\begin{defn}
		We denote by \(C^{*}(\mathcal{WL})\) the \(C^{*}\)-algebra generated by weakly localized operators on \(H^{2}(\mathbb{C}^n, d\mu)\). Also, \(C^{*}(\mathcal{WL})\) is actually the norm closure of \(\mathcal{WL}\) since \(\mathcal{WL} \) is a \(\star\)-algebra.
	\end{defn}

	We will prove the following main result.

