 \begin{equation}\label{Fnorm1}
 \left\lVert f \right\rVert^{p}_{\alpha} := \left(\frac{p\alpha}{2\pi}\right)^{n} \int_{\mathbb{C}^n} |f(z)e^{-\frac{\alpha}{2}|z|^2}|^{p} dV(z) < \infty~.
 \end{equation}
 Similarly, for \(\alpha>0\) and \(p=\infty\), we denoted by \(L^{\infty}_{\alpha}\) the space of Lebesgue measurable function \(f\) on \(\mathbb{C}^n\) such that 
 \begin{equation*}
 \left\lVert f \right\rVert_{\infty,\alpha} := \text{esssup}\{|f(z)|e^{-\frac{\alpha|z|^2}{2}} : ~z \in \mathbb{C}^n\}< \infty ~.
 \end{equation*}
 The classical Fock space \(F^{p}_{\alpha}\) is the space of entire functions on \(\mathbb{C}^n\) which belong to \( L^{p}_{\alpha}(\mathbb{C}^n, dV)\). Similarly, the Fock space \(F^{\infty}_{\alpha}\) is the space of entire functions on \(\mathbb{C}^n\) which belong to \(L^{\infty}_{\alpha}\).

\begin{defn}
 We denote by \(\mathcal{S}\) the linear span of the normalized reproducing kernels \(k_z\). A linear operator \(B : \mathcal{S} \rightarrow H^{2}(\mathbb{C}^n,d\mu) \) is said to be \textbf{admissible} on \( H^{2}(\mathbb{C}^n,d\mu) \) if there exists a linear operator \( B^{*} : \mathcal{S} \rightarrow H^{2}(\mathbb{C}^n,d\mu) \) such that the duality relation 
 \begin{equation}\label{R1}
 \langle Bk_{z}, k_{w} \rangle = \langle k_{z}, B^{*}k_w \rangle
 \end{equation}
 holds for all \(z,w \in \mathbb{C}^n\). 
 \end{defn}
 The inner product here is with respect to \(d\mu\).

\begin{exa}\label{Ex1}
 If \(f\) is a \textbf{bounded measurable function} on \(\mathbb{C}^n\), then there is a positive constant \(0<C=C(f)<\infty\) such that 
 \begin{equation*}
 |\langle T_{f}k_{z}, k_{w}\rangle| \le C e^{-(1/8) |z-w|^2}
 \end{equation*}
 for all \(z,w \in \mathbb{C}^n\). That is, \(T_{f} \in \text{XZ-}\mathcal{SL}\). Also, \(T_{f} \in \mathcal{L}_{p}\) for \(2<p<\frac{8}{3}\).
 \end{exa}

\begin{proof}
 For each \(z, w, \xi \in \mathbb{C}^n\), we have 
 \begin{equation*}
 |k_{z}(\xi)k_{w}(\xi)|e^{-|\xi|^2} = |e^{\langle \xi , z \rangle - \frac{|z|^2}{2} } e^{\langle \xi, w \rangle - \frac{|w|^2}{2}} | e^{-|\xi|^2} = e^{-\frac{1}{2}\left(|z-\xi|^2 + |w-\xi|^2\right)} ~.
 \end{equation*}
 By the triangular inequality we have 
 \begin{equation*}
 |z-w|^2 \le |z-\xi + \xi -w|^2 \le (|z-\xi| + |w-\xi|)^2 \le 2 (|z-\xi|^2 + |w-\xi|^2)~.
 \end{equation*}
 It follows that
 \begin{eqnarray}\label{kzw}
 |k_{z}(\xi)k_{w}(\xi)|e^{-|\xi|^2} = e^{-\frac{1}{4}\left(|z-\xi|^2 + |w-\xi|^2\right)}e^{-\frac{1}{4}\left(|z-\xi|^2 + |w-\xi|^2\right)} \le e^{-\frac{1}{4}\left(|z-\xi|^2 + |w-\xi|^2\right)} e^{-\frac{1}{8}|z-w|^2}~.
 \end{eqnarray}
 Let \(f\) be a bounded measurable function on \(\mathbb{C}^n\), then for all \(g,h\in H^{2}(\mathbb{C}^n,d\mu)\), it holds
 \begin{equation}\label{Toepfgh}
 \langle T_{f}g, h \rangle = \int_{\mathbb{C}^{n}} f(\xi)g(\xi)\overline{h(\xi)} d\mu(\xi)~.
 \end{equation}
 In fact, 
 \begin{eqnarray*}
 \langle T_{f}g, h \rangle &=& \int_{\mathbb{C}^{n}} T_{f}g(w)\overline{h(w)} d\mu(w) \\
 &=& \int_{\mathbb{C}^{n}}\int_{\mathbb{C}^{n}} K(w,\xi) f(\xi)g(\xi) d\mu(\xi) \overline{h(w)} d\mu(w) \\
 &=& \int_{\mathbb{C}^{n}} f(\xi)g(\xi) \int_{\mathbb{C}^{n}} K_{\xi}(w) \overline{h(w)} d\mu(w) d\mu(\xi) \\
 &=& \int_{\mathbb{C}^{n}} f(\xi)g(\xi) \langle K_{\xi} , h \rangle d\mu(\xi) = \int_{\mathbb{C}^{n}} f(\xi)g(\xi) \overline{\langle h, K_{\xi} \rangle} d\mu(\xi) \\
 &=& \int_{\mathbb{C}^{n}} f(\xi)g(\xi)\overline{h(\xi)} d\mu(\xi)~.
 \end{eqnarray*}
 Therefore,
 \begin{eqnarray*}
 |\langle T_{f}k_{z}, k_{w} \rangle| &=& \left|\int_{\mathbb{C}^n} 
 f(\xi)k_{z}(\xi) \overline{k_{w}(\xi)} d\mu(\xi)\right| \\
 &\le & \frac{\left\lVert f \right\rVert_{\infty}}{\pi^n} \int_{\mathbb{C}^n} |k_{z}(\xi) k_{w}(\xi)| e^{-|\xi|^2} dV(\xi) \\
 & \le & \frac{\left\lVert f \right\rVert_{\infty}}{\pi^n} e^{-\frac{1}{8}|z-w|^2} \int_{\mathbb{C}^n} e^{-\frac{1}{4}\left(|z-\xi|^2 + |w-\xi|^2\right)} dV(\xi) \\
 & \le & \frac{\left\lVert f \right\rVert_{\infty}}{\pi^n} e^{-\frac{1}{8}|z-w|^2} \left(\int_{\mathbb{C}^n} e^{-\frac{1}{2}|z-\xi|^2} dV(\xi) \right)^{\frac{1}{2}} \left(\int_{\mathbb{C}^n} e^{-\frac{1}{2}|w-\xi|^2}dV(\xi) \right)^{\frac{1}{2}} \\
 &=& \frac{\left\lVert f \right\rVert_{\infty}}{\pi^n} e^{-\frac{1}{8}|z-w|^2} \int_{\mathbb{C}^n} e^{-\frac{1}{2}|\zeta|^2} dV(\zeta) \\
 &=& (\sqrt{2})^n \left\lVert f \right\rVert_{\infty} e^{-\frac{1}{8}|z-w|^2}~.
 \end{eqnarray*} 
 This completes the proof.
 \end{proof}

\begin{defn}
 We denote by \(C^{*}(\mathcal{WL})\) the \(C^{*}\)-algebra generated by weakly localized operators on \(H^{2}(\mathbb{C}^n, d\mu)\). Also, \(C^{*}(\mathcal{WL})\) is actually the norm closure of \(\mathcal{WL}\) since \(\mathcal{WL} \) is a \(\star\)-algebra.
 \end{defn}

We will prove the following main result.

\begin{defn}
 We denote by \(C^{*}(\mathcal{WL})\) the \(C^{*}\)-algebra generated by weakly localized operators on \(H^{2}(\C^n, d\mu)\). Also, \(C^{*}(\mathcal{WL})\) is actually the norm closure of \(\mathcal{WL}\) since \(\mathcal{WL} \) is a \(\star\)-algebra.
 \end{defn}

The organization of this paper is as follows. In Section 2, we will give propositions in the case of the Fock space \(H^{2}(\C^n, d\mu)\) which are the analogue of those given by Xia in \cite{xia2015localization} in the Bergman space case of the unit ball. Later, using these propositions in Section 3, we establish the proof of Theorem \ref{XiaFock} and present a consequence.

\begin{defn}\label{normstar}
 For an entire function \(h\) in \(\C^{n}\), we write
 \begin{equation*}
 \norm{h}_{*} = \left(\int_{\C^{n}} |h(\zeta)|^{2} e^{-\frac{1}{2}|\zeta|^2} dV(\zeta)\right)^{\frac{1}{2}}~.
 \end{equation*}
 We denote by \(\mathcal{H}_{*}\) the collection of entire functions \(h\) on \(\C^n\) satisfying \(\norm{h}_{*}<\infty\).
 \end{defn}
 \begin{rem}
 The norm \(\norm{\cdot}_{*}\) is equivalent to the norm on the Fock space \(F^{2}_{1/2}\) given in relation (\ref{Fnorm1}) which is an Hilbert space. More precisely, \(\norm{\cdot}_{*} = (2\pi)^{n/2} \norm{\cdot}_{F^{2}_{1/2}}\). This ensures the continuity of \(\norm{\cdot}_{*}\).
 \end{rem}
 In what follows, we will use the operator \(U_{z}\) defined by 
 \begin{equation*}
 U_{z}f(w) = f(z-w) k_{z}(w)~, \quad f \in H^{2}(\C^n, d\mu)~.
 \end{equation*}

\begin{pro}\label{proYz}
 Suppose \(\{c_{u}: u \in \Z^{2n}\}\) are complex numbers satisfying the condition \mbox{\(\sup_{u\in \Z^{2n}}|c_{u}| < \infty\)}. Then for each \(z\in \C^{n}\), the operator
 \begin{equation}\label{Yz}
 Y_{z} = \sum_{u \in \Z^{2n}} c_{u} k_{u-z} \otimes k_{u-z}
 \end{equation}
 is bounded on \(H^{2}(\C^n, d\mu)\). Moreover, the map \(z \mapsto Y_{z}\) from \(\C^{n}\) to \(\mathcal{B}(H^{2}(\C^{n},d\mu))\) is continuous with respect to the operator norm.
 \end{pro}
 \begin{proof}
 Let \(\{c_{u} : u \in \Z^{2n}\}\) be complex numbers such that \mbox{\(\sup_{u\in \Z^{2n}}|c_{u}| < \infty\)}. For \(z\in \C^{n}\), we define 
 \begin{equation*}
 A_{z} = \sum_{u \in \Z^{2n}} c_{u} (U_{u}k_{z}) \otimes e_{u} \quad \text{ and } \quad B_{z} = \sum_{u \in \Z^{2n}}(U_{u}k_{z})\otimes e_{u}~.
 \end{equation*}
 Using the relation (\ref{Uu2}), we have \(Y_{z} = A_{z}B^{*}_{z}\). Set \(h_{u} = c_{u}k_{z}\), then using Definition \ref{normstar}, we have
 \begin{equation*}
 \norm{h_{u}}_{*} = |c_{u}|\norm{k_{z}}_{*} = (2\pi)^{n/2} e^{\frac{|z|^2}{2}} |c_{u}|~.
 \end{equation*}
 Therefore, \(\sup_{u\in \Z^{2n}} \norm{h_{u}}_{*} < \infty\). Applying Lemma \ref{LemUh} to \(h_{u} = c_{u}k_{z}\), we see that \(\norm{A_{z}} \le C \sup_{u\in \Z^{2n}}|c_{u}|\). Thus each \(A_{z}\) is bounded. Since \(B_z\) is just a special case of \(A_{z}\) (with \(c_{u}=1\) for all \(u \in \Z^{2n}\)), then it is also bounded and hence \(Y_{z} = A_{z}B^{*}_{z}\) is bounded.

\begin{lem}\label{Lim=0}
 Let \(B \in \mathcal{WL} \), then for every \(z,w \in \C^n \), we have
 \begin{equation*}
 \lim_{R\to \infty} \sup_{u\in \Z^{2n}} \sum_{\underset{|u-v|>R}{v\in \Z^{2n} }} |\langle B k_{u-z}, k_{v-w} \rangle| =0 \quad \text{ and } \quad \lim_{R\to \infty} \sup_{u\in \Z^{2n}} \sum_{\underset{|u-v|>R}{v\in \Z^{2n} }} |\langle k_{u-z}, Bk_{v-w}\rangle| = 0~.
 \end{equation*}
 \end{lem}
 \begin{proof}
 By \cite[Lemma 2.32]{zhu2012}, for any entire function \(f\) on \(\C^n\), we have 
 \begin{equation*}
 \left|f(z)e^{-\frac{\alpha}{2}|z|^2}\right|^p \le C \int_{B(z,\delta)} |f(w)e^{-\frac{\alpha}{2}|w|^2}|^p dV(w) \quad \text{ for } z \in \C^n.
 \end{equation*}
 Hence for \(\alpha=p=1\) and \(\delta\) small such that the balls \(\{B(v-w,\delta): v \in \Z^{2n} \}\) are mutually disjoint, we have
 \begin{equation*}
 |\langle B k_{u-z}, k_{v-w} \rangle| = |Bk_{u-z} (v-w) |e^{-\frac{|v-w|^2}{2}} \le C \int_{B(v-w,\delta)} |Bk_{u-z}(\zeta) | e^{-\frac{|\zeta|^2}{2}} dV(\zeta).
 \end{equation*}
 Indeed, for \(\delta < \frac{1}{2} \), the balls \(\{B(v-w,\delta) : v \in \Z^{2n} \}\) are mutually disjoint. Otherwise, there would exist \(v,v' \in \Z^{2n} \) such that \(v \neq v' \), and a point \(\xi\) such that \(\xi \in B(v-w,\delta) \cap B(v'-w,\delta) \). In other words:
 \begin{equation*}
 |v-w-\xi| < \delta \quad \text{ and } \quad |v'-w - \xi| < \delta~.
 \end{equation*}
 This implies that 
 \begin{equation*}
 |v-v'|=|(v-w-\xi)-(v'-w-\xi)|\le |v-w-\xi| + |v'-w-\xi| < \delta + \delta= 2 \delta < 1~.
 \end{equation*}
 That is \(|v-v'|<1\). This contradicts the well-known fact that \(|v-v'|\ge 1\). This result actually implies that there exists \(N\in \N\) such that each \(\zeta\in \C^n \) belongs to at most \(N\) balls in \(\{B(v-w,\delta): v\in \Z^{2n}\}\). That is \(\sum_{v \in \Z^{2n}} \chi_{B(v-w,\delta)}(\zeta) \le N \) for each \(\zeta \in \C^n \).

\begin{proof}[\textbf{Proof of Proposition \ref{EwBEzD} }]
 From (\ref{EwBEz}), we have 
 \begin{equation*}
 E_{w} BE_{z} = \frac{1}{\pi^{2n}} \sum_{u,v \in \Z^{2n}} \langle Bk_{u-z}, k_{v-w} \rangle k_{v-w} \otimes k_{u-z}~.
 \end{equation*}
 Thus for any \(R>0\), we can write \(E_{w}BE_{z} = V_{R} + W_{R}\), where
 \begin{equation*}
 V_{R} = \frac{1}{\pi^{2n}} \sum_{\underset{|u-v|\le R}{u,v \in \Z^{2n}}} \langle Bk_{u-z}, k_{v-w} \rangle k_{v-w} \otimes k_{u-z} \quad \text{ and } 
 \end{equation*}
 \begin{equation*}
 \quad W_{R} = \frac{1}{\pi^{2n}} \sum_{\underset{|u-v|>R}{u,v \in \Z^{2n}}} \langle Bk_{u-z}, k_{v-w} \rangle k_{v-w} \otimes k_{u-z}~.
 \end{equation*}
 To complete the proof, it suffices to prove that:
 \begin{enumerate}[label=(\alph*)]
 \item \label{itm:first1} \(\lim_{R\to \infty} \norm{W_{R}}=0\).
 \item \label{itm:second1} \(V_{R} \in \) span(\(\mathcal{D}_{0}\)) for every \(R>0\).
 \end{enumerate}

\begin{pro}\label{DoT1}
 We have \(\mathcal{D}_{0} \subset \mathcal{T}^{(1)}\).
 \end{pro}
 To establish the proof of this proposition, we will need the next three propositions.
 \begin{pro}\label{YzT1}
 Suppose that \(\{c_{u}: u \in \Z^{2n}\}\) is a bounded set of complex coefficients. Then for each \(z \in \C^{n}\), the operator \(Y_{z}\) defined in (\ref{Yz}) belongs to \(\mathcal{T}^{(1)}\). 
 \end{pro}
 \begin{proof}
 \begin{enumerate}[label=(\alph*)]
 \item Let us first show that \(Y_{0} \in \mathcal{T}^{(1)}\). We have \(|u-v|\ge 1\) for all \(u \neq v \in \Z^{2n}\). Hence \(B(u,\frac{1}{2}) \cap B(v,\frac{1}{2}) = \emptyset \) for \(u\neq v\). For each \(0 < \varepsilon < \frac{1}{2}\), define the operator
 \begin{equation*}
 A_{\varepsilon} = \frac{1}{|B(0,\varepsilon)|} \int_{B(0,\varepsilon)} Y_{z} dV(z) .
 \end{equation*}
 From Proposition \ref{proYz}, we have the norm continuity of the map \(z\mapsto Y_{z}\) and it implies that
 \begin{equation*}
 \lim_{\varepsilon \to 0} \norm{Y_{0}-A_{\varepsilon}} = 0.
 \end{equation*}
 This comes from the fact that
 \begin{eqnarray*}
 \norm{Y_{0}-A_{\varepsilon}} &=& \norm{\frac{1}{|B(0,\varepsilon)|} \int_{B(0,\varepsilon)} (Y_{0}-Y_{z}) ~dV(z)} \le \frac{1}{|B(0,\varepsilon)|} \int_{B(0,\varepsilon)} \norm{Y_{0}-Y_{z}} ~dV(z)
 \end{eqnarray*}
 and \(\lim_{z\to 0}\norm{Y_{z}-Y_{0}}=0\) .

