\end{lemma}
\begin{proof}
 Let $\ell$ be the minimal length of an element in $\cO$. We prove the claim by induction on $|w| - \ell = k \in \NN_0$. For $k = 0$ there is nothing to prove.

\begin{notation}
 \label{not:delocalised-trace}
 Let $(W, S)$ be a Coxeter system of right-angled type and let $\cH$ be a generic Hecke algebra of type $(W, S)$ defined over $R$. For a conjugacy class $\cO \subseteq W$, we denote by $\Sigma_\cO\colon \cH \lra R$ the sum over all coefficients of minimal length elements in $\cO$, that is
 \begin{gather*}
 \Sigma_\cO(T_w)
 =
 \begin{cases}
 1 & \text{ if $w \in \cO$ and $w$ is of minimal length in $\cO$} \\
 0 & \text{ otherwise}\eqstop
 \end{cases}
 \end{gather*}
 Combining this with Notation~\ref{not:cyclic-reduction-map}, we will write $\vphi_\cO = \Sigma_\cO \circ \Phi$.
\end{notation}

\begin{theorem}
 \label{thm:delocalised-trace-identification}
 Let $\cH$ be a generic Hecke algebra of right-angled type $(W,S)$. For every conjugacy class $\cO \subseteq W$, the map $\vphi_\cO$ is a trace on $\cH$. If $(T_{\cU})_{\cU}$ denotes the basis of the cocentre of $\cH$ satisfying $T_{\cU} = T_w + [\cH, \cH]$ for every element of minimal length $w \in \cU$, then $\vphi_\cO(T_\cU) = \delta_{\cO, \cU}$.
\end{theorem}
\begin{proof}
 In order to show that $\vphi_\cO$ is a trace, it suffices to show that for all $w \in W$ and all $s \in S$ the equality $\vphi_\cO(T_s T_w) = \vphi_\cO(T_w T_s)$ holds. We prove this statement by induction on $|w| \in \NN_0$ and observe that the case $|w| = 0$ is clear. We distinguish several cases.

\begin{theorem}
 \label{thm:delocalised-trace-existence}
 Let $(W,S)$ be a right-angled, hyperbolic Coxeter system and let $\cH$ be the Iwahori-Hecke algebra of type $(W,S)$ with deformation parameter $(q_s)_{s \in S} \in \RR_{> 0}^S$. Let $\cS'(W, S, q), \cS(W, S, q) \subseteq \Cstarred(W, S, q)$ be smooth subalgebras, such that $\cS'(W, S, q)$ is an unconditional completion of $\CC(W, S, q)$ and the natural quasi-derivation
 \begin{gather*}
 \Delta\colon T_w \mapsto \sum_{\substack{w = w_1w_2 \\ \text{ reduced decompositon}}} T_{w_1} \ot T_{w_2}
 \end{gather*}
 continuously extends to a map into the unconditional tensor product $\cS(W, S, q) \lra \cS'(W, S, q) \ot \cS'(W, S, q)$. Then for every conjugacy class $\cO \subseteq W$ the trace $\vphi_\cO$ continuously extends to $\cS(W, S, q)$.
\end{theorem}
\begin{proof}
 Let us first observe that the map $\Sigma_\cO$ summing over the finitely many coefficients of elements of minimal length in $\cO$ extends to a continuous map on $\cS'(W, S, q)$, as $\cS'(W, S, q)$ is an unconditional completion of $\CC(W, S, q)$. Consider maps $\gamma, \rho\colon W \lra W$ defined as in Lemma~\ref{lem:cyclic-reduction-hecke-algebra}. Since $\Delta$ extends continuously to a map $\cS(W, S, q) \lra \cS'(W, S, q) \ot \cS'(W, S, q)$ and since $\cS'(W, S, q)$ is an unconditional completion of $\CC(W, S, q)$, the map $\Delta'\colon \cS(W, S, q) \lra \cS'(W, S, q) \ot \cS'(W, S, q)$ satisfying $\Delta'(T_w) = T_{\gamma(w) \rho(w)} \ot T_{\gamma(w)^{-1}}$ is well-defined and continuous. Let $\Phi\colon \CC(W, S, q) \lra \CC(W, S, q)$ be the unique linear map satisfying $\Phi(T_w) = T_{\gamma(w)^{-1}} T_{\gamma(w)} T_{\rho(w)}$. Then we have $\vphi_\cO = \Sigma_\cO \circ \Phi$ as shown in Theorem~\ref{thm:delocalised-trace-identification}. So a continuous extension of $\vphi_\cO$ to $\cS(W, S, q)$ is obtained by the composition
 \begin{multline*}
 \cS(W, S, q) \stackrel{\Delta'}{\lra}
 \cS'(W, S, q) \ot \cS'(W, S, q) \stackrel{\text{tensor flip}}{\lra} \\
 \cS'(W, S, q) \ot \cS'(W, S, q) \stackrel{\text{multiplication}}{\lra}
 \cS'(W, S, q) \stackrel{\Sigma_\cO}{\lra}
 \CC
 \eqcomma
 \end{multline*}
This finishes the proof.
\end{proof}

Before proving Theorem~\ref{thmintro:pairing}, let us clarify its context and notation beyond what we have done in the introduction already. Recall from \cite[Theorem A.2.1]{bost1990-principe-oka} that the inclusion of a smooth subalgebra into a unital C*-algebra induces an isomorphism in K-theory. We also recall the K-theory calculations for right-angled Hecke C*-algebras from \cite[Section 4]{raumskalski2022}. To this end we use the description of conjugacy classes of finite order elements from Remark~\ref{rem:finite-order-element-cliques}. Denote by $\mathrm{Cliq}(\Gamma)$ the set of cliques in the commutation graph $\Gamma$ of a right-angled Coxeter system $(W, S)$, that is subsets $C \subseteq S$ such that $st = ts$ for all $s,t \in C$. For a clique $C \in \mathrm{Cliq}(\Gamma)$, we write $p_C = \prod_{s \in C} \chi_1^s$. Here $\chi_1^s = \pi_s(\chi_1)$ denotes the image of the projection $\chi_1 \in \CC[\ZZ/2]$ associated with the trivial representation under the linear map extending the group homomorphism $\pi_s\colon \ZZ/2 \lra \CC(W, S, q)^\times$ which satisfies $\pi_s(1) = \frac{2}{q_s^{1/2} + q_s^{-1/2}}T_s + \frac{q_s^{-1/2} - q_s^{1/2}}{q_s^{1/2} + q_s^{-1/2}}$. Then for every deformation parameter $q \in \RR_{> 0}^S$ the map $\mathrm{Cliq}(\Gamma) \lra \rK_0(\Cstarred(W, S, q))\colon C \mapsto [p_C]$ induces an isomorphism $\ZZ^{\mathrm{Cliq}(\Gamma)} \lra \rK_0(\Cstarred(W, S, q))$.
\begin{proof}[Proof of Theorem~\ref{thmintro:pairing}]
 As described above, for $D \in \mathrm{Cliq}(\Gamma)$ we have $p_D = \prod_{s \in D} \chi_1^s$ where $\chi_1^s$ is the projection associated with the trivial representation of the unitary representation $\ZZ/2 \mapsto \CC(W, S, q)$ mapping $1$ to $\frac{2}{q_s^{1/2} + q_s^{-1/2}}T_s + \frac{q_s^{-1/2} - q_s^{1/2}}{q_s^{1/2} + q_s^{-1/2}}$. We have $\chi_1^s = \mathbb{1}_{(0,\infty)}(T_s) = \frac{1}{q_s^{1/2} + q_s^{-1/2}} (T_s + q_s^{-1/2}) =\frac{1}{q_s^{1/2} + q_s^{-1/2}} T_s + \frac{1}{1 + q_s}$. Writing $T_D = \prod_{s \in D} T_s$, we find that
 \begin{gather*}
 p_D = \sum_{C \subseteq D} \bigl ( \prod_{s \in C} \frac{1}{q_s^{1/2} + q_s^{-1/2}} \bigr ) \bigl ( \prod_{s \in D \setminus C} \frac{1}{1 + q_s} \bigr ) T_C
 \eqstop
 \end{gather*}
 Since all elements in the support of $p_D$ have minimal length and are pairwise non-conjugate, we find that
 \begin{gather*}
 \vphi_C(p_D)
 =
 \Sigma_C(p_D)
 =
 \begin{cases}
 0 & C \nsubseteq D \eqcomma \\
 \prod_{s \in C} \frac{1}{q_s^{1/2} + q_s^{-1/2}} \prod_{s \in D \setminus C} \frac{1}{1 + q_s} & C \subseteq D \eqstop
 \end{cases}
 \end{gather*}
 Now the claimed formula for $\vphi_C(p_D)$ follows.

post_theorem_intro_text:
We mention that in order to prove this result, we establish in Theorem~\ref{thm:right-angled-cocentre-basis} that the cocentre of Iwahori Hecke algebra of right-angled type has a basis indexed by representatives of conjugacy classes.  The problem of describing the cocentre of Hecke algebras is well-known in the context of character theory.  See e.g. \cite{geckpfeiffer2000-characters} for spherical Coxeter types and \cite{henie2014} for affine Coxeter types.  The recent work \cite{chen2025-centralizers} explicitly states folklore conjectures about the cocentre for indefinite Coxeter types.

The next theorem extends Puschnigg's construction of Schwartz algebras for hyperbolic groups to the realm of right-angled Hecke algebras.
\begin{introtheorem}
  \label{introthm:Schwartz-algebra-existence}
  Let $(W,S)$ be a right-angled, hyperbolic Coxeter system and $\cH$ the complex Iwahori-Hecke algebra of type $(W,S)$ with deformation parameter $(q_s)_{s \in S} \in \RR_{> 0}^S$.  There is a  subalgebra $\cS(W, S, q) \subseteq \Cstarred(W, S, q)$, which
  \begin{itemize}
  \item is dense and closed under holomorphic functional calculus,
  \item and such that for every conjugacy class $\cO \subseteq W$, the trace $\vphi_\cO$ continuously extends to $\cS(W, S, q)$.
  \end{itemize}
\end{introtheorem}

From the point of view of operator algebras, one of the main purposes of delocalised traces is to determine K-theory classes via their pairing.  The K-theory of right-angled Hecke C*-algebras was calculated in \cite{raumskalski2022}.  We briefly recall that for every clique $C$ in the commutation graph of a right-angled Coxeter system there is a projection $p_C$, such that the classes $([p_C])_C$ freely generate K-theory.  In Remark~\ref{rem:finite-order-element-cliques}, we observe that these cliques are in natural bijection with finite order elements of a right-angled Coxeter system.  We obtain the following result, which determines the pairing of K-theory and delocalised traces.
\begin{introtheorem}
  \label{thmintro:pairing}
  Let $(W,S)$ be a right-angled, hyperbolic Coxeter system and $(q_s)_{s \in S} \in \RR_{> 0}^S$ a deformation parameter.  Denote by $\mathrm{Cliq}(\Gamma)$ the set of cliques of the commutation graph $\Gamma$ of $(W, S)$, identified with the set of conjugacy classes of finite order elements in $W$.  For a clique $C \in \mathrm{Cliq}(\Gamma)$ let $p_C$ be the associated projection and let $\vphi_C$ be the delocalised trace associated with $C$.  Then the pairing between K-theory of $\Cstarred(W, S, q)$ and delocalised traces of finite order elements is determined by the formula
  \begin{gather*}
    \vphi_C(p_D) =
    \begin{cases}
      0 & C \nsubseteq D\eqcomma \\
      \prod_{s \in C} \frac{1}{q_s^{1/2} + q_s^{-1/2}} \prod_{s \in D \setminus C} \frac{1}{1 + q_s} & C \subseteq D \eqstop
    \end{cases}
  \end{gather*}
  In particular, the pairing $\rK_0(\Cstarred(W,S,q)) \times \RR^{\mathrm{Cliq(\Gamma)}} \lra \RR$ is non-degenerate.
\end{introtheorem}

As mentioned above, in the last section of \cite{puschnigg2010} Puschnigg used his main results to obtain certain decompositions of cyclic cohomology for his smooth algebras and the group C*-algebras of hyperbolic groups, close in spirit to the computation of cyclic homology of group rings due to Burghelea \cite{burghelea1985, burghelea2023-erratum-for-1985}. This line of research was later continued, using the Jolissaint's rapid decay subalgebras, for example in \cite{jiogleramsey14} and in \cite{engel20}. Our results in principle open the way to obtaining similar decompositions of cyclic cohomology in the context of Hecke algebras, such as the Fr{\'e}chet algebra $\cS(W, S, q)$ appearing in Theorem \ref{introthm:Schwartz-algebra-existence}. However, the setting of right-angled hyperbolic Coxeter types remains too narrow to make such an endeavour worthwhile at present, since higher cyclic cohomology is expected to vanish.  Further work in this direction, would chime with the recent progress in understanding noncommutative geometric properties of the Iwahori-Hecke algebras such as in the work \cite{klisseperovic25} already mentioned.

This paper is organised as follows: after this introduction, in the preliminaries we describe background material and fix notation, focusing on Coxeter groups and Hecke algebras.  Then in the third section, we investigate the combinatorics of the multiplication in right-angled Hecke algebras, which plays a major role in this work.  In the fourth section, we adapt work of Blackadar-Cuntz and Puschnigg on differential seminorms and quasi-derivations to the needed generality.  In the fifth section, we use this framework in order to exhibit specific smooth subalgebras of the Hecke algebras under consideration, to which the natural quasi-derivation extends.  In the sixth section, we describe traces on right-angled Hecke algebras, and in that last section combine this with the previous results on smooth subalgebras, to obtain delocalised traces on Hecke-Schwartz algebras and calculate their pairing with K-theory.

