ref_dict.def:mapbetweenstacks:
\begin{definition}[{\cite[Section 0012]{HL25}, \cite[Definition 3.1.3]{Ol16}}]\label{def:mapbetweenstacks}
Let $\SX$ and $\SY$ be categories fibered over a category $\SC$.
The category $\op{Map}_{\op{Cat}^{\op{cart}}_{/\SC}}(\SX,\,\SY)$ of morphisms of fibered categories 
between $\SX$ and $\SY$ is defined as follows. 
\begin{itemize}
\item An object is a functor $f\,:\,\SX\,\longrightarrow\, \SY$ which preserves Cartesian morphisms.
\item A morphism between functors $f$ and $g$ is a natural transformation
$\eta\,:\,f\,\Rightarrow\, g$ such that, for every $\xi\,\in \,\SX$, the associated
morphism $\eta_\xi\,:\,f(\xi)\,\longrightarrow\, g(\xi)$ lies over the identity morphism.
\end{itemize}
\end{definition}

ref_dict.lemma:2approximation:
\begin{lemma}
\label{lemma:2approximation}
Let $\SE$ be a family of vector bundles on $X$ --- with $g\,=\, {\rm genus}(X) \, \geq\, 3$ --- of
rank $r$ and determinant $\xi$ of degree $d$ parameterized by a scheme $T$. Then there
exists a scheme $Q$ together with a vector bundle $\SF$ on $X\times Q$ and a morphism of schemes
$\tau\,:\,T\,\longrightarrow\, Q$ such that
\begin{itemize}
\item $Q$ is smooth,

\item the locus $Q^{ns}$ of points $q\,\in\, Q$ such that $\SF\big\vert_{X\times\{q\}}$ is non-stable has
codimension at least 2 in all the irreducible components of $Q$,

\item $\det(\SF)\,\cong\, \pi_X^* \xi$, where $\pi_X\,:\,X\times Q\,\longrightarrow\, X$ is the natural projection, and

\item $\SE\ \cong\ (\id_X\times \tau)^*\SF$.
\end{itemize}
\end{lemma}

ref_dict.lemma:tensorLineBundle:
\begin{lemma}
\label{lemma:tensorLineBundle}
Let $X$ be a smooth complex projective curve of genus $g\ge 3$. Let 
$$
\Phi\,:\,\SM^{\svb}(X,r,\xi) \,\longrightarrow \,\SM^{\svb}(X,r,\xi)
$$
be an automorphism such that the induced map $\varphi\,:\,M^{\svb}(X,r,\xi) \,\longrightarrow\, M^{\svb}(X,r,\xi)$ coincides with the
identity map, i.e., $\Phi(E)\,\cong \,E$ for each stable vector bundle
$E$. Then $\Phi$ is isomorphic to the identity map.
\end{lemma}

ref_dict.thm:intro:
\begin{theorem}[{See Theorem \ref{thm:main}}]
\label{thm:intro}
Let $X$ and $X'$ be smooth complex projective curves of genus $g$ and $g'$ respectively, with $g,\, g'\, \ge\, 4$. Let $\xi$ and $\xi'$ be line bundles on $X$ and $X'$
respectively. If $\Psi\,:\, \SM(X,r,\xi) \,\longrightarrow \,\SM(X',r',\xi')$ is an isomorphism of stacks,
then $r\,=\,r'$, and there exist a basic transformation $\ST_{\sigma,L,s}$, for which $s$ can always be taken as $+1$ if $r\,=\,2$, and such that $\Psi$ is isomorphic to $\ST_{\sigma,L,s}$.
\end{theorem}

ref_dict.thm:main:
\begin{theorem}\label{thm:main}
Let $X$ and $X'$ be smooth complex projective curves of genus $g$ and $g'$ respectively, with $g,\, g'\, \ge\, 4$. Let $\xi$ and $\xi'$ be line bundles on $X$ and $X'$
respectively. Let $r,\,r'\,>\,0$. Let $\Psi\,:\, \SM(X,r,\xi)\,\longrightarrow\, \SM(X',r',\xi')$ be an
isomorphism between the moduli stacks. Then $r\,=\,r'$, and there exists
\begin{itemize}
\item an isomorphism $\sigma\,:X'\,\too\, X$,
\item a sign $s\,\in \, \{+1,\, -1\}$, which can always be taken as $+1$ if $r\,=\,2$,
\item a line bundle $L$ over $X$ together with an isomorphism $\xi'\,\cong\, \sigma^*(\xi\otimes L^r)^s$
\end{itemize}
such that the map $\Psi$ is isomorphic to the basic transformation $\ST_{\sigma,L,s}$ defined in Definition \ref{def:basicTransformation}.
\end{theorem}

ref_dict.cor:2approximation:
\begin{corollary}
\label{cor:2approximation}
For any vector bundle $E$ on a curve $X$ of genus $g\,\ge\, 3$, there exists a family of vector bundles $\SE$ on $X\times T$ for a certain smooth 2-dimensional scheme
$T$ and a point $t_0\,\in\, T$ such that $\SE\big\vert_{X\times \{t\}}$ is stable for each $t\,\neq\, t_0$ and $\SE\big\vert_{X\times \{t_0\}}\,\cong\, E$.
\end{corollary}

ref_dict.definition:nonsplit:
\begin{definition}\label{definition:nonsplit}
 Let $r \geq 3$ be an integer. A \emph{Shimura curve of Mumford type} in $\Agr$ (see \cite{viehwegzuo-2004}) is a proper Shimura curve $C  \subset \Agr$ of the following form. Consider a polarized abelian scheme $B_1 \to C_1$ as defined above. 
Pick an étale cover $C_2 \to C_1$ with pull-back $B_2 \to C_2$, so that there is a principally polarized abelian scheme $A_2 \to C_2$ isogenous to the polarized abelian scheme $B_2 \to C_2$, such that $A_2 \to C_2$ carries a symplectic level $r$ structure. This gives a morphism $C_2 \to \ca A_{g,[r]}$, and we let $C \subset \ca A_{g,[r]}$ denote its image. 

Let us say that the Shimura curve of Mumford type $C$ is \emph{split} (resp.\ \emph{non-split}) if we are in case \eqref{case:i} (resp.\ \eqref
{case:ii}) of Lemma \ref{lemma:cases}. 
\end{definition}

ref_dict.theorem:special:
\begin{theorem} \label{theorem:special}
    Let $g=2^d$ with $d \geq 4$. Then there exists an abelian variety $A$ of dimension $g$ over $\overline{\mathbb{Q}(t)}$ with no power $A^n$ isogenous to a Jacobian. 
\end{theorem}

ref_dict.theorem:generic:
\begin{theorem} \label{theorem:generic}
Let $g = 2^d \geq 16$ and $N \geq 1$. Then there exists a Hodge generic point $x = [A] \in \Ag(\Qtbar)$ such that the corresponding abelian variety $A$ over $\Qtbar$ has no power $A^n$ with $n \leq N$ which is isogenous to a Jacobian.
\end{theorem}

post_theorem_intro_text:
Let $\mathcal{A}_g$ be the moduli space of principally polarized abelian varieties of dimension $g$. A point $x \in \mathcal{A}_g$ is called \emph{Hodge generic} if $x$ is not contained in a special subvariety of $\mathcal{A}_g$ of positive codimension---equivalently, the associated Mumford--Tate group is $\GSp_{2g}$. 
In \cite{tsimerman-jacobian}, Tsimerman showed that one can find CM abelian varieties of dimension $g \geq 4$ which are not isogenous to a Jacobian; in \cite{masser-zannier} and \cite{shankartsimerman-Fptbar}, the authors (using different methods) showed that there are also Hodge generic $\overline{\Q}$ points of $\mathcal{A}_g$ with that property. 

As the proof of Theorem \ref{theorem:special} shows, for $g = \smash{ 2^d} \geq 16$, there are $x\in \smash{\mathcal{A}_g(\overline{\Q(t)})}$, the geometric generic point of a special curve $C \subset \mathcal{A}_g$, such that $A_x$ has no power isogenous to a Jacobian. It is natural to ask whether there exist Hodge generic points $x \in \smash{\mathcal{A}_g(\overline{\Q(t)})}$ with that same property. Our second main result says that at least for bounded powers, the answer is yes.

\begin{theorem} \label{theorem:generic}
Let $g = 2^d \geq 16$ and $N \geq 1$. Then there exists a Hodge generic point $x = [A] \in \mathcal{A}_g(\overline{\Q(t)})$ such that the corresponding abelian variety $A$ over $\overline{\Q(t)}$ has no power $A^n$ with $n \leq N$ which is isogenous to a Jacobian.
\end{theorem}

\subsection{Outline of proof}
We now briefly describe our methods. Let $\mathcal A_{g,[r]}$ be the moduli space of principally polarized abelian varieties of dimension $g$ with symplectic level $r\geq 3$ structure. The proof of Theorem \ref{theorem:special} uses an Arakelov inequality due to Lu and Zuo \cite[Theorem 1.4]{luzuo-2019}, which says in particular that given a smooth proper curve $C \subset \mathcal A_{g,[r]}$ with induced abelian scheme $\pi \colon A \to C$, one has $\deg(\pi_\ast \Omega_{A/C}) < (g/2) \cdot \deg(\Omega_C)$ whenever $g \geq 12$ and $C$ is generically contained in the Torelli locus. On the other hand, this becomes an equality if $C$ is a Shimura curve of Mumford type (cf.\ Definition \ref{definition:nonsplit}), from which Lu and Zuo deduce that such Shimura curves cannot be generically contained in the Torelli locus if $g \geq 12$. We apply their Arakelov inequality to show that, more generally, the $n$-th power $A_{\bar \eta}^n$ cannot be isogenous to a Jacobian for every $n$, for $\eta \in C$ the generic point. 

We prove the above for Shimura curves of Mumford type $C \subset \mathcal A_{g,[r]}$ which are not necessarily smooth. Such curves exist in $\mathcal A_{g,[r]}$ for each $r \geq 3$. For technical reasons, we proceed in the second part of the paper to assume that $r$ is prime. We pick a suitable surface $S\subset\mathcal A_{g,[r]}$ that contains $C$ as well as Hodge generic points. Theorem \ref{theorem:special} implies that the induced abelian scheme $B\rightarrow S$ has the property that the $n$-th power $B_{\bar \eta}^n$ is not isogenous to a Jacobian for every $n$, where now $\eta \in S$ denotes the generic point of $S$. Bounding $n$, we then use an intersection-theoretic argument to find a curve $C_{\textrm{gen}} \subset S$ over $\overline{\Q}$ that satisfies the conclusion of Theorem \ref{theorem:generic}. 

\subsection{Acknowledgements}

We would like to thank Emiliano Ambrosi, Philip Engel, Stefan Schreieder and Jacob Tsimerman for stimulating discussions. 

O.d.G.F.~has received funding from the ERC Consolidator Grant FourSurf \textnumero 101087365. A.S.~was partially supported by the NSF grant DMS-2338942, the Institute for advanced studies (via the NSF grant DMS-2424441), and a Sloan research fellowship.

theorem.content:
\label{thm:sob-pull-back}
Let $n,m,Q\ge 1$ be natural numbers, $U\subset \mathbb{R}^m$ open, and $f\in W_{loc}^{1,p}(f(\Omega),\mathcal A_Q(\mathbb{R}^n))$. If $\omega$ is a $S_Q$-invariant smooth $k$-form on $(\mathbb{R}^n)^Q$, and either $k+1\le p$ of $\mathrm {d} \omega=0$ and $k\le p$, then $\omega$ has a well-defined pull-back $f^*\omega \in L^{p/k}_{loc}(U,\bigwedge^k\mathbb{R}^m)$ and moreover
\begin{align*}
    \mathrm {d}(f^*\omega)=f^*(\mathrm {d}\omega)
\end{align*}
weakly.

ref_dict.prop:ball-meas-upper-bound:
\begin{proposition}\label{prop:ball-meas-upper-bound}
For any compact set $K\subset \Omega_f$ there exists $r_K>0$ such that
\begin{align*}
    \Ha^n(B_{\Omega_f}(z,r))\le \omega_nd^{n/2}K_IK_O r^n,\quad z\in K,\ r<r_K.
\end{align*}
\end{proposition}

ref_dict.thm:higher-integrability:
\begin{theorem}\label{thm:higher-integrability}
If $f:\Omega\to \R^n$ is a non-constant quasiregular map of degree $d$, then there exists $p>n$ such that $\minv f\in W_{loc}^{1,p}(f(\Omega),\mathcal A_d(\Omega))$.
\end{theorem}

ref_dict.thm:geom-QC:
\begin{theorem}\label{thm:geom-QC}
Let $f:\Omega\to \R^n$ be a proper quasiregular map of finite degree $d$, and equip $\Omega_f=\minv f(f(\Omega))$ with the metric from $\mathcal A_d(\R^n)$ and the Hausdorff $n$-measure on $\Omega_f$. 
\begin{itemize}
    \item[(1)] $\Omega_f$ is $n$-rectifiable, upper Ahlfors $n$-regular and satisfies the infinitesimal $n$-Poincar\'e inequality;
    \item[(2)] $\minv f:f(\Omega)\to \Omega_f$ is geometrically quasiconformal. More precisely, 
\begin{align*}
    \frac 1{K_IK_O}\Mod_n\Gamma\le \Mod_n\minv f(\Gamma)\le K_IK_O\Mod_n\Gamma
\end{align*}
fir any path family $\Gamma $ in $f(\Omega)$.
\end{itemize}
\end{theorem}

ref_dict.def:multi-valued-inv:
\begin{definition}\label{def:multi-valued-inv}
Let $f:X\to Y$ be a proper branched cover of finite degree $d>0$ between topological $n$-manifolds. The multi-valued inverse $\minv f:f(X)\to \mathcal A_d(X)$ of $f$ is defined by
\begin{align*}
\minv f(y)=\sum_{x\in f\inv(y)}\iota(f,x)\bb x    
\end{align*}
\end{definition}

ref_dict.thm:QR-curve:
\begin{theorem}\label{thm:QR-curve}
Let $f:\Omega\to \R^n$ be a proper quasiregular map of finite degree $d$. Then the multivalued inverse $\minv{f}:f(\Omega)\to \mathcal A_d(\Omega)$ is an $\omega$-quasiregular curve, where $\omega=\operatorname{tr}(\operatorname{vol}_{\R^n})$ is given by \eqref{eq:natural-n-form}. More precisely,  $\minv f\in W_{loc}^{1,n}(f(\Omega),\mathcal A_d(\R^n))$, and 
\[
\|\omega\|\circ \minv f\ |D\minv f|^n\le d^{n/2-1}K_I(f)\star \minv f^*\omega\quad \textrm{almost everywhere on }\Omega.
\]
\end{theorem}

ref_dict.thm:wug:
\begin{theorem}\label{thm:wug}
For $\Mod_n$-a.e. curve $\gamma$ in $f(\Omega)$, $\minv f\circ\gamma$ is an absolutely continuous curve in $\mathcal{A}_d(\Omega)$, and satisfies
\begin{align}\label{eq:ug-ineq}
H(\gamma_t)|\gamma_t'|\le |(\minv f\circ\gamma)'_t|\le (K_IK_O)^{1/n} H(\gamma_t)|\gamma_t'|
\end{align}
a.e. $t$, where
\begin{align}\label{eq:H}
    H(y):=\big(f_\ast(\|Df\|^{-2})(y)\big)^{1/2},\quad y\in f(\Omega).
\end{align}
\end{theorem}

ref_dict.lem:homeo:
\begin{lemma}\label{lem:homeo}
The generalized inverse $\minv f:f(X)\to \mathcal A_d(X)$ is a homeomorphism onto its image.
\end{lemma}

ref_dict.thm:lip-pullback-flat-form:
\begin{theorem}\label{thm:lip-pullback-flat-form}
Suppose $U\subset\R^m$ is an open set, $f:U\to\mathcal A_d(\R^n)$ is Lipschitz and $\omega\in \Omega^k(\mathcal A_d(\R^n))$. Then $\ud(f^*\omega)=f^*(\ud\omega)$ weakly. In particular, $f^*\omega$ is a flat form on $U$ in the sense of Whitney. 
\end{theorem}

ref_dict.thm:sob-pull-back:
\begin{theorem}\label{thm:sob-pull-back}
Let $n,m,Q\ge 1$ be natural numbers, $U\subset \R^m$ open, and $f\in W_{loc}^{1,p}(f(\Omega),\mathcal A_Q(\R^n))$. If $\omega$ is a $S_Q$-invariant smooth $k$-form on $(\R^n)^Q$, and either $k+1\le p$ of $\ud \omega=0$ and $k\le p$, then $\omega$ has a well-defined pull-back $f^*\omega \in L^{p/k}_{loc}(U,\bigwedge^k\R^m)$ and moreover
\begin{align*}
    \ud(f^*\omega)=f^*(\ud\omega)
\end{align*}
weakly.
\end{theorem}

