In particular, if $f:U\to \mathcal A_Q(\R^n)$ is a multi-valued (locally) Lipschitz map, the pull-back $f^*\omega$ of any $S_Q$-invariant smooth $k$-form is a (locally)flat $k$-form on $U$ in the sense of Whitney (cf. Theorem \ref{thm:lip-pullback-flat-form}).

An element $\omega\in \Omega^k(\mathcal A_d(V))$ is a smooth map $\omega:V^d\to \bigwedge^k(\R^n)^d$ with 
\begin{align}\label{eq:S_d-invariant}
\omega_x(v_1,\ldots,v_k)=\omega_{\sigma(x)}(\sigma v_1,\ldots,\sigma v_k),\quad x\in V^d,\ v_1,\ldots, v_k\in (\R^n)^d.
\end{align}
In particular, for each $\bb{x}\in \mathcal A_d(V)$, the value $\omega_{\bb{x}}:=\omega_{\sigma(x)}\circ \sigma\in \bigwedge^k(\R^n)^d$
is well-defined and independent of $\sigma\in S_d$. We define the comass $\|\omega\|:\mathcal A_d(V)\to \R$ of a $k$-form $\omega\in \Omega^k(\mathcal A_d(V))$ by 
\begin{align*}
\|\omega\|_{\bb x}=\|\omega_{x}\|,\quad \bb x\in \mathcal A_d(V).
\end{align*}
This is well-defined by \eqref{eq:S_d-invariant}.

\begin{lemma}\label{lem:pullback-est}
Suppose $U\subset \R^m$ and $V\subset \R^n$ are open sets, $\omega$ is a smooth $k$-form on $\mathcal A_d(V)$ and $h:U\to \mathcal A_d(V)$ a.e. approximately differentiable. Then $h^*\omega$ is a measurable $k$-form on $U$ and 
\begin{align*}
\|h^*\omega\|_x\le \|D_xh\|_x^k\|\omega_{h(x)}\|\quad\textrm{a.e. }x\in U.
\end{align*}
\end{lemma}
\begin{remark}
In particular $h^*\omega\in L^{p/k}_{loc}(U)$ if $h\in W^{1,p}_{loc}(U,\mathcal A_d(V))$.
\end{remark}
\begin{proof}
The approximate differentials $Dh_1,\ldots,Dh_d$ are measurable, cf. ***. For all $x\in U$ where $h$ is approximately differentiable, we have
\begin{align*}
\|h^*\omega\|_x&=\max\{\omega_{h(x)}(Dh(v_1),\ldots,Dh (v_d)):\ |v_1|,\ldots,|v_d|\le 1\}\\
&\le \|D_xh\|^k\|\omega_{h(x)}\|,
\end{align*}
completing the proof.
\end{proof}

\begin{lemma}\label{lem:pull-back-of-decomp}
Suppose $f_i:U\to \mathcal A_{d_i}(V)$ is Lipschitz ($i=0,1$), $d=d_0+d_1$, and $\omega$ is a $S_{d_0}\times S_{d_1}$-invariant form on $V^d$. Then the pull-back $\bb{f_0,f_1}^*\omega$ is a well-defined $k$-form on $U$. Moreover, 
\begin{align*}
\bb{f_0,f_1}^*(\omega_0\otimes\omega_1)=f_0^*\omega_0\wedge f_1^*\omega_1
\end{align*}
whenever $\omega_i\in \Omega^{k_i}(\mathcal A_{d_i}(V))$ ($i=0,1$) and $k=k_0+k_1$.
\end{lemma}
\begin{proof}
Let $x\in U$ be such that $f_0,f_1$ are differentiable at $x$, and let $f_i^1(x),\ldots, f_i^{d_i}(x)$ and $D_xf_i^1,\ldots,D_xf_i^{d_i}$ be as in Theorem \ref{thm:multi-valued-rademacher} (i) and (ii). (In particular, note that $f=\bb{f_0,f_1}$ is differentiable at $x$ and $Df=\bb{D_xf_0^1,\ldots,D_xf_0^{d_0},D_xf_1^1,\ldots,D_xf_1^{d_1}}$.) Given $(\sigma_0,\sigma_1)\in S_{d_0}\times S_{d_1}$, denote
\[
D_xf^{(\sigma_0,\sigma_1)}=(D_xf_0^{\sigma_0\inv(1)},\ldots D_xf_0^{\sigma_0\inv(d_0)},D_xf_1^{\sigma_1\inv(1)},\ldots,D_xf_1^{\sigma_1\inv(d_1)})
\]
and similarly 
\[
(f_0^{\sigma_0}(x),f_1^{\sigma_1}(x))=(f_0^{\sigma_0\inv(1)}(x),\ldots,f_0^{\sigma_0\inv(d_0)},f_1^{\sigma_1\inv(1)},\ldots,f_1^{\sigma_1\inv(d_1)}).
\]
We define
\begin{align*}
 (f^*\omega)_x(v_1,\ldots,v_k)=\omega_{(f_0^{\sigma_0}(x),f_1^{\sigma_1}(x))}(D_xf^{(\sigma_0,\sigma_1)}v_1,\ldots,D_xf^{(\sigma_0,\sigma_1)}v_k)
\end{align*}
for $v_1,\ldots,v_k\in T_xU=\R^m$. By the $S_{d_0}\times S_{d_1}$-invariance of $\omega$, this expression is independent of $(\sigma_0,\sigma_1)$ and gives a well-defined element in $\bigwedge^k\R^m$, which we denote by $(f^*\omega)_x=\omega_{(f_0(x),f_1(x))}\circ(D_xf_0,D_xf_1)$.

\begin{proposition}\label{prop:flat-form}
Let $d_0,d_1\ge 1$ be natural numbers, $d:=d_0+d_1$, and let $U\subset \R^m$ be an open set. If $f_i:U\to \mathcal A_{d_i}(\R^n)$ are Lipschitz functions such that $\ud(f_i^*\omega)=f_i^*(\ud\omega)$ weakly for all $l$-forms $\omega\in \Omega^l(\mathcal A_{d_i}(\R^n))$, $l\le k$ ($i=0,1$), then $\ud(\bb{f_0,f_1}^*\omega)=\bb{f_0,f_1}^*(\ud\omega)$ weakly for all $k$-forms $\omega\in \Omega^k(\mathcal A_d(\R^n))$.
\end{proposition}
\begin{proof}
Denote $f:=\bb{f_0,f_1}$, and let $\omega\in \Omega^k(\mathcal A_d(\R^n))$. Let 
\[
(\omega_j)\subset \bigcup_{r+l=k}\Omega^l((\R^n)^{d_0})\otimes \Omega^r((\R^n)^{d_1})
\]
be a sequence such that $(\omega_j)_x\to \omega_x$ and $(\ud\omega_j)_x\to (\ud\omega)_x$ for all $x\in (\R^n)^d$ and $\sup_j\max\{\|\omega_j\|_\infty,\|\ud\omega_j\|_\infty\}<\infty$. Then
\begin{align*}
\tilde\omega_j&:=P_{S_{d_0}\times S_{d_1}}\omega_j\to P_{S_{d_0}\times S_{d_1}}\omega=\omega,\\ 
\ud\tilde\omega_j&=P_{S_{d_0}\times S_{d_1}}(\ud\omega_j)\to P_{S_{d_0}\times S_{d_1}}(\ud\omega)=\ud\omega
\end{align*}
and $\sup_j\max\{\|\tilde \omega_j\|_\infty,\|\ud\tilde \omega_j\|_\infty\}<\infty$, cf. Lemma \ref{lem:proj-onto-invariant-forms}. By Lemma \ref{lem:pull-back-of-decomp} each $\tilde\omega_j$ is a sum of tensor products $\omega_0\otimes\omega_1$ where $\omega_i$ is $S_{d_i}$-invariant and $f^*(\omega_0\otimes\omega_1)=(f_0^*\omega_0)\wedge(f^*_1\omega_1)$. Together with the assumption that $f_i^*(\ud\omega_i)=\ud(f^*_i\omega)$ weakly for $S_{d_i}$-invariant forms $\omega$, this yields 
\begin{align*}
f^*(\ud(\omega_0\otimes\omega_1))&=f^*(\ud\omega_0\otimes \omega_1+(-1)^{\deg\omega_0}\omega_0\otimes\ud\omega_1)\\
&=f^*_0(\ud\omega_0)\wedge(f^*_1\omega_1)+(-1)^{\deg\omega_0}(f_0^*\omega_0)\wedge (f_1^*(\ud\omega_1))\\
&=\ud(f_0^*\omega_0)\wedge(f_1^*\omega_1)+(-1)^{\deg\omega_0}(f_0^*\omega_0)\wedge\ud(f_1^*\omega_1)\\
&=\ud(f_0^*\omega_0\wedge f_1^*\omega_1)=\ud f^*(\omega_0\otimes\omega_1)
\end{align*}
weakly. Consequently $f^*(\ud\tilde\omega_j)=\ud(f^*\tilde\omega_j)$ weakly. Now the pointwise convergence $f^*\tilde\omega_j\to f^*\omega$, $f^*(\ud\tilde\omega_j)\to f^*(\ud\omega)$ together with the dominated convergence theorem yield
\begin{align*}
\int_U \alpha\wedge f^*(\ud\omega)&=\lim_{j\to\infty}\int_U \alpha\wedge f^*(\ud\tilde\omega_j)=(-1)^{k+1}\lim_{j\to\infty}\int_U\ud\alpha\wedge f^*\tilde\omega_j\\
&=(-1)^{k+1}\int_U\ud\alpha\wedge f^*\omega
\end{align*}
for all $\alpha\in \Omega_c^{m-k-1}(U)$. This proves the claim. 
\end{proof}

