ref_dict.def:ct:
\begin{definition}\label{def:ct}
{\em 
Let $(X,B)$ be log Calabi--Yau pair of dimension $n$. 
We say that $(X,B)$ is of {\em cluster type}
or that $(X,B)$ is a {\em cluster type pair} if there exists an embedding 
in codimension one 
\[
\mathbb{G}_m^n \dashrightarrow X\setminus B, 
\]
i.e., there exists a closed subset of codimension at least two $Z\subset \mathbb{G}_m^n$ 
and an embedding $\mathbb{G}_m^n\setminus Z \hookrightarrow X\setminus B$.
}
\end{definition}

ref_dict.thm:manyclasses:
\begin{theorem}\label{thm:manyclasses}
    Suppose that a finitely generated group \(G\) has free abelian abelianisation.
    If \(H^2(G,\mathbb{Z})\) contains uncountably many distinguished classes which are both rich and weakly bounded, then among the corresponding central extensions of \(G\) by \(\mathbb{Z}\), there are uncountably many groups which are quasi-isometric but pairwise not isomorphic.
\end{theorem}

ref_dict.thm:largeclass:
\begin{theorem}\label{thm:largeclass}
    There exist uncountably many finitely generated pairwise non-isomorphic torsion-free groups which are all quasi-isometric.
\end{theorem}

expanded_sketch:
To prove the main theorem, the introduction indicates the following strategy: construct “central extensions with properties controlled by group cohomology”. The relevant cohomological conditions (to be defined later) are \emph{distinguished}, \emph{rich} and \emph{weakly bounded}, whose purposes are “to ensure sufficiently many extensions, the ability to tell apart isomorphism classes and to establish the quasi-isometries, respectively.” This is formalized in the following theorem.

\begin{theorem}\label{thm:manyclasses}
    Suppose that a finitely generated group \(G\) has free abelian abelianisation.
    If \(H^2(G,\mathbb{Z})\) contains uncountably many distinguished classes which are both rich and weakly bounded, then among the corresponding central extensions of \(G\) by \(\mathbb{Z}\), there are uncountably many groups which are quasi-isometric but pairwise not isomorphic.
\end{theorem}

In particular, if a finitely generated group $G$ (with free abelian abelianisation) has $H^2(G,\mathbb{Z})$ containing “uncountably many distinguished classes which are both rich and weakly bounded”, then “among the corresponding central extensions of $G$ by $\mathbb{Z}$, there are uncountably many groups which are quasi-isometric but pairwise not isomorphic,” and “these groups will all be quasi-isometric to $G\times\mathbb{Z}$.” The group $G$ used to establish the main theorem is then taken from “small-cancellation groups which are not finitely presented,” and the paper’s outline says that next one proves the theorem above, and later one exhibits a particular finitely generated group with the correct properties to deduce the statement of the main theorem.

ref_dict.prop:permutohedral:
\begin{proposition}\label{prop:permutohedral}
    Let $\bm{\chi}$ be the character of the defining representation of $\Wn$ (i.e. the action on $\C^n$). Let $\fh_i$ be the character of the action of $\Wn$ on the cosets of $\mathfrak{S}_i \times \mathfrak{W}_{n-i}$. Let $\mathbb{1}$ be the character of the trivial representation. Then 
   \[
     \lrep{\Delta}_1 = \sum_{i=1}^n \fh_i - \bm{\chi} 
    \hspace{1cm}\text{and}\hspace{1cm}
    \rrep{\Delta}_1 = \sum_{i=1}^n \fh_i - n\,\mathbb{1}.
    \]
\end{proposition}

ref_dict.def:itypes:
\begin{definition}\label{def:itypes}
Consider $S(H)$ and $i \in [n]$. We call $i$\begin{itemize}
    \item \emph{uncovered} if $\begin{cases} \{t_{i-1},t_i\} \cap S(H) = \emptyset &\text{and } i \neq n-1\text{, or} \\ \{t_{n-1},t_{n-1},t_{n}\} \cap S(H) = \emptyset &\text{and } i = n-1\end{cases}$
    \item \emph{surrounded} if $i \in [n-2]$ and $\{t_{i-1},t_i\} \cap S(H) = \{t_{i-1}\}$ and $t_m \in S(H)\text{ for some } m>i$,
    \item \emph{shaded} if $t_i \in S(H)$ or if $t_n \in S(H)$ and $i=n-1$.
\end{itemize}
\end{definition}

ref_dict.thm:character:
\begin{theorem}\label{thm:character}
    Say $\Delta \subsetneq H$. Let $\bm{\chi}$ be the character of the defining representation of $\Wn$ (i.e. the action on $\C^n$). Let $\fh_i$ be the character of the action of $\Wn$ on the cosets of $\mathfrak{S}_i\times \mathfrak{W}_{n-i}$. Let $\fs$ be the character of the action of $\Wn$ on cosets of $\mathfrak{W}_1 \times \mathfrak{W}_{n-1}$. Let $\mathbb{1}$ be the character of the trivial representation and $\bm{\delta}$ be the character $w\mapsto (-1)^{\abs{\Neg(w)}}$. Then 
    \begin{align*}
     \lrep{H}_1 = \abs{\{i \in [n] \mid i\text{ shaded}\,\}}\mathbb{1} &+ \sum_{i\text{ uncovered}} \fh_i \\[6pt]&+ \abs{\{i \in [n-2] \mid i\text{ surrounded}\,\}}\fh_1 \\[6pt]&+ \begin{cases}
    \fs &\text{if $t_n \notin S(H)$}\\
    \bm{\delta} &\text{if }\{t_{n-1},t_n\} \cap S(H) = \{t_{n}\}\\
    0 &\text{otherwise.}
\end{cases}
    \end{align*}
    and 
        \begin{align*}
     \rrep{H}_1 = \bm{\chi} &+ \sum_{i\text{ uncovered}} \left(\fh_i - \mathbb{1}\right) \\[6pt]&+ \abs{\{i \in [n-2] \mid i\text{ surrounded}\,\}}\left(\fh_1-\mathbb{1}\right) \\[6pt]&+ \begin{cases}
    \fs-\mathbb{1} &\text{if $t_n \notin S(H)$}\\
    \bm{\delta} &\text{if }\{t_{n-1},t_n\} \cap S(H) = \{t_{n}\}\\
    0 &\text{otherwise.}
\end{cases}
    \end{align*}
\end{theorem}

ref_dict.def:phi homogenization:
\begin{Definition}\label{def:phi homogenization}
Fix $\lambda = \lambda(n) > 0$ sufficiently small such that $\sigma = C_1(n)\lambda$ satisfies $4^{n+1}\sigma < c(n)$, where $C_1(n)$ is the one in Lemma \ref{lem:covering Lemma} and $c(n)$ is the one in Proposition \ref{prop:basic}. For $\Lambda\ge \max\{\Lambda_0,\Lambda_1,\Lambda_2\}$, and any nonnegative functions $v \in C(\Omega)$, we define its $\phi$-homogenization $M_{\phi,\Lambda}v(x):=M_{\phi,\lambda,\Lambda}v(x)$ in $\frac{7}{8}\Omega$ through the following maximal averaging type operator:
\begin{equation}\label{eq:phi homogenization}
\begin{split}
M_{\phi,\Lambda}v(x)=  \sup\left\{ t\in\R:\; \exists \ \check{h}(x)<h<  \hat{h}(x),\ s.t., \
\frac{\mu ( \{v> t\} \cap S_h (x)  )}{\mu(S_h (x))} > \lambda \right\}.
\end{split}
\end{equation}  
\end{Definition}

ref_dict.thm:solutions are periodic:
\begin{Theorem}\label{thm:solutions are periodic}
Let $\mu \not\equiv 0$ be a nonnegative locally finite Borel measure satisfying \eqref{eq:periodic f}, and let $u$ be a convex solution of \eqref{eq:periodic equation ma}. Then $u$ is a periodic solution in the sense of Definition \ref{def:periodic solution}.
\end{Theorem}

ref_dict.thm:uniqueness within periodic:
\begin{Theorem}\label{thm:uniqueness within periodic}
Let $\mu \not\equiv 0$ be a nonnegative locally finite Borel measure satisfying \eqref{eq:periodic f}, and let $P(x)=\frac{1}{2}x^{\top}Ax+b\cdot x+c$ be a quadratic function with $A\in \mathcal{S}_+^{n\times n}$ satisfying \eqref{eq:A compatible}. Then there exists a unique periodic solution (up to addition of constants) to \eqref{eq:periodic equation ma} with quadratic component $P$.  
\end{Theorem}

ref_dict.def:periodic solution:
\begin{Definition}[Periodic solution]\label{def:periodic solution}
A \emph{periodic solution} to \eqref{eq:periodic equation ma} is a convex function $u \in C(\mathbb{R}^n)$ satisfying \eqref{eq:periodic equation ma} in the Alexandrov sense, and can be decomposed as
\begin{equation}\label{eq:periodic solution}
u(x) = v(x) +P(x),
\end{equation}
where $v$ is periodic  with respect to  $\mathbb{Z}^n$ and  $P(x)=\frac{1}{2}x^{\top}Ax+b\cdot x+c$ is a quadratic function with $A\in \mathcal{S}_+^{n\times n}$, $b\in\R^n$ and $c\in\R$.  
\end{Definition}

ref_dict.thm:harnack super:
\begin{Theorem}\label{thm:harnack super} 
Assume that $v \in C^2(\Omega)$ is a nonnegative supersolution of \eqref{eq:linearized ma phi} in $\Omega$.
Then there exist positive constants  $\Lambda_6(n)$, $\epsilon(n) $ and $C(n) $ such that if 
\[
\inf_{B_{1/4}} v \leq 1,
