\begin{abstract}
 Consider a continuous bundle $\mathcal{E}\to X$ of Banach/Hilbert spaces or Banach/$C^*$-algebras over a paracompact base space, equivariant for a compact Lie group $\mathbb{U}$ operating on all structures involved. We prove that in all cases homogeneous equivariant subbundles extend equivariantly from $\mathbb{U}$-invariant closed subsets of $X$ to closed invariant neighborhoods thereof (provided the fibers are semisimple in the Banach-algebra variant). This extends a number of results in the literature (due to Fell for non-equivariant local extensibility around a single point for $C^*$-algebras and the author for semisimple Banach algebras). The proofs are based in part on auxiliary results on (a) the extensibility of equivariant compact-Lie-group principal bundles locally around invariant closed subsets of paracompact spaces, as a consequence of equivariant-bundle classifying spaces being absolute neighborhood extensors in the relevant setting and (b) an equivariant-bundle version of Johnson's approximability of almost-multiplicative maps from finite-dimensional semisimple Banach algebras with Banach morphisms. 
\end{abstract}

To proceed to an outline of the paper's contents, the first extensibility result considered below reads as follows.

The multiplicative counterpart to \Cref{th:prlng.homog.bdls} is as follows.

\begin{theorem}\label{th:prlng.homog.abdls}
 \begin{enumerate}[(1),wide]
 \item\label{item:th:prlng.homog.abdls:ban} Let $\bU$ be a compact Lie group, $\cA\xrightarrowdbl{\hspace{0pt}} X$ a continuous (unital) Banach-algebra bundle$_{\bU}$ over a paracompact base space, $Z\subseteq X$ a closed $\bU$-subset, and $\cB\le \cA|_Z$ a locally-trivial algebra subbundle$_{\bU}$ with finite-dimensional semisimple fibers.

The proofs of \Cref{th:prlng.homog.bdls,th:prlng.homog.abdls} rely on a few technical asides presumably of some interest in their own right:
\begin{enumerate}[(a),wide]
\item\label{item:intro.equiv.bdls} There is, first, the ability to extend $\bU$-equivariant principal $\bG$-bundles locally around $\bU$-invariant closed subspaces $Z\subseteq X$ of paracompact $\bU$-spaces. This forms the object of \Cref{pr:princ.bdl.ext}, and is reminiscent of familiar results on he extensibility of (bundle or sheaf) \emph{sections} from closed subspaces: \cite[Theorem I.5.10]{kar_k_1978}, \cite[Th\'eor\`eme 3.3.1]{god_faisc_1958}, \cite[Proposition 1.1]{seg}, etc.

\item whereupon we can average against the Haar probability measure of $\bU$ to obtain a $\bU$-equivariant morphism $\cG\to \cE$ agreeing with the original embedding over $Z$ (much as in \cite[Proposition 1.1]{seg}, for instance). 
 \end{itemize}
 Such an extension will still be an embedding
 \begin{equation*}
 \cG|_W
 \lhook\joinrel\xrightarrow{\quad \iota\quad}
 \cE|_W
 ,\quad
 \text{closed neighborhood }W\supseteq Z,
 \end{equation*}
 providing the desired \emph{Banach} bundle. In the more rigid setup of Hilbert bundles, an additional step will replace $\iota$ with the isometric component $\iota_{\mathrm{iso}}$ in the \emph{polar decomposition} \cite[\S I.5.2.2]{blk} $\iota=\iota_{\mathrm{iso}}|\iota|$.
\end{th:prlng.homog.bdls}

\begin{remarks}\label{res:gen.triv}
 \begin{enumerate}[(1),wide]
 \item For $\bU=\{1\}$ and \emph{trivial} (rather than locally trivial) $\cF$ \Cref{th:prlng.homog.bdls} reflects the fact (e.g. \cite[Corollary 2.10]{laz_bb-sel} or \cite[p.15]{dg_ban-bdl}) that bounded sections of (even (H), rather than (F)) Banach bundles extend from closed subsets of paracompact base spaces:
 \begin{itemize}[wide]
 \item having selected $n$ sections witnessing triviality across all of $Z$;

\begin{enumerate}[label={},wide]
 \item\textbf{\Cref{item:th:prlng.homog.abdls:ban}} In first instance, \Cref{pr:princ.bdl.ext} applied the automorphism group $\bG$ of some finite-dimensional $C^*$-algebra, i.e. a semidirect product of the form
 \begin{equation*}
 \left(\prod_{i=1}^k PU(n_i)\right)\rtimes \left(\text{finite group}\right),
 \end{equation*}
 will extend $\cB$ over a closed neighborhood (so we may as well assume globally) to a locally-trivial, $B$-fibered bundle$_{\bU}$ $\cM\xrightarrowdbl{\hspace{0pt}}X$ with $\cM|_A\cong \cB$. Precisely as in the proof of \Cref{th:prlng.homog.bdls}, we have a $\bU$-equivariant embedding
 \begin{equation*}
 \cM|_{W}
 \lhook\joinrel\xrightarrow{\quad\iota\quad}
 \cA|_W
 ,\quad
 \text{some closed neighborhood }W\supseteq Z
 \end{equation*}
 of \emph{vector} bundles, (unital and) multiplicative over $Z$. As a matter of convenience, a slight perturbation
 \begin{equation*}
 \iota
 \xmapsto{\quad}
 \bigg(
 \cM_x\ni a
 \xmapsto{\quad}
 \iota(a)+1_{\cA_x}-\iota\left(1_{\cM_x}\right)
 \in \cA_x
 \bigg)
 ,\quad
 x\in W
 \end{equation*}
 over sufficiently small $W$ followed by averaging over $\bU$ will further ensure $\iota$ is unital throughout $W$ (observe that this process will not have altered $\iota$ over the original smaller subspace $Z\subseteq X$).

\begin{proposition}\label{pr:princ.bdl.ext}
  Consider
  \begin{itemize}[wide]
  \item a compact Lie group $\bU$ acting via $\alpha:\bU\circlearrowright \bG$ on another;

  \item a closed $\bU$-equivariant embedding $Z\subseteq X$ into a paracompact $\bU$-space;

  \item and a principal $\bG$-bundle$_{\alpha}$ $\cP\xrightarrowdbl{\pi}Z$.
  \end{itemize}
  For some closed $\bU$-neighborhood $W\supseteq Z$ there is a principal $\bG$-bundle$_{\alpha}$ $\wt{\cP}\xrightarrowdbl{\hspace{0pt}}W$ with $\wt{\cP}|_Z\cong \cP$. 
\end{proposition}

\begin{theorem}\label{th:prlng.homog.bdls}
  \begin{enumerate}[(1),wide]
  \item Let $\bU$ be a compact Lie group, $\cE\xrightarrowdbl{\hspace{0pt}} X$ a continuous Banach bundle$_{\bU}$ over a paracompact base space, $Z\subseteq X$ a closed $\bU$-subset, and $\cF\le \cE|_Z$ a locally-trivial $n$-homogeneous subbundle$_{\bU}$.

    There are
    \begin{itemize}[wide]
    \item a closed $\bU$-invariant neighborhood $W\supseteq Z$ in $X$;

    \item and a locally-trivial $n$-homogeneous subbundle$_{\bU}$ $\wt{\cF}\xrightarrowdbl{\hspace{0pt}} W$ of $\cE|_W$;

    \item with $\wt{\cF}|_Z=\cF$. 
    \end{itemize}

  \item The analogous result holds also for continuous Hilbert bundles$_{\bU}$. 
  \end{enumerate}  
\end{theorem}

post_theorem_intro_text:
The multiplicative counterpart to \Cref{th:prlng.homog.bdls} is as follows. 

\begin{theorem}\label{th:prlng.homog.abdls}
  \begin{enumerate}[(1),wide]
  \item\label{item:th:prlng.homog.abdls:ban} Let $\bU$ be a compact Lie group, $\cA\xrightarrowdbl{\hspace{0pt}} X$ a continuous (unital) Banach-algebra bundle$_{\bU}$ over a paracompact base space, $Z\subseteq X$ a closed $\bU$-subset, and $\cB\le \cA|_Z$ a locally-trivial algebra subbundle$_{\bU}$ with finite-dimensional semisimple fibers.

    There are
    \begin{itemize}[wide]
    \item a closed $\bU$-invariant neighborhood $W\supseteq Z$ in $X$;

    \item and a locally-trivial subbundle$_{\bU}$ $\wt{\cB}\xrightarrowdbl{\hspace{0pt}} W$ of $\cA|_W$;

    \item with $\wt{\cB}|_Z=\cB$. 
    \end{itemize}

  \item\label{item:th:prlng.homog.abdls:cast} The analogous result holds also for continuous $C^*$ bundles$_{\bU}$. 
  \end{enumerate}  
\end{theorem}

\Cref{th:prlng.homog.abdls} generalizes \cite[Theorem 3.1]{fell_struct} (in the $C^*$ setting) and \cite[Proposition 2.8]{2409.03531v2} (for both $C^*$ and Banach-algebra bundles) by allowing equivariance and extensibility locally around arbitrary ($\bU$-invariant) closed subsets rather than single points. 

The proofs of \Cref{th:prlng.homog.bdls,th:prlng.homog.abdls} rely on a few technical asides presumably of some interest in their own right:
\begin{enumerate}[(a),wide]
\item\label{item:intro.equiv.bdls} There is, first, the ability to extend $\bU$-equivariant principal $\bG$-bundles locally around $\bU$-invariant closed subspaces $Z\subseteq X$ of paracompact $\bU$-spaces. This forms the object of \Cref{pr:princ.bdl.ext}, and is reminiscent of familiar results on he extensibility of (bundle or sheaf) \emph{sections} from closed subspaces: \cite[Theorem I.5.10]{kar_k_1978}, \cite[Th\'eor\`eme 3.3.1]{god_faisc_1958}, \cite[Proposition 1.1]{seg}, etc.

\item\label{item:intro.amnm} Secondly, in order to leverage the ``purely-linear'' \Cref{th:prlng.homog.bdls} into the ``multiplicative'' \Cref{th:prlng.homog.abdls}, we employ an equivariant bundle version of Johnson's principle \cite[Theorem 3.1, Corollary 3.2, Theorem 7.2]{john_approx} that almost-multiplicative linear ($*$-)maps from semisimple finite-dimensional Banach/$C^*$-algebras into arbitrary Banach/$C^*$-algebras are close to morphisms in the apposite category. This is one instance of what has since come to be termed \emph{Hyers-Ulam-Rassias stability} \cite[Introduction]{jung_hur-stab} and the family-wide, equivariant adaptation of Johnson's arguments can be regarded as fitting in that broad framework. 
\end{enumerate}

In reference to item \Cref{item:intro.equiv.bdls} above it becomes topical to contrast the various topologies one typically equips the total space of the \emph{(Milnor-model) universal bundle} $E\bG$ \cite[Definition 7.2.7]{hjjm_bdle} of a(n always Hausdorff) topological group. \Cref{se:colim.top} revolves around that issue:
\begin{itemize}[wide]
\item \Cref{th:disc.cone} observes that the principal action $E\bG\times \bG\to E\bG$ is discontinuous for the colimit topology on $E\bG$ whenever, say, $\bG\times -$ fails to preserve the topological quotient
  \begin{equation*}
    \bG\times [0,1]
    \xrightarrowdbl{\quad}
    \text{\emph{cone} }
    \cC \bG:=\bG\times [0,1]\big/\bG\times \{0\}.
  \end{equation*}
  Indeed, such groups fail to act continuously even on the truncated total space
  \begin{equation*}
    E_1\bG=\bG*\bG
    \underset{\text{closed}}{\subseteq}
    E\bG,
  \end{equation*}
  with `*' denoting the \emph{topological join} \cite[p.9]{hatch_at} recalled in \Cref{eq:x.ast.y}. As simple a group as $(\bQ,+)$ will exhibit this behavior: \Cref{pr:q.discont.act.join}.

\item while \Cref{th:lb.cc} notes that by contrast, a group with \emph{countably-compact} power $\bG^n$ always acts continuously on its colimit-topologized truncated universal space $E_n \bG=\bG^{*(n+1)}$. 
\end{itemize}

