 $H^2_{rd} \hookrightarrow\hookrightarrow L^q$ is compact for every $q\in(2,\frac{2N}{N-4})$ if $N\geq5$ and every $2<q<\infty$ if $N\leq4$;
\item
for any $u\in H^1_{rd}$ and any $\frac12\leq s<1$, holds

\begin{align}\label{frcs}
\sup_{x\in\mathbb{R}^N}|x|^{\frac{N-2s}2}|u(x)|\leq C_{N,s}\|u\|^{1-s}\|\nabla v\|^s.\end{align}
\item
for any $\frac12< s<\frac N2$ and any $u\in\dot H^s_{rd}$, holds

\begin{align}\label{frcs'}
\sup_{x\in\mathbb{R}^N}|x|^{\frac{N-2s}2}|u(x)|\leq C_{N,s}\||\nabla|^s u\|.\end{align}
\end{enumerate}
\end{lem}

Finally, we give a helpful compact Sobolev embedding, proved in the appendix.

\begin{lem}\label{compact}
Let $N\geq1$ and $b\geq0$ and $2<1+q-\frac{2b}{N-1}<2+\frac{8}{N-4}$, where $\frac{1}{N-4}=\infty$, for $1\leq N\leq4$. Thus, the next injection is compact
$$H^2_{rd}\hookrightarrow\hookrightarrow L^{1+q}(|x|^{b}\,dx).$$
\end{lem}

The rest of this paper is organized as follows. Section \ref{sec3} proves the Gagliardo-Nirenberg type estimate in Theorem \ref{gag2}. Section \ref{sec4} establishes the global/non-global existence of energy solutions stated in Theorem \ref{glb}.

