expanded_theorem:
\label{gag}
Let $N\geq2$, $b>0$ and $1+\frac{2b}{N-1}< q< q^e$. Thus, 
\begin{enumerate}
\item
there exists a sharp constant $\texttt{C}_{opt}>0$, such that for all $v\in H^2_{rd}$,

\begin{align}
\int_{\mathbb{R}^N}|v|^{1+q}|x|^{b}\,dx\leq \texttt{C}_{opt}\|v\|^E\|\Delta v\|^D;    \label{gag2}
\end{align}
\item
there exists $\zeta\in H^2_{rd}$ a minimizing of the problem

$$\frac1{\texttt{C}_{opt}}=\inf_{0\neq v\in H^2_{rd}}\frac{\|v\|^E\|\Delta v\|^D}{\int_{\mathbb{R}^N}|v|^{1+q}|x|^{b}\,dx},$$
 such that  \begin{align}\label{grnd}
\zeta+\Delta^2\zeta-|x|^{b}|\zeta|^{q-1}\zeta=0,\quad0\neq \zeta\in H^2_{rd};
\end{align}
\item
moreover,
\begin{align}\label{part32}
\texttt{C}_{opt}=\frac{1+q}E\big(\frac ED\big)^{\frac{D}2}\|\zeta\|^{-(q-1)};
\end{align}
\item
furthermore, the next Pohozaev identities holds

\begin{align}\label{poh}
\int_{\mathbb{R}^N}|\zeta|^{1+q}|x|^b\,dx=\frac{1+q}{E}\,\texttt{M}(\zeta)=\frac{1+q}{D}\|\Delta\zeta\|^2.
\end{align}
\end{enumerate}

theorem.content:
\label{thm_main}
Let $M$ be a closed topological manifold of dimension $2n$ and let $b = \dim H^2(M,\mathbb{C})$.

Then there exist non-zero elements $e_1,\ldots,e_q \in H^2(M,\mathbb{C})$ with $q \leq b+1$ such that if $X$ is a smooth complex projective variety of dimension $n$ with underlying topological space $M$ and $f\colon X \to Y$ is a divisorial contraction to a point with exceptional divisor $E$, then there exists $i \in \{1, \dots, q\}$ such that $[E] = e_i$.

ref_dict.thm:W_F:
\begin{theorem}\label{thm:W_F}
Let $F \in \C[x_0, x_1, \ldots,x_b]$ be a form of degree $n \ge 3$. 
\begin{enumerate}
\item If $F$ is honest, then $W_F \cap \{F \ne 0\}$ is a finite set, and more precisely, 
$$
|W_F  \cap \{F \ne 0\} | \le b+1.
$$

\item If $F$ is non-degenerate, then $W_F$ is a finite set.
\end{enumerate}
\end{theorem}

