\label{thm:sos}
		For $f\in\cA_{2d}$ the following are equivalent:
		\begin{enumerate}[\rm(i)]\itemsep=5pt
			\item \label{i:sos:i}
			For any Hilbert space $\mathcal{K}$ and any tuple of self-adjoint operators $Y = (Y_{1}, \dots, Y_{\vg})\in\mathcal{B}(\mathcal{K})^\vg$, $f(Y)\succeq0$;
			\item \label{i:sos:ii}
			For any $n\in\mathbb N$ and any tuple of self-adjoint matrices 
			$Y = (Y_{1}, \dots, Y_{\vg})\in M_n(\mathbb C)^\vg$, $f(Y)\succeq0$;
			\item \label{i:sos:iii}
			There exist $r_1,\ldots,r_{N(d)}\in\cA_d$ s.t.
			\begin{equation}\label{eq:sosthm}
				f \ =\ \sum_{i=1}^{N(d)} r_i^*r_i.
			\end{equation}
		\end{enumerate}

		\noindent If $\mathcal{H}$ is infinite-dimensional, then the above statements are also equivalent to
		\begin{enumerate}[label=\textup{(\roman*)}, resume]\itemsep=5pt
			\item \label{i:sos:iv}
			There exists $r\in\cA_d$ s.t.
			\begin{equation}\label{eq:1sosthm}
				f \ =\ r^*r.
			\end{equation}

		\end{enumerate}

