\section{Construction of free boundary disks in \texorpdfstring{$\mathbb{B}^3$}{}}\label{sec:2}
We will introduce a method to construct a free boundary immersion $\psi(u,v)$ of a disk in the unit ball $\mathbb{B}^3 \subset \mathbb{R}^3$ in terms of a certain ribbon-shaped planar curve $\gamma(u)$, which we describe next. In what follows, let $\mathbb{D}^2 = \mathbb{B}^3 \cap \{x_3 = 0\}$ denote the horizontal unit disk in $\mathbb{B}^3$.

\begin{remark}
 There exist infinitely many $\mathcal{C}^\infty$ curves in $\mathbb{D}^2$ satisfying the properties listed above. However, none of these curves is analytic.
\end{remark}

\begin{proposition}\label{pro:psiFB}
 Let $\gamma(u)$ be a ribbon and $\psi_\gamma(u,v)$ be the corresponding immersion in Definition \ref{def:psigamma}. Then, $\Sigma_\gamma$ is a free boundary disk in $\mathbb{B}^3$.
\end{proposition}
\begin{proof}
 We may decompose $\Sigma_\gamma$ into three parts, namely
 \begin{equation}\label{eq:Sigma123}
 \begin{aligned}
 \Sigma_{\gamma}^{(1)} &:= \psi_\gamma\left(\mathcal{D} \cap \{u \leq -u_2\}\right), \\
 \Sigma_{\gamma}^{(2)} &:= \psi_\gamma\left(\mathcal{D} \cap \{-u_2 < u < u_2\}\right), \\
 \Sigma_{\gamma}^{(3)} &:= \psi_\gamma\left(\mathcal{D} \cap \{u \geq u_2\}\right),
 \end{aligned}
 \end{equation}
 respectively. It is clear that $\Sigma_{\gamma}^{(1)}$ and $\Sigma_{\gamma}^{(3)}$ are pieces of equatorial disks, so they meet $\partial \mathbb{B}^3$ orthogonally; see Definition \ref{def:ribbon}. We also note that the piece $\Sigma_{\gamma}^{(2)}$ intersects $\partial \mathbb{B}^3$ along the curves $u \mapsto \psi_{\gamma}(u,\pm v_{\gamma(u)})$, $u \in (-u_2,u_2)$. For every $u_0 \in (-u_2,u_2)$, the circle $v \mapsto \psi_\gamma(u_0,v) = c_{\gamma(u_0)}(v)$ meets $\partial \mathbb{B}^3$ orthogonally; see Definition \ref{def:cpv}. Thus, $\Sigma_{\gamma}^{(2)}$ meets $\partial \mathbb{B}^3$ orthogonally, as we wanted to show.
\end{proof}

\subsection*{Proof of Theorem \ref{thm:main}}
Let $\gamma(u)$ be any ribbon and consider the family of ribbons $\gamma_t$ in Definition \ref{def:gammat}. According to Propositions \ref{pro:curvaturapositiva} and \ref{pro:curvaturanegativa}, for sufficiently small values of $t$, the corresponding disks $\Sigma_{\gamma_t} \subset \mathbb{B}^3$ are saddle. Moreover, by Proposition \ref{pro:psiFB}, they are free boundary in $\mathbb{B}^3$. This completes the proof of Theorem \ref{thm:main}.

\begin{definition}\label{def:ribbon}
    Let $\gamma$ be a planar regular curve in $\mathbb{D}^2$. We say that $\gamma$ is a {\em ribbon} if, up to an isometry, it admits a parametrization $\gamma(u):[-u_3,u_3] \to \mathbb{D}^2$, where $u$ is the arc-length parameter, satisfying the following properties:
    \begin{enumerate}
    \item $\Psi(\gamma(u)) = \gamma(-u)$, where $\Psi$ denotes the symmetry with respect to the line $\{x = y \}$. In particular, $\gamma(0)$ belongs to this line.
    \item There exist $a \in (0,1)$ and $u_2 \geq 0$ such that, on the interval $[u_2,u_3]$, $\gamma(u)$ parametrizes the segment $\{0\}\times [-1,a] \times \{0\}$, with $\gamma(u_3) = (0,-1,0)$. In particular, $u_2 = u_3 - (1+a) > 0.$ Consequently, on the interval $[-u_3,-u_2]$, $\gamma(u)$ parametrizes the segment $[-1,a]\times \{0\} \times \{0\}$, and $\gamma(-u_3) = (-1,0,0)$.
