\begin{defi}\label{defiC} A coefficient of normal restitution $\re \: :\: r \mapsto \re(r) \in (0,1]$ belongs to the class~$\mathcal{R}_0$ if it satisfies the following:
\begin{enumerate}
\item The mapping  $r \in \mathbb{R}^{+} \longmapsto \re(r) \in (0,1]$ is  {differentiable} and non-increasing.
\item The mapping $r\in\mathbb{R}^{+}\longmapsto \eta_{\re}(r):=r\,\re(r )$ is strictly increasing.
\item $\lim_{r \to \infty} \re(r)=\re_0 \in [0,1)$.
\end{enumerate}
Moreover, for a given $\gamma > 0$ we say that $\re(\cdot)$ belongs to the class $\mathcal{R}_\gamma$ if it belongs to $\mathcal{R}_0$ and there exist positive $\mathfrak{a}_0$, $\mathfrak{b}_0$, and $\overline{\g}>\frac{3}{2}\g$ such that for any $r\geq0$, 
\begin{equation}\label{gamma0bis}
|\re(r)-1+\mathfrak{a}_{0}r^{\g}| \leq \mathfrak{b}_{0} r^{\overline{\g}}\,.\end{equation}
In addition, we assume that there exist $\alpha >0$ and $m \in (0,1)$ such that for any $r \geq 0$, 
\begin{equation}\label{eq:Je-e}
\frac{\d}{\d r} \eta_{\re}(r) \gtrsim \re(r)^\alpha\,,  \qquad  \qquad \left|{\frac{\d}{\d r} \eta_{\re}(r)}-\re(r)\right| \lesssim |1-\re(r)|\,,
\end{equation}
and 
\begin{equation}\label{eq:Je-e1}
\limsup_{z\to\infty}z^{-m}\eta_{\re}^{-1}(z)\lesssim 1\,. \end{equation}
\end{defi}

