\subsection{Previous Results}

The 2-dimensional case of the LYZ equation was solved by Jacob-Yau \cite{jacobyau2017},
who also obtained partial results in higher dimensions. Collins-Jacob-Yau \cite{cjy2020} then solved the supercritical case under the assumption of a subsolution $\underline{u}$ and an additional condition $\theta_{\omega}(\chi_{\underline{u}})>(n-2)\frac{\pi}{2}$. The authors \cite{fyz2024} introduced a geometric flow to solve the equation under the same conditions. The extra condition was
subsequently removed by Pingali \cite{Pingali2022APDE} for $n=3$, by Lin \cite{lin2023adv} for $n=3,4$, and finally
by Lin \cite{lin2023} in full generality. 
An alternative proof, based on Chen's significant result \cite{Chen2021Invent}, was given by Sun \cite{sun2024}.
For further recent developments, we refer to
\cite{ChanJacob2023arxiv, ChuCollinsLee2021GT,ChuLee2023Crelle, clt2024jdg, CollinsXieYau2018,CollinsYau2021APDE,HanJin2021CVPDE,HanJin2023Tran,HanJin2024Manu,HuangZhangZhang2022SCM,Jacob2021PAMQ, jacob2022arxiv,JacobSheu2022AsianJM,KhalidDyrefelt2024imrn,Lin2024MRL,Takahashi2021ijm}.

\subsection{Our main results}
Collins-Jacob-Yau \cite{cjy2020} suggested studying the LYZ equation when $\theta\le (n-2)\frac{\pi}{2}$. This was later explicitly posed as a question by Li \cite{YangLi2022arxiv}, as resolving it is essential for the LYZ equation to induce a Bridgeland stability condition on $D^b \text{Coh}(M)$, the bounded derived category of coherent sheaves on $M$.

In this paper, we solve the critical case; that is, 
we establish the existence of smooth solutions for the \textit{critical} LYZ equation:
\begin{align}\label{LYZ1}
\theta_{\omega}(\chi_u)=(n-2)\frac{\pi}{2}.
\end{align}
In this case, the principal argument of $\int_{M}(\chi+\sqrt{-1} \omega)^n$ is $\pi$,
and the subsolution condition becomes
\begin{align}\label{subsolution}
 \min\limits_{1\le j\le n}\sum\limits_{\substack{i=1 \\ i\neq j}}^n\mathrm{arctan}\lambda_i(\chi_{\underline {u}})>{(n-3)\frac \pi 2}.
\end{align}

\begin{equation}\label{LYZ2}
 	\begin{aligned}
 		\theta_{\omega}(\chi_u)=\theta
 	\end{aligned}
 \end{equation}

\begin{equation}\label{LYZe}
 	\begin{aligned}
 		\mathrm{Im}\big(e^{-\sqrt{-1}\hat\theta}(\chi_u+\sqrt{-1}\omega)^n\big)=0.
 	\end{aligned}
 \end{equation}

\begin{align}\label{subsolution}
	\min\limits_{1\le j\le n}\sum\limits_{\substack{i=1 \\ i\neq j}}^n\mathrm{arctan}\lambda_i(\chi_{\underline {u}})>{(n-3)\frac \pi 2}.
\end{align}

Let $(M,\omega)$ be a compact K\"ahler manifold and $\chi$ a closed real $(1,1)$-form. 
Suppose that $\mathcal{Z}=\int_{M}(\chi+\sqrt{-1}\omega)^n\neq 0$ and let $\hat\theta$ be the principal argument of $\mathcal{Z}$.
 The LYZ equation seeks a smooth function $u: M\rightarrow\mathbb{R}$ such that
 \begin{equation}\label{LYZe}
 \begin{aligned}
 \mathrm{Im}\big(e^{-\sqrt{-1}\hat\theta}(\chi_u+\sqrt{-1}\omega)^n\big)=0.
 \end{aligned}
 \end{equation}
 Let $\lambda=(\lambda_1,\cdots,\lambda_n)$ be the eigenvalues of $\chi_u$ with respect to $\omega$ and define the special Lagrangian operator as 
\[
\theta_{\omega}(\chi_u):=\sum\limits_{i=1}^n\arctan \lambda_i.
\]
 Then equation (\ref{LYZe}) can be rewritten in the form
 \begin{equation}\label{LYZ2}
 \begin{aligned}
 \theta_{\omega}(\chi_u)=\theta
 \end{aligned}
 \end{equation}
 where $\theta=n\frac{\pi}{2}-\hat \theta$. We refer to (\ref{LYZ2}) as the \emph{supercritical} LYZ equation if $\theta\in\big( (n-2)\frac{\pi}{2}, n\frac{\pi}{2}\big)$, and as the \emph{critical} LYZ equation if $\theta=(n-2)\frac{\pi}{2}$, i.e., $\hat \theta=\pi$.

In this paper, we solve the critical case; that is, 
we establish the existence of smooth solutions for the \textit{critical} LYZ equation:
\begin{align}\label{LYZ1}
\theta_{\omega}(\chi_u)=(n-2)\frac{\pi}{2}.
\end{align}
In this case, the principal argument of $\int_{M}(\chi+\sqrt{-1} \omega)^n$ is $\pi$,
and the subsolution condition becomes
\begin{align}\label{subsolution}
 \min\limits_{1\le j\le n}\sum\limits_{\substack{i=1 \\ i\neq j}}^n\mathrm{arctan}\lambda_i(\chi_{\underline {u}})>{(n-3)\frac \pi 2}.
\end{align}

\begin{remark}
For the special Lagrangian equation in $\mathbb{R}^n$, interior Hessian estimates for critical and supercritical cases were proved by
Warren-Yuan \cite{WarrenYuan2010} and Wang-Yuan \cite{WangYuan2014}. 
For $\theta<(n-2)\frac{\pi}{2}$, 
$C^{1,\alpha}$ solutions were constructed by Nadirashvili-Vl\u{a}du{t} \cite{NV2010IHP} and Wang-Yuan \cite{wangyuan2013ajm}. Very recently, Mooney-Savin \cite{mooneysavin2023duke} obtained a Lipschitz solution that is not $C^1$. 
\end{remark}

To solve the critical LYZ equation \eqref{LYZ1}, 
we consider the family of equations: 
\begin{align}\label{LYZt}
 \theta_{\omega}(\chi_{u^{t}}+t\omega)=\theta(t).
\end{align}
We verify that there exists a uniform constant $C>0$ such that 
$$\theta(t)\in ((n-2)\frac{\pi}{2}+Ct,
(n-2)\frac{\pi}{2}+2Ct)$$ for small $t>0$ (see Lemma \ref{thetatrange} in Section 2). Hence equations \eqref{LYZt} are the supercritical LYZ equations. Then we prove the subsolution $\underline{u}$ of the critical LYZ equation \eqref{LYZ1} is also a subsolution of equations \eqref{LYZt} for small $t>0$. Thus we can apply Lin's result \cite{lin2023} (see also Sun \cite{sun2024} ) to obtain the smooth solution $u^t$ to equation \eqref{LYZt} with $\sup_M u^{t}=0$.

When $n=4$, the critical LYZ equation is the Hessian quotient equation
$$
\sigma_3(\chi_u)=\sigma_1(\chi_u).
$$ 
Another consequence of our result is to solve the above Hessian quotient equation in dimension 4 under weaker conditions than those by Sun \cite{sun2017cpam} and Sz\'{e}kelyhidi \cite{szek2018}.
 \begin{corollary}\label{4dHQ}
 Let $(M, \omega)$ be a compact K\"ahler manifold with dimension $n=4$.
 Let $\chi$ be a closed real $(1,1)$-form satisfying $3\chi^2\wedge\omega-\omega^3>0\ \text{as a positive $(3,3)$-form}$ and
 \begin{align*}
 \int_M\chi^3\wedge\omega=&\int_M\chi\wedge\omega^3,\\
 \int_M\chi\wedge\omega^{3}>&0,\ 
 \mathrm{Re}\int_M (\chi+\sqrt{-1}\omega)^4<0.\label{4dRe}\notag
 \end{align*}
 Then there exists a unique 
 smooth function $u$ solving 
 \begin{align}
 \sigma_3(\chi_u)=\sigma_1(\chi_u),\\
 \chi_u\in \Gamma_3(M), \ \sup_{M} u=0.\notag
 \end{align}
\end{corollary}

\subsection{$C^0$-estimates}
Let $\hat \theta(t)$ denote the principal argument of the complex number $\int_M (\chi + t\omega + \sqrt{-1}\omega)^n$, and set $\theta(t) = (n-2)\frac{\pi}{2} - \hat \theta(t)$. We first show that $\hat \theta(t)$ is close to $\pi$ when $t>0$ is sufficiently small.
\begin{lemma}\label{thetatrange}
 Assume that $\underline u$ is a subsolution of the critical LYZ equation \eqref{LYZ1}. Then there exist uniform positive constants $t_0$ and $C$, depending only on $\chi$ and $\omega$, such that for all $t \in (0, t_0)$,
 \[
 \hat \theta(t) \in \bigl( \pi - 2Ct,\; \pi - Ct \bigr).
 \]
\end{lemma}

\begin{theorem}\label{thm: Hessian estimate}
 Let $\underline{u}$ be a subsolution of the critical LYZ equation \eqref{LYZ1} and let $u^t$ be the solution of the LYZ equation \eqref{LYZt} with $\sup_M u^t = 0$. 
 Then there exist uniform positive constants $t_0$ and $C$, independent of $\bigl(\theta(t)-(n-2)\frac{\pi}{2}\bigr)^{-1}$, such that for any $t \in (0, t_0)$,
 \begin{align}\label{eq: Hessian estimate}
 \sup_M |\sqrt{-1}\partial\bar{\partial} u^t|_{\omega} \le C \bigl(1 + \sup_M |\nabla u^t|_{\omega}^2 \bigr).
 \end{align}
\end{theorem}

We consider a family of LYZ equations \eqref{LYZt} 
 \begin{align*}
 3(\chi+t\omega+\sqrt{-1}\partial\bar\partial u^t)^2\wedge\omega=&
 \tan\hat\theta(t)(\chi+t\omega+\sqrt{-1}\partial\bar\partial u^t)^3\\
 &-3\tan\hat\theta(t)(\chi+t\omega+\sqrt{-1}\partial\bar\partial u^t)\wedge\omega^2+\omega^3.
 \end{align*}
 As a corollary of our theorem, we solve the 2-Hessian equation under weaker conditions instead of the usual condition $\chi\in \Gamma_2(M)$.
 \begin{corollary}
 Let $(M,\omega)$ be a compact K\"ahler manifold with dimension $n=3$ and $\chi$ be a real $(1,1)$-form satisfying the following conditions:
 \begin{enumerate}[(i)]
 \item
 $3\int_M\chi^2\wedge\omega=\int_M\omega^3$,
 $\int_M\chi^3<3\int_M \chi\wedge\omega^2\label{re<0}$;
 \item
 the subsolution condition
 \begin{align}
 \chi\wedge\omega>0\ \ \text{as a $(2,2)$-form}.
 \end{align}
 \end{enumerate}
 Then there exists a unique smooth solution $u$ solving
 \begin{align}
 \sigma_2(\chi_u)=1,
 \\ \chi_u\in \Gamma_{2}(M), \ \sup_M u=0.
 \end{align}
 \end{corollary}

\begin{equation}\label{LYZ2}
 	\begin{aligned}
 		\theta_{\omega}(\chi_u)=\theta
 	\end{aligned}
 \end{equation}

\begin{equation}\label{LYZe}
 	\begin{aligned}
 		\mathrm{Im}\big(e^{-\sqrt{-1}\hat\theta}(\chi_u+\sqrt{-1}\omega)^n\big)=0.
 	\end{aligned}
 \end{equation}

\begin{align}\label{LYZt}
	\theta_{\omega}(\chi_{u^{t}}+t\omega)=\theta(t).
\end{align}

\begin{align}\label{subsolution}
	\min\limits_{1\le j\le n}\sum\limits_{\substack{i=1 \\ i\neq j}}^n\mathrm{arctan}\lambda_i(\chi_{\underline {u}})>{(n-3)\frac \pi 2}.
\end{align}

\begin{lemma}\label{thetatrange}
    Assume that $\underline u$ is a subsolution of the critical LYZ equation \eqref{LYZ1}. Then there exist uniform positive constants $t_0$ and $C$, depending only on $\chi$ and $\omega$, such that for all $t \in (0, t_0)$,
