\end{equation}
Then, he obtained the well-posedness of cubic fractional Schr\"odinger equation for $s>\frac{d-1}{2}$.

Now, we prove an observability inequality uniform with respect to the potential for solutions at high frequency.
 \begin{proposition}
 Let $T>0$, $M>0$, $d\in\mathbb{N}$ and $s>\frac{d}{2}$ be fixed. Let $\omega$ be an open set satisfying the GCC and let $\mathcal{C}u=b_{\omega}u$. Then there exist $n_{0}\in\mathbb{N}$ and $C>0$ such that for any $V_{1}$, $V_{2}\in \mathcal{B}_{M}^{[0,T]}(H^{s}(M))$ and $n\geq n_0$, the following observability inequality holds
 \begin{equation}
 \|w_{0}\|_{H^{s}}^{2}\leq C\int_{0}^{T}\|\mathcal{C}w(t)\|_{H^{s}}^{2}\,\dd t
 \end{equation}
 for any $w_0\in\mathcal{Q}_{n}H^{s}(M)$, where $w\in C^{0}([0,T],\mathcal{Q}_{n}H^{s}(M))$ is solution to 
 \begin{equation}\label{fourth order with potential}
 \begin{cases}
 i\partial_{t}w+\Delta_{g}^{2}w-\beta\Delta_{g}w=\mathcal{Q}_{n}(V_{1}w+V_{2}\bar{w}),&(t,x)\in (0,T)\times M,\\ w(0)=w_{0},& x\in M.
 \end{cases}
 \end{equation}
 \end{proposition}
 \begin{proof}
 We proceed by contradiction. Suppose, for contradiction, there exist a sequence $\{n_{j}\}_{j\in\mathbb{N}}$ with $n_{j}\to\infty$ as $j\to\infty$, a sequence of potentials $\{
 (V_{1,j},V_{2,j})\}_{j\in\mathbb{N}}$ belonging to $\mathcal{B}_{M}^{[0,T]}(H^{s}(M))$ and a sequence of solutions $(w_{j})_{j}$ to \eqref{fourth order with potential} in $C([0,T],\mathcal{Q}_{n_{j}}H^{s}(M))$ associated with $(V_{1,j})$ and $(V_{2,j})$ with $\|w_{0,j}\|_{H^{s}}=1$ such that
 \begin{equation}
 \int_{0}^{T}\|\mathcal{C}w_{j}(t)\|^{2}_{H^{s}(M)}\,\dd t\to0,~~j\to\infty.
 \end{equation}
 The uniform bounds on $(w_{0,j})$, $(V_{1,j})$ and $(V_{2,j})$ implies that $w_{j}$ is a uniformly bounded sequence in $C([0,T],H^{s}(M))$. Moreover, since $w_{j}\in \mathcal{Q}_{n_{j}}H^s(M)$ for almost every $t\in[0,T]$, by spectral decomposition, we have \begin{equation}
 \|w_{j}\|_{L^{\infty}([0,T],H^{s-1}(M))}\leq \lambda_{n_{j}}^{-1/2}\|w_{j}\|_{L^{\infty}([0,T],H^{s}(M))}
 \end{equation}
 and thus infer $w_{j}\to0$ in $L^{\infty}([0,T],H^{s-1}(M))$ as $j\to\infty$.

\begin{proof}
 If $u$ is a solution of \eqref{fourth order schrodinger with general f} which belongs to $X^{2,b}_{T}$ with $b>\frac{1}{2}$, due to elliptic regularity arguments, $u$ is smooth in $(0,T)\times\omega$ and then we use the propagation of regularity theorem \ref{propagation nonlinear} to obtain that $u$ belongs to $X_{T}^{1+\nu,b}$ for $\nu\in(1/2,1]$. According to Sobolev embedding, it also belongs to $C^{0}([0,T],H^{1+\nu}(M))$ and hence $t\in(0,T)\mapsto u(t,\cdot)\in H^{1+\nu}(M)$ is analytic by Theorem \ref{analytic propogation theorem}. Let $z=\partial_{t}u$, we can apply Theorem \ref{Tataru-Robbiano-Zuily-Hormander} to obtain $\partial_{t}u=0$ in $(0,T)\times M$. Multiplying $\bar{u}$ and integral by parts gives that $u\equiv0$.
