In each case, we will see that $\autp(X)$ can in fact be realized by a finite subgroup of the automorphism group for which $\wg_X$ is nontrivial (see \S \ref{proof:classresult}).

\begin{remark} \label{autp:2.2exception}\begin{enumerate}[leftmargin=*]
 \normalfont\item[(i)] The result of the theorem is not true for $X$ in family \textnumero 2.2. In this case, the Kleiman-Mori cone $\neo(X)$ is generated by two extremal rays of different types, $C_1$ and $D_1$. Any automorphism of $X$ must keep each invariant, thus acts trivially on $\pic(X)$. So, $\autp(X)=0$, but $\wg_X=\zz/2\zz$.
 \item[(ii)] If $X$ is a smooth member of \textnumero 3.9 or \textnumero 4.2, we have an upper bound on $\autp(X)$ by Proposition \ref{imagealphainweylgroup}. It is not yet known whether the bound is attained in these two cases.
 \item[(iii)] A smooth Fano threefold in families \textnumero 6.1, \dots , \textnumero 10.1 is isomorphic to $\pp^1 \times S$, where $S$ is a del Pezzo surface of degree at most $5$. For all these cases, Matsuki's Weyl group coincides with the classical Weyl group of root system for the underlying $S$. It is known that the group $\autp(X)$ is usually much smaller than their complete Weyl group (see \S \ref{autP:P1timesdP}). 
 \end{enumerate}
 \end{remark}

\smallskip
From Proposition \ref{imagealphainweylgroup} and Table \ref{weylfano}, we immediately get 
\begin{coro} \label{im=0forsure}
 Let $X$ be a Fano threefold. Then $\autp(X)=0$ for all deformation families of Fano threefolds except possibly,
 \begin{enumerate}
 \item[(i)] $5$ families with $\rho =2$, 
 \begin{center}
 \textnumero 2.2,\; \textnumero 2.6,\; \textnumero 2.12,\; \textnumero 2.21, \; \textnumero 2.32.
 \end{center}
 \item[(ii)] $12$ families with $\rho =3$,
 \begin{center}
 \textnumero 3.1,\; \textnumero 3.3,\; \textnumero 3.7,\; \textnumero 3.9,\; \textnumero 3.10,\;\textnumero 3.13,\; \textnumero 3.17,\; \textnumero 3.19,
 \; \textnumero 3.20,\; \textnumero 3.25,\; \textnumero 3.27,\; \textnumero 3.31.
 \end{center}
 \item[(iii)] $10$ families with $\rho =4$,
 \begin{center}
 \textnumero 4.1,\; \textnumero 4.2, \; \textnumero 4.3,\; \textnumero 4.4,\; \textnumero 4.6,\; \textnumero 4.7, \textnumero 4.8,\; \textnumero 4.10,\; \textnumero 4.12,\; \textnumero 4.13.
 \end{center}
 \item[(iv)] $8$ families with $\rho \geq 5$,
 \begin{center}
 \textnumero 5.1,\; \textnumero 5.2,\; \textnumero 5.3,\; \textnumero 6.1,\; \textnumero 7.1,\; \textnumero 8.1,\; \textnumero 9.1,\; \textnumero 10.1.
 \end{center}
 \end{enumerate}
\end{coro}

\section{Classification of \texorpdfstring{$\autp(X,G)$}{AutP(X,G)}} \label{proof:classresult}
\subsection {Divisors on a products of projective spaces} \label{im(alpha)divisortype}
Let $X$ be a smooth Fano threefold that is a member of any of the five deformation families
\begin{center}
\textnumero 2.6\;(a),\; \textnumero 2.32,\; \textnumero 3.3,\; \textnumero 3.17, \; \textnumero 4.1.
\end{center}
For each family, we use their Mori-Mukai description in \cite[Tables 2-4]{MM81classtable}. A smooth Fano threefold in \textnumero 2.6 is either isomorphic to a divisor of bidegree $(2,2)$ in $\pp^2\times\pp^2$ (\textnumero 2.6 (a)), or a double cover (\textnumero 2.6 (b), see Lemma \ref{autP:2-6b)}).

\begin{lemma} \label{autP:3.13}
There exists an $X$ in \textnumero 3.13 such that $\autp(X)=\wg_X \cong S_3$.
\end{lemma}
\begin{proof}
If $X$ is in family \textnumero 3.13, the center of the blow-up is a curve $C$ of bidegree $(2,2)$ and
\[
C \hookrightarrow W \hookrightarrow \mathbb{P}^2 \times \mathbb{P}^2 \xrightarrow{\operatorname{pr}_i} \mathbb{P}^2
\]
is an embedding for $i=1,2$. Recall an alternate description of $X$ from \cite[\S 5.19]{calabi}-- one can choose coordinates $(x_0:x_1:x_2],[y_0:y_1,y_2],[z_0:z_1,z_2])$ on $\pp^2 \times \pp^2 \times \pp^2$ such that $X$ can be given by the following set of equations 
\[
\begin{cases}
 x_0y_0 + x_1y_1+x_2y_2=0\\
 y_0z_0+ y_1z_1 + y_2z_2 =0\\
 x_0z_1+ x_1z_0 + x_1z_2 - x_2z_1 -2x_2z_2 =0
\end{cases}
\]
with $\aut(X)\cong \mathbb{G}_a \rtimes S_3$. Here the subgroup $S_3$ is generated by the involutions 
\begin{align*}
\tau_{x,y}: ([x_0:x_1:x_2],&[y_0:y_1:y_2],[z_0:z_1:z_2]) \mapsto 
([y_0+2y_1+\\
&y_2:2y_0:y_0+y_2],[x_1:x_0-x_2:2x_2-x_1],[z_0:z_1:-z_2]),\\
\tau_{x,z}: .([x_0:x_1:x_2]&,[y_0:y_1:y_2],[z_0:z_1:z_2]) \mapsto \\
&([z_0:z_1:-z_2],[y_0:y_1:-y_2],[x_0:x_1:-x_2])
\end{align*} 
such that its action on $\pic(\pp^2\times\pp^2\times\pp^2)$ coincides with the permutation action of $S_3$. From Proposition \ref{thm:lefschetz}, we know $\pic(X)\cong \pic(\pp^2\times\pp^2\times\pp^2)$. Thus, we have $\autp(X,G)= S_3$ where $G$ is generated by $\tau_{x,y},\tau_{x,z}$. 
\end{proof}

\begin{lemma} \label{autP:4.7}
There exists an $X$ in \textnumero 4.7 such that $\autp(X)=\wg_X \cong \zz/2\zz$. 
\end{lemma}
\begin{proof} 
If $X$ is in family \textnumero 4.7, the center of the blow-up is a curve $C$ which is given by the disjoint union $C_1\sqcup\; C_2$ of curves $C_1$ and $C_2$ of degrees $(0,1)$ and $(1,0)$, respectively. Recall the Fano threefold $W$ from \eqref{eqn:W}, defined by $x_0y_0 + x_1y_1 + x_2y_2=0$, and the involution $\sigma \in \aut(W)$
\[
\sigma : ([x_0:x_1:x_2],[y_0:y_1:y_2]) \mapsto ([y_0:y_1:y_2],[x_0:x_1:x_2]),
\]
as in \eqref{eqn:involutionforW}.
Assume that
\begin{align*}
 C_1:= \{y_0 = y_1 =0\}, \hspace{0.5cm} C_2:= \{x_0 = x_1 =0\}.
\end{align*}
Then $\sigma$ also swaps the curves $C_1$ and $C_2$ but keeps $C_1\sqcup C_2$ invariant. Note that $C_1 \sqcup C_2$ is smooth and irreducible on $W$ since each curve $C_i$ is, and $\sigma \in \aut(W;C_1\sqcup C_2)$. Let $E_i$ denote the exceptional divisor corresponding to $C_i$, for $i=1,2$. Then $\pic(X) \cong \zz[\pi^*H_1]\oplus \zz[\pi^*H_2]\oplus \zz[E_1]\oplus \zz[E_2]$.

\subsection{Product of \texorpdfstring{$\mathbb{P}^1$}{P1} and a del Pezzo surface} \label{autP:P1timesdP}
Let $X$ be a smooth Fano threefold of the form $\mathbb{P}^1 \times S_d$, where $S_d$ is a del Pezzo surface of degree $d$, $1 \leq d \leq 9$. Then $X$ is a member of one of the following $10$ deformation families 
\begin{center}
\textnumero 2.34,\; \textnumero 3.27, \; \textnumero 3.28, \; \textnumero 4.10, \; \textnumero 5.3, \; \textnumero 6.1,\; \textnumero 7.1,\; \textnumero 8.1,\; \textnumero 9.1,\; \textnumero 10.1.
\end{center}
If $X$ is in family \textnumero $2.34$, we have $d=9$ and it is isomorphic to $\mathbb{P}^1 \times \mathbb{P}^2$. If $X$ is in family \textnumero $3.28$, $d=8$ and $X$ is isomorphic to $\mathbb{P}^1 \times \operatorname{Bl}_p\mathbb{P}^2$. We forego the discussion of these two families since each has $WG_X=0$ from \cite{Mat23}.

