$$\exists a^1_1,...,a^1_k,...,a^N_1,...,a_k^N: a^i_j\in \bigcap_{j=1}^i \phi(\mathfrak{M},x_j)\wedge a^i_j{a^i_k}^{-1}\not\in \phi(\mathfrak{M},x_j)\wedge \forall_{i\leq N}\ \phi(\mathfrak{M},x_i)\leq G(\mathfrak{M})$$
for all $k<\omega$, is finitely satisfable. By compactness and saturation, there exist subgroups $\{H_i\}_{i\leq N}$ such that $|\bigcap_{i<j}H_i/\bigcap_{i\leq j}H_i|$ is infinite for every $i$. This would imply that the dimension of $G$ is strictly greater than $n$, a contradiction.
\end{proof}
If we apply these results to the centralizers of elements in $G$, we obtain that a finite-dimensional definable group has the hereditary $\widetilde{\mathfrak{M}}_c$-property.
\begin{defn}
    A group $G$ is \emph{hereditarily-$\widetilde{\mathfrak{M}}_c$} if for any definable subgroups $H,N$, such that $N$ is normalised by $H$, there exist natural numbers $n_{HN}$ and $d_{HN}$ such that any sequence of centralisers 
    $$C_H(a_0/N)\geq C_H(a_0,a_1/N)\geq...\geq C_H(a_0,a_1,...,a_n/N)\geq...$$
    with each centraliser of index at least $d_{HN}$ in the previous one, has length at most $n_{HN}$.
\end{defn}
The notions of almost containment and commensurability are fundamental in the study of groups definable in finite-dimensional theories.
\begin{defn}
\begin{itemize}
    \item  Let $G$ be a group and $A, B\leq G$ subgroups. $A$ \emph{almost contains} $B$, denoted $A\apprge B$, if $|B:B\cap A|$ is finite.
    \item  If $A\apprle B$ and $B\apprle A$, $A$ and $B$ are \emph{commensurable}.
    \item Given a family of subgroups $\{G_i\}_{i\in I}$ in $G$, the family $\{G_i\}_{i\in I}$ is \emph{uniformly commensurable} if there exists $n<\omega$ such that $|G_i/G_i\cap G_j|\leq n$ for every $i,j\in I$.
\end{itemize}
  \end{defn}

