\begin{lem}\label{lemma4.2}
There exists $\delta>0$ which is independent of $D_m(x)$ such that if $y,z\in G_m(x)$ and $\gamma (t),\ 0\leq t\leq 1$ is a continuous curve in $D_m(x)$ from $y$ to $\partial_o D_m(x)$, then 
\begin{equation}\label{e:4.1}
 P^z(W\ hits \ \gamma \ before \ \tau) >\delta.
\end{equation}
\begin{proof}
Set 
\[
\partial_oG_m(x)= \partial([x_0^{(1)}-\frac{2}{3} 3^{m},x_0^{(1)}+\frac{2}{3} 3^{m}]\times [x_0^{(2)}-\frac{2}{3} 3^{m},x_0^{(2)}+\frac{2}{3} 3^{m}])\cap \tilde{F}_0.
\]
By applying the corner move (Theorem \ref{theorem3.3}) and knight move (Theorem \ref{theorem3.7}) construction inside the squares each of side length $3^{-m-2}$, surrounding $G_m(x)$ (see Figure \ref{fig:chain of squares}) for the process starting at $W_{\mathcal{T}_{\partial_oG_m(x)}}$, and by a same idea of \cite{barlow1989construction}, there is $\delta>0$ depending only on the number of small squares such that 
\[
P^z(W\hbox{ hits every }L\in \mathcal{H}_{m+2}\hbox{ that satisfies }L\cap \partial_oG_m(x)\neq\emptyset)>\delta.
\]
Noticing that in the above event $W$ divides $D_m(x)$ into two parts, one of which contains $G_m(x)$, it holds that
\[
P^z(W\ \hbox{hits} \ \gamma \ \hbox{before} \ \tau) \geq P^z(W\hbox{ hits every }L\in \mathcal{H}_{m+2}\hbox{ that satisfies }L\cap \partial_oG_m\neq\emptyset)>\delta.
\]
\end{proof}
\end{lem}

\begin{lem}\label{lemma6.1}
For each $k\geq 1$, there exists a constant $C(k)>1$ such that
\begin{equation*}\begin{aligned}
 C(k)^{-1} \frac{R_n\,{\mu_0(F^n_0)}}{\mu_0(B_\infty(x_0,3^n))}\leq \res({B_\infty(x_0,k3^n)},B_\infty(x_0,(k+1)3^n))\leq C(k) \frac{R_n\,{\mu_0(F^n_0)}}{\mu_0(B_\infty(x_0,3^n))}
\end{aligned}
\end{equation*}
for every $n\in \Z$ and $x_0=(i3^{n},j3^{n})$ with $i,j\in \mathbb{Z},\ i,j\geq0$. 
\end{lem}
\begin{proof}
Let $B_1=B_\infty(x_0,k3^n)$ and $B_2=B_\infty(x_0,(k+1)3^n)$. We prove the lower bound estimate of $\res(B_1,B_2)$ by constructing a function $f$ feasible for $\res({B_1},B_2)$. Let $S_1,...,S_{8k+4}$ be the squares in
\[
\mathcal{Q}_{n}([(i-k-1)3^n,(i+k+1)3^n]\times [(j-k-1)3^n,(j+k+1)3^n]\setminus \overline{B_1}).\]
We label counterclockwise $S_l,\ l=1,...,8k+4$ starting with 
\[
S_1=[(i+k)3^n,(i+k+1)3^n]\times[j3^n,(j+1)3^n].
\] 
For $l\in\{1,...,2k+1\}$, we write $\varphi_l$ for the translation that maps $[0,3^n]^2$ to $S_l$. Let $u$ be the optimum function for \eqref{e:5.1}, and rotate $u$ to get $v,w$ such that 
\begin{equation}
\begin{aligned}\label{1}
 &v=1\hbox{ on }L_4,\quad\ v=0\hbox{ on }L_2,\quad\, \tmcE_0|_{F_0^n}(v)=1/R_n,\\
&w=1\hbox{ on }L_1,\quad w=0\hbox{ on }L_3,\quad \tmcE_0|_{F_0^n}(w)=1/R_n. 
\end{aligned}
\end{equation}
Note that $v\wedge w=\frac{1}{2}(v+w-|v-w|)$, by the Markov property of $\tmcE_0$, 
\begin{align}\label{2}
\tmcE_0(v\wedge w)\leq \tmcE_0(v)+\tmcE_0(w)=2/R_n. 
\end{align}
For $1\leq l\leq 2k+1$, we set $f_l:S_l\cap \tilde{F}_0\rightarrow \R$ by 
\[f_l=\begin{cases}
v\circ \varphi_l^{-1},&\qquad\hbox{ if }l=1,...,k,\\
(v\wedge w)\circ \varphi_l^{-1}, &\qquad\hbox{ if }l=k+1,\\
w\circ \varphi_l^{-1},&\qquad\hbox{ if }l=k+2,...2k+1.
\end{cases} 
\]
For $l=2k+2,...8k+4$, we choose a reflection $g$ that maps $[(i-k-1)3^n,(i+k+1)3^n]\times [(j-k-1)3^n,(j+k+1)3^n]$ onto itself such that $g(S_{l})=S_{l^{\prime}}$ for some $l^{\prime}\in \{1,...,2k+1\}$, and set $f_l= f_l^{\prime}\circ g$ on $S_l\cap\tilde{F}_0$. Define $f:{ \tilde{F}_0}\rightarrow \R$ as 
\[
f=\begin{cases}
 f_l \qquad &\hbox{on }S_l,\ \hbox{if }S_l\subset\tilde{F}_0,\\
 1 &\hbox{on }\overline{B_1},\\
 0 &\hbox{otherwise}.
\end{cases}
\]
Let $c_k=\max\{\frac{\mu_0(S_l\cap\tilde{F}_0)}{\mu_0(B_\infty(x_0,3^n))}:l=1,...8k+4\}$. 
 Then
\begin{align*}
\tmcE_0(f)&=\sum_{l=1}^{8k+4}\tmcE_0|_{S_l\cap \tilde{F}_0}(f)\\ &\leq\sum_{l= k+1,3k+2\atop 5k+3,7k+4}2\frac{\mu_0(S_l\cap\tilde{F}_0)}{\mu_0(F^n_0)}R^{-1}_n+\sum_{\substack{1\leq l\leq 8k+4, \\l\neq k+1,3k+2\\
 5k+3,7k+4}}\frac{\mu_0(S_l\cap\tilde{F}_0)}{\mu_0(F^n_0)}R^{-1}_n\\
 &\leq (8k+8)c_k\frac{\mu_0(B_\infty(x_0,3^n))}{\mu_0(F_0^n)}R^{-1}_n,
\end{align*}
where the first inequality follows from \eqref{1} and \eqref{2}. This implies the desired lower bound of $\res(B_1,B_2)$.

