ref_dict.def:ODandOPDVectorSpaces:
\begin{definition}
\label{def:ODandOPDVectorSpaces}
Let $V$ be a finite-dimensional vector space defined over a field $k$.
The poset of ordered partial decompositions of $V$, denoted by $\OPD(V)$ consists of tuples of distinct subspaces $(S_1,\ldots,S_r)$ such that $\{S_1,\ldots,S_r\}\in \PD(V)$.
The ordering in $\OPD(V)$ is given by refinement that preserves the order of the elements of the tuples.
That is, if $d_1 = (S_1,\ldots,S_r)$ and $d_2 = (W_1,\ldots,W_t)$, then $d_1\leq d_2$ if for all $1\leq i\leq j\leq r$ there are $1\leq k\leq l\leq t$ such that $S_i\leq W_k$ and $S_j\leq W_l$.

The poset $\OD(V)$ of ordered full decompositions of $V$ is the subposet of
$\OPD(V)$ on the set of $(S_1,\ldots,S_r)$ such that $\{S_1,\ldots,S_r\}\in \D(V)$.
\end{definition}

ref_dict.def:decompBuilding:
\begin{definition}
\label{def:decompBuilding}
Let $\Delta$ be a spherical building.
We denote by $\D(\Delta)$ the poset of all non-empty Levi spheres, with order induced by reverse inclusion.
\end{definition}

ref_dict.prop:lowLeviIntervalPD:
\begin{proposition}
\label{prop:lowLeviIntervalPD}
Let $L\in \D(\GG,k)$.
Then $\PD(\GG,k)_{\prec L} \simeq \Delta(\GG,k)^L * \PD(L,k)$. 
Moreover, in homology, we have an isomorphism of $L(k)$-modules
\begin{equation}
\label{eq:isoHomologyIntervalsPDLevi}
\widetilde{H}_*\big(\PD(\GG,k)_{\prec L},R \big) \cong \widetilde{H}_*\big(\, \Delta(\GG,k)^L *\PD(L,k), R \, \big) \cong \widetilde{H}_*\big(\,\PD(L,k), R \, \big),
\end{equation}
provided that $RL(k)$ is semisimple.
\end{proposition}

ref_dict.def:ODandOPDbuildings:
\begin{definition}
\label{def:ODandOPDbuildings}
Let $\Delta$ be a spherical building.
We define the posets:
\begin{itemize}
\item $\OD(\Delta) := \Opp(\Delta) = \{ (\sigma,\sigma')\tq \sigma,\sigma'$ are opposite simplices$\}$, with order relation 
$(\sigma,\sigma') \leq (\tau,\tau')$ if $\tau\subseteq \sigma$ and $\tau'\subseteq \sigma'$.
\item $\OPD(\Delta) = \X(\Delta) \cup \Opp(\Delta)$ with order relation $\preceq$ defined as follows. Among elements of $\X(\Delta)$ and 
among elements of $\Opp(\Delta)$ the order $\preceq$ is inherited from the order on the respective posets. If $\sigma \in \X(\Delta)$ and
$(\tau,\tau') \in \Opp(\Delta)$ then we set 
$\sigma \prec (\tau,\tau')$ if there is an apartment containing $\sigma,\tau$, and $\tau'$.
\end{itemize}
We call $\OD(\Delta)$ the ordered decomposition poset associated with $\Delta$, and $\OPD(\Delta)$ the ordered partial decomposition poset.
\end{definition}

ref_dict.coro:DDeltaCM:
\begin{corollary}
\label{coro:DDeltaCM}
Let $\Delta$ be a spherical building.
Then the poset of Levi spheres $\D(\Delta)$ is Cohen-Macaulay of dimension $\dim \Delta$.
\end{corollary}

ref_dict.thm:PDandPDBuildingVectorSpace:
\begin{theorem}
\label{thm:PDandPDBuildingVectorSpace}
Let $V$ be an $n$-dimensional vector space over a field $k$.
Let $\sigma \in \OPD(V)'$, and write $\sigma = \sigma_0\cup \sigma_1$ where $\sigma_0$ is the set of ordered partial decompositions in $\sigma$ that span a proper subspace of $V$, and $\sigma_1$ is the set of full ordered decompositions in $\sigma$.
Then, for $\sigma \in \OPD(V)'$, we set
\[ \phi(\sigma) = \begin{cases}
\{ \gen{s} \tq s\in \sigma_0\} & \sigma_1 = \emptyset,\\
\max \sigma_1 & \sigma_1\neq\emptyset.
\end{cases}\]
Then $\phi$ is a $\GL(V)$-equivariant poset map $\phi: \OPD(V)' \to \OKtwo{V}$ such that for all $H\leq \GL(V)$, the induced map $\phi_H: (\OPD(V)')^H \to \OKtwo{V}^H$ is a homotopy equivalence.

We get analogous conclusions for the corresponding map $\PD(V)'\to \Ktwo{V}$.
\end{theorem}

ref_dict.lm:convexIsleviSphere:
\begin{lemma}
\label{lm:convexIsleviSphere}
Let $\Sigma$ be a finite Coxeter complex, and let $K\subseteq \Sigma$ be a convex subcomplex.
Then $K$ is a Levi sphere if and only if $K$ contains a pair of opposite simplices $\sigma_1,\sigma_2$ with dimension $\dim \sigma_i = \dim K$.
In such a case, $K$ is the convex hull of $\sigma_1,\sigma_2$ and $|K|$ is a sphere of dimension $\dim K$.
\end{lemma}

