\subsection{Main results}
Our goal in this paper concerns controllability and stabilization problem for \eqref{4NLS}. More precise, the exact controllability and stabilization theorem.

As an application of Strichartz estimates, Burq-G\'erard-Tzvetkov established the local well-posedness for the cubic nonlinear Schr\"odinger equation with initial data $u_0\in H^{s}$, with $s>\frac{d-1}{2}$. Later, Dinh \cite{Dinh} generalized \eqref{strichartz on manifolds} to fractional case:
\begin{equation}
 \|e^{it(-\Delta_{g})^{\frac{\sigma}{2}}}f\|_{L^{p}_{t}L^{q}_{x}(I\times M)}\leq C(I)\|f\|_{H^{\frac{1}{p}}},~ \frac{2}{p}\leq d\big(\frac{1}{2}-\frac{1}{q}\big),~ p\geq2, ~q<\infty.
\end{equation}
Then, he obtained the well-posedness of cubic fractional Schr\"odinger equation for $s>\frac{d-1}{2}$.

Now, we prove an observability inequality uniform with respect to the potential for solutions at high frequency.
 \begin{proposition}
 Let $T>0$, $M>0$, $d\in\mathbb{N}$ and $s>\frac{d}{2}$ be fixed. Let $\omega$ be an open set satisfying the GCC and let $\mathcal{C}u=b_{\omega}u$. Then there exist $n_{0}\in\mathbb{N}$ and $C>0$ such that for any $V_{1}$, $V_{2}\in \mathcal{B}_{M}^{[0,T]}(H^{s}(M))$ and $n\geq n_0$, the following observability inequality holds
 \begin{equation}
 \|w_{0}\|_{H^{s}}^{2}\leq C\int_{0}^{T}\|\mathcal{C}w(t)\|_{H^{s}}^{2}\,\dd t
 \end{equation}
 for any $w_0\in\mathcal{Q}_{n}H^{s}(M)$, where $w\in C^{0}([0,T],\mathcal{Q}_{n}H^{s}(M))$ is solution to 
 \begin{equation}\label{fourth order with potential}
 \begin{cases}
 i\partial_{t}w+\Delta_{g}^{2}w-\beta\Delta_{g}w=\mathcal{Q}_{n}(V_{1}w+V_{2}\bar{w}),&(t,x)\in (0,T)\times M,\\ w(0)=w_{0},& x\in M.
 \end{cases}
 \end{equation}
 \end{proposition}
 \begin{proof}
 We proceed by contradiction. Suppose, for contradiction, there exist a sequence $\{n_{j}\}_{j\in\mathbb{N}}$ with $n_{j}\to\infty$ as $j\to\infty$, a sequence of potentials $\{
 (V_{1,j},V_{2,j})\}_{j\in\mathbb{N}}$ belonging to $\mathcal{B}_{M}^{[0,T]}(H^{s}(M))$ and a sequence of solutions $(w_{j})_{j}$ to \eqref{fourth order with potential} in $C([0,T],\mathcal{Q}_{n_{j}}H^{s}(M))$ associated with $(V_{1,j})$ and $(V_{2,j})$ with $\|w_{0,j}\|_{H^{s}}=1$ such that
 \begin{equation}
 \int_{0}^{T}\|\mathcal{C}w_{j}(t)\|^{2}_{H^{s}(M)}\,\dd t\to0,~~j\to\infty.
 \end{equation}
 The uniform bounds on $(w_{0,j})$, $(V_{1,j})$ and $(V_{2,j})$ implies that $w_{j}$ is a uniformly bounded sequence in $C([0,T],H^{s}(M))$. Moreover, since $w_{j}\in \mathcal{Q}_{n_{j}}H^s(M)$ for almost every $t\in[0,T]$, by spectral decomposition, we have \begin{equation}
 \|w_{j}\|_{L^{\infty}([0,T],H^{s-1}(M))}\leq \lambda_{n_{j}}^{-1/2}\|w_{j}\|_{L^{\infty}([0,T],H^{s}(M))}
 \end{equation}
 and thus infer $w_{j}\to0$ in $L^{\infty}([0,T],H^{s-1}(M))$ as $j\to\infty$.

\begin{proof}
 If $u$ is a solution of \eqref{fourth order schrodinger with general f} which belongs to $X^{2,b}_{T}$ with $b>\frac{1}{2}$, due to elliptic regularity arguments, $u$ is smooth in $(0,T)\times\omega$ and then we use the propagation of regularity theorem \ref{propagation nonlinear} to obtain that $u$ belongs to $X_{T}^{1+\nu,b}$ for $\nu\in(1/2,1]$. According to Sobolev embedding, it also belongs to $C^{0}([0,T],H^{1+\nu}(M))$ and hence $t\in(0,T)\mapsto u(t,\cdot)\in H^{1+\nu}(M)$ is analytic by Theorem \ref{analytic propogation theorem}. Let $z=\partial_{t}u$, we can apply Theorem \ref{Tataru-Robbiano-Zuily-Hormander} to obtain $\partial_{t}u=0$ in $(0,T)\times M$. Multiplying $\bar{u}$ and integral by parts gives that $u\equiv0$.
 \end{proof}
 \subsubsection{Propogation of regularity in Bourgain space}
 \begin{proposition}\label{propagation of regularity in Bourgain space}
 Let $T>0$ and $0\leq b<1$, and suppose that $u\in X^{s,b}_{T}$, $s\in\mathbb{R}$, be a solution of 
 \begin{equation*}
 i\partial_{t}u+\Delta^{2}_{g}u-\Delta_{g}u=f\in X^{s,-b}_{T}
 \end{equation*}
 Given $\rho_{0}=(x_{0},\xi_{0})\in T^{\star}M\backslash\{0\}$, we assume that there exists a zeroth pseudo-differential operator $\chi(x,D_{x})$, elliptic in $\rho_{0}$ such that 
 \begin{equation*}
 \chi(x,D_{x})u\in L^{2}_{\rm loc}((0,T), H^{s+\nu})
 \end{equation*}
 for some $\nu\leq\frac{1-b}{2}$. Then, for every $\rho_{1}\in\Phi_{t}(\rho_{0})$, the geodesic ray starting at $\rho_{0}$, there exists a pseudo-differential operator $\psi(x,D_{x})$ elliptic at $\rho_{1}$ such that 
 \begin{equation}
 \psi(x,D_{x})u\in L^{2}_{\rm loc}((0,T), H^{s+\nu}).
 \end{equation}
 Moreover, if an open set $\omega$ satisfies GCC condition and $a(x)u\in L^{2}_{\rm loc}((0,T),H^{s+\nu})$ with $a(x)\in C^{\infty}(M)$, $\operatorname{supp} a(x)\subset\omega$ also satisfies GCC, then $u\in L^{2}_{\rm loc}((0,T),H^{s+\nu})$. 
 \end{proposition}
 \begin{proof}
 Firstly, we regularize $u_{n}=e^{\frac{1}{n}\Delta_{g}}u$ with $\|u_{n}\|_{X^{s,b}_{T}}\leq C$. Let $r=s+\nu$ and $B(x,D_{x})$ be a pseudo-differential operator of order $2r-1=2s+2\nu-1$ that will be chosen later. Let $A=A(t,x,D_{x})=\varphi(t)B(x,D_{x})$, where $\varphi\in C_{0}^{\infty}((0,T))$.

We prove a cutoff version of \eqref{obervability inequality} $\forall u_{0}\in L^{2}(M)$ and $0<h<h_{0}$
 \begin{equation}\label{cutoff observability inequality}
 \|\Pi_{h}u_{0}\|^{2}_{L^{2}(M)}\leq C\int_{0}^{T}\int_{\omega}|e^{it(\Delta^{2}_{g}-\beta\Delta_{g})}\Pi_{h}u_0|^2\,\dd x\dd t.
 \end{equation}
 If \eqref{cutoff observability inequality} is not right, there exist a sequence $h_{j}\to0$ and functions $u^{0}_{h_{j}}$ such that
 \begin{equation}
 \|\Pi_{h_{j}}u_{h_{j}}^{0}\|_{L^{2}(M)}=1, ~~~\lim_{j\to\infty}\int_{0}^{T}\int_{\omega}|e^{it(\Delta_{g}^{2}-\Delta_{g})}\Pi_{h_{j}}u^{0}_{h_j}|^2\,\dd x\dd t=0,
 \end{equation}
 the first equality means that $W^{h_{j}}_{u_{h_{j}}}$ converges to a finite measure in $T^{\star}M$, and the second inequality means that $W^{h_{j}}_{u_{h_{j}}}$ converges to zero measure in $T^{\star}\omega\setminus0$.
 Thus, we have 
 \begin{equation}\label{contradiction part}
 \int_{0}^{T}\mu_{t}(T^{\star}M\setminus0)\,\dd t=T,~~\int_{0}^{T}\int_{T^{\star}M}b(x)\mu_{t}(\dd x,\dd\xi)\,\dd t=0,~~\forall b\in C^{\infty}_{c}(\omega)
 \end{equation}
 Denote $$F_{\omega}^{T}:=\bigcup_{t\in[0,T]}\{\phi_{t}(x,\xi):(x,\xi)\in T^{\star}\omega\setminus0\}.$$ Since $\omega$ satisfies Geometric Control Condition, there exsits $T_{0}$ such that $F_{\omega}^{T_{0}}=T^{\star}M\setminus0$. Combining the fact that $\mu_{t}$ is invariant by the Hamiltonian flow of $\sigma_{4}(|\xi|_{g}^{2})$, we infer that $\mu_t(T^{\star}M\setminus0)=0$, which is a contradition to the first part of \eqref{contradiction part}.
 \section{Local Controllability}
 Before the proof of nonlinear controllability, we briefly recall the HUM method for linear equation
 \begin{equation}
 \begin{cases}
 i\partial_{t}u+(\Delta_{g}^{2}-\beta\Delta_{g})u=-|u|^{2k}u+h(x,t),\\ u(0,x)=u_{0}(x).
 \end{cases}
 \end{equation}
 When observability inequality is proved, HUM method gives the exact controllability of linear equation
 \begin{equation}\label{linear equation}
 \begin{cases}
 i\partial_{t}u+(\Delta_{g}^{2}-\beta\Delta_{g})u=0,\\ u(0,x)=u_{0}(x).
 \end{cases}
 \end{equation}
 \subsection{Local controllability in energy space}
 Since $\omega$ satisfies the Geometric Control Condition, we can find $\omega'$ satisfying GCC and $\omega'\Subset \omega$, we then introduce $\varphi\in C^{\infty}(M)$ real-valued supported in $\omega$ such that $\varphi=1$ on $\omega'$.
 Consider the systems
 \begin{equation}\label{HUM dual double equation}
 \begin{cases}
 i\partial_{t}u+\Delta^2_g u-\beta\Delta_{g}u=h\in L^{2}(0,T;H^2), u(T)=0,\\ i\partial_{t}v+\Delta^{2}_{g}v-\beta\Delta_{g}v=0, v(0)=v_{0}\in H^{-2}(M),
 \end{cases}
 \end{equation}

