The rest of this paper is organized as follows. In the next section we make some preliminary observations about adding $\aleph_\omega$ versus adding $\aleph_{\omega+1}$ Cohen reals. In Section \ref{Sectionfew} we prove the generalization of Item (1) of Theorem \ref{main} while in Section \ref{sectionmany} we prove the generalization of Item (2) of Theorem \ref{main}. The paper concludes with some questions for further research. Throughout our notation is mostly standard, conforming e.g. to that of \cite{jechSetTheory2003} or \cite{kunenSetTheory2011}. Those texts are referred to for any undefined terms.

\begin{proposition}
Assume $\CH$. Let $G_0$ be $\Add(\omega,\aleph_\omega)$-generic over $V$ and let $G_1$ be $\Add(\omega,\aleph_{\omega+1})$-generic over $V$.
\begin{enumerate}
\item
In $V[G_0]$ there are $\aleph_1$-many Borel functions $\{f_\alpha : \alpha \in \omega_1\}$ and a set of $\aleph_\omega$-many reals, $A = \{a_\alpha : \alpha \in \aleph_\omega\}$ so that the following hold.
\begin{enumerate}
\item For all $\alpha < \omega_1$ the domain of $f_\alpha$ is $[\omega^\omega]^\omega$.
\item For every $x \in \omega^\omega$ there is a $c \in [\aleph_\omega]^\omega \cap V$ and an $\alpha < \omega_1$ so that $x = f_\alpha (\{a_\xi : \xi \in c\})$.
\end{enumerate}

We conclude this section by making some simple observations about the principle $\mathsf{Pr}(\sigma, \theta, \mu, \lambda)$ in an attempt to clarify it and prepare the reader for the arguments in Lemmas \ref{addingfew} and \ref{addingmany}. All of these are easy, as should be obvious to the reader who is clear on what the principle states.
\begin{proposition}
Let $\sigma \leq \theta \leq \mu \leq \lambda$ be infinite cardinals.
\begin{enumerate}
\item If $\theta = 2^\sigma$, then $\mathsf{Pr}(\sigma, \theta, \mu, \lambda)$ is true for any choice of $\mu$ and $\lambda$. 
\item If $\lambda=\mu^+$, the statement $\mathsf{Pr}(\sigma, \theta, \mu, \lambda)$ is unchanged by allowing in clause (C) of the definition that $A$ has size $\leq \lambda$.
\item $\Pr(\sigma,\theta,\mu,\lambda)$ is monotone in $\theta$ and $\mu$. More precisely, if $\theta_0 \le \theta_1$ or $\mu_0\le \mu_1$ are infinite cardinals, then $\Pr(\sigma,\theta_0,\mu_0,\lambda)$ implies $\Pr(\sigma,\theta_1,\mu_1,\lambda)$.
\end{enumerate}

\begin{lemma} \label{addingfew}
 Assume $2^\sigma = \theta < \mu <\lambda$. Let $\P$ be a forcing notion that has the $\sigma^+$-covering property and such that $\Vdash |\dot G|\le |\mu|$. Then $\forces_{\P} \mathsf{Pr}(|\sigma|, |\theta|, |\mu|, |\lambda|)$.
\end{lemma}

\begin{lemma} \label{addingmany}
 Assume $\mu$ is a strong limit cardinal of countable cofinality, $\sigma < \theta < \mu$ and $\lambda= \mu^+$. If $\P=\Add(\omega,\lambda)$, then $\forces_{\P} \neg \mathsf{Pr}(\sigma, \theta, \mu, \lambda)$.
\end{lemma}

Let $\langle W_n : n < \omega\rangle$ be a $\subseteq$-increasing sequence of sets of size ${<}\mu$ so that $\bigcup_{n < \omega} W_n = \gamma^*$. For $\delta \in E \cap S_*$ and $\xi \in u_*$ there is an $n_{\delta, \xi} \in \omega$ so that
 \begin{equation}\label{W}
 {\dom}(p_{\xi, \beta_\delta}) \cap \gamma_* \subseteq W_{n_{\delta, \xi}}
 \end{equation}
 simply by the finiteness of the domains. But this implies that for every $\delta \in S_* \cap E$ there is a $u_{*, \delta} \in [u_*]^{\theta^+}$ so that $n_{\delta, \xi} = n_\delta$ for some fixed $n_\delta \in \omega$ and every $\xi \in u_{*, \delta}$. By a pigeonhole argument, we can find a stationary set $S_{**} \subseteq S_{*} \cap E$, together with $n\in\omega$, $u_{**}\in [u_*]^{\theta^+}$ and a family $\seq{p_\xi:\xi\in u_{**}}$ so that, for every $\delta \in S_{**}$, the following hold: 
