\begin{thm}
\label{t:main}
Let \( (\mathbb{C}P^n, \omega_{\textup{FS}}) \) denote complex projective space equipped 
with the Fubini–Study symplectic form. Then, for every integer \( k \in \{1, \ldots, n\} \), the 
homotopy group  
\[
\pi_{2k-1}(\textup{Ham}(\mathbb{C}P^n, \omega_{\textup{FS}}))
\]  
is nontrivial.
\end{thm}

ref_dict.p:2n:
\begin{prop}
\label{p:2n}
Let \(1 \leq k \leq n\), and let
\(\{ \psi_{A_{\underline{t}}} \}_{\underline{t} \in S^{2k-1}}\)
be the family of Hamiltonian diffeomorphisms of 
\((\mathbb{C}P^n, \omega_\textup{FS})\) defined above. Then, the value of Weinstein’s morphism 
on the homotopy class \([\psi_{A_{\underline{t}}}]\) is given by
 $$
\mathcal{A}([\psi_{A_{\underline{t}}}]) = \frac{\pi^k}{ k! }\cdot
\frac{n!}{(n+k)! \, 2^k}
\sum_{I} \frac{k!}{i_1! \cdots i_{2k}!}
\prod_{j=1}^{2k} (2i_j - 1)!!
 \quad \in \mathbb{R}/\langle \pi^k / k! \rangle,
$$
where the sum runs over all multi-indices \(I = (i_1, \ldots, i_{2k})\) such that \(i_j \geq 0\) and \(i_1 + \cdots + i_{2k} = k\).
\end{prop}

ref_dict.p:ainblow:
