\begin{prop}\label{prop: equidistirbution for small balls}
 Let $V \subset H$ be bounded measurable with $m_H(\partial V) =0$. Let $K \subset X$ be compact and let $0<\sigma<\rho(K)$. 
 Let $L \subset X$ be another compact set, and let $\eta >0$. Then there exists $t_0 := t_0(V, K, \sigma, L, \eta) >0$ such that, for all $t > t_0$, base point $x \in L$ and center $y \in K$,
 \begin{equation*}
 m_H\left\lbrace h \in V: g_thx \in B_X(y,\sigma) \right\rbrace > m_H(V) m_G\big(B_G(\sigma)\big) - \eta.
 \end{equation*}
\end{prop}
\begin{proof}
 The proof is a modification of that of \cite[Proposition 2.4]{Kl2}. 
 By partitioning $V$ into finitely many smaller subsets with boundary of measure zero and noting the invariance of $m_H$, one can without loss of generality assume that $e_H\in V$, $m_H(V)<1$ and $\textup{diam}(V) < \rho(L)$. The latter condition implies that there is an open ball $U \subset G$ centered at $e_G$ and containing $V$ such that for all $x \in L$ the map
 $\pi_x$ is injective on $U$, and hence
 \begin{equation*}
 m_X(Ux) = m_G(U).
 \end{equation*}
Similarly we have, for any $0 < \alpha < 1$ and $y \in K$,
 \begin{equation*}
 m_X\big(B_X(y,\alpha \sigma)\big) = m_G\big(B_G(\alpha \sigma)\big).
 \end{equation*}
 Fix $\alpha <1$ such that
 \begin{equation}\label{eq: alpha ball close}
 m_G\big(B_G(\alpha \sigma)\big) > m_G\big(B_G(\sigma)\big) - \frac{\eta}{2}. 
 \end{equation}
 Now let $\tilde{H}$ and $m_{\tilde{H}}$ 
 be as in Definition~\ref{horosph}.
Choose a nonempty open ball $\tilde V \subset \tilde{H}$ such that $\tilde VV \subset U$ and such that for all $\tilde v \in \tilde V$ and $t>0$ we have
 \begin{equation*}
 \dist_G\big(e_G,\Phi_t(\tilde v)\big) < (1-\alpha)\sigma. \end{equation*}
 Now for $y \in K$, $x \in L$ and $t>0$ denote
 \begin{equation*}
 W := \left\lbrace h \in V : g_t hx \in B_X(y,\sigma)\right\rbrace\ \text{ and }\ U' := \tilde V V.
 \end{equation*}
 \begin{claim}\label{claim: 99 containment}
 The set $U'x \cap g_t^{-1} B_X(y, \alpha \sigma)$ is contained in $\tilde V W x$.
 \end{claim}
 \begin{proof} Let $\tilde v \in \tilde V$, $h \in V$ be such that $g_t\tilde vhx \in B_X(y, \alpha \sigma)$. We have
 \begin{equation*}
 \begin{split}
 \dist_X(g_t h x, y) &\leq \dist_X(g_t hx, \Phi_t(\tilde v)g_thx) + \dist_X(g_t\tilde vhx, y) \\
 &< (1-\alpha)\sigma + \alpha \sigma = \sigma.
 \end{split}
 \end{equation*}
 Thus $g_thx \in B_X(y,\sigma)$.
 \end{proof}
 We now use Proposition \ref{thm: KM mixing} with \begin{equation*}
 \Xi := \left\lbrace \mathds{1}_{U'x} : x \in L\right\rbrace,\ 
\Psi := \{\mathds{1}_{B_X(y,\alpha \sigma}) : y \in K\},
 \end{equation*} 
 and with $\eta$ replaced by $\eta m_{\tilde{H}}(\tilde V)/2$.
 This gives $t_0 >0$ such that, for all $t>t_0$, $x \in L$ and $y \in K$, we have
 \begin{equation*}
 \left|m_X\big(U'x \cap g_t^{-1}B_X(y,\alpha \sigma)\big) - m_G(U')m_G\big(B_G(\alpha \sigma)\big) \right| < \eta m_{\tilde{H}}(\tilde{V})/2.
 \end{equation*}
 In particular, using the choice of $m_{\tilde{H}}$ and Claim \ref{claim: 99 containment}, we compute
 \begin{equation*}
 \begin{split}
 m_{\tilde{H}}(\tilde{V})m_H(W) &=m_X(\tilde VWx) \\
 &\geq m_X\big(U'x \cap g_t^{-1}B_X(y,\alpha \sigma)\big) \\
 &\geq m_G(U') m_G\big(B_G(\alpha \sigma)\big) - \eta m_{\tilde{H}}(\tilde V)/2 \\
 &= m_{\tilde{H}}(\tilde V)m_H(V) m_G\big(B_G(\alpha \sigma)\big) - \eta m_{\tilde{H}}(\tilde V)/2.
 \end{split}
 \end{equation*}
 Canceling $m_{\tilde{H}}(\tilde V)$, using \eqref{eq: alpha ball close} and the fact that $m_H(V) < 1$, we get
 \begin{equation*}
 \begin{split}
 m_{H}(W) &\geq m_H(V) m_G\big(B_G(\alpha \sigma)\big) - \eta/2 \\
 &\geq m_H(V) m_G\big(B_G( \sigma)\big) - m_H(V)\eta/2 - \eta/2 \\
 &\geq m_H(V)m_G\big(B_G( \sigma)\big) - \eta
 \end{split}
 \end{equation*}
 which gives the desired result.
\end{proof}

\begin{defn}[Strongly tree-like collections and Cantor sets]\label{defn: tree like collection}\label{defn: tree-like collection}
 We say a collection of subsets $\ca{E} \subset 2^H$ is \textsl{strongly tree-like} if:
 \begin{itemize}
 \item Each $E \in \ca{E}$ is a compact set with nonempty interior.
 \item We have a partition
 \begin{equation*}
 \ca{E} = \bigcup_{k \in \Z_{\geq 0}} \ca{E}_k
 \end{equation*}
 with each $\ca{E}_k$ being finite and $\ca{E}_0$ being a singleton.
 \item If $E' \in \ca{E}_k$ with $k \in \N$, there is a unique $E \in \ca{E}_{k-1}$ with $E' \subset E$.
 \item For each $E \in \ca{E}_k$ with $k \in \Z_{\geq 0}$, there exists $E' \in \ca{E}_{k+1}$ with $E' \subset E$.
 \item If $E_1, E_2 \in \ca{E}_k$ are distinct, then $m_H(E_1 \cap E_2)=0$. 
 \item If we define 
 \begin{equation}\label{eq: diam} 
 d_k := \sup\{\on{diam}_H(E) : E \in \ca{E}_k\}, \text{ then } \lim_{k \to \infty} d_k = 0.
 \end{equation}
 \end{itemize}
 We write
 \begin{equation*}
 \cup \ca{E}_k := \bigcup_{E \in \ca{E}_k} E
 \end{equation*}
 and define the {\sl limit set} of the collection to be $E_\infty := \bigcap_{k \in \N} \cup \ca{E}_k$.
\end{defn}
Associated to a tree-like collection $\ca{E}$ we also define, for $E \in \ca{E}_k$,
\begin{equation*}
 \on{density}(\ca{E}_{k+1},E) := \frac{m_H((\cup \ca{E}_{k+1}) \cap E)}{m_H(E)}.
\end{equation*}
Further, for each $k \in \Z_{\geq 0}$, we set 
\begin{equation}\label{eq: density}
 \Delta_k := \inf\left\lbrace \operatorname{density}(\mathcal{E}_{{k+1}}, E) : E \in \mathcal{E}_k \right\rbrace
\end{equation}
\begin{thm}[Lemma 2.1 in \cite{U}]\label{thm: urbanski}
 For a tree-like collection $\ca{E}$ and the resulting limit set $E_\infty$, we have the dimension estimate
 \begin{equation*}
 \dim H - \dim E_\infty \leq \limsup_{k \to \infty} \frac{\sum_{j=0}^{k} \log \Delta_j}{\log d_k}.
 \end{equation*}
\end{thm}

Conversely, let us assume that $x_\alpha \in E(F_+, K_i)$. Then, by the compactness of $K_i$ and by Mahler's compactness criterion, there exists an $r$ with $0< r < \sqrt{r_0}$ and a time $s_0 >0$ such that for all $s > s_0$,
 \begin{equation*}
 g_s x_\alpha \notin K_i(r).
 \end{equation*}
 In particular, 
 \begin{equation*}
 x_\alpha \cap \left\lbrace (z,w)\in \Co^2: |z| \leq e^{-s}r, |w| \leq e^{s}r \right\rbrace \neq \{(0,0)\}.
 \end{equation*}
 In particular, $\alpha \in \DI_i$ with constant $\frac{r^2}{r_0}$.
\end{proof}
This dynamical perspective on $\DI_i$ allows one to effortlessly establish certain properties of $\DI_i$ using existing techniques in ergodic theory and dynamics: the question of measure and dimension. (The interested reader may consult \cite[Theorem 1.5]{KW2} and \cite[Theorem 2.8]{AGK} where very general dynamical analogs of these questions are considered.)
In particular, we may use the above dynamical results to conclude that $\DI_i$ has measure zero but full Hausdorff dimension.
With respect to this current article, we are primarily concerned with the relation between Dirichlet improvability and bad approximability (cf. \cite[Theorems 1 and 2]{DS}).
Consider the set of badly approximable complex numbers with respect to $\Z[i]$; those $\alpha \in \Co$ for which there is a constant $c >0$ such that for all nonzero $q \in \Z[i]$,
\begin{equation*}
 |q| \min_{p \in \Z[i]} |q\alpha - p| >c.
\end{equation*}
We write this set as $\BA_i$.
\begin{ques}\label{ques: BA DI i}
 What is the relationship between Dirichlet improvability and bad approximabilty in the case of the Gaussian integers? Is it true that $\BA_i$ is a subset of $\DI_i$?
\end{ques}
We are able to provide a partial answer to this question as follows. However, it seems that a complete answer might require a further study of the set $K_i$ in Proposition \ref{prop: DIi dynamical}.

