\begin{abstract}
We investigate the overdetermined torsion problem
\begin{align}
\begin{cases}
-\Delta u = 1 & \inn \Omega\\ u=0 & \onn \partial \Omega\\ \pder{u}{\nu}=\textnormal{const.} & \onn \partial \Omega,
\end{cases}
\end{align}
where $\Omega$ is a smooth Riemannian domain. Domains admitting a solution to this problem are called \textit{Serrin domains}, after the celebrated work of Serrin \cite{Se71}, where is proved that in $\rr^n$ such domains are geodesic balls.
In the present paper we establish the existence of two distinct types of Serrin domains of $\sss^3$, respectively of small and large volume, 
each of whose boundary is connected and is neither isometric to a geodesic sphere nor to a Clifford torus. These domains arise as nontrivial perturbations of some classical symmetric solutions to the same problem. 
Our approach relies on an implicit construction based on the Crandall-Rabinowitz bifurcation theorem, which allows us to detect branches of non-radial solutions bifurcating from a family of radial ones. 
The resulting examples highlight new geometric configurations of the torsion problem in the three-dimensional sphere, providing another proof of the fact that the rigidity of Serrin-type results can fail in the presence of curvature.
\end{abstract}

\section{Introduction}
Let $(M,g)$ be a smooth Riemannian manifold and $\Omega\subset M$ a bounded, smooth domain with outer unit normal field $\nu$. Denote by $\Delta$ the negative, in the spectral sense, Laplace-Beltrami operator of $M$ (i.e., in $\rr$ we have $\Delta=\pder{^2}{x^2}$). Assuming the existence of a solution to the following boundary value problem
\begin{align}\label{Eq:Torsion}
\begin{cases}
-\Delta u = 1 & \inn \Omega\\ u=0 & \onn \partial \Omega\\ \pder{u}{\nu}= \textnormal{const.} & \onn \partial \Omega,
\end{cases}
\end{align}
in the seminal paper \cite{Se71}, J. Serrin proved that if $M=\rr^n$ then the domain $\Omega$ is forced to be a geodesic ball, hence providing one of the most fascinating and celebrated rigidity results in geometric analysis.
\medskip

\begin{remark}
What seen so far led to another deep question:
\begin{center}
\begin{enumerate}
\item[5.] \textit{Is any Serrin domain of $\sss^n$ with connected and simply connected boundary a geodesic ball?}
\end{enumerate}
\end{center}
A possible answer is suggested by the very interesting work \cite{RSW}. Here D. Ruiz, P. Sicbaldi and J. Wu constructed some domains with connected and simply connected boundary that are non-isometric to geodesic balls and that support a positive solution to the homogeneous Dirichlet problem associated to the equation $-\Delta u =\frac{u^p-u}{\e}$, for certain positive parameters $p$ and $\e$, and having constant normal derivative on $\partial \Omega$. The result is obtained by combining, in a very delicate way, a stereographic projection with a suitable bifurcation theorem (in this case the one by Krasnoselskii). Even if the differential equation considered is different from that of \eqref{Eq:Torsion}, this result seems to suggest that the answer to the question 5 might be \textit{No}.
\end{remark}

\begin{theorem}[Crandall-Rabinowitz]\label{Thm:CRBifurcation}
Let $(A,\norm{\cdot}{A})$ and $(B,\norm{\cdot}{B})$ be two Banach spaces, $\mathcal{O}\subset \rr \times A$ an open set and $I\subset \rr$ an open interval so that $I\times \{0\}\subset \mathcal{O}$. Denote by $(\lambda,\phi)$ the elements of $ \rr \times A$. Consider $G\in C^2(\mathcal{O};B)$ and suppose there exist $\lambda_*\in I$ and $a_*\in A\setminus\{0\}$ so that
\begin{enumerate}
\item $G(\lambda,0)=0$ for all $\lambda \in I$;
\item $\textnormal{ker}(D_\phi G(\lambda_*,0))=\textnormal{Span}_\rr\{a_*\}$;
\item $\textnormal{codim}(\textnormal{Im}(D_\phi G(\lambda_*,0)))=1$;
\item $D_\lambda D_\phi G(\lambda_*,0)(a_*) \notin \textnormal{Im}(D_\phi G(\lambda_*,0))$.
\end{enumerate}
Then, for any complement $\mathcal{C}$ of the space $\textnormal{Span}_\rr\{a_*\}$ in $A$ there exists a continuous curve
\begin{align}
(-\e,\e) & \to \left(\rr \times \mathcal{C}\right)\cap \mathcal{O}\\
s & \mapsto (\lambda(s),w(s))
\end{align}
such that
\begin{enumerate}
\item $\lambda(0)=\lambda_*$ and $w(0)=0$;
\item $s(a_*+w(s)) \in \mathcal{O}$ and $\lambda(s) \in I$;
\item $G\Big(\lambda(s), s(a_*+w(s))\Big)=0$;
\item there exists a neighbourhood of $(\lambda_*,0)$ in $\rr \times A$ where every solution to $G(\lambda,\phi)=0$ is either in $\left\{\Big(\lambda(s), s(a_*+w(s))\Big)\ :\ s\in (-\e,\e)\right\}$ or in $\rr\times \{0\}$.
\end{enumerate}
\end{theorem}

\begin{proposition}[Properties of $L^*$]\label{Prop:Properties_L_ball}
Let $n \in \mathbb N$. The following properties hold
\begin{enumerate}
\item $(L^*)'(0)=0$;
\item $L^*>0$ in $\left[0,\frac{\pi}{2} \right]$ and $(L^*)''(0)>0$;
\item $(L^*)'>0$ in $\left( 0,\frac{\pi}{2}\right)$.
\end{enumerate}
\end{proposition}
\begin{proof}
Multiplying the differential equation of \eqref{Eq:L^*_ball} by $\theta$ and letting $\theta \to 0^+$ yield that $(L^*)'(0)=0$.
Hence by letting $\theta \to 0^+$ in the differential equation of \eqref{Eq:L^*_ball} we have 
\begin{align}\label{the second derivative at 0}
(L^*)^{\prime\prime}(0)=\frac 12n^2L^*(0).
\end{align}

\begin{proposition}\label{Prop_Prop5.1_m=n}
Consider $\lambda_j$, with $j\geq 2$, as given in Proposition \ref{Prop_Asymptotics_Sigma_1}, point $(4)$. For every $j\geq 2$ the linear operator
\begin{align}
\mathbb{L}_j:=\mathbb{L}_{\lambda_j}^{S_2} \in \mathcal{L}(S_{2},S_1)
\end{align}
has the following properties
\begin{enumerate}
\item the kernel $\textnormal{ker}(\mathbb{L}_j)$ of $\mathbb{L}_j$ is spanned by $w_j(\xi)=\cos(j\xi)$;
\item the range $\textnormal{Im}(\mathbb{L}_j)$ of $\mathbb{L}_j$ is given by
\begin{align}
\textnormal{Im}(\mathbb{L}_j)=\left\{v\in S_1\ :\ \scal{v,w_j}=0\right\}.
\end{align}
\end{enumerate}
Moreover,
\begin{align}
\frac{\partial}{\partial \lambda}\Big|_{\lambda=\lambda_j} \mathbb{L}_j w_j \notin \textnormal{Im}(\mathbb{L}_j).
\end{align}
\end{proposition}
\begin{proof}
Let us define
\begin{align}
&S_{1}^j:=\left\{ v\in S_1\ :\ \scal{v,w_j} =0 \right\}\\
&S_{2}^j:=\left\{ v\in S_{2}\ :\ \scal{v,w_j} =0 \right\}.
\end{align}
We want to prove that $\mathbb{L}_j$ defines an isomorphism between $S_{2}^j$ and $S_{1}^j$: this, together with the fact that $\mathbb{L}_j w_j=\sigma_j(\lambda_j)w_j=0$, will provide the claims (1) and (2). By Proposition \ref{Prop_Prop4.1_m=n} we have a continuous linear operator
\begin{align}
\mathbb{L}_j:S_{2}^j\to S_{1}^j.
\end{align}
Now note that
\begin{align}\label{App1_Prop_Prop5.1_m=n}
S_{2}^j=W_2^j\cap S_{2} \quad \andd \quad S_{1}^j=W_1^j\cap S_1.
\end{align}
By Proposition \ref{Prop_Prop4.1_m=n} we have that
\begin{align}\label{App2_Prop_Prop5.1_m=n}
\mathbb{L}_j:W_2^j\to W_1^j \quad \textnormal{defines an isomorphism}
\end{align}
and so, by \eqref{App1_Prop_Prop5.1_m=n},
\begin{align}
\mathbb{L}_j:S_{2}^j\to S_{1}^j \quad \textnormal{is injective.}
\end{align}

\begin{proposition}[Properties of $L^*$]\label{Prop:Properties_L_ball_2}
Let $n \in \mathbb{N}$. The following properties hold
\begin{enumerate}
\item $L^*>0$ in $\left(0,\frac{\pi}{2} \right)$ and $L^*(0)=0$;
\item $(L^*)'>0$ in $\left( 0,\frac{\pi}{2}\right)$, and hence $L^*\left(\frac{\pi}{2}\right)>0$.
