\begin{theorem}\label{thm-disk-model} 
	Let $(X,\omega)$ be a hyperbolic Riemann surface. Let $(L,h)\to X$ be a holomorphic Hermitian line bundle with $i\Theta_h=\omega$. Let $p\in X$ have injectivity radius $r(p)$. Then for $k\geq 2$ and $(\cosh \frac{r(p)}{2})^{2k-2}>7\sqrt{k}$, we have
	\[
	\left|\rho_k(p)-\frac{1}{2\pi}(k-\frac12)\right| < 14k^{3/2}e^{-2(k-1)\log\cosh \frac{r(p)}{2}}.
	\]
\end{theorem}

ref_dict.thm-max-min:
\begin{theorem}\label{thm-max-min}
	Let $X$ be a hyperbolic Riemann surface of finite topology with no cusps. Assume further that no two systoles intersect. Then, there exists $l'>l_1$ and $k_0 > 0$ such that for all $k \geq k_0$, if the holonomies of $(kL, h^k)$ around all systoles are $1$ ($-1$, respectively), the maximum (minimum, respectively) of $\rho_k$ is attained in the exponentially small region $$\left\{ x \in X ,\Big| d(x,\gamma) < \left(\frac{\cosh\left(\frac{l_1}{2}\right)}{\cosh\left(\frac{l'}{2}\right)}\right)^{k} \right\}$$ for some systole $\gamma$.
\end{theorem}

ref_dict.thm-main:
\begin{theorem}\label{thm-main}
  Suppose that $(X,\omega)$ is a Riemann surface equipped with a complete hyperbolic metric. Let $(L,h)$ be a Hermitian holomorphic line bundle over $X$, whose curvature is $-i\omega$. We further assume that $(X,\omega)$ either has finite topology(i.e., genus of $X$ is finite), or the injectivity radius $r_X$ of $X$ is positive.  
  Let $k_0=3$ ($k_0=2$ when $X$ is compact).
  Then for all $k \geq k_0$, the Bergman kernel function $\rho_k(p)$ satisfies the following equality:
\[
\rho_k(p)
= \frac{k-\tfrac12}{2\pi}\left(1+\sum_{\gamma\in\mathfrak{G}_p}
\cosh^{-2k}\!\Big(\frac{l(\gamma)}{2}\Big)\cos\!\big(2\pi k\alpha_\gamma\big)\right).
\]

\end{theorem}

