\begin{thm} \label{lemma_lattice}
	For $d=2$ or $3$, the poset map $\Phi$ from $\HST(n,d)$ to the poset $\PP=\left(2^{\binom{[n]}{\lceil d/2 \rceil+1}}, \subseteq\right)$
	given by $\Phi:T \mapsto \sub(T)$ is an injection, and the subposet of $\PP$ induced by the image of $\Phi$ is a lattice where the meet $\sub(T_1) \wedge \sub(T_2)$ is given by the intersection $\sub(T_1)\cap \sub(T_2)$.	In particular, $\HST(n,d)$ is a lattice.
\end{thm}

