\subsection{Presentation}
\subsubsection*{The formal discrete Maxwell operator}
 Let $\boldsymbol{\epsl}$ and $\boldsymbol{\mu}$ be the permittivity and the permeability in the ambient space $\mathbf Z^3$, 
 which are the $3\times 3$ constant diagonal matrices with diagonal elements,
 $\epsl_1, \epsl_2, \epsl_3\in (0,\infty)$ for $\boldsymbol{\epsl}$, and $\mu_1,\mu_2,\mu_3 \in (0,\infty)$
 for $\boldsymbol{\mu}$.
 Letting $\mathbf Z^d=\{n=(n_1,\ldots,n_d);\; n_j\in\mathbf Z\}$, $d\ge 1$, the square lattice,
 setting $(e_1,\ldots,e_d)$ the usual euclidian basis of $\mathbf R^d$, and denoting by $\mathcal F(E;F)$
 (respect., by $\mathcal A(E;F)$) the set of functions (respect., applications) from a set $E$
 into another set $F$, we put, for $u=(u^E,u^H)\in \mathcal F(\mathbf Z^3;\mathbf C^6)$ with $u^E,u^H \in \mathcal F(\mathbf Z^3;\mathbf C^3)$,
 the isotropic discrete Maxwell operator:
\begin{equation}
\label{def.H0u}
 H_0 u = (M u^H, -M u^E),
\end{equation}
 where $M$ denotes the discrete rotational operator defined by
\begin{equation}
\label{def.hatM}
 M v = (2i)^{-1} \rotdisc v :=
 (2i)^{-1} (- D_3 v_2 + D_2 v_3, D_3 v_1 - D_1 v_3, - D_2 v_1 + D_1 v_2),
\end{equation}
 with $v=(v_1,v_2,v_3) \in \mathcal F(Z^3;\mathbf C^3)$,
 and $D_j$ denotes the discrete difference operator defined by
$$ D_j u\; (n) := u(n+e_j)- u(n-e_j) , \quad j\in [[1,d]].$$

Let $D_{\rm a}:\: \mathbf Z^3 \to \mathbf R^6$ be a function such that $D_{\rm a}(n)$ is a real positive diagonal
 of the form
\[
 D_{\rm a} = \left(\begin{array}{cc} \bfepsl_p & 0_{3\times3} \\ 0_{3\times3} &\bfmu_p
 \end{array}\right).\qedhere
\]
 We assume that $(\bfepsl_p,\bfmu_p)=(\bfepsl_0,\bfmu_0)$ is constant outside a compact set,
 $\Omega$. 
 We put $D_0= D_{\rm a}$ when $(\bfepsl_p,\bfmu_p)=(\bfepsl_0,\bfmu_0)$.
 The anisotropic Maxwell operator is defined by
\[ \HDp = D_{\rm a} H_0.\]

From now we consider the case where $\Omega$ is a paving, i.e. a bounded set of the form
 $\Omega=\Pi_{j=1}^d[[a_j,b_j]]\subset\mathbf Z^d$ with $a_j, b_j\in\mathbf Z$.
 Letting $n\in\partial\Omega$, there exists then exactly one point $m=m_\Omega(n)\in\Omega$ such that
 $n\sim m$. Hence, we define the (outgoing) normal vector field at the boundary $\partial\Omega$:
$$ \nu(n)=n-m_\Omega(n) \in \{\pm e_j;\; j\in [[1,d]]\},\quad n\in\partial\Omega.$$ 
 From now we consider the case $d=3$.
 Setting
\begin{eqnarray*}
 \partOm_k^+ &:=& \{n\in \mathbf Z^3; \; \quad n_k = b_k+1, \; n_j\in [[a_j,b_j]] 
 \quad \forall j\neq k\} ,\\
 \partOm_k^- &:=& \{n\in \mathbf Z^3; \; \quad n_k = a_k-1, \; n_j\in [[a_j,b_j]]
 \quad \forall j\neq k\} ,\\
 \partOm_k &:=& \partOm_k^+ \cup \partOm_k^- =
 \{n\in \partial\Omega; \; n_j\in [[a_j,b_j]] , \quad \forall j\neq k\} ,
\end{eqnarray*}
 we then can write the boundary as the partitions:
$$ \partial\Omega = \cup_j \partOm_j= \cup_\pm \cup_j \partOm_j^\pm ,$$
 and we have, for $n\in\partOm_k$, $\nu(n)=e_k$ if $n_k=b_k$ and $\nu(n)=-e_k$ if $n_k=a_k$.
 We put, for $u\in \mathcal A(\Omega';\mathbf C^{3})$,
$$ u\tanOm(n) := u(n) - (u(n)\cdot\nu(n))\nu(n) , \quad n\in \partial\Omega ,$$ 
$$ \partial_{\rm tan} u(n) = (u(n)-u(m_\Omega(n))) \wedge \nu(n), \quad n\in \partial\Omega,$$ 
 and, for $l\ge 1$, $u=(u^{(1)},\ldots,u^{(l)})\in \mathcal A(\Omega';\mathbf C^{3l})$,
$$
 u\tanOm=(u^{(1)}\tanOm,\ldots,u^{(l)}\tanOm), \quad \partial_{\rm tan} u(n)
