\begin{center}
 $\mathcal H(\Omega;\mathbf C^{3l}):= \{u=(u^{(1)},\ldots,u^{(l)})$; $u^{(s)}\in \mathcal A(\Omega\cup\partOm_k;\mathbf C^l)$, $k\neq j$,
 $s\in [[1,l]]\}$,
\end{center}
