\begin{equation}
\label{def.Hadm}
 \Hadm:=\{f=(f_1,f_2,f_3)\in \mathcal A(\partial\Omega;\mathbf C^3);\; f(n)\cdot \nu(n)=0 ,\: \forall n\in\partial\Omega\},
\end{equation}
