 Thanks to Corollary \ref{coro.2.5} we have $w(n;p)=0$ for $n\in \calE^-(p)$.
 Let $n_1\ge0$ and $n\in \calE_0(p-1)$. The 2nd and 4th relations in\refq{eq21.b}
 and that $w(;p)|_{\calE^-(p)}=0$ imply $w(;p)^{E/H}_3(n+e_1)=0$.
 Hence, $w^{E/H}_3(;p) = 0$ in $\calE_0(p)$.
 Then, $u$ satisfies\refq{eq1.H0u=-Vu} in $\Om$ and
\begin{equation}
\label{eq.v-w}
\left\{
\begin{array}{rcll}
 u^{E/H}_\tanOm(n) &=& 0 & n\in \partOm_1^-,\\
 \partanOm u^{E/H}(n) &=& 0 & n\in \partOm_1^-,\\
 u^{E/H}_1(n) &=& 0 & n\in \partOm_2^+\cap \calE_0(p),\\
 u^{E/H}_1(n) &=& 0 & n\in \partOm_2\cap \calE^-(p-1),\\
 u^{E/H}_3(n) &=& 0 & n\in \partOm_2^+\cap \calE_0(p+1),\\
 u^{E/H}_3(n) &=& 0 & n\in \partOm_2\cap \calE^-(p).
\end{array} \right.
\end{equation}
 Thanks to Lemma \ref{lem.2.6} we obtain that $u$ vanishes in $\calE^-(p+1)$.
 Hence, it suffices to prove\refq{rel1.wp}$\sim$\refq{rel5.wp} with $v$
 replaced by $w(;p)$ and $\calD(v;p+1)$ replaced by $\calD(w(;p),p+1)$.
 We also extend $v_j^{E/H}$ by setting $v_j^{E/H}(n)=w_j^{E/H}(n;p)$ at the points
 $n\in \calE^+(p-1)\cap [[-1,0]]\times\Z^2$ where $w_j^{E/H}(;p)$ is already
 defined and not $v_j^{E/H}$. 
\begin{itemize}
\item 
 Consequently,\refq{rel1.wp} is proved since it is proved for $w(;p)$.
\item Let $n_1\ge1$ and $n\in \calE_0(p-1)$.
 The first and 3rd relations in\refq{eq21.b} and\refq{rel1.wp} imply
 the first relation in\refq{rel2.wp} with $n$ replaced by $n+e_2$.
 Let $n_1\ge0$ and $n\in \calE_0(p-1)$. Relations\refq{eq22.a},\refq{eq22.b}
 and\refq{rel1.wp} imply the second relation in\refq{rel2.wp} (with $n$
 replaced by $n+e_1$).
 Thus,\refq{rel2.wp} is proved.
\item Let $n_1\ge1$ and $n\in \calE_0(p+1)$. The 1st relation in\refq{eq21.b}
 and\refq{rel2.wp} implies:
\begin{eqnarray*}
 2iV_3^H(n)v^H_3(n) = v_1^E(n-e_2) - v_2^E(n-e_1) - v_1^E(n+e_2) + v_2^E(n+e_1) ,
\end{eqnarray*}
 which provides the 1st relations of\refq{rel3.wp} with
 $C^H(n):= - v_1^E(n+e_2) + v_2^E(n+e_1)$.
 The same applies to $2iV_3^E(n)v^E_3(n)$. Thanks to Lemma \ref{lem.2.8}, and since
 $n+e_1$ and $n+e_2$ belong to $\calE_0(p+2)$, we see that $C^{E/H}|_{\calE_0(p+1)}$
 depends only on $\calD(v;p+1)$ and $\calV(V,p+2)$.\\
 Let $n_1\ge2$ and $n\in \calE_0(p+2)$. The 2nd relation in\refq{eq21.b} implies
\begin{eqnarray*}
 v_3^E(n-e_1) &=& v^E_3(n+e_1) + 2iV_2^H(n) v_2^H(n) - v_1^E(n+e_3) + v_1^E(n-e_3) \\
 &=:& D^E(n-e_1).
\end{eqnarray*}
 The same applies to $v_3^H(n-e_1)$.
 We obtain the 3rd relation in\refq{rel3.wp} with $n$ replaced by $n-e_1\in \calE_0(p+1)$.
 Thus, $D^{E/H}|_{\calE_0(p+1)}$ depends only on $v_|{\calE^+(p+1)}$ and $V_2^H|_{\calE_0(p+2)}$.
 Thanks to Lemma \ref{lem.2.8}, we then see that $D^{E/H}|_{\calE_0(p+1)}$ depends
 only on $\calD(v;p+1)$ and $\calV(V,p+2)$.
 Thus,\refq{rel3.wp} is proved.
\item Let $n_1\ge0$ and $n\in \calE_0(p)$. The 2nd and 4th relations in\refq{eq21.b}
 and\refq{rel1.wp} imply the first relation in\refq{rel4.wp}.
 Similarly, with the exponents $E$ and $H$ swapped.
 Thus,\refq{rel4.wp} is proved (with $n$ replaced by $n+e_1$).
\item Let $n_1\ge0$ and $n\in \calE_0(p+1)$.
 Relations\refq{eq22.a}-\refq{rel1.wp}-\refq{rel2.wp} provide:
\begin{eqnarray*}
 -2iV_2^E(n-e_2)v^E_2(n-e_2) - v_2^H(n+e_3-e_2) + v_2^H(n-e_3-e_2) \\
 + 2iV_3^E(n+e_3)v^E_3(n+e_3) - 2iV_3^E(n-e_3)v^E_3(n-e_3) + v_3^H(n+e_2-e_1) \\
 = -2iV^E_1(n+e_1)v^E_1(n+e_1) -2iV^E_2(n+e_2) v^E_2(n+e_2) 
 =: \tilde F^E(n-e_2).
\end{eqnarray*}
 We see that $\tilde F^E$ is defined on $\calE_0(p)$ and depends only on
 $v|_{\calE^+(p+1)}$ and $V|_{\calE_0(p+2)}$, and so, thanks to Lemma \ref{lem.2.8},
 only on $\calD(v;p+1)$ and $\calV(V,p+2)$.
 We replace in the above relation $2iV^{E/H}_3v^{E/H}_3$ and $v^{E/H}_3$
 by the corresponding expressions in\refq{rel3.wp}.
 We thus obtain
\begin{eqnarray*}
 -2iV_2^E(n-e_2)v^E_2(n-e_2) - v_2^H(n+e_3-e_2) + v_2^H(n-e_3-e_2) \\ \\
 = \tilde F^E(n-e_2) - C^E(n+e_3) + C^E(n-e_3) - D^H(n+e_2-e_1) \\
 =: F^E(n-e_2).
\end{eqnarray*}
 Hence, $F^E$ is defined on $\calE_0(p)$ and depends only on $\calD(v;p+1)$
 and $\calV(V,p+2)$. Similarly, with the exponents $E$ and $H$ swapped.
 Replacing $n-e_2$ by $n\in \calE_0(p)$ in the above relation we obtain\refq{rel5.wp}.
 Thus,\refq{rel5.wp} is proved.
\end{itemize}
\qed
\begin{remark}
\label{rem.v=w}
 In Lemma \refq{lem.32} we can consider that $n$ is in $\Om$ or not
 since we can extend $v$ by setting $v(n)=w(n;p)$ for $n\in \calE_0(p)$
 and $v^{E/H}_3(n)=w^{E/H}_3(n;p)$ for $n\in \calE_0(p+1)$. 
\end{remark}

