\subsection{The case of few constants}\label{ssec:few-constants}
When the constants are included in the valuation ring, several notions of convexity collapse to notions already present in the literature and thoroughly studied in \cite{aschenbrenner2019asymptotic}.

\begin{remark}[Asymptotic and pre-d-valued fields]
    Recall the following notions from \cite[Sec.~9.1, 10.1]{aschenbrenner2019asymptotic}, that a valued differential field $(\bE_*, \cO_*, \partial)$ is
    \begin{enumerate}
        \item \emph{asymptotic} if for all $x,y\prec 1$ (or equivalently, by \cite[Prop.~9.1.3]{aschenbrenner2019asymptotic}, all $x,y \notin \cO_* \setminus \co_*)$, $x\prec y \Leftrightarrow \partial x \prec \partial y$;
        \item \emph{pre-d-valued} if for all $y\preceq 1$ and all $x \prec 1$ (or equivalently all $x \notin \cO_* \setminus \co_*$), $\lder(x) \succ \partial y$;
        \item \emph{asymptotic of type H}, if it is asymptotic and furthermore for all $x\prec y\prec 1$, $\lder(x) \succeq \lder(y)$. 
    \end{enumerate}
    Also recall that every pre-d-valued field is asymptotic, \cite[Lem.~10.1.1]{aschenbrenner2019asymptotic}.
    The next Lemma shows that if the constants of $\partial$ are included in $\cO_*$ (i.e.\ there are \emph{few constants}, \cite[p.192]{aschenbrenner2019asymptotic}), then the notion of $\cO_*$-Liouville-convex specializes to the notion of a pre-d-valued field of type H and the notion of almost $\cO_*$-Liouville-convex specializes to the notion of pre-d-valued field.
\end{remark}

\begin{lemma}\label{lem:pre-d-valued}
    If $\partial$ is a derivation on $(\bE_*, \cO_*)$ with constants $\bE=\Kr(\partial) \subseteq \cO_*$, and $\val_{\cO_*}(\bE)$ divisible, then
    \begin{enumerate}
        \item if $\partial$ is $\cO_*$-valuation-convex, then $(\bE_*, \cO_*, \partial)$ is asymptotic;
        \item if $(\bE_*, \cO_*, \partial)$ is pre-d-valued if and only if $\cO_* \setminus \co_*$ is $\lder$-convex;
        \item if $(\bE_*, \cO_*, \partial)$ is pre-d-valued, then $\partial$ is $\cO_*$-valuation-convex, so $(\bE_*, \cO_*, \partial)$ is pre-d-valued if and only if it is almost Liouville-$\cO_*$-convex;
        \item if $(\bE_*, \cO_*, \partial)$ is pre-d-valued, then it is of type H if and only if it is logarithmically convex.
    \end{enumerate}
    \begin{proof}
        (1). Suppose that $\partial$ is $\cO_*$-valuation convex and $x,y\prec 1$. If $\partial x \in \cO_*\partial y \subseteq \cO_* \partial (y \cO_*)$, then by convexity $\partial x \in \partial (y \cO_*)$, so $x \in \bE+ y \cO_*$, but since $x, y \prec \bE^{\neq 0}$ by construction, this implies $x \in \cO_* y$. Similarly if $\partial x \in \co_* \partial y\subseteq \cO_* \partial (y \co_*)$ (here we are using Lemma~\ref{lem:module-derivatives}(4)),
        then $\partial x \in \partial (y \co_*)$, so by the same argument $x \prec y$.

        (2). $\cO_* \setminus \co_*$ is $\lder$-convex if and only if $\val(x) \notin \val(\bE)\Rightarrow \lder(x) \succ \partial \cO_*$. But since $\bE \subseteq \cO_*$, we have $\val(x) \notin \val(\bE) \Leftrightarrow x \not \asymp 1$ and thus this is equivalent to $\lder(x) \succ \partial \cO_*$ for all $x\not \asymp 1$ which is being pre-d-valued.

        (3)         We need to show to show that for all $y$, $\partial(y \cO_*)$ is $\preceq$-convex in $\partial \bE_*$ for all $y$, that is: $x \notin \bE+y\cO_* \Rightarrow \partial x \succ \partial (y \cO_*)$.

        Note that since $\bE \subseteq \cO_*$, we have $x \notin \bE+y \cO_* \Leftrightarrow x\succ y$.
        So if $y \not\asymp 1$, we get $\partial x \succ \partial y$. Furthermore we have $\lder(y)\succ \partial \cO_*$, so by Lemma~\ref{lem:module-derivatives}(1) $\cO_*\partial (y \cO_*)=\cO_*\partial y  + y \cO_*\partial \cO_*=\cO_* \partial y$ and we are done.

        For the case $y \in \cO_* \setminus \co_*$, note that by the hypothesis that $\val(\cO_*)$ is divisible we have $x\succ z$ for some $1\prec z \prec x$, so we can reduce to the previous case and deduce $x \succ \partial(z\cO_*)\supseteq \partial (\cO_*)$.

        (4) Note that since $\bE^{\neq0} \subseteq \cO_*\setminus \co_*$, we have that for $1\prec x\prec y$, $\not\exists c \in \bE,\, 1 \prec c \preceq y$, so (\ref{axiom:new-type-H}) is equivalent to $1 \prec x\prec y \Rightarrow \lder(x) \preceq \lder(y)$. On the other hand it is easy to see that if $1 \prec x\prec y \Rightarrow \lder(x) \preceq \lder(y)$, then (\ref{axiom:new-type-H-relative}) holds.
    \end{proof}

ref_dict.prop:height_over_absorbed:
\begin{proposition}\label{prop:height_over_absorbed}
    If $\partial\br(\partial) \prec 1$, then
    \[\height(x,\partial)=\inf\{k\in \omega: \val(\lder^k(\partial x))\in \val(\bE)\}\in \omega+1.\]
    \begin{proof}
        Set $a=\partial x$. Clearly the height of $x$ is $0$ if and only if $\val(a)\in \val(\bE)$.

        It suffices to show that for all $m\ge 0$, there is an essential approximate logarithmic scale $(y_k)_{k < m}$ with $a \sim \partial y_0$ (in the case $m>0$) if and only if $\val(\lder^k(a))\notin \val(\bE)$ for all $k<m$.

        If there is such a sequence, then $(\partial y_i)_{i<m}$ is a $\lder$-sequence by Lemma~\ref{lem:essential_log-scales_are_dagger_seq}, so $\lder^k(\partial x)\sim \lder(\partial y_0) \sim \partial y_k$ and we have $\val(\lder^k(a))\notin \val(\bE)$ for all $k<m$.

        Conversely if by $\val(\lder^k(a))\notin \val(\bE)$ for all $k<m$, then by Lemma~\ref{lem:essential_log-scales_are_dagger_seq}(2), there is an essential approximate $\partial$-logarithmic scale $(y_{k})_{k<m}$ with $\partial y_{0}\sim a=\partial x$.
    \end{proof}
\end{proposition}

ref_dict.def:v-convex_derivation:
\begin{definition}\label{def:v-convex_derivation}
    Let $(\bE_*, \cO_*)$ be a valued field and $\partial: \bE_* \to \bE_*$ be a derivation.
    I will say that a derivation $\partial$ on $\bE_*$ is \begin{enumerate}
        \item \emph{$\cO_*$-valuation-convex} if all $\cO_*$-submodules are $\partial$-convex (w.r.t.\ $\preceq_{\cO_*}$);
        \item \emph{weakly logarithmically $\cO_*$-valuation-convex} if for all $\cO_*$-modules $M\subseteq \co_*$, $1+M$ is $\lder$-convex;
        \item \emph{almost logarithmically $\cO_*$-valuation-convex} if it is almost $\cO_*$-valuation-convex and $\cO_*\setminus \co_*$ is $\lder$-convex;
        \item \emph{logarithmically $\cO_*$-valuation convex} if it is weakly logarithmically $\cO_*$-valuation-convex and for all $x,y,z$
        \begin{equation}\tag{H1}\label{axiom:new-type-H}
            (x \preceq z \preceq y \;\& \; \lder(x) \prec \lder(y)\prec \lder(z)) \Rightarrow \exists c, \; (\partial c=0 \; \& \; x \prec c \preceq y).
        \end{equation}
        \item \emph{weakly $\cO_*$-Liouville-convex} if it is valuation-convex and $1+\co_*$ is $\lder$-convex;
        \item \emph{almost $\cO_*$-Liouville-convex} if it is valuation-convex and $\cO_*\setminus\co_*$ is $\lder$-convex;
        \item \emph{$\cO_*$-Liouville-convex} if it is valuation-convex and logarithmically valuation-convex.
    \end{enumerate}
    We will often drop the ``$\cO_*$-'' in front of the definition if it is clear from the context or specified otherwise (e.g.\ saying w.r.t.\ $\cO_*$).
\end{definition}

ref_dict.def:order-convex_der:
\begin{definition}\label{def:order-convex_der}
    Let $\bE_*$ be an ordered field. We will say that $\partial: \bE_* \to \bE_*$ is \emph{order-convex}, if for all $y \in \bE_*^{\ge0}$, $[-y,y]$ is $\partial$-convex, we will say that $\partial$ is \emph{logarithmically order-convex} if for all $y \in \bE_*^{\ge1}$, $[1/y,y]$ is $\lder$-convex. We will say that it is \emph{order-Liouville-convex} if it is both order-convex and logarithmically order-convex.
\end{definition}

full_context:
Let $T$ be the theory of an o-minimal expansion of an ordered field and let $T_\mathrm{convex}$ be the (complete) theory of models of $T$ expanded by a predicate for a non-trivial $T$-convex valuation subring (cf \cite[Def.~2.7, Cor.~3.13]{dries1995t}). If $\mathcal{O}$ is a convex subring of a field $\mathbb E$ we denote by $\mathfrak{o}$ the corresponding maximal ideal. We will use the standard notations $\val_\mathcal{O}$, $\rv_\mathcal{O}$, and $\res_\mathcal{O}$, respectively for the valuation induced by $\mathcal{O}$, the rv-sort induced by $\mathcal{O}$, and the map $\res_\mathcal{O}: \mathbb E \to \mathcal{O}/\mathfrak{o}$ which is $0$ outside of $\mathcal{O}$ and is given by the quotient modulo $\mathfrak{o}$ on $\mathcal{O}$. We drop the subscript $\mathcal{O}$ if it is clear from the context.

In \cite{freni2024t}, the author introduced the $T$-$\lambda$-spherical completion of a model $(\mathbb E, \mathcal{O})\models T_\mathrm{convex}$ (where $\lambda$ is an uncountable cardinal): this is a prime elementary $\lambda$-spherically extension of $(\bE_\lambda, \cO_\lambda)\succ(\mathbb E, \mathcal{O})$, it is in general unique up to isomorphism and has the same residue field as $(\mathbb E,\mathcal{O})$, \cite[Thm.~B]{freni2024t}.

Toward the goal of better understanding these completions, it was shown in the same paper that if $T$ is simply exponential (that is, an expansion of a power-bounded o-minimal theory by a compatible exponential), then $(\bE_\lambda, \cO_\lambda)$ only realizes unary types $p$ over $\mathbb E$ which are images of some other $\mathcal{O}$-weakly immediate type $q$ over $\mathbb E$ by a $\mathbb E$-definable \emph{generalized nested exponential} (henceforth a \emph{gne}): a finite composition $g$ of translations by elements of $\mathbb E$, sign changes and exponentials \cite[Prop.~5.27 and Cor.~5.30]{freni2024t}.

In this paper I characterize those complete exponential o-minimal theories $T$ for which this fact holds true. These are called \emph{transserial} o-minimal theories and are those satisfying the following strengthening of exponential-boundedness:
\begin{enumerate}[label=(TS), ref=(TS)]
 \item\label{axiom:transserial0} for all $n\in \mathbb N$ and for all $(n+1)$-ary $T$-definable functions $f$, said 
 \[\dagger_n f(x_0, \ldots, x_{n-1}, t)=\frac{\partial f(x_0, \ldots, x_{n-1}, t)/\partial t}{f(x_0, \ldots, x_{n-1}, t)} \quad \text{if it is defined}\]
 and $\dagger_n f(\overline{x}, t)=\infty$ otherwise, and set $G_m^f(\overline{x},t)\coloneqq\min\{|(\lder^k_nf)(\overline{x},t)|: k \le m\}$ one has that for some $m \in \mathbb N$
 \[T_\mathrm{convex} \models \forall \overline{x},\; \exists r\in \mathcal{O}, \;\forall t \in \mathcal{O},\; \big(t>r \rightarrow G_m^f(\overline{x},t) < 1 \big).\]
\end{enumerate}

It turns out that for transserial theories, a similar property to the one outlined above for $T$-$\lambda$-spherical completions, is shared by other kind of extensions. So, to state the main result in a compact way, let us say that an elementary extension $(\mathbb E, \mathcal{O}) \prec (\bE_*, \cO_*)$ of models of $T_\mathrm{convex}$,
\begin{enumerate}[label=(E\arabic*)]
 \item\label{df:gne-ppty} has the \emph{gne-property} if for all elements $y\in \bE_*$, there is a $\mathbb E$-definable gne such that $\mathbf{v}(g^{-1}(y)-\mathbb E)\subseteq \mathbf{v}(\mathbb E)$.
\end{enumerate}
and recall that an elementary extension $(\mathbb E, \mathcal{O}) \preceq (\bE_*, \cO_*)\models T_\mathrm{convex}$ is said to be
\begin{enumerate}[label=(E\arabic*), resume]
 \item\label{df:res-constructible} \emph{residually constructible} (or \emph{res-constructible}, (cf \cite[Def.~14]{freni2025residually}), if there is a $\dcl_T$-basis $\overline{r}$ of $\bE_*$ over $\mathbb E$, such that $\mathbf{r}(\overline{r})$ is $\dcl_T$-independent over $\mathbf{r}(\mathbb E)$;
 \item\label{df:wim-constructible} \emph{($\lambda$-bounded) wim-constructible} (cf \cite[Def.~3.15]{freni2024t}) if there is an ordinal indexed $\dcl_T$-basis $(x_i: i<\alpha)$ of $\bE_*$ over $\mathbb E$, such that for all $j<\alpha$, $x_j$ is a pseudolimit of a p.c.\ sequence in $\mathbb E \langle x_i: i<j\rangle$ without pseudolimits therein and of length $<\lambda$.
\end{enumerate}
Also recall that by \cite[Thm.~A]{freni2024t},
\begin{enumerate}[label=(\alph*)]
 \item if $(\mathbb E, \mathcal{O}) \prec (\bE_*, \cO_*)$ is wim-constructible then $\mathbf{r}(\mathbb E, \mathcal{O})=\mathbf{r}(\bE_*, \cO_*)$, hence if $y \in \bE_*\setminus \mathbb E$, $\mathbf{v}(y-\mathbb E)\subseteq \mathbf{v}(\mathbb E)$ means that $y$ is a pseudolimit;
 \item if $(\mathbb E, \mathcal{O}) \prec (\bE_*, \cO_*)$ is residually constructible, then $\bE_*$ does not contain pseudolimits of limitless p.c. sequences in $\mathbb E$, hence if $y \in \bE_*\setminus \mathbb E$, $\mathbf{v}(y-\mathbb E)\subseteq \mathbf{v}(\mathbb E)$ means that $y=c+dz$ for some $c,d \in \mathbb E$, and $z\in \bE_*\setminus \mathbb E$ with $\mathbf{r}(z)\notin \mathbf{r}(\mathbb E, \mathcal{O})$.
\end{enumerate}
Note that a $T$-$\lambda$-spherical completion is a wim-constructible extension (in fact a maximal $\lambda$-bounded one).
The main result is thus stated as follows:

In this paper I characterize those complete exponential o-minimal theories $T$ for which this fact holds true. These are called \emph{transserial} o-minimal theories and are those satisfying the following strengthening of exponential-boundedness:
\begin{enumerate}[label=(TS), ref=(TS)]
 \item\label{axiom:transserial0} for all $n\in \bN$ and for all $(n+1)$-ary $T$-definable functions $f$, said 
 \[\dagger_n f(x_0, \ldots, x_{n-1}, t)=\frac{\partial f(x_0, \ldots, x_{n-1}, t)/\partial t}{f(x_0, \ldots, x_{n-1}, t)} \quad \text{if it is defined}\]
 and $\dagger_n f(\overline{x}, t)=\infty$ otherwise, and set $G_m^f(\overline{x},t)\coloneqq\min\{|(\lder^k_nf)(\overline{x},t)|: k \le m\}$ one has that for some $m \in \bN$
 \[T_\convex \models \forall \overline{x},\; \exists r\in \cO, \;\forall t \in \cO,\; \big(t>r \rightarrow G_m^f(\overline{x},t) < 1 \big).\]
\end{enumerate}

The name \emph{transserial}, comes from the field of logarithmic exponential transseries, where certain configurations such as formal asymptotic solutions of the equation $\log(f(x)-x)=f(\log_2(x))$ are prohibited.

The way results are obtained is an analysis of the ordered differential valued fields $(\bE\langle x\rangle, \cO_x, \partial_x)$ where
\begin{enumerate}[label=(C\arabic*)]
 \item $\bE\langle x\rangle\coloneqq\dcl_T(\bE, x)$ is a 1-$\dcl_T$-dimensional elementary extension of $\bE\models T$ and $\cO_x$ is a $T$-convex valuation subring;
 \item $\partial_x$ is the unique non-trivial $\bE$-linear $T$-derivation with $\partial_x (x)=1$ (cf \cite{fornasiero2021generic}, \cite{kaplan2023t});
 \item $\val_{\cO_x}(x-\bE)\subseteq \val_{\cO_x}(\bE)$.
\end{enumerate}

\begin{corollary}\label{cor:sOabs_to_sOabs_der}
 Let $x \in \bE_*\setminus \bE$ and $f,g,h: \bE_* \to \bE_*$ be $\bE$-definable functions. Then the following hold:
 \begin{enumerate}
 \item if $x \in \bE_* \setminus \bE$ is strongly $\cO$-absorbed and $h(x) \in (B_x^+:\cO)$, then $h'(x) \in \co_*^-$, furthermore if $\cO$ is $T$-convex, then $h'(x) \in \co_*^+$;
 \item if $x \in \bE_* \setminus \bE$ is $\cO$-wim and $f(x)\equiv_\bE g(x)$ are strongly $\cO$-absorbed, then $f(x), g(x)$ are $\cO$-wim and moreover $f'(x) \sim_{\cO_*^-} g'(x)$.
 \end{enumerate}
 \begin{proof}
 (1) is a direct application of Lemma~\ref{lem:sOabs_to_sOabs_der} with $f(x)=x$ and $g(x)=x+h(x)$. The ``furthermore'' follows from the fact that if $\cO$ is $T$-convex, and $x$ is strongly $\cO$-absorbed, then by \cite[Thm.~A]{freni2024t} $\co_*^-\cap \bE \langle x \rangle = \co_*^+\cap \bE \langle x \rangle$.
 (2) if $x$ is $\cO$-wim, then $B_x^+$ is a $\cO$-module. Furthermore since $f(x), g(x)$ are strongly $\cO$-absorbed, by Lemma~\ref{lem:wim-cofres_orto}, we must have that $f(x)$ and $g(x)$ are $\cO$-wim as well so $B_{f(x)}$ is a $\cO$-module as well, but then Lemma~\ref{lem:sOabs_to_sOabs_der}, implies $|f'(x)-g'(x)|<f'(x)/r$ for all $r \in \cO$, whence $f'(x) \sim_{\cO_*^-} g'(x)$.
 \end{proof}
\end{corollary}

\begin{proposition}\label{prop:der_order-convexity}
 Let $T$ be an exponential o-minimal theory, $\bE \prec \bE\langle x\rangle\models T$ a 1-$\dcl_T$-dimensional extension of models of $T$, and $\partial_x$ be the only $\bE$-linear $T$-derivation with $\partial_x x=1$, then for all $y \in \bE\langle x\rangle^{\neq 0}$, $[-y, y]$ is $\partial_x$-convex and $[1/y, y]$ is $\dagger_x$-convex.
 \begin{proof}
 We have to show that if $f, h$ are continuously differentiable $\bE$-definable unary functions, with $|f'(x)|\le |h'(x)|$ and $|h(x)|\le y$, then $f(x) \in \bE + [-y,y]$.
 Note that we can in fact assume that $0<|h(x)|\le y$ and that $h'(x) \neq 0$, otherwise $f'(x)=0$ and the thesis is trivial. Similarly we can assume $|f'(x)|<|h'(x)|$, because otherwise $f'=h'$ in a $\bE$-definable neighborhhod of $x$ and $f(x)-h(x)\in \bE$ and again the thesis is trivial.

\begin{corollary}\label{cor:main-cor}
 The following are equivalent:
 \begin{enumerate}
 \item every element of $\bE \langle x\rangle\setminus \bE$ has finite height over $\partial$;
 \item $(\bE\langle x\rangle, \cO_*)\succ (\bE, \cO_*\cap \bE)$ has the gne-property;
 \end{enumerate}
 If furthermore $\val_{\cO_*}(x-\bE)\subseteq \val_{\cO_*}(\bE)$, then they are equivalent to 
 \begin{enumerate}[resume]
 \item for every $y \in \bE \langle x \rangle\setminus \bE$, there is $k\in\bN$ such that $\val(\lder^k(y)) \in \val(\bE)$.
 \end{enumerate}
 \begin{proof}
 Suppose (1), then by Lemma~\ref{lem:approximate_to_exact_log_scale}, we for all $y \in \bE\langle x \rangle$ find a $\bE$-definable gne $g$ and a $z \in \bE \langle z\rangle$ with $g(z)=y$ and $\val(z-\bE)\subseteq \val(\bE)$, thus we get (2).

\begin{lemma}\label{lem:unary_functions}
 Let $T$ be an exponential o-minimal theory.
 \begin{enumerate}
 \item $T$ is weakly transserial if and only if for all $(\bE, \cO) \models T_\convex$ and every unary $\bE$-definable function $f$, there is a natural number $m$ such that
 \begin{equation}\tag{$\mathrm{WTS}^{f}_m$}
 (\bE, \cO) \models \exists r \in \cO, \forall t\in \cO, \big(t>r \rightarrow G_m^f(t) \in \cO\big).
 \end{equation}
 \item $T$ is transserial if and only if for all $(\bE, \cO) \models T_\convex$ and every unary $\bE$-definable function $f$, there is a natural number $m$ such that
 \begin{equation}\tag{$\mathrm{TS}^{f}_{m,1}$}
 (\bE, \cO) \models \exists r \in \cO, \forall t\in \cO, \big(t>r \rightarrow G_m^f(t) \le 1\big).
 \end{equation}
 \end{enumerate}
 \begin{proof}
 We prove (2), the proof of (1) is similar.
 $\Rightarrow$ is obvious.
 The converse is a compactness argument. Suppose that for some $T$-definable $n$-ary $f: \bE^{n+1} \to \bE$ we have for all $m \in \bN$
 \[T_\convex \models \exists \overline{x},\, \forall r\in \cO, \exists t\in \cO, (t > r \land G_m^f(\overline{x}, t)>1)\]
 which by weak o-minimality of $T_\convex$ is equivalent to \begin{equation}\label{eqn:strong_negation}
 T_\convex \models \exists \overline{x},\, \exists r\in \cO, \forall t\in \cO,\, (t > r \rightarrow G_m^f(\overline{x}, t)>1).
 \end{equation}
 Notice that since 
 \[G_{m+1}^f(\overline{x}, t)=\min\{G_{m}^f(\overline{x}, t), \lder_n (G_m^f)(\overline{x},t)\} \le G_{m}^f(\overline{x}, t),\]
 said 
 \[\varphi_m(\overline{x}):= \big(\exists r\in \cO, \forall t\in \cO,\, (t > r \rightarrow G_m^f(\overline{x}, t)>1)\big),\]
 we have $\varphi_{m+1}(\overline{x}) \rightarrow \varphi_{m}(\overline{x})$ hence the validity of \ref{eqn:strong_negation} for all $m$ is equivalent to the consistency of the type $p(\overline{x})=\{\varphi_m(\overline{x}): m \in \bN\}$. If $(\bE, \cO)$ is a model of $T_\convex$ realizing such type and $\overline{c} \in \bE^n$ is a realization of $p$, we get that $g(t)=f(\overline{c}, t)$ is such that for all $m$ $(\bE, \cO)\models \exists r \in \cO,\, \forall t \in \cO,\, (t>r \rightarrow G_m^g(t)>1)$.
 \end{proof}
\end{lemma}

