\begin{theorem}[Uniform Shiu bound]\label{thm:shiu} Let $q \geq 2$ be a prime power and $N \geq 1$ be an integer. Let $g : \mathcal{M} \to [0,\infty)$ be a non-negative multiplicative function on $\mathcal{M}$ satisfying $\log g(P^{\ell}) \ll \ell $  for every integer $\ell$ and monic irreducible $P$, and $g(F) \ll_{\epsilon} 2^{\epsilon \deg F}$ for every $\epsilon > 0$ and any $F \in \mathcal{M}$.  If  $A \in \mathcal{M}_N$,  $0< \beta < 1/2$, $\beta N < h \leq N-1$, and $N$ is sufficiently large depending only on $\beta$, then  
    \begin{align*}
        \sum_{\substack{F\in \mathcal{I}(A,h)}}g(F)\ll_{\beta} \frac{q^{h+1}}{N}\exp\Big(\sum_{\substack{P\in\mathcal{P}_{\leq N}}}\frac{g(P)}{q^{\deg P}}\Big). 
    \end{align*}
\end{theorem}

