\end{Thm}

ref_dict.def: Roe algebra:
\begin{Def}\label{def: Roe algebra}
The \emph{algebra Roe algebra} of $X$, denoted by $\IC[X,\H_X]$ (or $\IC[X]$ for simplicity), is a subalgebra of $\B(\H_X)$ consisting of all operators $T$ satisfying:
\begin{itemize}
\item $T$ has \emph{finite propagation} (or \emph{controlled propagation}), i.e., the \emph{support} of $T$
$$\supp(T)=\{(x,y)\in X\times X\mid T_{xy}\ne 0\},$$
is an entourage.
\item $T_{xy}\in\K(\H)$ for any $(x,y)\in X\times X$.
\end{itemize}
The completion of $\IC[X]$ in $\B(\H_X)$ is called the \emph{Roe algebra} of $X$, denoted by $C^*(X,\H_X)$ (or $C^*(X)$ for simplicity).
\end{Def}

ref_dict.cor: CElp implies ONLFin:
\begin{Cor}\label{cor: CElp implies ONLFin}
If $X$ admits a coarse embedding into $\ell^p$, then $X$ has $ONL_{\P_{Fin}}$.
\end{Cor}

ref_dict.def: geom vs ghost:
\begin{Def}\label{def: geom vs ghost}
Let $U\subseteq \beta X$ be an invariant open set. The \emph{geometric ideal} of $C^*(X)$ with respect to $U$, denoted by $\I(X, U)$, is defined to be the closed ideal generated by
$$\II[X,U]=\left\{T\in\IC[X]\ \big|\ \overline{r(\supp_{\varepsilon}(T))}\subseteq U\right\}.$$
The \emph{ghostly ideal} of $C^*_u(X)$ with respect to $U$, denoted by $\I_\G(X,U)$, is defined to be
$$\G(X,U)=\left\{T\in C^*(X)\ \big|\ \overline{r(\supp_{\varepsilon}(T))}\subseteq U\right\}.$$
\end{Def}

ref_dict.cor: maximal corollary:
\begin{Cor}\label{cor: maximal corollary}
Let $X$ be a metric space with bounded geometry that admits a coarse embedding into an $\ell^p$-space ($p\geq 1$). \begin{itemize}
\item[(1)] The canonical quotient map $\pi: C^*_{\max}(X)\to C^*(X)$ induces an isomorphism on $K$-theory, i.e.,
$$\pi_*: K_*(C^*_{\max}(X))\xrightarrow{\cong} K_*(C^*(X)).$$
\item[(2)] For any subspace $Y$, the canonical quotient map $\pi: C^*_{\max,Y,\infty}(X)\to C^*_{Y,\infty}(X)$ induces an isomorphism on the level of $K$-theory, i.e.,
$$\pi_*: K_*(C^*_{\max,Y,\infty}(X))\xrightarrow{\cong} K_*(C^*_{Y,\infty}(X)).$$
\item[(3)] For any subspace $Y$, the maximal relative coarse Baum-Connes conjecture holds for $(X, Y)$.
\end{itemize}\end{Cor}

