\begin{equation}\label{eq:FinEe}\lim_{\varepsilon\to0}\frac{1}{\varepsilon}\int_{\mathbb{T}^{3}\times \mathbb R^{3}}\left(f_{\varepsilon}(0,x,v)-\mathcal M(v)\right)|v|^{2}\,\mathrm{d} v\,\mathrm{d} x=\lim_{\varepsilon\to0}\int_{\mathbb{T}^{3}\times \mathbb R^{3}} h_\varepsilon(0,x,v) \,|v|^2 \mathrm{d} v \, \mathrm{d} x = 0\,.
\end{equation}
