In \cref{sec:lemmas}, we state and prove a few simple lemmas. We prove \cref{thm:main} in \cref{sec:proof} by inducting on the number of odd prime factors of $n$. Essentially all of the real work happens in \cref{lem:t(n)=3}. We conclude with \cref{sec:observations}, where we pose a couple questions that arose while working on this project.

\begin{lem}\label{lem:not 5 or not 3 and 5}
 Let $p\in\{3,5\}$. If $p\nmid n$, then $p\in T(n)$. In particular:
 \begin{itemize}
 \item If $5\nmid n$, then $t(n)\geq 1$.
 \item If $3,5\nmid n$, then $t(n)\geq 2$.
 \end{itemize}
\end{lem}
\begin{proof}
 Let $p\in\{3,5\}$. Then $p-1\mid 4n$, and $\gcd(4n,p)=1$ by assumption. Thus $\gcd(\frac{4n}{p-1},p)=1$, so $p\in T(n)$.
\end{proof}

\begin{lem}\label{lem:t(n)=3}
 Assume \cref{conj:main}. Let $n$ be an odd, square-free multiple of 3. Then $t(n)\geq 3$. Moreover, $t(n)=3$ if and only if $T(n)=\{5,7,13\}$.
\end{lem}
\begin{proof}
 We will induct on $\omega(n)$. Our base cases will consist of $\omega(n)\leq 4$. Note that if $p\nmid n$ for each $p\in\{5,7,13\}$, then $T(n)\supseteq\{5,7,13\}$. In particular, we may restrict our attention to multiples of these three primes. Moreover, $t(ap)\geq t(a)$ for any prime $p\not\in T(a)$ by \cref{cor:multiply by prime}, so we may assume that every prime factor $p\mid n$ is a Toda prime of some divisor of $n$.
 \begin{itemize}
 \item The case of $\omega(n)=1$ is just the calculation $T(3)=\{5,7,13\}$.
 \item For $\omega(n)=2$, we just need to compute $t(15)=t(39)=5$ and $t(21)=4$.
 \item For $\omega(n)=3$, we first compute $t(3\cdot 5\cdot 7)=9$ and $t(3\cdot 5\cdot 13)=t(3\cdot 7\cdot 13)=8$. It remains to compute, for each $p\in\{5,7,13\}$, the Toda primes of $3pq$ for each $q\in T(3p)$. Using the code provided in \cref{sec:code}, we find that $t(3pq)\geq 4$ for all such $p,q$.
 \item For $\omega(n)=4$, we first compute $t(3\cdot 5\cdot 7\cdot 13)=16$. For the remaining computations in this case, we use the code in \cref{sec:code}.
 \begin{itemize}
 \item If $\{p,q\}\subseteq\{5,7,13\}$ and $r\in T(3pq)$, then $t(3pqr)\geq 9$.
 \item If $p\in\{5,7,13\}$ and $\{q,r\}\subseteq T(3p)$, then $t(3pqr)\geq 7$.
 \item If $p\in\{5,7,13\}$, $q\in T(3p)$, and $r\in T(3pq)$, then $t(3pqr)\geq 5$.
 \end{itemize}
 \end{itemize}

\begin{cor}\label{prop:divisible by 3}
 Assume \cref{conj:main}. If $3\mid n$, then $t(n)\geq 3$.
\end{cor}
\begin{proof}
 By \cref{cor:multiply by divisor}, we may assume that $n$ is square-free. By \cref{cor:odd}, we may further assume that $n$ is odd. The result now follows from \cref{lem:t(n)=3}.
\end{proof}

Firstly, if there exists $q'\in T(3p)-\{5,7,13,q\}$ such that $q'\nmid n$, then $\{5,7,13,q,q'\}-\{p\}\subseteq T(n)$, and we are done. In fact, the Toda primes of $n$ are precisely those primes among $\{2d+1:d\mid 2n\}$ that are not factors of $n$. Thus if
\begin{equation}\label{eq:heuristic}
\{2d+1\text{ prime}:d\mid 2n\}-(\Omega(n)\cup\{5,7,13,q\})
\end{equation}
is non-empty, then $t(n)\geq 4$. Our heuristic for \cref{conj:main} is that the set $\{2d+1:d\mid 2n\}$ consists of $2^{\omega(n)+1}$ elements, while $\Omega(n)\cup\{5,7,13,q\}$ consists of $\omega(n)+3$ elements.

\begin{prop}\label{prop:t(p)}
Assume $p\geq 7$ is a prime. Let $\vphi$ denote the totient function. If $\vphi(x)=4p$ for some integer $x$, then $T(p)=\{3,5,2p+1\}$ or $\{3,5,4p+1\}$. Otherwise, $T(p)=\{3,5\}$.
\end{prop}
\begin{proof}
 One can directly check that $3,5\in T(p)$ for all primes greater than 5. Now by Euler's product formula, we have $\vphi(x)=p_1^{e_1-1}(p_1-1)\cdots p_m^{e_m-1}(p_m-1)$, where $x=\prod_{i=1}^m p_i^{e_i}$ is the prime factorization of $x$. It follows that there exists $x$ such that $\vphi(x)=4p$ if and only if one of the following cases holds:
 \begin{enumerate}[(i)]
 \item $x=2^2\cdot q$, where $q$ is an odd prime such that $q-1=2p$. In this case, $q$ is a Toda prime of $p$ with $\frac{4p}{q-1}=2$.
 \item $x=2^r\cdot 3\cdot q$, where $r\in\{0,1\}$ and $q$ is an odd prime such that $q-1=2p$. In this case, $q$ is a Toda prime of $p$ with $\frac{4p}{q-1}=2$.
 \item $x=2^r\cdot q$, where $r\in\{0,1\}$ and $q$ is an odd prime such that $q-1=4p$. In this case, $q$ is a Toda prime of $p$ with $\frac{4p}{q-1}=1$.
 \item $x=2^r\cdot 5^2$, where $r\in\{0,1\}$ (in which case $p=5$). This case is not relevant for this lemma, as we have assumed $p\geq 7$.
 \end{enumerate}
 It remains to show that no other primes can be the Toda prime of $p$. To this end, let $q>5$ be a Toda prime of $p$. Then $q-1\mid 4p$, so we either have $q-1=4p$ or $q-1=2p$ (as $q-1$ is even and $p$ is odd). The existence of such a $q$ gives us a solution to $\vphi(x)=4p$ as outlined in cases (i), (ii), and (iii).

\begin{lem}\label{lem:strategy for denoms}
 Let $d$ be a Bernoulli denominator with $F(d)=4a$ for some integer $a$. If $\{2pi+1:i\mid 2a\}$ contains a prime number for each $p\in T(a)$, then \cref{conj:general bernoulli} \eqref{conj:toda for bernoulli} holds for this Bernoulli denominator.
\end{lem}
\begin{proof}
 We know that $p-1\mid 4a$ with $\gcd(\frac{4a}{p-1},p)=1$ for all $p\in T(a)$. Thus $p-1\mid 4am$, and we have $\gcd(\frac{4am}{p-1},p)=1$ if and only if $p\nmid m$. It therefore suffices to show that if $p\mid m$ for some $p\in T(a)$, then $D_{4am}>D_{4a}$.

\begin{conj}\label{conj:main}
    Let $n$ be an odd, square-free multiple of 3. Assume that there exists $p\in\{5,7,13\}$ such that $p\mid n$, and that $r\nmid n$ for $r\in\{5,7,13\}-\{p\}$. Finally, assume there exists $q\in T(3p)-\{5,7,13\}$ such that $q\nmid n$. Then $t(n)\geq 4$.
\end{conj}

\begin{lem}\label{lem:t(n)=3}
    Assume \cref{conj:main}. Let $n$ be an odd, square-free multiple of 3. Then $t(n)\geq 3$. Moreover, $t(n)=3$ if and only if $T(n)=\{5,7,13\}$.
\end{lem}

\begin{thm}\label{thm:main}
    Assume \cref{conj:main}. If $n$ is a positive integer, then $t(n)\geq 1$. If $5\nmid n$, then $t(n)\geq 2$. If $3\mid n$, then $t(n)\geq 3$.
\end{thm}

