\]
be a sequence such that $(\omega_j)_x\to \omega_x$ and $(\ud\omega_j)_x\to (\ud\omega)_x$ for all $x\in (\R^n)^d$ and $\sup_j\max\{\|\omega_j\|_\infty,\|\ud\omega_j\|_\infty\}<\infty$. Then
\begin{align*}
\tilde\omega_j&:=P_{S_{d_0}\times S_{d_1}}\omega_j\to P_{S_{d_0}\times S_{d_1}}\omega=\omega,\\ 
\ud\tilde\omega_j&=P_{S_{d_0}\times S_{d_1}}(\ud\omega_j)\to P_{S_{d_0}\times S_{d_1}}(\ud\omega)=\ud\omega
\end{align*}
