The proof of Theorem \ref{main_thm} hinges upon several intermediate results. The key hurdles are understanding the compactness properties of a sequence of states $(u_\e,m_\e)\in \mathcal{A}_\e$ with equibounded energies, and a characterization of the two-scale limit of the magnetization. They are the subjects of Propositions \ref{compact} and \ref{prop:two_scale}, respectively. A crucial difficulty for both results is the fact that magnetization is an {\it actual} quantity and, thus, is defined and equibounded only on the deformed set. This requires a careful simultaneous analysis of the displacement and the magnetization, as well as a stability result for the inverse of the determinant of the admissible deformations. This is the main motivation for the choice of $h$ in assumption \ref{H2}, for it implies that for a bounded energy sequence not only satisfies
\begin{equation}
\label{5.15a}
 |\det\nabla w|^{-1} \in L^s(\Omega) \quad \textnormal{ for } \ s > \frac{p}{p-2}
\end{equation}
for any $w$ in the sequence, but also implies that $|\det\nabla w_\e|^{-1}$ is uniformly bounded in $L^s(\Omega)$.
\\
Our second contribution is to show in Section \ref{sec:commute} that the functional $F_{\hom}$ in \eqref{hommagnetoel} can be recovered by first linearizing magnetostrictive contribution and then passing to the homogenization limit. This is illustrated in the following diagram, where we denote by $G_{\e}^{\textrm{lin}}$ the corresponding linearized functional.

\begin{prop}
\label{prop:two_scale}
 Let $\alpha > 0$. Let $(u_\e, m_\e) \in \A_\e$ be such that $w_\e := id + \e^\alpha u_\e \in \Y$, and let
 \begin{equation*}
 \sup_{\e > 0} F_\e(u_\e, m_\e) < + \infty,
 \end{equation*}
 where the energy $F_\e$ is defined as in \eqref{resc-en}. Then we have up to a subsequence that
 \begin{equation}
 \label{5.10}
 \nabla m_\e \circ w_\e |\det\nabla w_\e|^\frac{1}{2} \wts \nabla m(x) + \nabla_y \phi(x,y) \quad \textnormal{ weakly two-scale in } L^2(\Omega \times Y; \R^3),
 \end{equation}
 where $\phi \in L^2(\Omega; H^1_\per(Y; \R^3))$.
 \qed
\end{prop}

\begin{proof}[Proof of Theorem \ref{main_thm}]
 Given our rescaled magnetoelastic energy $F_\e$ defined as in \eqref{resc-en}, we have proven already in Subsection \ref{low-bou} the $\Gamma$-liminf inequality with respect to the convergence in Propositions \ref{compact} and \ref{prop:two_scale} with respect to the homogenized functional $F_{\hom}$ defined by \eqref{hommagnetoel}. In order to deal with the upper bound for our family of energy functionals, let us firstly remark, by the subadditivity of the $\limsup$, that
 \begin{equation*}
 \begin{aligned}
 \limsup_{\e \to 0} F_\e (u_\e, m_\e)
 \le & \, \limsup_{\e \to 0} \frac{1}{\e^{2\alpha}} \int_\Omega W \left(\frac{x}{\e}, \Id + \e^\alpha \nabla u_\e(x), m_\e(x + \e^\alpha u(x)) \right) \dx \\
 + & \, \limsup_{\e \to 0} \int_\Omega a \left(\frac{x}{\e}\right) |\nabla m_\e(x + \e^\alpha u_\e(x))|^2 |\det\nabla w_\e| \dx \\
 + & \, \limsup_{\e \to 0} \, \frac{\mu_0}{2} \int_{\R^3} |\nabla \psi_{m_\e}|^2 \dx.
 \end{aligned}
 \end{equation*}
 In Subsection \ref{lim_magnetostatic} we dealt with the magnetostatic self-energy term of the energy, proving its limit. Moreover, in Subsection \ref{conv_rec_seq} we constructed the recovery sequence of admissible states, see \eqref{adm}, converging as in Propositions \ref{compact} and \ref{prop:two_scale} and we proved the optimality of the upper bound for the exchange energy term, see \eqref{opt_rec_exchange}. The last step in order to complete the proof is to deal with the elastic term of the energy.
 \\
 Let us consider the sequences constructed in \eqref{def:recoveryseq}. Keeping in mind the definition of $Q_\hom$, namely \eqref{Qhom}, and the density of the space $C^\infty_\per(\Omega; \R^3)$ in $H^1_\per(\Omega; \R^3)$, we know that for any fixed $\eta > 0$, there exists $\psi\in C^\infty_\per(\Omega; \R^3)$ such that for any $\nu \in \s^2$ we have
 \begin{equation}
 \label{almostminforelasticpart}
 \int_Y Q(y, \nabla u(x) + \nabla_y\psi(y), \nu) \dif y \le Q_\hom(\nabla u, \nu) +\eta.
 \end{equation}
 Employing \eqref{newH5}, we deduce that 
 \begin{equation*}
 \begin{aligned}
 & \limsup_{\e \to 0} \frac{1}{\e^{2\alpha}} \int_\Omega W \left( \frac{x}{\e}, \Id + \e^\alpha \left(\nabla u + \nabla_y \psi \left(\frac{x}{\e}\right)\right), m_\e(w_\e(x)) \right) \dx \\
 \le \, & \limsup_{\e \to 0} \frac{1}{2\e^{2\alpha}} \int_\Omega Q \left(\frac{x}{\e}, \e^\alpha \left(\nabla u(x) + \nabla_y \psi \left(\frac{x}{\e}\right) \right), m_\e(w_\e(x)) \right) \dx \\
 & + \limsup_{\e \to 0} \ r(\e^\alpha) \int_\Omega \left|\nabla u(x) + \nabla_y \psi\left(\frac{x}{\e}\right)\right|^2 \dx \\
 \le \, & \limsup_{\e \to 0} \frac{1}{2}\int_\Omega Q \left(\frac{x}{\e}, \nabla u(x) + \nabla_y \psi\left(\frac{x}{\e}\right), m_\e(w_\e(x)) \right) \dx \\
 = \, & \frac{1}{2} \int_\Omega \int_Y Q(y, \nabla u(x) + \nabla_y\psi(y), m(x)) \dx,
 \end{aligned}
 \end{equation*}
 where in the last equality we used the Riemann-Lebesgue Lemma and the continuity of $Q$ with respect to the third variable alongside \eqref{rs_conv_chim}. Finally, using \eqref{almostminforelasticpart}, it follows that 
 \begin{equation*}
 \begin{aligned}
 \limsup_{\e\to 0} & \int_\Omega W \left(\frac{x}{\e}, \Id + \e^\alpha \left(\nabla u + \nabla_y \psi\left(\frac{x}{\e}\right)\right), m_\e(w_\e(x)) \right) \dx \\
 \le \, & \frac{1}{2} \int_\Omega \int_Y Q(y, \nabla u(x) + \nabla_y\psi(y), m(x)) \dx \\
 \le \, & \frac{1}{2} \int_\Omega Q_\hom (\nabla u(x), m(x)) \dx + \frac{\eta}{2}|\Omega|,
 \end{aligned}
 \end{equation*}
 and by the arbitrariness of $\eta$ we get the desired upper bound for the elastic part. This concludes the proof.
\end{proof}

\begin{prop}
\label{prop:only-lin}
 Assume \ref{H1}-\ref{H5}. Then, the family of magnetoelastic energies $(F_\e^{\delta})_\delta$, given by \eqref{resc-en/delta}, $\Gamma$-converges with respect to the convergence in Proposition \ref{compact/delta} to the linearized functional $G_\e^{\textrm{lim}}$ defined by \eqref{lin-en/delta}.
\end{prop}
\begin{proof}
 We omit the proof of this proposition, for it follows by a direct adaptation of the arguments in \cite{AKM24}, along the lines of the proof of Theorem \ref{main_thm}.
\end{proof}

\begin{prop}
 Assume \ref{H1}-\ref{H5}. Then, the energies $(G_\e^{\textrm{lin}})_\e$ $\Gamma$-converge with respect to the weak topology in $W^{1,p}(\Omega;\R^3)\times H^1(\Omega;\mathbb{S}^2)$ to the homogenized functional $F_{\hom}$ in \eqref{hommagnetoel}.
 \qed
\end{prop}

