 -\Delta u + c_nRu=0 &\text{on \ } M,\\
 \frac{\partial u}{\partial\nu} + d_nhu= |u|^\frac{2}{n-2}u &\text{on \ }\partial M,
\end{cases}
\end{equation}
and 
\begin{equation}\label{minimal boundary}
\begin{cases}
 -\Delta u + c_nRu=|u|^\frac{4}{n-2}u &\text{on \ } M,\\
 \frac{\partial u}{\partial\nu} + d_nhu=0 &\text{on \ }\partial M.
\end{cases}
\end{equation}
A positive solution $u$ to \eqref{scalar flat} gives rise to a metric $\widetilde{g}:=u^{4/(n-2)}g$ on $M$, conformally equivalent to $g$, whose scalar curvature on $M$ is zero and for which the mean curvature of the boundary is constant. On the other hand, if $u$ is a positive solution to \eqref{minimal boundary}, then $\widetilde{g}:=u^{4/(n-2)}g$ is a metric on $M$, conformally equivalent to $g$, whose scalar curvature is constant and for which the mean curvature of the boundary is zero. The existence of such metrics was first studied by Escobar in \cite{e2} and \cite{e1}.
We obtain least-energy sign-changing solutions to both problems under suitable geometric assumptions on 
$M.$

Consider the quadratic form
\begin{equation}\label{eq:quadratic form}
\mathscr{Q}u:=\int_{M}(|\nabla u|^2+c_nRu^2)\,\mathrm{dv}+\int_{\partial M} d_nhu^2\,\mathrm{d} \sigma,
\end{equation}
where $\,\mathrm{dv}$ and $\,\mathrm{d} \sigma$ are the Riemannian measures on $M$ and $\partial M$ induced by the metric $g$. We assume that $M$ is \emph{positive}, this means that the first eigenvalue satisfies
\begin{align} \label{eq:M positive}
\lambda_1(M)&:=\inf_{v\in H^1(M)\smallsetminus\{0\}}\frac{\mathscr{Q}v}{\int_{M} v^2\,\mathrm{dv}}>0.
\end{align}
We prove the following results.

In this paper, we find nodal solutions to \eqref{problem} in two particular cases:
\begin{equation}\label{scalar flat}
\begin{cases}
 -\Delta u + c_nRu=0 &\text{on \ } M,\\
 \frac{\partial u}{\partial\nu} + d_nhu= |u|^\frac{2}{n-2}u &\text{on \ }\partial M,
\end{cases}
\end{equation}
and 
\begin{equation}\label{minimal boundary}
\begin{cases}
 -\Delta u + c_nRu=|u|^\frac{4}{n-2}u &\text{on \ } M,\\
 \frac{\partial u}{\partial\nu} + d_nhu=0 &\text{on \ }\partial M.
\end{cases}
\end{equation}
A positive solution $u$ to \eqref{scalar flat} gives rise to a metric $\tilde{g}:=u^{4/(n-2)}g$ on $M$, conformally equivalent to $g$, whose scalar curvature on $M$ is zero and for which the mean curvature of the boundary is constant. On the other hand, if $u$ is a positive solution to \eqref{minimal boundary}, then $\tilde{g}:=u^{4/(n-2)}g$ is a metric on $M$, conformally equivalent to $g$, whose scalar curvature is constant and for which the mean curvature of the boundary is zero. The existence of such metrics was first studied by Escobar in \cite{e2} and \cite{e1}.
We obtain least-energy sign-changing solutions to both problems under suitable geometric assumptions on 
$M.$

Consider the quadratic form
\begin{equation}\label{eq:quadratic form}
\mathscr{Q}u:=\im(|\nabla u|^2+c_nRu^2)\dv+\idm d_nhu^2\d \sigma,
\end{equation}
where $\dv$ and $\d \sigma$ are the Riemannian measures on $M$ and $\partial M$ induced by the metric $g$. We assume that $M$ is \emph{positive}, this means that the first eigenvalue satisfies
\begin{align} \label{eq:M positive}
\lambda_1(M)&:=\inf_{v\in H^1(M)\smallsetminus\{0\}}\frac{\mathscr{Q}v}{\im v^2\dv}>0.
\end{align}
We prove the following results.

\begin{theorem} \label{thm:main minimal boundary}
If $n\geq 7$ and $M$ has a nonumbilic point $\xi\in\partial M$, then the problem \eqref{minimal boundary} has a least energy sign-changing solution.
\end{theorem}

The strategy to prove Theorem \ref{thm:main scalar flat} is as follows. If $u\in H^1(M)$ is a nontrivial solution to \eqref{scalar flat}, then multiplying that problem by $u$ and integrating by parts shows that $u$ belongs to the set
$$\cN:=\Big\{u\in H^1(M): u\neq 0 \text{ and }\mathscr{Q} u=\idm |u|^{2(n-1)/(n-2)}\d \sigma\Big\}.$$
If $u$ changes sign, then multiplying \eqref{scalar flat} by the positive and negative parts $u^\pm$ of $u$ shows that $u$ belongs to
$$\cE:=\{u\in\cN:u^+\in\cN\text{ and }u^-\in\cN\}.$$ 
We define
$$\mu_1(M):=\inf_{u\in\cN}J(u)\qquad\text{and}\qquad\mu_2(M):=\inf_{u\in\cE}J(u),$$
where $J$ is the energy functional associated with problem \eqref{scalar flat} and defined in \eqref{eq:J}. As shown in Proposition \ref{prop:mu is invariant}, these are conformal invariants. The first is related to Escobar's invariant $Q(M,\partial M)$, defined in \cite{e1}, and is attained by a positive multiple of a minimizer of $Q(M,\partial M)$. Theorem \ref{thm:mu_2} sets a condition for $\mu_2(M)$ to be attained by a function $u\in\cE$ which is a solution to \eqref{scalar flat} that changes sign. Its Corollary \ref{cor:mu_2a} provides a friendlier condition in terms of a linear combination of two test functions. In Section \ref{sec:scalar flat} we show that a minimizer of $\mu_1(M)$ and a cut-off of a minimizer of $\mu_1(\mathbb{B}^n)$ for the unit ball $\mathbb{B}^n$ serve this purpose. The proof is based on the estimates provided by Escobar in \cite{e1}.

In \cite{hls} Ho, Lee and Shin defined a second Yamabe invariant for the problem \eqref{scalar flat} using the second eigenvalue of the boundary conformal Laplacian, and established a condition for its realization in terms of $Q(M,\partial M)$ and $Q(\mathbb{B}^n,\partial\mathbb{B}^n)$, similar to the condition \cite[(22)]{ah} of Ammann and Humbert. Ho and Pyo did something similar for the problem \eqref{minimal boundary} in \cite{hp}. The conditions given by our Corollaries \ref{cor:mu_2a} and \ref{cor:kappa_2a} are easier to verify. In Sections \ref{sec:scalar flat} and \ref{sec:minimal boundary} we will show that they are satisfied if $n\geq 7$ and $M$ has a nonumbilic point in $\partial M$.

\begin{corollary} \label{cor:mu_2}
If there exists $u\in H^1(M)$ such that $u^+\neq 0$, $u^-\neq 0$ and
$$\left(\frac{\mathscr{Q}u^+}{\big(\idm |u^+|^q\d \sigma\big)^{2/q}}\right)^{q/(q-2)} + \left(\frac{\mathscr{Q}u^-}{\big(\idm |u^-|^q\d \sigma\big)^{2/q}}\right)^{q/(q-2)} < Q(M,\partial M)^{q/(q-2)}+Q(\mathbb{B}^n,\partial\mathbb{B}^n)^{q/(q-2)},$$ 
then problem \eqref{scalar flat} has a least energy sign-changing solution.
\end{corollary}

\begin{corollary}\label{cor:mu_2a}
If there exist $u,v\in H^1(M)$ such that $u,v\geq 0$, $\big((1-s)u-sv\big)|_{\partial M}$ is nontrivial for all $s\in[0,1]$ and 
$$J(r(1-s)u-rsv) < \mu_1(M)+\mu_1(\mathbb{B}^n)\qquad\text{for all \ }s\in[0,1]\text{ \ and \ }r\geq 0,$$ 
then the problem \eqref{scalar flat} has a least energy sign-changing solution.
\end{corollary}

\begin{corollary}\label{cor:kappa_2a}
If there exist $u,v\in H^1(M)$ such that $u,v\geq 0$, \ $(1-s)u-sv$ is nontrivial for all $s\in[0,1]$ and 
$$I(r(1-s)u-rsv) < \kappa_1(M)+\kappa_1(\mathbb{B}^n)\qquad\text{for all \ }s\in[0,1]\text{ \ and \ }r\geq 0,$$ 
then the problem \eqref{minimal boundary} has a least energy sign-changing solution.
\end{corollary}

\begin{equation}\label{eq:J}
J(u):=\frac{1}{2}\mathscr{Q}u - \frac{1}{q}\idm |u|^q\d \sigma,
\end{equation}

\begin{equation}\label{problem}
\begin{cases}
 -\Delta u + c_nRu=\tilde Ru^{n+2\over n-2} &\text{on \ } M,\\
 \frac{\partial u}{\partial\nu} + d_nhu= \tilde h u^\frac{n}{n-2} &\text{on \ }\partial M,
\end{cases}
\end{equation}

\begin{proposition} \label{prop:mu is invariant}
The numbers $\mu_1(M)$ and $\mu_2(M)$ are conformal invariants.
\end{proposition}

\begin{theorem} \label{thm:main scalar flat}
If $n\geq 7$ and $M$ has a nonumbilic point $\xi\in\partial M$, then the problem \eqref{scalar flat} has a least energy sign-changing solution.
\end{theorem}

\begin{theorem} \label{thm:mu_2}
If
$$\mu_2(M)<\mu_1(M)+\mu_1(\mathbb{B}^n),$$ 
then there exists $u\in\cE$ such that $J(u)=\mu_2(M)$ and $J'(u)=0$, that is, $u$ is a least energy sign-changing solution of \eqref{scalar flat}.
\end{theorem}

