\begin{algorithm}[H]
\caption{Compute a lower bound on $\lambda_F$}
\label{alg_lb}
\begin{algorithmic}[1]
\Require $\varepsilon > 0$, integer $M \geq 0$
\Ensure  a lower bound on $\lambda_F$
\State $\mathcal{L}_{\text{periodic\_orbits}} \gets \textsc{FindPeriodicOrbits}(M, \varepsilon)$
\cmt{\textsc{FindPeriodicOrbits} return all periodic orbits of $T$ of length $\leq M$, approximated with error $\leq \varepsilon$}
\State $\text{bound} \gets -\infty$

\ForAll{$\text{orbit} \in \mathcal{L}_{\text{periodic\_orbits}}$}
    \State $\text{bound\_q} \gets \textsc{LowerBoundQ}(\text{orbit}, \varepsilon)$
    \cmt{\textsc{LowerBoundQ} computes a lower bound on $q(Tx)$ for all $x$ in the orbit (see Lemma~\ref{lem_lb_q})}
    \State $\text{orbit\_bound} \gets \uo{i=1}{\text{length}(\text{orbit})}{\sum} \inf \partial_s \varphi([\text{orbit}[i]-\varepsilon,\text{orbit}[i]+\varepsilon], \text{bound\_q}[i])$
    \cmt{\eqref{in_lf}}
    \State $\text{bound} \gets \max(\text{bound}, \text{orbit\_bound})$
\EndFor
\State  \Return $\text{bound}$
\end{algorithmic}
\end{algorithm}

