\begin{prop}\label{prop: counterexample}
  Let $\lambda^{(1)} / \mu^{(1)}, \ldots, \lambda^{(k)} / \mu^{(k)}$
  be a collection of connected skew shapes
  that is not essentially $(3 \times 2)$-avoiding.
  Then there exists a multinetwork $\vec{H}$ for this collection satisfying $ f_1(\beta(\vec{H})) = \sgn(\beta(\vec{H})) < 0$.
\end{prop}

