 \mu:=\frac{n-2}{2}-\sqrt{\left( \frac{n-2}{2}\right)^2-\gamma}, \qquad A(n,\gamma):=\left(\frac{n(n-2-2\mu)^2}{n-2}\right)^{\frac{n-2}{4}},
\end{equation*}
and $\lambda>0$ is a scaling factor. Obviously, $\mathcal{U}_\lambda=\mathcal{V}_{\lambda,0}$ if $\gamma=0$.

The case of $p$-Lapalce operator was firstly treated in \cite{abdellaoui}, where the authors studied the existence of solutions to \eqref{eq:HardySobolev} and a very fine ODE's analysis was carried out. The radial symmetry of the solutions there was an assumption. In \cite{OSV} the authors proved that each solution to \eqref{eq:HardySobolev} with finite energy is radially symmetric (and radially decreasing) about the origin. Having in force the radial symmetry of the solution it is easy to derive the ordinary differential equation associated to the PDE and fulfilled by the solution $u = u(r)$ and, hence, to apply the results in \cite{abdellaoui}. In particular, they proved also uniqueness up to scaling of the \emph{radial} solutions as well as the asymptotic behavior are proved showing in particular that, a \emph{radial} solution \eqref{eq:HardySobolev}, satisfy the following properties:
\begin{equation*}
 \begin{split}
 &\mathcal{U}_{p,\lambda}(x)= \lambda^\frac{ p-n}{p} \mathcal{U}_p\left(\frac{x}{\lambda}\right) \quad \text{ with } \quad \mathcal U_p(x)= u(r)\\
 &\lim_{r\to0^+} r^{\mu_1} \mathcal U_p(r)=C_1,\qquad \lim_{r\to+\infty}r^{\mu_2} \mathcal U_p(r)=C_2,\\
 &\lim_{r\to0^+} r^{\mu_1+1} |\mathcal U_p'(r)|=C_1\mu_1,\qquad \lim_{r\to+\infty}r^{\mu_2+1}|\mathcal{U}_p'(r)|=C_2\mu_2,
 \end{split}
\end{equation*}
for some positive constants $C_1, C_2$. {Obviously, $\mathcal{U}_{p,\lambda}=\mathcal{U}_{\lambda}$ and $\mathcal{U}_{p}=\mathcal{U}$ if $p=2$.} Here and in the sequel $\mu_1, \mu_2\in [0, +\infty)$, $\mu_1<\mu_2$ are two roots of the equation
\begin{equation*}
\mu^{p-2}\left[(p-1)\mu^2-(n-p)\mu\right]+\gamma=0.
\end{equation*}
We remark (for later use) that
\begin{equation*}\label{relgammaj}
0\le \mu_1<\frac{n-p}{p}<\mu_2\le \frac{n-p}{p-1}.
\end{equation*}
Note that when $p=2$ then $\mu_{1}=\tau$ and $\mu_2=n-2-\tau$. Instead, when $p\neq 2$ but $\gamma=0$ then $\mu_1=0$ and $\mu_2=\frac{n-p}{p-1}$.\\

The primary objective of this paper is to show that any positive solutions, with finite energy, to problem \eqref{P} is radially symmetric and radially decreasing around the origin, in the same spirit of \cite{ELS}.

\begin{rem}
This result holds (and is new) also in the case $\gamma=0$. 
\end{rem}

Now, we state the upper and lower estimates of the solutions and the upper one of their gradient, contained in \cite{KL20}, in our case.
\begin{thm} \label{thm:asymptEst}$($Theorem $1.1$, \cite{KL20}$)$
 Let $(u,v) \in \mathcal{D}^{1,p}(\R^n)\times \mathcal{D}^{1,p}(\R^n)$ be a weak solution of \eqref{P}
 with $1<p<n$, $0 \leq \gamma < \Lambda_{n,p}$, $\alpha+\beta=p^*$. Then there exist positive constants $0 < R_0< 1 < R_1$ depending on $n, p, \gamma, \nu, \alpha,\beta$, $u$ and $v$, such that
 \begin{equation}\label{eq:estat0}
 \frac{c_1^u}{|x|^{\mu_1}} \leq u(x) \leq \frac{C_1^u}{|x|^{\mu_1}},\quad \frac{c_1^v}{|x|^{\mu_1}} \leq v(x) \leq \frac{C_1^v}{|x|^{\mu_1}} \qquad x \in B_{R_0}\setminus\{0\},
 \end{equation}
 and
 \begin{equation}\label{eq:estatInf}
 \frac{c_2^u}{|x|^{\mu_2}} \leq u(x) \leq \frac{C_2^u}{|x|^{\mu_2}},\quad \frac{c_2^v}{|x|^{\mu_2}} \leq v(x) \leq \frac{C_2^v}{|x|^{\mu_2}} \qquad x \in (B_{R_1})^c,
 \end{equation}

\begin{thm}\label{stimagradiente1}$($Theorem $1.3$, \cite{KL20}$)$
 Let $(u,v) \in \mathcal{D}^{1,p}(\R^n)\times \mathcal{D}^{1,p}(\R^n)$ be a weak solution of \eqref{P}
 with $1<p<n$, $0 \leq \gamma < \Lambda_{n,p}$ and $\alpha+\beta=p^*$. Then there exist positive constants $\tilde C^u$, $\tilde C^v$ depending on $n,p, \gamma, \nu, \alpha,\beta$ and $u$ or $v$, respectively, such that
 \begin{equation}\label{eq:estat0grada}
 |\nabla u(x)| \leq \frac{\tilde C^u}{|x|^{\mu_1+1}}, \quad |\nabla v(x)| \leq \frac{\tilde C^v}{|x|^{\mu_1+1}} \qquad x \in B_{R_0},
 \end{equation}
 and
 \begin{equation}\label{eq:estatInfgrada}
 |\nabla u(x)| \leq \frac{\tilde C^u}{|x|^{\mu_2+1}}, \quad |\nabla v(x)| \leq \frac{\tilde C^v}{|x|^{\mu_2+1}} \qquad x \in (B_{R_1})^c,
 \end{equation}
where $\mu_1, \mu_2$ are roots of \eqref{eq:algebraicHardy} as in Theorem \ref{thm:asymptEst}, and $0 < R_0< 1 < R_1$ are constants depending on $n, p, \gamma,\nu, \alpha,\beta$, $u$ and $v$.
\end{thm}

\begin{thm}\label{stimagradiente2}
 Let $(u,v) \in \mathcal{D}^{1,p}(\R^n)\times \mathcal{D}^{1,p}(\R^n)$ be a weak solution of \eqref{P}
 with $1<p<n$, $0 \leq \gamma < \Lambda_{n,p}$ and $\alpha+\beta=p^*$. Then there exist positive constants $\tilde c^u$, $\tilde c^v$ depending on $n,p, \gamma, \nu, \alpha,\beta$ and $u$ or $v$, respectively, such that
 \begin{equation}\label{eq:estat0gradb}
 |\nabla u(x)| \geq \frac{\tilde c^u}{|x|^{\mu_1+1}}, \quad |\nabla v(x)| \geq \frac{\tilde c^v}{|x|^{\mu_1+1}} \qquad x \in B_{R_2},
 \end{equation}
 and
 \begin{equation}\label{eq:estatInfgradb}
 |\nabla u(x)| \geq \frac{\tilde C^u}{|x|^{\mu_2+1}}, \quad |\nabla v(x)| \geq \frac{\tilde C^v}{|x|^{\mu_2+1}} \qquad x \in (B_{R_3})^c,
 \end{equation}
where $\mu_1, \mu_2$ are roots of \eqref{eq:algebraicHardy} as in Theorem \ref{thm:asymptEst}, and $0 < R_2< 1 < R_3$ are constants depending on $n, p, \gamma,\nu, \alpha,\beta$, $u$ and $v$.
\end{thm}

