The post-theorem text does not give a proof sketch for the main theorem. It only comments that the estimate
\begin{equation}\label{kato}\left(\sup _{0<x<+\infty} \int_{0}^{T}\left|\partial_{x}^{s+1} u(x, t)\right|^{2} d t\right)^{\frac{1}{2}} \leq C\left(\|u_0\|_{H^{s}\left(\R^{+}\right)}+\|f\|_{H^{\frac{s+1}{3}}(0, T)}\right);
\end{equation}
is “Kato's smoothing effect” and is “crucial to obtain propagation of the regularity result for nonlinear dispersive equations in general.”

The only explicit proof-outline present is for the following theorem.

\begin{thm}\label{thm1}
 If $u_{0} \in H^{3 / 4^{+}}(\mathbb{R}^+)$ and $f\in H^{\frac{3}{2}^+}(\R^+)$ for some $l \in \mathbb{Z}^{+}, l \geq 1$ and $x_{0} \in \mathbb{R}^+$

	\begin{equation}\label{hipl}
	\left\|\partial_{x}^{l} u_{0}\right\|_{L^{2}\left(\left(x_{0}, \infty\right)\right)}^{2}=\int_{x_{0}}^{\infty}\left|\partial_{x}^{l} u_{0}(x)\right|^{2} d x<\infty,
	\end{equation}
	then  for any $v \geq 0, \epsilon>0$ and $R>0$ hold the following statements for the solutions $u(t)$ on $[0,T]$ of the IBVP \eqref{IBVP} given by the following theorem: \begin{thm}\label{katot}
For $s>\frac{3}{4}$, if $u_0 \in H^{s}\left(\R^{+}\right)$and $f \in H_{l o c}^{\frac{s+1}{3}}\left(\R^{+}\right)$ satisfy certain compatibility conditions at $(x,t)=(0,0)$, then the IBVP \eqref{IBVP} admits a unique solution
$$
u \in C\left(0, T ; H^{s}\left(\R^{+}\right)\right) \cap L^{2}\left(0, T ; H_{l o c}^{s+1}\left(\R^{+}\right)\right),
$$
which satisfies the additional properties

\begin{equation}\label{reg-trace}
\partial_x^ju \in C(\R^+; H^{\frac{s-j+1}{3}}((0,T))),\ j\in \{0,1,2,3,...\};
\end{equation}
\begin{equation}\label{kato}\left(\sup _{0<x<+\infty} \int_{0}^{T}\left|\partial_{x}^{s+1} u(x, t)\right|^{2} d t\right)^{\frac{1}{2}} \leq C\left(\|u_0\|_{H^{s}\left(\R^{+}\right)}+\|f\|_{H^{\frac{s+1}{3}}(0, T)}\right);
\end{equation}
\begin{equation}\label{stri}
\left(\int_{0}^{T} \sup _{0<x<+\infty}\left|\partial_{x} u(\cdot, t)\right|^{4} d t\right)^{\frac{1}{4}} \leq C\left(\|u_0\|_{H^{s}(\R^+)}+\|f\|_{H^{\frac{s+1}{3}}(0, T)}\right)
\end{equation}
and
\begin{equation}
\left(\int_{0}^{+\infty} \sup _{0 \leq t \leq T}|u(x, t)|^{2} d x\right)^{\frac{1}{2}} \leq C\left(\|u_0\|_{H^{s}(\R^+)}+\|f\|_{H^{\frac{s+1}{3}}(0, T)}\right),
\end{equation}
where the constants depend only on $s$ and $T$.
\end{thm}:
	\begin{itemize}
\item[(a)] (Propagation of regularity) There exists $C>0$ such that
	$$
	\sup _{0 \leq t \leq T^*} \int_{\max\{ x_{0}+\epsilon-v t,0\}}^{\infty}\left(\partial_{x}^{j} u\right)^{2}(x, t) d x<C,
	$$
	where $T^*=T$ if $j=1$ and $T^*=\min\left\{T,\frac{x_0+\epsilon}{v}\right\}$; $j=2, \ldots, l$.
	In particular, for all $t \in(0, T^*]$, the restriction of $u(\cdot, t)$ to any interval $\left(x_{0}, \infty\right)$ belongs to $H^{l}\left(\left(x_{0}, \infty\right)\right)$.
\item[(b)] (Kato smoothing effect)	For any $v\geq 0$, $\epsilon>0$, $R>0$ and $T^*=T$ if $j=1$ and $T^*=\min\left\{T,\frac{x_0+\epsilon}{v}\right\}$; $j=2, \ldots, l$.
	$$
	\int_{0}^{T^*} \int_{\max\{ x_{0}+\epsilon-v t,0\}}^{x_{0}+R-v t}\left(\partial_{x}^{l+1} u\right)^{2}(x, t) d x d t<C.
	$$

	\item[(c)] (Trace estimate) Additionally, for  $T^*=\min\left\{T,\frac{x_0+\epsilon}{v}\right\}$, we have the following estimate for the trace: 
	 \be
	 \int_{\frac{b+x_0}{v}}^{T^*}(\partial_{x}^{2}u(0,t))^2d t\leq C.
	 \ee

		\end{itemize}
		(The constant $C$ depends on the numbers  $\left\|u_{0}\right\|_{H^{{3/4}^{+}}(\R^+)}$ $\left\|\partial_{x}^{l} u_{0}\right\|_{L^{2}\left(\left(x_{0}, \infty\right)\right)}$, $\|f\|_{H^{\frac{3}{2}^+}(\R^+)},$ $l,$ $v$, $\epsilon$ and  $T$.)
\end{thm}

The outline given there is: “The argument of the proof initially follows the ideas of \cite{Isaza}, but we need to take care with the trace terms… The main ingredients are the use of some Kato smoothing effects combined with a interpolation inequality, which is essential to control some problematic traces terms.”

