pre_theorem_intro_text:
\label{s1}

We are concerned with the 3D incompressible Navier-Stokes equations,
\begin{equation}\begin{split}
&\partial_tv-\nu\Delta v+v\cdot\nabla v+\nabla p=f,\cr
&{\rm div}\, v=0\quad {\rm in}\ \ \Omega^T,\cr
\end{split}
\label{1.1}
\end{equation}
under the axisymmetry constraint, where $\Omega^T:=\Omega\times(0,T)$, $T>0$, \\$v=v(x,t)\in{\Bbb R}^3$ denotes the velocity field, $p=p(x,t)\in{\Bbb R}$ denotes the pressure function, $f=f(x,t)\in{\Bbb R}^3$ denotes the external force field, $\nu>0$ denotes the viscosity, and $x=(x_1,x_2,x_3)$ denotes the Cartesian coordinates. As for $\Omega$ we focus on the case of a finite cylinder,
$$
\Omega=\{x\in{\Bbb R}^3\colon x_1^2+x_2^2<R^2,|x_3|<a\},
$$
where $a$, $R>0$ are constants. We note that
$$
S:=\partial\Omega=S_1\cup S_2,
$$
where
\[
\begin{split}
&S_1=\{x\in{\Bbb R}^3\colon\sqrt{x_1^2+x_2^2}=R,\ x_3\in[-a,a]\},\\
&S_2=\{x\in{\Bbb R}^3\colon\sqrt{x_1^2+x_2^2}<R,\ x_3\in\{-a,a\}\}
\end{split}
\]
denote the lateral boundary and the top and bottom parts of the boundary, respectively.

In order to state the boundary conditions stating our main result we use the cylindrical coordinates $r$, $\varphi$, $z$ defined by
$$
x_1=r\cos\varphi,\quad x_2=r\sin\varphi,\quad x_3=z,
$$
and we will use standard cylindrical unit vectors, so that, for example
$$
v=v_r\bar e_r+v_\varphi\bar e_\varphi+v_z\bar e_z.
$$
We will denote partial derivatives by using the subscript comma notation, e.g.
$$
v_{r,z}:=\partial_zv_r.
$$
We assume the boundary conditions
\begin{equation}\begin{aligned}
&v_r=v_\varphi=\omega_\varphi=0 &{\rm on }\ \ S_1^T=S_1\times(0,T),\\
&v_z=\omega_\varphi=v_{\varphi,z}=0 &{\rm on}\ \ S_2^T=S_2\times(0,T),
\end{aligned}
\label{1.2}
\end{equation}
where $\omega:={\rm curl}\, v$ denotes the vorticity vector and we assume the initial condition
\begin{equation}
v|_{t=0}=v_0,
\label{1.3}
\end{equation}
where $v_0$ is a given divergence-free vector field satisfying the same boundary conditions.

We note that such boundary conditions have first appeared in the work of Ladyzhenskaya \cite{L}. In a sense, the boundary conditions (\ref{1.2}) are natural, since, when considering the vorticity-stream function formulation we need $\omega_\varphi|_S$. This together with the no-penetration condition naturally lead to (\ref{1.2}).

We will denote the swirl by
\begin{equation}
u:=rv_\varphi.
\label{1.4}
\end{equation}
Note that
\begin{equation}
\begin{aligned}
    &\omega_r=-v_{\varphi,z}=-{1\over r}u_{,z},\cr
&\omega_\varphi=v_{r,z}-v_{z,r},\cr
&\omega_z={1\over r}(rv_\varphi)_{,r}=v_{\varphi,r}+{v_\varphi\over r}={1\over r}u_{,r},\cr
\end{aligned}
\label{1.5}
\end{equation}
so that the boundary conditions (\ref{1.2}) imply in particular that
\begin{equation}\eqal{
&\omega_r=v_{z,r}=u=0,\ \ \omega_z=v_{\varphi,r}\quad &{\rm on}\ \ S_1^T,\cr
&\omega_r=v_{r,z}=\omega_{z,z}=u_{,z}=0\quad &{\rm on}\ \ S_2^T.\cr}
\label{1.6}
\end{equation}
The Navier-Stokes equations (\ref{1.1}) in cylindrical coordinates become
\begin{equation}\eqal{
&v_{r,t}+v\cdot\nabla v_r-{v_\varphi^2\over r}-\nu\Delta v_r+\nu{v_r\over r^2}=-p_{,r}+f_r,\cr
&v_{\varphi,t}+v\cdot\nabla v_\varphi+{v_r\over r}v_\varphi-\nu\Delta v_\varphi+\nu{v_\varphi\over r^2}=f_\varphi,\cr
&v_{z,t}+v\cdot\nabla v_z-\nu\Delta v_z=-p_{,z}+f_z,\cr
&(rv_r)_{,r}+(rv_z)_{,z}=0,\cr}
\label{1.7}
\end{equation}
where
$$
v\cdot\nabla=(v_r\bar e_r+v_z\bar e_z)\cdot\nabla=v_r\partial_r+v_z\partial_z,\quad \Delta u={1\over r}(ru_{,r})_{,r}+u_{,zz}.
$$
On the other hand, the vorticity formulation becomes
\begin{equation}\eqal{
&\omega_{r,t}+v\cdot\nabla\omega_r-\nu\Delta\omega_r+\nu{\omega_r\over r^2}=\omega_rv_{r,r}+\omega_zv_{r,z}+F_r,\cr
&\omega_{\varphi,t}+v\cdot\nabla\omega_\varphi-{v_r\over r}\omega_\varphi-\nu\Delta\omega_\varphi+\nu{\omega_\varphi\over r^2}={2\over r}v_\varphi v_{\varphi,z}+F_\varphi,\cr
&\omega_{z,t}+v\cdot\nabla\omega_z-\nu\Delta\omega_z=\omega_rv_{z,r}+\omega_zv_{z,z}+F_z,\cr}
\label{1.8}
\end{equation}
where $F:={\rm curl}\, f$ and the swirl is a solution to the problem
\begin{equation}\eqal{
&u_{,t}+v\cdot\nabla u-\nu\Delta u+{2\nu\over r}u_{,r}=rf_\varphi:=f_0,\cr
&u=0\quad &{\rm on}\ \ S_1^T,\cr
&u_{,z}=0\quad &{\rm on}\ \ S_2^T,\cr
&u|_{t=0}=u_0=rv_{\varphi}(0)\quad &{\rm in}\ \ \Omega.\cr}
\label{1.9}
\end{equation}
We will use the notation
\begin{equation}
(\Phi,\Gamma)=\bigg({\omega_r\over r},{\omega_\varphi\over r}\bigg),
\label{1.10}
\end{equation}
and we note that $\Phi$, $\Gamma$ satisfy
\begin{equation}
\Phi_{,t}+v\cdot\nabla\Phi-\nu\bigg(\Delta+{2\over r}\partial_r\bigg)\Phi-(\omega_r\partial_r+\omega_z\partial_z){v_r\over r}=F_r/r\equiv\bar F_r,
\label{1.11}
\end{equation}
\begin{equation}
\Gamma_{,t}+v\cdot\nabla\Gamma-\nu\bigg(\Delta+{2\over r}\partial_r\bigg)\Gamma+2{v_\varphi\over r}\Phi=F_\varphi/r\equiv\bar F_\varphi,
\label{1.12}
\end{equation}
recall (\cite{CFZ}, (\ref{1.6})). Moreover, by (\ref{1.2}), (\ref{1.6}), $\Gamma$ and $\Phi$ satisfy the boundary conditions
\begin{equation}
\Phi=\Gamma=0\quad {\rm on}\ \ S^T.
\label{1.13}
\end{equation}
Finally, the following initial conditions are assumed
\begin{equation}
\Phi|_{t=0}=\Phi_0,\quad \Gamma|_{t=0}=\Gamma_0.
\label{1.14}
\end{equation}
We note that $(\ref{1.7})_4$ implies existence of the stream function $\psi$ which solves the problem
\begin{equation}\begin{split}
&-\Delta\psi+{\psi\over r^2}=\omega_\varphi,\cr
&\psi|_S=0.\cr
\end{split}
\label{1.15}
\end{equation}
Then $v$ can be expressed in terms of the stream function,
\begin{equation}
\begin{aligned}
    &v_r=-\psi_{,z}, &&v_z={1\over r}(r\psi)_{,r}=\psi_{,r}+{\psi\over r},\cr
&v_{r,r}=-\psi_{,zr}, &&v_{z,z}=\psi_{,rz}+{\psi_{,z}\over r},\cr
&v_{r,z}=-\psi_{,zz}, &&v_{z,r}=\psi_{,rr}+{1\over r}\psi_{,r}-{\psi\over r^2}.
\end{aligned}
\label{1.16}
\end{equation}
We will also use the modified stream function,
\begin{equation}
\psi_1:={\psi\over r},
\label{1.17}
\end{equation}

which satisfies
\begin{equation}\begin{split}
-&\Delta\psi_1-{2\over r}\psi_{1,r}=\Gamma,\cr
&\psi_1|_S=0.\cr
\end{split}
\label{1.18}
\end{equation}
Using the modified stream function we can express coordinates of $v$ in the form
\begin{equation}
\begin{aligned}
    &v_r=-r\psi_{1,z},\quad &v_z=(r\psi_1)_{,r}+\psi_1=r\psi_{1,r}+2\psi_1,\cr
&v_{r,r}=-\psi_{1,z}-r\psi_{1,rz},\quad &v_{z,r}=3\psi_{1,r}+r\psi_{1,rr},\cr
&v_{r,z}=-r\psi_{1,zz},\quad &v_{z,z}=r\psi_{1,rz}+2\psi_{1,z}.\cr
\end{aligned}
\label{1.19}
\end{equation}
Projecting $(\ref{1.18})_1$ on $S_2$, using $(\ref{1.18})_2$ and that $\Gamma|_{S_2}=0$ by (\ref{1.2}), we obtain
\begin{equation}
\psi_{1,zz}=0\quad {\rm on}\ \ S_2.
\label{1.20}
\end{equation}
Since in this paper we are looking for regular solutions to problem (\ref{1.1})--(\ref{1.3}), we need the following expansions near the axis of symmetry due to Liu-Wang (see \cite{LW}),
\begin{equation}
\begin{aligned}
    &v_r(r,z,t)=a_1(z,t)r+a_2(z,t)r^3+\dots,\cr
&v_\varphi(r,z,t)=b_1(z,t)r+b_2(z,t)r^3+\dots,\cr
&\psi(r,z,t)=d_1(z,t)r+d_2(z,t)r^3+\dots,\cr
&\psi_1(r,z,t)=d_1(z,t)+d_2(z,t)r^2+\dots,\cr
&\psi_{1,r}(r,z,t)=2d_2(z,t)r+\dots,.\cr
\end{aligned}
\label{1.21}
\end{equation}
In order to formulate the main results we introduce constants which depend on the initial data and forcing
\begin{notation}\label{n1.1}
\[
\begin{aligned}
    &D_1=|f|_{2,1,\Omega^t}+|v(0)|_{2,\Omega}\quad &({\rm see}\ (\ref{2.5}),\cr
&D_2=|f_0|_{\infty,1,\Omega^t}+|u(0)|_{\infty,\Omega},\;f_0=rf_\varphi,\;u(0)=r\varphi (0) &({\rm see}\ (\ref{2.6})),\cr
&D_*=\min\{1,D_2\}\quad &({\rm see}\ (\ref{3.15})),\cr
&D_3=\frac{1}{\sqrt{2\nu}}\left(|\bar F_r|_{6/5,2,\Omega^t}+|\bar F_\varphi|_{6/5,2,\Omega^t}\right)+|\Phi(0)|_{2,\Omega}+|\Gamma(0)|_{2,\Omega}\quad &({\rm see}\ (\ref{3.16})),\cr
\end{aligned}
\]
where $\bar F_r=F_r/r$, $\bar F_\varphi=F_\varphi/r$,
\[
\begin{aligned}
  &D_4={1\over\sqrt{\nu}}(D_1+D_2+|u_{,z}(0)|_{2,\Omega}+|f_0|_{2,\Omega}) &({\rm see}\ (\ref{2.13})),\cr
&D_5^2=D_1^2(1+D_2)+D_1^2D_2^2+|u_{,r}(0)|_{2,\Omega}^2+|f_0|_{2,\Omega^t}^2\quad &({\rm see}\ (\ref{2.14})),\cr
&D_6^2=(D_4+D_5)\|f_\varphi\|_{L_2(0,t;L_5(S_1))}\cr
&\quad+{1\over\nu}(|F_r|_{6/5,2,\Omega^t}^2+|F_z|_{6/5,2,\Omega^t}^2)+ |\omega_r(0)|_{2,\Omega}^2+|\omega_z(0)|_{2,\Omega}^2 &({\rm see}\ (\ref{2.15})),\cr
&D_7=D_2^{1/2}|f_\varphi/r|_{\infty,1,\Omega^t}^{1/2}+|v_\varphi(0)|_{\infty,\Omega}\quad &({\rm see}\ (\ref{2.16})),\\
&D_8=\frac{D_2^{4-2{\delta}}}{4\nu}\frac{R^{2{\delta}}}{{\delta}^2}D_1 &({\rm see}\ Lemma \; \ref{l3.1}),\\
&D_9=\lp{f_\varphi}{10/(1+6{\delta}),{\Omega^t}}{}D_1^{3-2{\delta}}&({\rm see}\ Lemma  \;\ref{l3.1}).\\
\end{aligned}
\]

We emphasize that the global well-posedness of axially symmetric solutions to the Navier-Stokes equations (either in the above setting of on $R^3$) remains an important open problem. We only note a few references on this topic [\cite{CFZ}, \cite{KP}, \cite{NZ}, \cite{NZ1}, \cite{NP1}, \cite{NP2}, \cite{OP}].
\end{notation}

