{\textit{ If a suitable weak solution to the stationary Navier-Stokes system develops a singularity, 
 can it asymptotically become self-similar?}}

Our main result in this direction can be stated as follows:

\begin{equation}\label{eq:problem}
\left.\begin{array}{rrr}
u^ju^i_j+P_i=\Delta u^i, \quad i=1, 2, 3, 4, 5,\\
\div u =0,
\end{array}
\right\}
\quad\mbox{in}\ \Omega\subset \R^5
\end{equation}

\begin{equation}\label{eq:problem-3d}
\left.\begin{array}{rrr}
u_t^i+u^ju^i_j+P_i=\Delta u^i, \quad i=1, 2, 3,\\
\div u =0,
\end{array}
\right\}
\mbox{in}\ \Omega\times(0, T), \Omega\subset \R^3.
\end{equation}

{\textit{ If a suitable weak solution to the stationary Navier-Stokes system develops a singularity, 
 can it asymptotically become self-similar?}}

If $\liminf_{r\to 0}M(r)<\infty$
then the singularity may occur only if the function 
\begin{equation}
\text{\Large$\wp$}(r) =\frac{1}{r^2} \int_{B_r} \Big\{{|u|^2} + 2P \Big\} (u\cdot \frac{x}{|x|}) \, dx .
\end{equation}
takes nonpositive values as $r\to 0$. Moreover, 
if $u$ is of the form $\frac{\zeta(\frac x{|x|})}{|x|}$ then one can check that 
$\text{\Large$\wp$}(r) =0$. This observation motivates the formulation of 
a condition in our next result that allows to control $\text{\Large$\wp$}(r)$. 
\begin{theorem}\label{TH}
Let $u$ be a suitable weak solution of \eqref{eq:problem}, $B_1\subset \Omega$, and
\[
m:=\liminf_{R\to 0}M(R)<\infty \qquad \text{where} \quad M(R):=\int_{B_R} \Big( \frac{|u|^2}{R^3} + \frac{|\nabla u|^2}{R} \Big).
\] Let $\mP_R[\,\cdot\,]: \mathcal W^{1,2}(B_R)\to \mH(R)$ be the projection operator for the space \eqref{mH1}. There exists $\ep(m)>0$ 
such that 
if 
\begin{equation}\label{eq:13-alt}
\frac{1}{R^3} \int_{B_R} \left| u - \mP_R[u] \right|^2 + \frac{1}{R} \int_{B_R} \left| \nabla u - \nabla \mP_R[u] \right|^2 \le \ep(m) M(R)
\end{equation}
holds
for all $R\in (0, R_0)$ then $u$ is regular at $x=0$. 
\end{theorem}

\begin{proposition}\label{prop:dAdr}
 Suppose $N=5$ and $(u,P)$ is a suitable weak solution of \eqref{st-NS-N}. For $r>0$, define
 \begin{equation}
 \left\{
 \begin{aligned}
 &D(r)\vcentcolon= \int_{B_r} \Big\{ \frac{15}{4r^3}|u|^2 + \frac{1}{4r}|\nabla u |^2 + \frac{3}{4r^3}\left| \nabla (|x|u) \right|^2 + \frac{3(r^2-|x|^2)}{4r^3} |\nabla u|^2\Big\}\, dx,\\
 &A(r) \vcentcolon= \frac{1}{r^3}\int_{B_r}(x\cdot \nabla)\frac{|u|^2}{2}\, dx + \frac{9}{4r^3}\int_{ B_r}|u|^2 \, dx - \frac{1}{r^{2}} \int_{B_r} \big\{ \frac{|u|^2}{2} + P \big\} u\cdot \frac{x}{|x|} \, dx .
 \end{aligned}
 \right. 
 \end{equation}
 Then the following differential equation holds for $r>0$,
 \begin{equation*}
 \frac{d A}{d r} \ge \frac{1}{r} D(r) + \frac{2}{r^3} \int_{B_r} \Big\{\frac{|u|^2}{2} + P \Big\} (u\cdot \frac{x}{|x|}) \, dx .
 \end{equation*}
\end{proposition}
\begin{proof}
 Let us consider the function 
 \begin{equation}
 \phi(x)=
 \left\{
 \begin{array}{lll}
 1 \quad & \mbox{if} \ |x|<r,\\
 \frac{r-|x|}\epsilon \quad &\mbox{if} \ r\le |x|\le r+\epsilon,\\
 0 \quad & \mbox{if}\ |x|>r+\epsilon.\\
 \end{array}
 \right.
 \end{equation}
 We then mollify this function and take $\psi=\phi*\rho_\delta$, 
 where $\rho$ is the mollification kernel. 
 Note that $\psi\in \mathcal C_c^\infty(\R^N)$.
 We use $\psi$ as a test function in the local 
 energy inequality to obtain 
 \begin{equation}
 \int |\nabla u|^2 \psi
 \le 
 \int \left(-u \nabla u +(|u|^2+2P)u\right)\cdot \nabla \psi.
 \end{equation}

\begin{lemma}\label{lemma:reg}
Suppose $m:=\liminf_{R\to 0}M(R)<\infty$. 
 If there exists a sufficiently small $\ep>0$, depending on $m$, such that $(u,P)$ is a suitable weak solution to the Navier-Stokes equations satisfying
 \begin{equation}\label{H-Assump}
 \ep \frac{1}{R^{3}}\int_{B_R} |p| + \frac{1}{R^3} \int_{B_R} \left| u - \mP_R[u] \right|^2 + \frac{1}{R} \int_{B_R} \left| \nabla u - \nabla \mP_R[u] \right|^2 \le \ep M[u](R), 
 \end{equation}
 for all $R\in(0,1]$ then $u$ is regular at $x=0$.
\end{lemma}
\begin{proof}
If $m\le 8C_E$ then we can apply Proposition \ref{prop:fM}, and 
hence the result follows.
 Now suppose $m\in(8C_E, \infty)$. In light of Lemma \ref{lemma:MBound}, there exists $\ep_1>0$ such that if $(u,P)$ satisfies \eqref{H-Assump} with $\ep\in (0,\ep_1)$ then $M(R)$ is uniformly bounded in $R\in(0,1]$ and we set 
 \begin{equation}\label{Mast}
 M_{\ast} \vcentcolon= \sup\limits_{0<R\le 1} M(R) \le 2^5 C_0(m), 
 \end{equation}
 where $C_0(m)$ is given by \eqref{eq:Cmm}.
 At this point we can apply Proposition \ref{prop:fM}
 with $C_0=2^5C_0(m)$ by choosing $\ep_0$ sufficiently small, however we can avoid this by using the monotonicity formula.

\begin{lemma}\label{lem:Lin}
If $u$ is a suitable weak solution and 
\[
\int_{B_1} |u|^3+|p|^{\frac32}<\ep^*
\]
for some sufficiently small $\ep^*$, 
then 
\begin{equation}\label{eq:Lin1}
\frac1{\theta^5}\int_{B_\theta}\frac{|u-[u]_\theta|^3}{\theta^{\alpha_0}}+\frac{|p-[p]_\theta|^\frac32}{\theta^{\alpha_0}}\le \frac12 \int_{B_1} |u|^3+|p|^{\frac32},
\end{equation}
for some positive $\theta$ and $\alpha_0\in (0, \frac12)$.
\end{lemma}
\begin{proof}
If \eqref{eq:Lin1} fails, then there would be a sequence of solutions 
$(u_i, p_i)$ such that $\int_{B_1}|u_i|^3+|p_i|^{\frac32}:=\epsilon_i\to 0$ but 
\eqref{eq:Lin1} is not valid. Introduce 
\[
\bar u_i=\frac{u_i}{\epsilon_i}, \quad \bar p_i=\frac{p_i}{\epsilon_i}, 
\]
then 
\begin{equation}\label{eq:Lin4}
\epsilon_i \bar u_i\cdot \nabla \bar u_i+\nabla \bar p_i=\Delta \bar u_i, 
\quad 
\frac1{\theta^5}\int_{B_\theta}\frac{|\bar u-[\bar u]_\theta|^3}{\theta^{\alpha_0}}
+
\frac{|\bar p-[\bar p]_\theta|^\frac32}{\theta^{\alpha_0}}> \frac12, 
\quad \int_{B_1} |\bar u_i|^3+|\bar p_i|^{\frac32}\le 2. 
\end{equation}
From the local energy inequality $u\in \mathcal W^{1, 2}_{loc}(B_1).$
Moreover, the following equation is satisfied in distributional sense
\begin{equation}
\Delta \bar p_i=-\epsilon_i \frac{\partial^2 (\bar u^k\bar u^l)}{\partial x_l\partial x_k}, 
\quad \mbox {in}\ B_1.
\end{equation}
From the Poisson representation theorem we can write $\bar p_i=h_i+g_i$, 
where $h_i$ is harmonic in $B_1$, and 
\begin{equation}
\left\{
\begin{array}{lll}
\Delta g_i=-\epsilon_i \frac{\partial^2 (\bar u^k\bar u^l)}{\partial x_l\partial x_k}
\quad \mbox {in}\ B_{\frac23},\\ 
g_i=0 \quad \mbox {on}\ \partial B_{\frac23}.
\end{array}
\right.
\end{equation}
From the Calder\'on-Zygmund estimates 
$g_i$ is uniformly bounded in ${L^{5/3}(B_{2/3})}$.
Consequently, $h_i\in L^{3/2}(B_{2/3})$ uniformly, hence 
from the local estimates for the harmonic functions 
\begin{align}
\int_{B_\theta}|\bar p_i-[\bar p_i]_\theta|^{\frac32}\le 
\int_{B_\theta}| h_i-[h_i]_\theta|^{\frac32}
\int_{B_\theta}|g_i-[g_i]_\theta|^{\frac32}\\
\le C_0 \theta^5\theta^{3/2}+C_0\epsilon_i\int_{B_{2/3}}|\bar u_i|^3.
\end{align}
For a suitable subsequence $\bar u_i\to \bar u$ in $\mathcal W^{1, 2}(B_{2/3})$
and $\bar p_i\to \bar p$ strongly in ${L^{3/2}(B_{2/3})}$.
Consequently, for sufficiently large $i$, we have 
\begin{equation}\label{eq:Lin2}
\int_{B_\theta}|\bar p_i-[\bar p_i]_\theta|^{\frac32} \le C_0 \theta^5\theta^{3/2}
\end{equation}
Since the limit $\bar u$ solves the Stokes system, then it follows that 
$\bar u$ is H\"older continuous with, say, exponent $2\alpha_0$, and therefore 
$\int_{B_\theta}|\bar u-[\bar u]_\theta|^{\frac32}\le \frac14 \theta^5\theta^{\alpha_0}$.
From the strong convergence $\bar u_i\to \bar u$ in $L^3(B_{2/3})$, we infer that 
\begin{equation}\label{eq:Lin3}
\int_{B_\theta}|\bar u-[\bar u]_\theta|^{\frac32}\le \frac13 \theta^5\theta^{\alpha_0}.
\end{equation}
Combining \eqref{eq:Lin2} and \eqref{eq:Lin2} we get a contradiction with the 
second inequality in \eqref{eq:Lin4}. 
\end{proof}

