theorem.content:
\label{thm:main}
For $s >1 $ and $\delta>0$ there exist $c_s>0$ and $\ep_0>0$ with the following. For any $0< \epsilon \leq \ep_0$ and any zero-mean initial data $\om_{in} \in H^s(\mathbb{T} \times \mathbb{R})$ such that 
\begin{equation}\label{eq thm main 1}
\| \om_{in}\|_{H^{s} }  \leq \epsilon \quad \text{and} \quad \| y \om_{in}\|_{L^{2} }  \leq \epsilon ,
\end{equation}
define the lifespan  
\begin{equation}\label{eq thm main 2}
T_\epsilon: = c_s \epsilon^{-\delta_s }  \quad \text{with}  \quad  \delta_s = 
    \begin{cases}
  \frac{1}{4-s}  \quad\text{if $1<s<2 $  } &\\
\frac{1}{2+\delta}    \quad\text{ if $s=2 $  } &\\
\frac12 \quad\text{if $s > 2 $  }. & 
\end{cases}
\end{equation} 

 Then the (unique) solution to \eqref{eq:eu_eq} satisfies the following.

\begin{itemize}

	\item (Regularity):
	The re-normalized vorticity $W( t, X,Y): = \omega(t,X + Yt, Y)$ satisfies
	\begin{eqnarray}\label{eq:reg intro}
		\| W \|_{L^\infty_t ([0,T_\epsilon]; H^s)} \leq 3 \epsilon .
	\end{eqnarray}

	\item (Invisicid damping): The velocity field $u = (u^x, u^y )$ satisfies
	\begin{equation}\label{eq:damping intro}
		\begin{aligned}
			\|P_{\neq 0} u^x (t)\|_{L^2} & \lesssim \epsilon \langle t \rangle^{-1} \\
			\|  u^y (t) \|_{L^2} & \lesssim \epsilon \langle t \rangle^{- \min \{ 2,s\}}  
		\end{aligned}
		\quad \text{for all $t \in [0, T_\epsilon] $ }
	\end{equation}
	where $P_{\neq 0}f : = f -\int_{\mathbb{T} } f(x,y) \, dx $ denotes the projection of removing the $x$-mean.

\end{itemize}

