\begin{remark}
\hfill
\begin{enumerate}
 \item Our nonlinear estimates remain valid down to $H^{1+}$ matching the well-posedness threshold of 2D Euler. There is no contradiction with steady states\footnote{Note that the examples in \cite{MR2796139} are on the periodic channel $\T \times [-1,1]$, where the stationary structure appears near $y=0$. Nevertheless, the result in this paper is likely to hold on $\T \times [-1 ,1]$ when restricting away from the boundary. }~\cite{MR2796139} or traveling waves~\cite{MR4595614} constructions, since the initial velocities in those examples are already smaller than the decay rate predicted by \eqref{eq:damping intro} at $t=T_\ep$.

\begin{lemma}\label{lemma:Hs a priori}
Let $s>1$. The system \eqref{eq:eu_XY} satisfies the a priori estimates:
\begin{equation}
\frac{ d \| W(t) \|_{H^s} }{dt} \lesssim \| \nabla U \|_{L^\infty } \| W \|_{H^s} +
\begin{cases}
\| J^{ 2} U \|_{ L^2 } \| W \|_{H^s} & \quad \text{1<s<2}\\
\| J^{ 2+\delta} U \|_{ L^2 } \| W \|_{H^s} &\quad \text{ s=2} \\
\| J^{ s} U \|_{ L^2 } \| W \|_{H^s} &\quad \text{ s>2}.
\end{cases} 
\end{equation}

If $\int_{\T \times \R} \om_{in} = 0 $ and $ y \om_{in} \in L^2 $, then the system \eqref{eq:eu_XY} admits the following a priori estimates:
\begin{equation}\label{eq prop:apriori_yw}
\frac{ d \| W (t) \|_{ \bar{H}^s } }{dt} \lesssim \langle t\rangle^{\beta_s} \|W \|_{\bar{H}^s}^2 ,
\end{equation} 
where the exponent $ \beta_s =3-s $ if $1<s<2 $, $ \beta_s =1+\delta $ for arbitrary $\delta>0$ if $s=2 $, and $ \beta_s =1 $ if $s > 2 $.

Combining \eqref{eq aux apriori 1b}, \eqref{eq aux apriori 5} and \eqref{eq aux apriori 6} with Lemma \ref{lemma:Hs a priori}, we have:
\begin{equation*}
\frac{ d \| W(t) \|_{\bar H^s} }{dt} 
\begin{cases}
\lesssim \langle t\rangle^{3- s} \| W(t) \|_{\bar H^s}^2 \quad & \text{if $1<s<2$}\\
\lesssim_\delta \langle t\rangle^{1+\delta} \| W(t) \|_{\bar H^s}^2 \quad & \text{if $ s =2$}.
\end{cases}
\end{equation*}

We conclude that the decay estimate \eqref{eq:damping intro} follows from Lemma \ref{lemma:damping}; for $u^x$,
\begin{align*}
\| P_{\neq 0 } u^x (t)\|_{L^2} \lesssim \| P_{\neq 0 } \om \|_{\dot H^{-1}} 
 \lesssim \langle t\rangle^{-1} \|W \|_{L^\infty_t([0,T_\ep]; H^1)}
\end{align*}
while for $u^y$ (applying Lemma \ref{lemma:damping} for $\p_x \om $ and $\p_X W$),
\begin{align*}
\| u^y (t)\|_{L^2} = \| P_{\neq 0 } \Delta^{-1}_t ( \p_X W) \|_{L^2} \lesssim \langle t \rangle^{- \min \{ 2,s\}} \|W \|_{L^\infty_t([0,T_\ep];H^s) } 
\end{align*}
for any $s>1$ since the extra $\p_X$ can be absorbed in $H^s$. We have thus proven Theorem \ref{thm:main}

By standard duality, it suffices to bound
\begin{equation}
 \| P_{ \neq 0 } \om \|_{\dot H^{-1} } = \sup_{ 
 |\varphi \|_{\dot H^1} \leq 1 ; P_{=0} \varphi = 0} \int \om \varphi \, dx dy.
\end{equation}
So we fix such a smooth test function $\varphi \in C^\infty_c(\T \times \R)$ with zero $x$-mean and consider
\begin{equation}\label{eq:om_int}
 \int \om \varphi \, dx dy =\int W (X, Y )\varphi( X+ t Y, Y) \,dX dY.
\end{equation}
Because $\varphi$ has zero x-mean and periodic in $x$, there exists a unique zero x-mean function $ \phi= \p_x^{-1} \varphi$. 
Then we use the identity
\begin{equation}\label{eq:om_int 2}
 \varphi(\cdot) = \frac{1}{t}\p_Y \left( \phi(\cdot) \right) - \frac{1}{t}\p_y \phi(\cdot)
\end{equation}
where the argument $(\cdot) = (X+ t Y, Y )$ is omitted.
Inserting this into \eqref{eq:om_int} gives
\begin{align}
