	\om|_{t= 0 } = \om_{in} &
\end{cases}	
\end{equation}
satisfies the following.

\begin{itemize}

	\item (Regularity):
	The re-normalized vorticity $W( t, X,Y): = \omega(t,X + Yt, Y)$ satisfies
	\begin{eqnarray}\label{eq:reg intro}
		\| W \|_{L^\infty_t ([0,T_\epsilon]; H^s)} \leq 3 \epsilon .
	\end{eqnarray}

	\item (Invisicid damping): The velocity field $u = (u^x, u^y )$ satisfies
	\begin{equation}\label{eq:damping intro}
		\begin{aligned}
			\|P_{\neq 0} u^x (t)\|_{L^2} & \lesssim \epsilon \langle t \rangle^{-1} \\
			\|  u^y (t) \|_{L^2} & \lesssim \epsilon \langle t \rangle^{- \min \{ 2,s\}}  
		\end{aligned}
		\quad \text{for all $t \in [0, T_\epsilon] $ }
	\end{equation}
	where $P_{\neq 0}f : = f -\int_{\mathbb{T} } f(x,y) \, dx $ denotes the projection of removing the $x$-mean.

\end{itemize}

