\subsection{Moments}
Noting $X \sim Weibull(\alpha, \lambda)$ and $Y \sim Weibull(\gamma, \nu)$, we have:
\begin{align}
 E(X) &= \frac{1}{\alpha} \Gamma\left(1+ \frac{1}{\lambda}\right), \label{eq: Weibull ex} \\
 E(Y) &= \frac{1}{\gamma} \Gamma\left(1+ \frac{1}{\nu}\right), \label{eq: Weibull ey} \\
 {Var}(X) &= \frac{1}{\alpha^2}\left( \Gamma\left( 1+ \frac{2}{\lambda}\right) - \left(\Gamma\left(1+\frac{1}{\lambda}\right)\right)^2 \right),\label{eq: Weibull varx} \\
 {Var}(Y) &= \frac{1}{\gamma^2}\left( \Gamma\left( 1+ \frac{2}{\nu}\right) - \left(\Gamma\left(1+\frac{1}{\nu}\right)\right)^2 \right).\label{eq: Weibull vary} 
\end{align}
Accordingly:
\begin{align}
\operatorname{Cov}(X, Y) 
&= \int_0^\infty \int_0^\infty 
 \big( P(Y>y , X> x) - P(X> x)P(Y> y) \big) \,dy\,dx \nonumber \\
&= \int_0^\infty \int_0^\infty 
 \bar{F}_0(x) \left( \bar{F}_1\bigl(\beta(x)y\bigr) - \bar{F}_1\bigl(\beta(0)y\bigr) \right) \,dy\,dx \nonumber \\
&= \int_0^\infty e^{-(\alpha x)^\lambda}
 \left( \int_0^\infty \left( e^{-(\beta(x)y )^\nu}- e^{-(\beta(0)y )^\nu} \right) dy \right) dx \nonumber \\
&= \int_0^\infty e^{-(\alpha x)^\lambda}
 \left( \frac{\Gamma\!\left(1+\frac{1}{\nu}\right)}{\beta(x)} -\frac{\Gamma\!\left(1+\frac{1}{\nu}\right)}{\beta(0)} \right) dx \nonumber \\
&= \frac{1}{\gamma } \Gamma\!\left( 1+ \frac{1}{\nu}\right) 
 \left[\int_0^\infty e^{-(\alpha x)^\lambda - \frac{1}{\nu}(\alpha \tau x)^\lambda} \, dx 
 - \int_0^\infty e^{-(\alpha x)^\lambda} \, dx \right] \nonumber \\
&= \frac{1}{\alpha \gamma} \Gamma\!\left(1+ \frac{1}{\nu} \right)\Gamma\!\left(1+ \frac{1}{\lambda} \right)
 \left[ \left(\frac{\nu}{\nu + \tau^\lambda} \right)^{\frac{1}{\lambda}} - 1 \right].
\label{eq: Weibull cov}
\end{align}
Now, using \eqref{eq: Weibull varx}, \eqref{eq: Weibull vary} and \eqref{eq: Weibull cov}, the correlation function is:
\begin{align}
 \rho(X,Y)
 &= \frac{\operatorname{Cov}(X,Y)}{\sqrt{\operatorname{Var}(X)\operatorname{Var}(Y)}} \nonumber\\
 &= \frac{\Gamma\left(1+ \frac{1}{\nu} \right)\Gamma\left(1+ \frac{1}{\lambda} \right)\left[ \left(\frac{\nu}{\nu + \tau^\lambda} \right)^{\frac{1}{\lambda}} - 1 \right]}{\sqrt{\left( \Gamma\left( 1+ \frac{2}{\lambda}\right) - \left(\Gamma\left(1+\frac{1}{\lambda}\right)\right)^2 \right)\left( \Gamma\left( 1+ \frac{2}{\nu}\right) - \left(\Gamma\left(1+\frac{1}{\nu}\right)\right)^2 \right)}}.
 \label{eq: Weibull rho}
\end{align}
Clearly, \eqref{eq: Weibull rho} is strictly decreasing in $\tau \in [0, 1]$. Hence:
\begin{align}
