\section{Joint Densities and Log-likelihoods} \label{app: joint lik}
\subsection{Exponential} 
We obtain the joint density function by differentiating the joint survival function \eqref{eq: exp joint survival}:
\[
f_{X,Y}(x,y) 
= \alpha \gamma \,\bigl(\gamma \tau y e^{\alpha \tau x} - \tau + 1 \bigr) 
 e^{\!\left(\alpha x(\tau - 1) - \gamma y e^{\alpha \tau x}\right)},
 \qquad x,y>0.
\]
where $\alpha, \gamma > 0 $ and $\tau \in [0, 1]$. The log-likelihood is thus:
\begin{align}
\ell(\alpha,\gamma,\tau)
&= n \log \alpha + n \log \gamma 
+ \sum_{i=1}^n \log\!\Big( \gamma \tau y_i e^{\alpha \tau x_i} - \tau + 1 \Big) \nonumber \\
&\quad + \alpha (\tau - 1)\sum_{i=1}^n x_i 
- \gamma \sum_{i=1}^n y_i e^{\alpha \tau x_i}. \nonumber
\end{align}
\subsection{Lomax}
We obtain the joint density function by differentiating the joint survival function \eqref{eq: Lomax joint survival}:
\begin{align*}
f_{X,Y}(x,y) 
&= \nu \,(1+\alpha x)^{-3\lambda - 1}\,
 \bigl(1+\gamma y (1+\alpha \tau x)^{\lambda}\bigr)^{-3\nu - 4} \\[6pt]
&\quad \times \Biggl[
 \frac{\alpha \gamma^{2} \lambda \tau y (\nu+1)\,(1+\alpha x)^{2\lambda+1}(1+\alpha \tau x)^{2\lambda}
 \,\bigl(1+\gamma y (1+\alpha \tau x)^{\lambda}\bigr)^{2\nu+2}}
 {1+\alpha \tau x} \\[6pt]
&\qquad - \frac{\alpha \gamma \lambda \tau \,(1+\alpha x)^{2\lambda+1}(1+\alpha \tau x)^{\lambda}
 \,\bigl(1+\gamma y (1+\alpha \tau x)^{\lambda}\bigr)^{2\nu+3}}
 {1+\alpha \tau x} \\[6pt]
&\qquad + \alpha \gamma \lambda \,\bigl((1+\alpha x)^{2}(1+\alpha \tau x)\bigr)^{\lambda}
 \,\bigl(1+\gamma y (1+\alpha \tau x)^{\lambda}\bigr)^{2\nu+3}
 \Biggr], \quad x,y >0,
\end{align*}
where $\alpha, \lambda, \nu,\gamma > 0 $ and $\tau \in [0, 1]$. The log-likelihood is thus:
\begin{align}
\ell(\alpha,\lambda,\nu,\gamma,\tau)
&= n \log \nu 
 - (3\lambda+1)\sum_{i=1}^n \log(1+\alpha x_i) \nonumber \\
&\quad - (3\nu+4)\sum_{i=1}^n \log\!\bigl(1+\gamma y_i (1+\alpha \tau x_i)^{\lambda}\bigr) \nonumber \\
&\quad + \sum_{i=1}^n 
 \log\!\Biggl\{
 \frac{\alpha \gamma^{2} \lambda \tau y_i (\nu+1)\,(1+\alpha x_i)^{2\lambda+1}(1+\alpha \tau x_i)^{2\lambda}}
 {1+\alpha \tau x_i}
 \bigl(1+\gamma y_i (1+\alpha \tau x_i)^{\lambda}\bigr)^{2\nu+2} \nonumber \\
&\qquad\qquad
 - \frac{\alpha \gamma \lambda \tau (1+\alpha x_i)^{2\lambda+1}(1+\alpha \tau x_i)^{\lambda}}
 {1+\alpha \tau x_i}
 \bigl(1+\gamma y_i (1+\alpha \tau x_i)^{\lambda}\bigr)^{2\nu+3} \nonumber \\
&\qquad\qquad
 + \alpha \gamma \lambda \,\bigl((1+\alpha x_i)^{2}(1+\alpha \tau x_i)\bigr)^{\lambda}
 \bigl(1+\gamma y_i (1+\alpha \tau x_i)^{\lambda}\bigr)^{2\nu+3}
 \Biggr\}. \nonumber
\end{align}
\subsection{Weibull}
We obtain the joint density function by differentiating the joint survival function \eqref{eq: Weibull joint survival}:
\[
f_{X, Y}(x,y) = \alpha^{\lambda} \gamma^{\nu} \lambda \nu x^{\lambda - 1} y^{\nu - 1}
\left( \tau^{\lambda} (\gamma y)^{\nu} e^{(\alpha \tau x)^\lambda}
- \tau^{\lambda} + 1 \right)
e^{(\alpha x)^\lambda(\tau^\lambda - 1)
- (\gamma y)^{\nu} e^{(\alpha\tau x)^{\lambda}}}, \quad x, y>0,
\]
where $\alpha, \lambda, \nu,\gamma > 0 $ and $\tau \in [0, 1]$. The log-likelihood is thus:
\begin{align}
\ell(\alpha,\lambda,\nu,\gamma,\tau)
&= n \lambda \log \alpha + n \nu \log \gamma 
 + n \log \lambda + n \log \nu \nonumber\\
&\quad + (\lambda - 1) \sum_{i=1}^n \log x_i
 + (\nu - 1) \sum_{i=1}^n \log y_i \nonumber \\
&\quad + \sum_{i=1}^n 
 \log\!\Bigl(\tau^{\lambda} (\gamma y_i)^{\nu} e^{(\alpha \tau x_i)^\lambda}
 - \tau^{\lambda} + 1 \Bigr) \nonumber \\
&\quad + (\tau^{\lambda} - 1)\sum_{i=1}^n (\alpha x_i)^\lambda
 - \sum_{i=1}^n (\gamma y_i)^{\nu} e^{(\alpha \tau x_i)^\lambda}. \nonumber
\end{align}
\subsection{Log-logistic}
We obtain the joint density function by differentiating the joint survival function \eqref{eq: Log joint survival}:
\[
\begin{aligned}
f_{X,Y}(x,y)
&= \frac{\lambda \nu\,(\gamma y)^{\nu}}
{x\,y\,\bigl((\alpha x)^{\lambda}+1\bigr)^{2}
\Bigl( (\gamma y)^{\nu}\bigl((\alpha \tau x)^{\lambda}+1\bigr)+1 \Bigr)^{3}}
\\[4pt]
&\quad\times
\Biggl\{
(\alpha x)^{\lambda}\bigl((\alpha \tau x)^{\lambda}+1\bigr)
\Bigl( (\gamma y)^{\nu}\bigl((\alpha \tau x)^{\lambda}+1\bigr)+1 \Bigr)
\\
&\qquad\qquad
+ (\alpha \tau x)^{\lambda}\bigl((\alpha x)^{\lambda}+1\bigr)
\Bigl( (\gamma y)^{\nu}\bigl((\alpha \tau x)^{\lambda}+1\bigr)+1 \Bigr)
\\
&\qquad\qquad
- 2\,(\alpha \tau x)^{\lambda}\bigl((\alpha x)^{\lambda}+1\bigr)
\Biggr\},
\qquad x,y>0,
\end{aligned}
\]

