\begin{theorem}[Continuous limit]\label{cts-limit} Let $\alpha$ be a real number, and let $a,b$ be coprime integer parameters with $b \to \infty$ and $a/b \to \alpha$. Then
\begin{equation}\label{up}
 \SD\left(\{0,1,\infty\};\frac{a}{b}\right) \geq 2 - \frac{c_\alpha+o(1)}{\log b}
 \end{equation}
 as $b\to \infty$ and $a/b \to \alpha$, where $0 < c_\alpha < \infty$ is the infimum of all quantities
\begin{equation}\label{hf}
 h_2(f_{(\alpha)}) - \max(h(f_0), h(f_\infty), h(f_\alpha))
 \end{equation}
where $f \colon \R^2 \to \R^+$ ranges over smooth compactly supported functions with total mass $\int_{\R^2} f(x,y)\ dx dy$ equal to $1$, $f_{(\alpha)} \colon \R \times [0,1) \to \R^+$ is a ``folded'' version
\begin{equation}\label{falpha-def}
 f_{(\alpha)}(x,y) \coloneqq \sum_{j \in \Z} f(x-\alpha j, y+j)
 \end{equation}
of $f$, $f_0, f_\infty, f_1 \colon \R \to \R^+$ are the projections
\begin{align}
f_0(x) &\coloneqq \int_\R f(x,y)\ dy\label{f0-def}\\
f_\infty(y) &\coloneqq \int_\R f(x,y)\ dx\label{finfty-def}\\
f_1(z) &\coloneqq \int_\R f(x,z- x)\ dx,\label{f1-def}
\end{align}
the two-dimensional differential entropy $h_2(f_{(\alpha)})$ of $f_{(\alpha)}$ is defined as
$$h_2(f_{(\alpha)}) \coloneqq \int_0^1 \int_\R \h(f_{(\alpha)}(x,y))\ dx dy,$$
and the one-dimensional differential entropies $h(f_r)$ for $r=0,1,\infty$ is defined as
$$ h(f_r) \coloneqq \int_\R \h(f_r(x))\ dx.$$
\end{theorem}

\begin{proposition}\label{dilate} Let $X$ be an $\Q$-valued random variable, and for any $a \in \Q$, let $g(a)$ denote the quantity $g(a) \coloneqq \H[X-aX'] - \H[X]$, where $X'$ is an independent copy of $X$.
\begin{itemize}
 \item[(i)] $g(0) = 0$ and $g(1)=d[X;X]$.
 \item[(ii)] For any $a \in \Q$, we have $g(-a) \leq 3g(a)$, and if $a$ is non-zero, $g(a^{-1}) = g(a)$.
 \item[(iii)] For any $k \geq 1$ and $a_1,\dots,a_k \in \Q$, we have $g(a_1 \dots a_k) \leq g(a_1)+ \dots + g(a_k)$ and $g(a_1 + \dots + a_k) \leq g(a_1)+\dots+g(a_k)+(k-1) g(1)$.
 \item[(iv)] If $a$ is a non-zero integer, then $g(a) \leq (4 + 10 \lfloor \log_2 |a| \rfloor) g(1)$.
 \item[(v)] If $R$ is a finite set of slopes containing $0,1,\infty$ of cardinality $k+3$, then
 $$ g(a) \ll D(R;a)^{k+1} \max_{r \in R \backslash \{\infty\}} g(r).$$
\end{itemize}
\end{proposition}

In this section we establish \Cref{cts-limit}. Let $\alpha$, $a$, $b$, $f$, $f_0, f_1, f_\infty$ be as in that theorem. We allow implied constants in the asymptotic notation to depend on $\alpha, f$. We will establish the lower bound
\begin{equation}\label{sd-targ}
 \SD\left(\{0,1,\infty\},\frac{a}{b}\right) \geq 2 - \frac{h_2(f_\alpha) - \max(h(f_0), h(f_\infty), h(f_1))+o(1)}{\log b}.
 \end{equation}
Comparing this with Theorem \ref{main-2}, we conclude that the expression $h_2(f_\alpha) - \max(h(f_0), h(f_\infty), h(f_1))$ is bounded from below, hence $c_\alpha > 0$; by taking an arbitrary test function for $f$ we also see that $c_\alpha < \infty$. Taking $h_2(f_\alpha) - \max(h(f_0), h(f_\infty), h(f_1))$ arbitrarily close to $c_\alpha$, we obtain the desired claim \eqref{up}.

It remains to establish \eqref{sd-targ}.
By the Poisson summation formula, the rapid decrease of the Fourier transform of the smooth compactly supported $f$, and the mass one hypothesis, we have
\begin{equation}\label{bib}
 \frac{1}{b^2} \sum_{n,m \in \Z} f\left(\frac{n}{b}, \frac{m}{b}\right) = 1 + \eps
 \end{equation}
for some $\eps = O(1/b)$; in fact one can get much better decay than this, but for our purposes any decay faster than $1/\log b$ will suffice. We then take $X,Y$ to be supported on the grid $\Z^2$ with probability distribution
$$ \P((X,Y) = (n,m)) \coloneqq \frac{1}{(1+\eps) b^2} \left(\frac{n}{b}, \frac{m}{b}\right)$$
thus $(X,Y)$ takes values in a ball of radius $O(b)$ and
\begin{equation}\label{pnx}
\P((X,Y) = (n,m)) = \frac{1}{b^2} f\left(\frac{n}{b}, \frac{m}{b}\right) + O\left( \frac{1}{b^3} \right).
\end{equation}
By Bezout's theorem, any integer can be uniquely written in the form $bn+am$ for some $0 \leq m < b$, and any other representation of the form $bn'+am'$ takes the form $b(n-aj) + a(m+bj)$. Thus
$$ \P(bX+aY = bn+am) = \sum_{j \in\Z} \P( (X,Y) = (n-aj, m+bj) ).$$
There are only $O(1)$ values of $j$ for which this sum is non-zero, so from \eqref{pnx} one has
$$ \P(bX+aY = bn+m) = \frac{1}{b^2} f_{(a/b)}\left(\frac{n}{b}, \frac{m}{b}\right) + O\left( \frac{1}{b^3} \right).$$
where $f_{(a,b)}: \R \times [0,1) \to \R^+$ is the function
$$f_{(a/b)}(x,y) \coloneqq \sum_{j \in \Z} f\left(x-\frac{a}{b} j, y+j\right).$$
Applying the entropy function $\h$, we conclude that
$$ \h(\P(bX+aY = bn+am)) = \frac{2 \log b}{b^2} f_{(a/b)}\left(\frac{n}{b}, \frac{m}{b}\right) +
\frac{1}{b^2} \h\left(f_{(a/b)}\left(\frac{n}{b}, \frac{m}{b}\right)\right) + O\left( \frac{\log b}{b^3} \right).$$
From \eqref{bib} one has
$$ \frac{1}{b^2} \sum_{n \in\Z; 0 \leq m < b} f_{(a/b)}\left(\frac{n}{b}, \frac{m}{b}\right) = 1 + \eps = 1 + O\left(\frac{1}{b} \right)$$
and from (uniform) Riemann integrability of the $f_{(a/b)}$ one has
$$ \frac{1}{b^2} \sum_{n \in\Z; 0 \leq m < b} \h\left(f_{(a/b)}\left(\frac{n}{b}, \frac{m}{b}\right)\right) = h_2(f_{(a/b)}) + o(1).$$
Finally, from dominated convergence one has
$$ h_2(f_{(a/b)}) = h_2(f_{(\alpha)})+o(1)$$
so we conclude that
$$ \H\left[\pi_{a/b}(X,Y)\right] = \H[bX+aY] = 2 \log b + h_2(f_{(\alpha)}) + o(1).$$
In a similar vein, from another application of Poisson summation and \eqref{f0-def} we see that
$$ \P(X=n) = \frac{1}{b} f_0\left(\frac{n}{b}\right) + O\left(\frac{1}{b^2}\right)$$
for any integer $n$, hence
$$ \h(\P(X=n)) = \frac{\log b}{b} f_0\left(\frac{n}{b}\right) + \frac{1}{b} \h\left(f_0 \left(\frac{n}{b}\right)\right) + O\left(\frac{\log b}{b^2}\right).$$
Since $X = O(b)$, one can sum using Riemann integrability and \eqref{bib} to conclude that
$$ \H[\pi_0(X,Y)] = \H[X]= \log b + h(f_0) + o(1).$$
Similar arguments give
$$ \H[\pi_\infty(X,Y)] = \H[Y] = \log b + h(f_\infty) + o(1)$$
and
$$ \H[\pi_1(X,Y)] = \H[X+Y] = \log b + h(f_1) + o(1).$$
Comparing this with \eqref{sdef}, we obtain \eqref{sd-targ}.

