\end{corollary}

\begin{proposition}\label{Prop: mass capacity}
 If $(M,g)$ has nonnegative scalar curvature, then we have
 $$m(M,g,E)\geq 2 \mathfrak c(M,g,E).$$
\end{proposition}
\begin{proof}
 Given any constant $\varepsilon>0$ we define
 \begin{equation}\label{Eq: approximation metric}
 g_\varepsilon=u_\varepsilon^{\frac{4}{n-2}}g\mbox{ with } u_\varepsilon=\frac{u+\varepsilon}{1+\varepsilon},
 \end{equation}
