\label{th:main}
Fix a truncation parameter $m_0\ge1$ and
assume that:
\begin{enumerate}[---]
\item the space dimension is sufficiently large depending on $m_0$, in the sense that
\begin{equation}\label{eq:def de d_0}
d\ge d_0=\left\{\begin{array}{cl}
2,&\text{if $m_0=1$},\\
8,&\text{if $m_0=2$},\\
28m_0+70,&\text{if $m_0\ge3$},
\end{array}\right.\end{equation}
\item the diffusion constant $\kappa$ is sufficiently large, in the sense that $\kappa\ge C_{m_0}\int_{\mathbb R^d}|k|\V(k)\,dk$ for some constant~$C_{m_0}>0$ depending only on $m_0$. In case $m_0=1$, this condition can be dropped.
\end{enumerate}
Then, for any initial condition $\mathfrak G\in C_c^\infty(\mathbb R^d)$, the solution $(G_m^{N,m_0})_{0\le m\le m_0}$ of the simplified hierarchy
\begin{equation}\label{eq:hierarchy-simpl}
\fbox{\text{$\partial_tG_m^{N,m_0}+(iL_m+\tfrac\kappa ND_m)G_m^{N,m_0}=iS_m^+G_{m+1}^{N,m_0}+\tfrac1N iS_m^-G_{m-1}^{N,m_0},\qquad 0\le m\le m_0,$}}
\end{equation}
with initial condition
\begin{equation}\label{eq:hierarchy-simpl-ci}
G_m^{N,m_0}|_{t=0}\,=\,\left\{\begin{array}{lll}
\mathfrak G&:&m=0,\\
0&:&m\ne0,
\end{array}\right.
\end{equation}
satisfies that the time-rescaled tagged-particle density
\[(\tau,v)\mapsto G_0^{N,m_0}(N\tau,v)\]
converges strongly in $L^2_\loc(\mathbb R^+;L^2(M\, dv))$ to the solution $G_0$ of the Fokker-Planck equation
\begin{equation}\label{eq:FP-exp-re}
\left\{\begin{array}{l}
\partial_\tau G_0=(\nabla_v-\tfrac\beta 2v)\cdot (\kappa\Id+A_0)(\nabla_{v}-\tfrac\beta 2v)G_0,\\
G_0|_{\tau=0}=\mathfrak G,
\end{array}\right.
\end{equation}
More precisely, we have
\begin{equation*}
\Big(\int_0^\infty e^{-2\tau}\|G_0^{N,m_0}(N\tau)-G_0(\tau)\|_{L^2(M\,dv)}^2\,d\tau\Big)^\frac12 \,\lesssim\,N^{-\frac1{12}}\|\<(\nabla_{v_0},v_0)\>^{4m_0+10}\mathfrak G\|_{L^2(M\, dv)},
\end{equation*}
and this bound can be improved to $N^{-1}\|\<(\nabla_{v_0},v_0)\>^{4m_0+21}\mathfrak G\|_{L^2(M\,dv)}$ if $d\ge 28m_0+147$.

