Our \lemref{lemma1.1} is parallel to the corresponding averaging lemma in Cheng and Mahalov\cite{Cheng2013}.
The structure and proof are essentially identical, except that we replace $\varepsilon$ with our notation $\omega$. For completeness, we restate the lemma below in our current setting on the ellipsoidal surface. Detailed proofs and intermediate estimates can be found in Cheng and Mahalov\cite{Cheng2013}[Lemma 1.1], and the same argument applies verbatim here with $1/\omega$ replacing $\varepsilon$.

\begin{equation}
 \mathcal{L}[u]=0\Leftrightarrow
 u=\Psi^{\prime}(\frac{-2\sin\theta}{\sqrt{\sin^{2}\theta+b^{2}\cos^{2}\theta}})\frac{-2b^{2}\cos\theta}{(\sin^{2}\theta+b^{2}\cos^{2}\theta)^{2}}e_{\phi}
\end{equation}
for some function $\Psi :[-1,1]\mapsto\mathbb{R}$. Thus we identify $\mathrm{null}\{\mathcal{L}\}$ when restricted to div-free velocity fields, with the space of longitude−independent zonal flows.
\end{lemma}

\begin{equation}
 \begin{aligned}\prod_{\mathrm{null}\{\mathcal{L}\}}(\nabla^{\perp}\Psi)&=\frac{\sqrt{\sin^{2}\theta+\frac{\cos^{2}\theta}{b^{2}}}}{2\pi\cos\theta}\left(\int_{0}^{2\pi}\partial_\theta\Psi d\phi\right)e\phi\\&=\nabla^{\perp}\left(\frac{\sqrt{\sin\theta+\frac{\cos^{2}\theta}{b^{2}}}}{2\pi}\int_{0}^{2\pi}\Psi d\phi\right)\end{aligned} \label{projection}
\end{equation}

$\mathcal{L}[u]=\nabla^{\perp}\Delta^{-1}\mathrm{curl}(\frac{-2\sin\theta}{\sqrt{\sin^{2}\theta+b^{2}\cos^{2}\theta}}u^{\perp}) \quad \mathrm{curl}(\frac{-2\sin\theta}{\sqrt{\sin^{2}\theta+b^{2}\cos^{2}\theta}}u^{\perp})=(\nabla\frac{-2\sin\theta}{\sqrt{\sin^{2}\theta+b^{2}\cos^{2}\theta}})u$\\
Thus
$$\mathcal{L}[\nabla^{\perp}\Psi]=\nabla^{\perp}\Delta^{-1}(\nabla\frac{-2\sin\theta}{\sqrt{\sin^{2}\theta+b^{2}\cos^{2}\theta}}\cdot\nabla^{\perp}\Psi)=\nabla^{\perp}\Delta^{-1}[\frac{b^{2}}{(\sin^{2}\theta+b^{2}\cos^{2}\theta)^{2}}\partial_\varphi\Psi]$$
By setting $\Psi=Y_{l}^{m}$ where $l\geq1$, we have
$$\mathcal{L}[\nabla^{\perp}\Psi]=\nabla^{\perp}\sum_{m\neq0}\frac{-im}{\Lambda_{l,m}}\Psi_{l}^{m}Y_{l}^{m} \quad\text{where}\quad\Psi=\widehat{\Psi}_{l}^{m}Y_{l}^{m}$$
So we have $\mathcal{L}[\nabla^{\perp}Y_{l}^{m}]=\frac{-im}{\Lambda_{l,m}}\nabla^{\perp}Y_{l}^{m}$, then 
$$\Delta^{k}\mathcal{L}[\nabla^{\perp}Y_{l}^{m}]=\Delta^{k}\cdot\frac{-im}{\Lambda_{e,m}}\nabla^{\perp}Y_{l}^{m}=\frac{-im}{\Lambda_{l,m}}\Delta^{k}\nabla^{\perp}Y_{l}^{m}=\mathcal{L}[\Delta^{k}\nabla^{\perp}Y_{l}^{m}]$$
Therefore, for any incompressible flow
$$u=\nabla^{\perp}\Psi=\nabla^{\perp}\sum_{l=1}^{\infty}\sum_{m=-l}^{l}\frac{(\sin^{2}\theta+b^{2}\cos\theta)^{2}}{b^{2}}\tilde{\psi}_{l}^{m}Y_{l}^{m}$$ 
we have $\Delta^{k}\mathcal{L}[u]=\mathcal{L}[\Delta^{k}u]$. Combining above properties together we obtain that 
$$\begin{aligned}\langle\Delta^ku,\mathcal{L}[u]\rangle&=-\langle \mathcal{L}[\Delta^ku],u\rangle=-\langle\Delta^k\mathcal{L}[u],u\rangle\\&=-\langle \mathcal{L}[u],\Delta^ku\rangle\end{aligned}$$
which leads to conclusion \eqref{5.9}
\qed\\

