In \cite{HS3}*{Lemma 2.8} we established the following large deviation theorem for $f_n$.
\begin{lemma}\label{lem:deno}
Let $\omega\in \mathrm{DC}$, and $\gamma>0$ be as in Lemma \ref{lem:LDTsig}.
Assume $L_d(\omega,M_E)\geq \nu>0$.
There exist $\gamma>0$, $N_0>1$ large and $0<\kappa_0\ll 1$ so that the {\it $\kappa_0$-admissible} sequence 
\begin{align}\label{def:admissible}
\mathcal{N}:=\{n\geq N_0: \|n\omega\|_{\T}\leq \kappa_0\}
\end{align}
has the following property: 
for any $|\varepsilon|\leq \delta/2$, and all large $\kappa_0$-admissible $n$, the following large deviation set 
\begin{align}\label{def:B_fEn}
\mathcal{B}_{f,E,n,\varepsilon}:=
\big\{\theta\in \T: n^{-1}\log |f_{n}(\theta+i\varepsilon,E)|<\langle \log |\det B(\cdot+i\varepsilon)|\rangle +{L}^d_{\varepsilon}(\omega,M_E)- n^{-\gamma}\big\}
\end{align}
satisfies $\mathrm{mes}(\mathcal{B}_{f,E,n,\varepsilon})<e^{-n^{\gamma}}$.
\end{lemma}
\begin{remark}\label{rem:admissible}
 For every large integer $n>0$ there exists an admissible $\tilde n>0$ with $|n-\tilde n|\le C_*$ for some constant $C_*$.
\end{remark}

Recall that $E\in I_{E_0}$.
Our goal is to analyze the following for an arbitrary fixed $\theta$ as $N\to\infty$:
\begin{align}\label{eq:goal}
 &d_{\omega,N}(\theta,E-\eta,E+\eta)=\frac{1}{N}\mathrm{tr}(P_{[E-\eta, E+\eta)}(H_{\omega,\theta}|_{[0,N-1]})),
\end{align}
in which $H_{\omega,\theta}|_{[0,N-1]}$ is $H_{\omega,\theta}$ restricted to the interval $[0,N-1]$ with Dirichlet boundary condition and $P_{[E-\eta,E+\eta)}$ stands for the spectral projection.
Bounding \eqref{eq:goal} through the trace of the resolvent yields
\begin{align}\label{eq:dN<G}
 d_{\omega,N}(\theta,E-\eta,E+\eta)
 &\leq \frac{2\eta}{N} \mathrm{Im}(\mathrm{tr}(G_{[0,N-1]}^{E+i\eta}(\theta)))\\
