			\item[(b)] \textbf{(Strong)} There exists a proper Zariski-closed subset $Z \subset X$ such that for any finite extension $K$ of $k$, the set of $K$-rational points on $X \setminus Z$ is finite.
		\end{enumerate}
	\end{conj}
		Then the rank $r(J_C(k))$ is uniformly bounded as $J_C$ varies over the Jacobian varieties of all smooth curves $C$ defined over $k$ by the equation
		\begin{equation} \label{curve_main}
		C_{a,b}: y^s=x(ax^r+b),
	\end{equation}
		with genus $g_{r,s}(C) \geq 1%.

