\section{Appendix}
\label{appendix}
\begin{theorem}
\label{grad_yuan}
    (Gradient estimate when $|\theta| \geq \frac{n-2}{2}\pi$). (\cite{private_note} Theorem 5.1.1).
    Let $n\geq 3$. Suppose that $u$ is a smooth solution to the special Lagrangian equation (\ref{SLE}) on $B_{R}(0)$ with $|\theta| \geq \frac{n-2}{2}\pi$, then 
\begin{equation}
    |Du(0)| \leq C(n)\frac{osc_{B_{R}(0)}u}{R}.
\end{equation}

\end{theorem}
\begin{proof}
    We may assume that $R= 1 $ by rescaling $u(Rx)/R^2$. Note that
\[D^2(\frac{u(Rx)}{R^2}) = D^2u(Rx).\]
Then $\frac{u(Rx)}{R^2}$ satisfies the special Lagrangian equation with the same phase constant $\theta$.
Suppose we have the estimate 
\begin{equation*}
    |D(\frac{u(R  x)}{R^2})(0)| \leq C(n)osc_{B_1(0)}(\frac{u(Rx)}{R^2}),
\end{equation*}
then we can simplify the equation and obtain the desired estimate. We may also assume $\theta \geq \frac{n-2}{2}\pi$ by symmetry. 

Let \[M:=osc_{B_1(0)} u.\]
We may assume $M>0$. We may replace $u$ by $\Tilde{u}:= u-\min_{B_1(0)}u+M$. We then have $M\leq u \leq 2M$ in $B_1(0)$.
Consider the test function
\begin{equation*}
    w = (1-|x|^2)|Du| + \frac{n}{M}u^2.
\end{equation*}
Write $\eta := 1-|x|^2$.
Suppose that the maximum of $w$ lies on the boundary, say at $x^*$ where $|x^*| = 1$, then
\begin{equation*}
    2nM \geq w(x^*) = \frac{n}{M}u^2(x^*) \geq w(0) = |Du(0)|+\frac{n}{M}u^2(0) \geq |Du(0)|.
\end{equation*}

If the maximum point $x^*$ lies in the interior, we may assume $|Du(x^*)|>0$, since otherwise we can obtain the desired bound. We may further assume there exists a $k \in{\{1,\dots,n\}}$ such that $u_k \geq \frac{|Du|}{\sqrt{n}}$ at $x^*$. If not, we may consider the function \[\Tilde{u}(x_1,\dots,x_k,\dots,x_n) = u(x_1,\dots,-x_k,\dots,x_n),\] which satisfies the special Lagrangian equation with the same phase constant $\theta$. At $x^*$, we have
\begin{equation}
\label{2_3}
    0 = w_i = \eta|Du|_i+\eta_i|Du|+2\frac{n}{M}uu_i.
    \end{equation}
A direct computation gives
\begin{equation*}
    |Du|_i = \frac{\sum_j u_j u_{ij}}{|Du|}.
\end{equation*}
Assume that $D^2u$ is diagonalized at $x^*$, we have
\begin{equation}
\label{2_4}
    \frac{u_i u_{ii}}{|Du|} = |Du|_i = -\frac{2\eta_i|Du|+2uu_i\frac{n}{M}}{\eta}.
\end{equation}
In particular, for the $k\in \{1,\dots,n\}$ chosen just now, 
\begin{align*}
     2\eta_k|Du|+2uu_k\frac{n}{M}&\geq -2|Du|+2u u_k \frac{n}{M}\\
     &\geq -2|Du| + 2M\frac{|Du|}{\sqrt{n}}{\frac{n}{M}} =2(\sqrt{n}-1)|Du| >0.
\end{align*}
Using (\ref{2_4}) and the fact that $u_k >0 $,
we have $\lambda_k = u_{kk} <0 $. Also, by Lemma 2.1 of \cite{Wang2014}, $|\lambda_n| \leq \lambda_i$ for $i \in \{1,\dots,n-1\}$. Hence, we have $\lambda_k = \lambda_n$.

At the maximum point $x^*$, we have
\begin{equation}
\label{2_5}
    0 \geq \Delta_g w = \Delta_g \eta |Du| + 2g^{\alpha\beta} \eta_a |Du|_\beta+ \eta \Delta_g |Du| + 2\frac{n}{M}g^{\alpha \beta}u_\alpha u_\beta+ 2\frac{n}{M}u\Delta_g u.
\end{equation}
We look at each term separately. We will use diagonal coordinates at $x^*$. Consider the first term, we have
\begin{equation*}
    \Delta_g \eta = -2\sum_\alpha g^{\alpha\alpha} \geq -2ng^{nn},
\end{equation*}
where we use the fact that $|\lambda_n|\leq \lambda_i$ for any $1 \leq i \leq n-1$. Hence, 
\begin{equation}
\label{2_6}
    \Delta_g \eta |Du| \geq -2ng^{nn}|Du|.
\end{equation}
Using (\ref{2_4}), the inequality $|\lambda_n|\leq \lambda_i$ for $1\leq i \leq n-1$, and the bound $M\leq u \leq 2M$ for the second term, we have
\begin{equation}
\label{secondterm2}
\begin{split}
\sum_{\alpha,\beta}2g^{\alpha\beta} \eta_a |Du|_\beta &= \sum_\alpha2g^{\alpha\alpha}(-2x_\alpha)(\frac{2x_\alpha|Du|+2\frac{n}{M}uu_\alpha}{\eta}) \\
&\geq -8g^{nn}(\sum_\alpha x_\alpha^2)\frac{|Du|}{\eta}-8n^2 g^{nn}\frac{|Du|}{\eta}\\
&\geq -8g^{nn}\frac{|Du|}{\eta}-8n^2 g^{nn}\frac{|Du|}{\eta}.
\end{split}
\end{equation}
Directly computing the third term, we have
\begin{align*}
    \Delta_g |Du| &= \sum_{\alpha,\beta} g^{\alpha\beta}\partial_\alpha\partial_\beta|Du|\\
    &= \sum_{\alpha,\beta} g^{\alpha \beta} (\frac{\sum_i u_{i\alpha}u_{\beta i}-\sum_i u_{\alpha\beta i}u_i}{|Du|}-\frac{\sum_i u_i u_{\beta i} \sum_j u_j u_{\alpha j}}{|Du|^3}) \\
    &= \sum_{\alpha,\beta} g^{\alpha \beta} (\frac{\sum_i u_{i\alpha}u_{\beta i}}{|Du|}-\frac{\sum_i u_i u_{\beta i} \sum_j u_j u_{\alpha j}}{|Du|^3}),
\end{align*}
where we use the fact that $\sum_{\alpha,\beta}g^{\alpha\beta}u_{\alpha\beta i} = 0$.
Suppose that, at the point $x^*$, $D^2u$ is diagonal, then
\begin{align*}
    \Delta_g |Du| &= \sum_{\alpha} g^{\alpha \alpha} \frac{ u_{\alpha\alpha}^2|Du|^2- u_\alpha^2 u_{\alpha \alpha}^2 }{|Du|^3} \geq 0.
\end{align*}
Hence, 
\begin{equation}
\label{thirdterm}
    \eta \Delta_g |Du| \geq 0.
\end{equation}
Recall that $u_n \geq \frac{|Du|}{\sqrt{n}}$ at $x^*$ and $|\lambda_n| \leq \lambda_i$ for $i \in \{1,\dots,n-1\}$, we can estimate the fourth term by 
\begin{equation}
\label{fourthterm}
    \sum_\alpha\frac{2n}{M}g^{\alpha\alpha}u_\alpha^2 \geq \frac{2n}{M}g^{nn}u_n^2 \geq \frac{2n}{M}g^{nn}\frac{|Du|^2}{n} = \frac{2}{M}g^{nn}|Du|^2.
\end{equation}
For the fifth term, using the fact that $\lambda_i\geq 0$ for $0\leq i\leq n-1$ and (\ref{2_4}), we have
\begin{equation}
\label{fifthterm2}
\begin{split}
    \Delta_g u=  \sum_\alpha g^{\alpha\alpha}u_{\alpha\alpha} \geq g^{nn}u_{nn}= -g^{nn}\frac{|Du|(\eta_n|Du|+2\frac{n}{M}u u_n)}{u_n\eta} \geq -g^{nn}\frac{6n|Du|}{\eta}.
\end{split}
\end{equation}
Applying the estimates (\ref{2_6}), (\ref{secondterm2}), (\ref{thirdterm}), (\ref{fourthterm}) and (\ref{fifthterm2}) to (\ref{2_5}), we have 
\begin{equation*}
    0 \geq g^{nn}(-C|Du|-\frac{C}{\eta}|Du|+\frac{C}{M}|Du|^2).
\end{equation*}
Hence, we have
\begin{equation*}
    \eta(x^*)|Du(x^*)| \leq CM,
\end{equation*}
and
\begin{equation*}
    |Du(0)| \leq w(0) \leq w(x^*) = \eta|Du(x^*)|+\frac{n}{M}u^2(x^*) 
    \leq CM.
\end{equation*}
\end{proof}

