\begin{lemma}
\label{grad_est}
Let $u$ be a smooth solution to the special Lagrangian equation (\ref{SLE}) with $\theta\geq 0$ on $B_{R}(0) \subset \mathbb{R}^n$. 
\begin{enumerate} [(a)]
 \item (Gradient estimate for Theorem \ref{thm1.1}.) Suppose that $n\geq 3$ and $\lambda(D^2 u) \subset \overline{\Gamma^{\frac{1}{2}(n-2)}_{n-1}}$, then we have 
\begin{equation}
 |Du(0)| \leq C(n)\frac{osc_{B_{R}(0)}u}{R}.
\end{equation}
\item (Gradient estimate for Theorem \ref{thm1.2}.) Suppose that $n = 3$ and $\sigma_2(D^2u) \geq (\frac{3}{5}-\varepsilon) \lambda_2 \lambda_3$ for some constant $\varepsilon >0$ where $\lambda_1 \geq \lambda_2 \geq \lambda_3 $ are eigenvalues of $D^2 u$, then we have 
\begin{equation}
 |Du(0)| \leq C(\varepsilon)\frac{osc_{B_{R}(0)}u}{R}.
\end{equation}
\end{enumerate}

We restate the Jacobi inequalities established by Zhou for our settings.
\begin{lemma}
\label{jacobi1}
 (Jacobi inequality for $n\geq 3).$ (\cite{Zhou2021} Lemma 4.3). 
 Consider the same setting as Theorem \ref{thm1.1}. Let $n\geq 3$ and let $u$ be a smooth solution to the special Lagrangian equation (\ref{SLE}) with $\theta\geq 0$ and $\lambda_1 = \lambda_2 = \dots = \lambda_m = \lambda > \lambda_{m+1} $ at a point $p$. Suppose that $\lambda(D^2 u) \subset \overline{\Gamma_{n-1}^{\frac{1}{2}(n-2)}}$, then there exist constants $\alpha,\delta>0 $ depending only on $n$ such that if $\lambda>\delta$, then $b_m:= \frac{1}{m}\sum_{i=1}^m \lambda_i$ is smooth near $p$ and 
 \begin{equation}
 \Delta_g b_m(p) \geq (1+ \alpha) \frac{|\nabla_g b_m|^2}{b_m}(p).
 \end{equation}

\begin{proposition}
\label{partial_regularity}
Let $n\geq 3$ and let $u_k \in C^\infty(B_2(0))$ be a sequence of smooth solutions to the special Lagrangian equation (\ref{SLE}) in $B_2(0)$ with the phase constant $\theta \geq 0$ and
\[\|u_k\|_{C^{0,1}(B_1(0))} \leq A.\] 
Suppose that a subsequence of $u_k$ converges uniformly in $B_1(0)$ to a continuous function $u \in C^0(B_1(0))$, and either 
\begin{enumerate}
[(i)]
 \item $\lambda(D^2 u_k) \subset \overline{\Gamma^{\frac{1}{2}(n-2)}_{n-1}}$ for all $k \in \mathbb{N}$, or
 \item $n =3$ and there exists a constant $\varepsilon > 0$ such that 
 \[\sigma_2(D^2 u_k) \geq (\frac{3}{5}-\varepsilon) \lambda_2(D^2u_k)\lambda_3(D^2u_k) \text{ for all } k \in \mathbb{N},\]
\end{enumerate}
then $u$ is twice differentiable almost everywhere in $B_1(0)$, and for almost every $x \in B_1(0)$, there is a quadratic polynomial $Q$ such that
\begin{equation}
 \sup_{y\in B_r(x)} |u(y)-Q(y)| = o(r^2).
\end{equation}
\end{proposition}
\begin{proof}
 Without loss of generality, we may assume that $u_k$ converges to $u$ uniformly. We can immediately see that $u$ is Lipschitz:
 \begin{equation}
 \label{lip}
 \|u\|_{C^{0,1}(B_1(0))} \leq A.
 \end{equation}
 Moreover, by Rademacher's theorem, $u$ is almost everywhere differentiable.

\section{Doubling inequality}
\label{section doubling inequality}
In this section, we establish the doubling inequalities for our settings. The argument in \cite{Shankar2024HessianEF} Section 4 applies here with minor modifications. First, if there exists a point $p$ such that $\lambda_{\max}(D^2u(p))$ is not sufficiently large, the Jacobi inequalities in Lemma \ref{jacobi1} and Lemma \ref{jacobi2} may not hold at $p$. However, $\lambda_{\max}(D^2u(p))$ is bounded in this case. Another difference is that, in the setting of Theorem \ref{thm1.2}, there could be two negative eigenvalues at a point $p$. However, by Lemma \ref{n=3eigenvalues}, $|D^2u(p)|$ is bounded in this case.
\begin{proposition}
\label{doubling1}
Let $n\geq 3$ and let $u$ be a smooth solution to the special Lagrangian equation (\ref{SLE}) in $B_2(0)$ with the phase constant $\theta \geq 0$. Suppose that $\lambda(D^2 u) \subset \overline{\Gamma^{\frac{1}{2}(n-2)}_{n-1}}$, then for any $y \in B_{\frac{1}{2}}(0)$ and $r<\frac{1}{4}$, we have
\begin{equation*}
 \sup_{B_\frac{1}{4}(y)} \lambda_{\max}(D^2u) \leq C \sup_{B_r(y)} \lambda_{\max}(D^2u)+C,
\end{equation*}
where $C$ is a constant depending on $r,n$ and $\|u\|_{C^{0,1}(B_1(0))}$.
\end{proposition}
\begin{proof}
 Let $\alpha, h^{-1} \gg 1$ be two constants to be chosen later. We choose the same cutoff function $\eta(x)$ as in \cite{Shankar2024HessianEF} Section 5:
 \begin{equation}
 \eta(x) = ( e^{(S- \varphi(x))/h} - 1)_+,
 \end{equation} where 
 \begin{equation}
 \varphi = (x-y)\cdot Du - u +u(y) - \frac{\alpha^{-1}2^\alpha}{|x-y|^{2\alpha}},
 \end{equation}
 and 
 \begin{equation}
 S = -1 - \|(x-y)\cdot Du - u+u(y)\|_{L^\infty(B_{\frac{1}{2}}(y))} - \alpha^{-1}2^{3\alpha}.
 \end{equation}
 The choice of cutoff function is motivated by Korevaar exponential type cutoff function \cite{Korevaar1987} and Guan-Qiu \cite{GuanQiu2019} type radial derivative $(x-y)\cdot Du - u$. Observe that $S-\varphi<0$ on $\partial B_{\frac{1}{2}}(y)$ and $S-\varphi>0$ on $B_{\frac{1}{4}}(y)$ if $\alpha$ is large enough.

\begin{proposition}
\label{doubling2}
 Let $n=3$ and let $u$ be a smooth solution to the special Lagrangian equation (\ref{SLE}) in $B_2(0)$ with the phase constant $\theta \geq 0$. Suppose that $\sigma_2(D^2u) \geq (\frac{3}{5}-\varepsilon) \lambda_2 \lambda_3$ for some constant $\varepsilon >0$ where $\lambda_1 \geq \lambda_2 \geq \lambda_3 $ are eigenvalues of $D^2 u$, then for any $y \in B_{\frac{1}{2}}(0)$ and $r<\frac{1}{4}$, 
\begin{equation*}
 \sup_{B_\frac{1}{4}(y)} \lambda_{\max}(D^2u) \leq C \sup_{B_r(y)} \lambda_{\max}(D^2u)+C,
\end{equation*}
where $C$ is a constant depending on $r, \|u\|_{C^{0,1}(B_1(0))}$ and $\varepsilon$.
\end{proposition}
\begin{proof}
The proof is nearly identical to that of Proposition \ref{doubling1} except we have an extra case $\lambda_2(p) < 0$. By Lemma \ref{n=3eigenvalues}, we can obtain the bound $|D^2u(p)| \leq \max(1,\varepsilon)$. Hence, the same argument as in Case (a) in Proposition \ref{doubling1} works after replacing the constant $\delta$ by $\max(1,\varepsilon)$.
\end{proof}
\section{Proof of Theorem \ref{thm1.1} and \ref{thm1.2}}
\label{section main theorem proof}
\begin{proof} of Theorem \ref{thm1.1}. Now we have established the Alexandrov-type theorems in Proposition \ref{partial_regularity} and the doubling inequality in Proposition \ref{doubling1}. The proof of Theorem \ref{thm1.1} follows the same argument as in \cite{Shankar2024HessianEF} Section 6, except that we have an additional constant term in the doubling inequality. (6.5) in \cite{Shankar2024HessianEF} will be modified to 
\begin{equation}
 \begin{split}
 \sup_{B_R(y)}|D^2u_k| &\leq C(r,n,A,\sup_{B_r(y)}|D^2u_k|) + C(r,n, A) \\
 &\leq C(r,n,A,C(n,Q,\sigma)) + C(r,n, A)\\
 &\leq C(n,A,Q,\sigma),
 \end{split}
\end{equation}
where $A$ is the uniform upper bound of $\|u_k\|_{C^{0,1}(B_1(0))}$ for any $k \in \mathbb{N}$, $Q$ is the quadratic polynomial given by Proposition \ref{partial_regularity} for the uniform limit $u$ at a point $y$ where $u$ is twice differentiable at, and $\sigma$ satisfies $|u(x)-Q(x)|\leq \sigma(|x-y|) $ with $\sigma(r) =o(r^2)$ as $r\rightarrow 0$. And the rest of the proof is the same.
\end{proof}
\begin{proof}
 of Theorem \ref{thm1.2}. The proof of Theorem \ref{thm1.2} is exactly the same with Theorem \ref{thm1.1} except that we use the doubling inequality in Proposition \ref{doubling2} instead of the one in Proposition \ref{doubling1}. And the constant $C$ depends on $\varepsilon$ as well.
\end{proof}

