We multiply \er{1.11} by $\Phi$ and integrate over $\Omega$ to obtain (for more details see the proof of Lemma 4.1 in \cite{OZ})
\begin{equation}\label{3.14}
 \begin{aligned}
 & \frac{1}{2} \frac{d}{d t}|\Phi|_{2, \Omega}^{2}+\frac{\nu}{2}|\nabla \Phi|_{2, \Omega}^{2} \les c \frac{D_{2}^{2}}{2 \nu}|\nabla \G|_{2, \Omega}^{2}\left(1+\frac{\lp{\vphi}{\iy,\O}{2\dl}R^{2 \delta}}{\dl^{2} D_{2}^{2 \delta}}\right)\\
 &+\frac{1}{\nu}\left|\bar{F}_{r}\right|_{6 / 5, \Omega}^{2},
 \end{aligned}
\end{equation}
where we used the maximum principle \er{2.6}, the Hardy inequality \er{2.1} and \er{2.11}.\\
Multiplying \er{1.12} by $\Gamma$, integrating over $\Omega$ and using the boundary conditions we have
\begin{equation}\label{3.15}
 \begin{aligned}
 &\frac{1}{2} \frac{d}{d t}|\G|_{2, \Omega}^{2}+\frac{\nu}{2}|\nabla\G|_{2, \Omega}^{2} \leqslant 2 \intop_{0}^{t} \frac{\vphi}{r} \Phi \Gamma d x\\
 &+\frac{1}{\nu}\left|F_{\varphi}\right|_{6 / 5, \Omega}^{2} .
 \end{aligned}
\end{equation}
Adding \er{3.14} and \er{3.15} yields
\begin{equation}\label{3.16}
 \begin{aligned}
 &D_{2}^{2} \frac{d}{d t}|\Gamma|_{2, \Omega}^{2}+\nu D_{2}^{2}|D \G|_{2, \Omega}^{2}+\frac{d}{d t}|\Phi|_{2, \Omega}^{2}+\nu|\nb \Phi|_{2, \Omega}^{2}\\
 &\leq c D_{2}^{2}\left(1+\frac{\left|v_{\varphi}\right|_{\iy, \Omega} ^{2 \delta} R^{2 \delta}}{\dl^{2} D_{2}^{2 \delta}}\right)\left[\intop_{\Omega} \frac{\vphi}{r} \Phi \Gamma d x\right. \\
& \left.+\frac{1}{2 \nu}\left(\left|\bar{F}_{r}\right|_{6 / 5, \Omega}^{2}+\left|\bar{F}_{\varphi}\right|_{6 / 5, \Omega}^{2}\right)\right] .
 \end{aligned}
\end{equation}
Using the notation $D_{*}=\min \left\{1, D_{2}\right\}$ in \eqref{3.16} and integrating \er{3.16} with respect to time yields
\begin{equation}\label{3.17}
 \begin{aligned}
&|\Phi\|_{V\left(\Omega^{t}\right)}^{2}+\|\Gamma\|_{V\left(\Omega^{t}\right)}^{2} \les c \frac{D_{2}^{2}}{D_{*}^{2}}\left(1+\frac{\lp{\vphi}{\iy,\Ot}{2\dl}R^{2\delta}}{\dl^2 D_{2}^{2\delta}}\right) \\
& \cdot\left(\intop_{\Omega^{t}} \frac{v_{\varphi}}{r} \Phi \Gamma d x d t^{\prime}+D_{3}^{2}\right),
 \end{aligned}
\end{equation}
where
\begin{equation}\label{3.18}
 \begin{aligned}
D_{3}^{2} & =\frac{1}{2 \nu}\left(\left|\bar{F}_{r}\right|_{6 / 5,2, \Omega^{t}}^{2}+\left|\bar{F}_{\varphi}\right|_{6 / 5,2, \Omega^{t}}^{2}\right) \\
& +|\Phi(0)|_{2, \Omega}^{2}+|\Gamma(0)|_{2, \Omega}^{2} .
\end{aligned}
\end{equation}
Simplifying, we write \eqref{3.17} in the form
\begin{equation}\label{3.19}
 X^{2} \leq\left(D_{10}^{2}+D_{11}^{2}\left|v_{\varphi}\right|_{\infty, \Omega}^{2\delta}\right)\left(\intop_{\Omega^{t}} \frac{v_{\varphi}}{r} \Phi \Gamma d x d t^{\prime}+D_{3}^{2}\right),
\end{equation}
where
$$
D_{10}^{2}=c\frac{D_{2}^{2}}{D_{*}^{2}}, \quad D_{11}^{2}=c\frac{R^{2\delta}}{\delta^2 D_{2}^{2\delta}} \frac{D_{2}^{2}}{D_{*}^{2}} .
$$
Now, we estimate the integral from the r.h.s. of \eqref{3.19}. We note that
$$
\begin{aligned}
& \left|\intop_{\Omega^{t}} \frac{\vphi}{r} \Phi \Gamma d x d t^{\prime}\right| \leqslant \int_{\Omega^{t}}\left|r v_{\varphi}\right|^{1-\varepsilon}\left|v_{\varphi}\right|^{\varepsilon}\left|\frac{\Phi}{r^{1-\varepsilon_{1}}}\right|\left|\frac{\Gamma}{r^{1-\varepsilon_{2}}}\right| d x d t \\
& \leqslant D_{2}^{1-\varepsilon}\left(\intop_{\Omega^{t}}\left|v_{\varphi}\right|^{2 \varepsilon}\left|\frac{\Phi}{r^{1-\varepsilon_{1}}}\right|^{2} d x d t^{\prime}\right)^{1 / 2}\left|\frac{\Gamma}{r^{1-\varepsilon_{2}}}\right|_{2, \Omega^{t}} \equiv I_{1},
\end{aligned}
$$
where $\varepsilon=\varepsilon_{1}+\varepsilon_{2}$.\\
Applying the Hardy inequality in the last factor in $I_{1}$ and also the H\"older in the middle, we get
$$
\begin{aligned}
I_{1} & \leqslant D_{2}^{1-\varepsilon} \frac{R^{\varepsilon_{2}}}{\varepsilon_{2}}\left|v_{\varphi}\right|_{d, \iy, \Omega^{t}}^{\varepsilon}\left|\frac{\Phi}{r^{1-\varepsilon_{1}}}\right|_{\frac{2 d}{d-2 \varepsilon}, 2, \Omega^{t}}|\nabla \Gamma|_{2, \Omega^{t}} \\
& \equiv I_{2}
\end{aligned}
$$
Using Lemma \ref{l2.3} with $s=\left(1-\varepsilon_{1}\right) q, \;q=\frac{2 d}{d-2 \varepsilon},\;p=2$, we get
$$\theta=\frac{3-s}{q}-\frac{1}{2}=\frac{3(d-2 \varepsilon)}{2 d}-\left(1-\varepsilon_{1}\right)-\frac{1}{2}=\varepsilon_{1}\left(1-\frac{3}{d}\right)-\frac{3}{d} \varepsilon_{2}.$$
Since $\theta>0$ we need that $d>3$.
Hence
$$\left|\frac{\Phi}{r^{1-\varepsilon_{1}}}\right|_{q, \Omega} \leq c|\Phi|_{2, \Omega}^{\theta}|\nabla \Phi|_{2, \Omega}^{1-\theta}.$$
Thus,
\begin{align*}
 &I_{2} \leqslant D_{2}^{1-\varepsilon} \frac{R^{\varepsilon_{2}}}{\varepsilon_{2}}\left|v_{\varphi}\right|_{d, \iy, \Ot}^{\varepsilon}|\Phi|_{2, \Ot}^{\theta}|\nabla \Phi|_{2, \Ot}^{1-\theta}|\nabla \Gamma|_{2, \Ot}\\
 &\equiv I_3.
\end{align*}
Using \eqref{2.15} yields
\begin{align*}
 &I_{3} \leq \phi( data )\left|v_{\varphi}\right|_{d, \infty, \Ot}^{\varepsilon}\left[(1+\lp{\vphi}{\iy,\Ot}{2\dl})^{\t/2}{X^{\t/2}}+1\right] X^{2-\theta}\\
 &+\phi( data )\equiv I_4,
\end{align*}
where $data$ replaces all constants from Notation \ref{1.1}.\\
Using \eqref{3.4} with $s=d$ we obtain
\begin{align*}
 &I_{4} \leq \phi_{1}(data)\left(1+\lp{\vphi}{\iy,\Ot}{2\dl}\right)^{\t/2}\left(\frac{D_8}{c_0^{d-4+2\dl}}X+\frac{D_9}{c_0^{d-4+2\dl}}+\right.\\
 & +\lp{\vphi(0)}{d,\O}{4-2\dl}\bigg)^\frac{\ve}{4-2\dl}X^{2-\t/2}+\phi(data).
\end{align*}
Employing the above estimate and \eqref{2.16} in \eqref{3.19} , we get
\begin{equation}\label{3.20}
 X^2\les \phi (data)X^{2+\frac{3}{2} \delta+\fr 3 2 \dl\t+\frac{\varepsilon}{4-2 \delta}-\frac{\theta}{2}}+\phi\left( \fr 1 {c_0},data \right).
\end{equation}
Since $\dl$ is small we consider
$$
\frac{\theta}{2}-\frac{\varepsilon}{4-2 \delta}=\frac{1}{2}\left[\varepsilon_{1}\left(1-\frac{3}{d}\right)-\frac{3}{d} \varepsilon_{2}\right]-\frac{\varepsilon}{4-2 \dl} \equiv J_{1} .
$$
For $\delta$ small we have
$$
J_{1}=\varepsilon_{1}\left[\frac{1}{2}\left(1-\frac{3}{d}\right)-\frac{1}{4}\right]-\frac{3}{d} \varepsilon_{2}-\frac{\varepsilon_{2}}{4-2 \delta}.
$$
We see that $J_{1}$ is positive for $\ve_2$ small if
$$
\frac{1}{2}\left(1-\frac{3}{d}\right)-\frac{1}{4}>0 \quad \text { so } \quad d>6.
$$
Then for sufficiently small $\varepsilon_{2}, \delta$, the Young inequality applied to \eqref{3.20} yields the estimate \eqref{3.13}. This concludes the proof. 
\end{proof}

Let $c_{0}$ be given.\\
In Lemma \ref{3.2} it is proved the estimate
\begin{equation}\label{5.1}
 X\les \phi_1\left(\fr 1 {c_0},data\right).
\end{equation}
if
\begin{equation}\label{5.2}
 \frac{\left|v_{\varphi}\right|_{s, \iy,\Ot}}{\left|v_{\varphi}\right|_{\iy, \Ot}} \geqslant c_{0}\;\text{ if }\;s>6.
\end{equation}
In Lemma \ref{l4.1} and Remark \ref{r4.2} we found the estimate
\begin{equation}\label{5.3}
 X \leq \phi_{2}\left(c_{0},data\right)
\end{equation}
if
\begin{equation}\label{5.4}
 \frac{\left|v_{\varphi}\right|_{s, \iy,\Ot}}{\left|v_{\varphi}\right|_{\iy, \Ot}} \geqslant c_{0}\;\text{ if }\;s>6.
\end{equation}
Hence we have
\begin{theorem}\label{t5.1}
 Assume that all parameters in Notation 1.1 are finite.
Then
\begin{equation}
 X \leq \phi_{1}\left(\frac{1}{c_{0}}, data \right)+\phi_{2}\left(c_{0}\right., data),\; s>6.
\end{equation}
The estimate implies existence of global regular solutions to problem \er{1.1}-\er{1.3}.
\end{theorem}

