\begin{align}
U(z)&=\integ{x}{-\infty}[z]<C_x(x-z,c,\epsilon)\left(\integ{y}{x-a}[x]<K(y)>\right)>,\label{eq: U_formal} \\
Q(z)&=\integ{x}{-\infty}[z]<D_x(x-z,c,\epsilon)\left(\integ{y}{x-a}[x]<K(y)>\right)>, \label{eq: Q_formal}\\
