\end{align}
where 
\begin{align}
C(x,c,\epsilon)&=\frac{1}{\omega_1-\omega_2}\left[\f{1-\omega_2}{\omega_1}e^{\frac{\omega_1 x}{c}}-\f{1-\omega_1}{\omega_2}e^{\frac{\omega_2 x}{c}}\right], \label{eq: C}\\
C_x(x,c,\epsilon)&=\frac{1}{c(\omega_1-\omega_2)}\left[(1-\omega_2)e^{\frac{\omega_1 x}{c}}-(1-\omega_1)e^{\frac{\omega_2 x}{c}}\right], \label{eq: Cx}\\
D(x,c,\epsilon)&=\frac{\epsilon}{\omega_1-\omega_2}\left[-\f{\omega_1}e^{\frac{\omega_1 x}{c}}+\f{\omega_2}e^{\frac{\omega_2 x}{c}}\right], \label{eq: D} \\
D_x(x,c,\epsilon)&=\frac{\epsilon}{c(\omega_1-\omega_2)}\left[-e^{\frac{\omega_1 x}{c}}+e^{\frac{\omega_2 x}{c}}\right]. \label{eq: Dx}
\end{align}
Using the properties of $\omega_1$ and $\omega_2$ from \eqref{eq: limits_eig}--\eqref{eq: omega_calcs}, we see that
\begin{align*}
C(0,c,\epsilon)&=\f{\omega_2(1-\omega_2)-\omega_1(1-\omega_1)}{\omega_1\omega_2(\omega_1-\omega_2)}=\f{-1+\omega_1+\omega_2}{\omega_1\omega_2}=\f{\gamma}{1+\gamma}, \numberthis \label{eq: C0}\\
D(0,c,\epsilon)&=\f{\epsilon}{\omega_1\omega_2}=\f{1+\gamma}. \numberthis \label{eq: D0}
\end{align*}

This brings us to the main difficulty and purpose of this paper. When is a solution to \eqref{eq: ansatz} really a solution to \eqref{eq: intro_system_1}--\eqref{eq: intro_system_2}? Assuming only the existence of a front (that we show is always unique), how do we prove the existence of unique parameters $(a(\epsilon),c(\epsilon))$ that solve the compatibility equations $U(0)=U(a)=\theta$? How do we demonstrate that the sub and super threshold regions truly correspond and that the pulse is close to the singular homoclinic orbit? Can we compare the difference between the pulse and front speed up to first order in $\epsilon$? We answer all of these questions.

\subsection{Main Results}\label{subsec: main_goal}
Our main goal is to rigorously prove the existence and uniqueness of fast traveling pulses to system \eqref{eq: intro_system_1}-\eqref{eq: intro_system_2} under minimal assumptions. In particular, we prove the following theorems, assuming hypotheses (H1)--(H3) discussed in \cref{subsec: hyp}.

In particular, to the author's knowledge, there have been no other results that rigorously study the fast pulse solutions in the Heaviside model when they are broken down by fast and slow representations in inner and outer regions for $\epsilon \ll 1$. Unlike the singular homoclinic orbit, when $\epsilon>0$, the fast and slow dynamics need to be analyzed when they overlap. When $K$ is chosen as the exponential type. we have PDE reductions and applications of classic geometric singular perturbation theory can be applied. We avoid requiring this reduction.

Finally, for $\Gamma_4$, with $z\in R_3$, we have 
\begin{align*}
|\Gamma_4(z,\epsilon)|&\leq \f{\alpha}{c_\epsilon(\omega_1-\omega_2)}\integ{x}{0}[z]<\left[(1-\omega_2)e^{\f{\omega_1(x-z)}{c_\epsilon}}+(1-\omega_1)e^{\f{\omega_2(x-z)}{c_\epsilon}}\right]\left(\integ{y}{x}[\infty]<e^{-\rho y}>\right)> \numberthis \label{eq: Gamma4_inequal}\\
&=\f{\alpha}{\rho(\omega_1-\omega_2)}\left[\f{1-\omega_2}{\omega_1-\rho c_\epsilon}\left(e^{-\rho z}-e^{-\f{\omega_1 z}{c_\epsilon}}\right)+\f{1-\omega_1}{\omega_2-\rho c_\epsilon}\left(e^{-\rho z}-e^{-\f{\omega_2 z}{c_\epsilon}}\right)\right] \\
&\leq \f{\alpha}{\rho(\omega_1-\omega_2)}\left[\f{1-\omega_2}{|\omega_1-\rho c_\epsilon|}\left(e^{-\rho (a_\epsilon-z_0)}+e^{-\f{\omega_1 (a_\epsilon-z_0)}{c_\epsilon}}\right)+\f{2(1-\omega_1)}{|\omega_2-\rho c_\epsilon|}\right] \longrightarrow 0
\end{align*}
\end{proof}
\begin{lemma}\label{lemma: unif_aminb_a}
There exists $\epsilon_3\leq \epsilon_2$ such that for all $\epsilon<\epsilon_3$, the uniform estimates on $R_3$ of $U_\epsilon(z)\approx U_b(z-a_\epsilon)$, $U_\epsilon'(z)\approx U_b'(z-a_\epsilon)$, and $Q_\epsilon(z)\approx 1-2\theta$ hold. The estimates are as close as we desire as $\epsilon\to 0$.
\end{lemma}
\begin{proof}
The uniform limit $(U_\epsilon(z)-U_b(z-a_\epsilon)\chi_{R_3}\to 0$ follows directly from \cref{prop: Gamma_errors}. For $Q_\epsilon$, after writing it in a similar way to that of $U_\epsilon$ in \eqref{eq: U_R3}. A tedious adjustment of \cref{prop: Gamma_errors} results in $(Q_\epsilon(z)-\underbrace{Q_b(z-a_\epsilon)}_{=1-2\theta})\chi_{R_3} \to 0$ uniformly. Finally, the back satisfies
\begin{equation} \label{eq: Uback_diff}
c_f U_b'(z-a_\epsilon)+U_b(z-a_\epsilon)+(1-2\theta)=\integ{x}{z-a_\epsilon}[\infty]<K(x)>=1-\integ{x}{-\infty}[z-a_\epsilon]<K(x)>,
\end{equation}
while $U_\epsilon$ satisfies
\begin{equation}\label{eq: U_R3_diff}
c_\epsilon U_\epsilon'(z)+U_\epsilon(z)+Q_\epsilon(z)=1-\left(\int_z^\infty+\int_{-\infty}^{z-a_\epsilon}\right)K(x)\,\mathrm{d}x.
\end{equation}
Subtracting \eqref{eq: Uback_diff} from \eqref{eq: U_R3_diff} leads to the inequality
\begin{align*}
|c_\epsilon U_\epsilon'(z)-c_f U_b'(z-a_\epsilon)| &\leq |U_\epsilon(z)-U_b(z-a_\epsilon)|+|Q_\epsilon(z)-(1-2\theta)| \\
&\phantom{\leq}+\integ{x}{a_\epsilon-z_0}[\infty]<|K(x)|>\longrightarrow 0
\end{align*}
so $(U_\epsilon'(z)-U_b'(z-a_\epsilon))\chi_{R_3}\to 0$ uniformly.
\end{proof}
In conclusion, for $\epsilon<\epsilon_3$, the curve $(U_\epsilon,Q_\epsilon)$ is uniformly close to the (fast time) back in the singular homoclinic orbit, and because $U_\epsilon'(z)\approx U_b'(z-a_\epsilon)$ and $Q_\epsilon'(z)\approx Q_b'(z-a_\epsilon)=0$ as well (where $U_b'(0)<0$), the solution successfully crosses the threshold from above one time at $z=a_\epsilon$. We conclude this subsection with a statement about the Hausdorff distance which is similar to \cref{prop: R1_Hausdorff}. If necessary, ensure $d(s_\epsilon(z),x_b(z-a_\epsilon))\chi_{R_3}<\f{\delta}{2}$ for all $z\in\R$.
\begin{proposition}\label{prop: R3_Hausdorff}
The estimate $d_H(\mathcal{S}_\epsilon^3,\mathcal{B}_0)< \delta$ holds for all $\epsilon<\epsilon_3$. Moreover, $s_\epsilon(a_\epsilon+z_0)\in B_d(\mathcal{M}_0^L,\delta)$.
\end{proposition}
\begin{proof}
Firstly,
\begin{equation}\label{eq: Haus_R3_first}
\sup_{z\in R_3}d(s_\epsilon(z),\mathcal{B}_0)\leq \sup_{z\in R_3}d(s_\epsilon(z),x_b(z-a_\epsilon)) <\f{\delta}{2}.
\end{equation}
On the other hand, let $x_b(z) \in \mathcal{B}_0$. If $|z-a_\epsilon |\leq z_0$, then
$$
d(\mathcal{S}_\epsilon^3,x_b(z-a_\epsilon))\leq d(s_\epsilon(z),x_b(z-a_\epsilon)) <\f{\delta}{2}.
$$
If $z-a_\epsilon>z_0$, then
$
d(\mathcal{S}_\epsilon^3,x_b(z-a_\epsilon))\leq d(s_\epsilon(a_\epsilon+z_0),x_b(z-a_\epsilon))$, which is bounded by
$$
d(x_b(z-a_\epsilon),m_L(1-2\theta))+ d(m_L(1-2\theta),x_b(z_0))+d(x_b(z_0),s_\epsilon(a_\epsilon +z_0))<\delta
$$
using \eqref{eq: z0_second}. The $z-a_\epsilon<-z_0$ case is similar. It is clear that $d_H(\mathcal{S}_\epsilon^3,\mathcal{B}_0)<\delta$.

Finally, for $L_5$, since $e^{-\f{\omega_i z}{c_\epsilon}}<e^{-\f{\omega_i (z-a_\epsilon)}{c_\epsilon}}$, we have
\begin{align*}
|L_5(z,\epsilon)|&< \f{2}{\omega_1-\omega_2}\left[\left(\f{1-\omega_2-\epsilon}{\omega_1}\right) e^{-\f{\omega_1 (z-a_\epsilon)}{c_\epsilon}}+\left|\f{1-\omega_1-\epsilon}{\omega_2}\right| e^{-\f{\omega_2 (z-a_\epsilon)}{c_\epsilon}}\right]\\
&\leq \f{2}{\omega_1-\omega_2}\left[\left(\f{1-\omega_2-\epsilon}{\omega_1}\right) e^{-\f{\omega_1 (\tau_1+\epsilon z_0)}{\epsilon c_\epsilon}}+\left|\f{1-\omega_1-\epsilon}{\omega_2}\right|\right] \longrightarrow 0.
\end{align*}
In conclusion, $W_\epsilon(z)\chi_{R_4^2}\to 0$ uniformly. For the derivative, by adding the $U_\epsilon$ and $Q_\epsilon$ equations, we find
\begin{align*}
c_\epsilon |W_\epsilon'(z)|\leq |W_\epsilon(z)|+\epsilon |U_\epsilon(z)-\gamma Q_\epsilon(z)|+\integ{x}{\f{\tau_1}{\epsilon}}[\infty]<|K(x)|> \longrightarrow 0.
\end{align*}
This concludes the proof.
\end{proof}
After $\epsilon_4\leq \epsilon_3$ is chosen so that $d(s_\epsilon(z),\mathcal{M}_0^L)<\delta$ for all $z\in R_4^2$, we have enough information to complete the proof of \cref{thm: E}.
\begin{proposition}\label{prop: R4_Hausdorff}
The limit $d_H(\mathcal{S}_\epsilon,\mathcal{S}_0)\to 0$ holds.
\end{proposition}
\begin{proof}
Since $s_\epsilon(a_\epsilon+z_0)\in B_d(\mathcal{M}_0^L,\delta)$, we may combine \cref{prop: R4_nearline,lemma: UplusQ_R4_errors} to show $d(\mathcal{S}_\epsilon^4,\mathcal{M}_0^L)<3\delta$ by a similar proof seen in \cref{prop: R2_Haus_proof} on $R_2$. It follows that for $\epsilon<\epsilon_4$, we have
$$
\max \Bigl\{d(\mathcal{S}_\epsilon^1,\mathcal{F}_0),d(\mathcal{S}_\epsilon^2,\mathcal{M}_0^R),d(\mathcal{S}_\epsilon^3,\mathcal{B}_0),d(\mathcal{S}_\epsilon^4,\mathcal{M}_0^L) \Bigr\}<3\delta.
$$
Hence, by \cref{prop: dH_regions}, it follows that $d_H(\mathcal{S}_\epsilon,\mathcal{S}_0)<3\delta$.
\end{proof}
In conclusion, we proved in this section that $U_\epsilon$ crosses the threshold only at $z=0$ and $z=a_\epsilon$. Therefore, the formal homoclinic orbit connecting $(u,q)=(0,0)$ to itself is a true solution to the original system with Heaviside nonlinearity structure. Moreover, the homoclinic orbit is as close to the singular homoclinic orbit as we desire. This completes the proof of \cref{thm: E}.
\section*{Discussion}
In the present study, we successfully completed a rigorous proof of the existence and uniqueness (modulo translation) of fast traveling pulse solutions to the standard nonlocal, singularly perturbed neural field system with Heaviside activation functions and linear feedback. In \cref{sec: calc}, we changed the time scale in the two speed index functions due to the $O\left(\f{\epsilon}\right)$ second threshold crossing point. This allowed us to proceed with first-order approximations of the differences between pulse and front speed, not seen in previous literature. We also showed that, provided they exist, traveling fronts with single threshold crossing points have speed index functions with unique positive roots. Therefore, the corresponding Evans function cannot have positive zeros and $\lambda=0$ is always simple.

post_theorem_intro_text:
As a result of the original work of Pinto and Ermentrout \cite{PintoandErmentrout-SpatiallyStructuredActivityinSynapticallyCoupledI.TravelingWaves}, as well as follow-up mathematical analysis (such as  by Pinto et al. \cite{Pinto2005}), there is a heuristically and computationally justified acceptance of much of \cref{thm: E} (especially for nonnegative kernels), but a complete proof of existence and uniqueness is lacking prior to this paper. 

In particular, to the author's knowledge, there have been no other results that rigorously study the fast pulse solutions in the Heaviside model when they are broken down by fast and slow representations in inner and outer regions for $\epsilon \ll 1$. Unlike the singular homoclinic orbit, when $\epsilon>0$, the fast and slow dynamics need to be analyzed when they overlap. When $K$ is chosen as the exponential type. we have PDE reductions and applications of classic geometric singular perturbation theory can be applied. We avoid requiring this reduction.

In order to prove \cref{thm: E}, we derive a number of new estimates of the solutions and their wave speeds and widths. The following corollary summarizes first-order approximations of the parameters. Denote $\tau(\epsilon):=\epsilon a(\epsilon)$, a natural change of variable since $a(\epsilon)=O\left(\f{\epsilon}\right)$ is known based on the fast and slow time scales. The functions $f$ and $g$ are discussed at length in \cref{sec: calc}.
\begin{corollary}[First-Order Approximations of $\tau(\epsilon)$ and $c(\epsilon)$] \label{thm: first_order}Consider the unique pair of $C^1$ curves $\tau_\epsilon=\tau(\epsilon)$ and $c_\epsilon=c(\epsilon)$ from \cref{thm: E}. The limits $\tau(\epsilon)\to \tau_0$ and $c(\epsilon)\to c_f$ hold, where
$$
\tau_0=-\f{c_f}{1+\gamma}\ln(2\theta(1+\gamma)-\gamma).
$$
The derivative of the vector $(\tau(\epsilon),c(\epsilon))^T$ satisfies
\begin{equation}
 \begin{pmatrix}
\tau'(0) \\ c'(0)
\end{pmatrix}
=-J^{-1}(\tau_0,c_f,0)
\begin{pmatrix}
f_\epsilon(\tau_0,c_f,0) \\ g_\epsilon(\tau_0,c_f,0)
\end{pmatrix},
\end{equation}
where $f(\tau(\epsilon),c(\epsilon),\epsilon)=U(0)=\theta$ and $g(\tau(\epsilon),c(\epsilon),\epsilon)=U(a(\epsilon))=\theta$ are the speed index equations for the pulse. Hence, $\tau(\epsilon)\approx \tau_0 +\tau'(0)\epsilon$ and $c(\epsilon)\approx c_f +c'(0)\epsilon$ are first-order approximations of $\tau(\epsilon)$ and $c(\epsilon)$, respectively. In particular,
\begin{equation}\label{eq: cp_zero}
c'(0)=-\f{\phi_f'(c_f)}\left\lbrace 2\theta-\f{c_f}\integ{x}{-\infty}[0]<|x|\left(e^{\f{x}{c_f}}+1\right)K(x)>\right\rbrace,
\end{equation}
where $\phi_f$ is the speed index function for the front that satisfies $\phi_f'(c_f)<0$.
\end{corollary}
\subsection{Hypotheses} \label{subsec: hyp}
We state our main hypotheses and then offer some remarks as to why they are necessary.
\begin{itemize}
\item[(H1)] The parameters satisfy $0<\theta<\min\{\f{2},\int_{-\infty}^0 K\}$, \, $\f{\gamma}{1+\gamma}<\theta,\,$ and $\epsilon \ll 1$.
\item[(H2)] When $\epsilon=0$, there exists a traveling front solution $u(x,t)=U_f(x+c_ft)$ to \eqref{eq: intro_scalar} with $U_f(\cdot)<\theta$ on $(-\infty,0)$, $U_f(\cdot)>\theta$ on $(0,\infty)$, $U_f(-\infty)=0$, and $U_f(\infty)=1$. The solution is translation invariant, but we will assume $U_f(0)=\theta$ unless stated otherwise.
\item[(H3)] There exists $\alpha>0$ and $\rho>0$ such that $|K(x)|\leq \alpha e^{-\rho|x|}$. Moreover, assume $K$ is continuous and $\int_\R K = 1$.
\end{itemize}
We require $0<\theta<\int_{-\infty}^0 K$ because it is necessary in order for the front to exist, while $\theta <\f{2}$ is required for the pulse. Often $K$ is symmetrical so these conditions are equivalent. To conclude remarks on (H1), we note that the assumption $\frac{\gamma}{1+\gamma}<\theta$ ensures that the line $Q=\frac{U}{\gamma}$ does not intersect $Q=-U+H(U-\theta)$ when $U>\theta$, which would lead to a second fixed point, and the homoclinic orbit would be replaced by a heteroclinic orbit. Hypothesis (H2) ensures we have a leading order inner solution. Finally, hypothesis (H3) is a common assumption in nonlocal problems. Biologically, long-range synaptic interaction strengths decay sharply, while mathematically, exponential decay ensures that terms of order $O\left(\epsilon^{-k}e^{-\f{|C|}{\epsilon}}\right)$ vanish.

expanded_theorem:
[Existence and Uniqueness of Fast Pulses]\label{thm: E}
When $0<\epsilon \ll 1,$ there exists a unique $C^2$ (modulo translation) fast traveling pulse solution $(U_\epsilon,Q_\epsilon)$ to the system
\begin{align}\nu_t&=-u-q+ \\integ{y}{\R}[]<K(x-y)H(u(y,t)-\theta)>, \\label{eq: intro_system_1}\\
q_t &=\epsilon (u-\gamma q). \\label{eq: intro_system_2}
\end{align}
In particular, with $z=x+ct$, there exists unique $C^1$ curves $c_\epsilon=c(\epsilon)$ and $a_\epsilon=a(\epsilon)$ such that $U_\epsilon(z)<\theta$ on $(-\infty,0)\cup(a_\epsilon,\infty)$ and $U_\epsilon(z)>\theta$ on $(0,a_\epsilon)$. The parameters satisfy $c_\epsilon\to c_f$ and $a_\epsilon\to +\infty$ as $\epsilon \to 0$, where $c_f>0$ is the unique speed of the front solution to \eqref{eq: intro_scalar}. As a homoclinic orbit, $\mathcal{S}_\epsilon=\Bigl\{(U_\epsilon(z),Q_\epsilon(z)): z\in \R \Bigr\}$ satisfies $d_H(\mathcal{S}_\epsilon,\mathcal{S}_0)\to 0$ as $\epsilon\to 0$. Here, 
$$
d_H(\mathcal{S}_\epsilon,\mathcal{S}_0)=\max\left\lbrace \sup_{(U,Q)\in \mathcal{S}_0}d\Bigl(\mathcal{S}_\epsilon,(U,Q)\Bigr),\sup_{(U_\epsilon,Q_\epsilon)\in \mathcal{S}_\epsilon}d\Bigl((U_\epsilon,Q_\epsilon),\mathcal{S}_0\Bigr) \right\rbrace
$$ 
is the Hausdorff distance between sets in $(U,Q)$ space with respect to the standard Euclidean metric, and $\mathcal{S}_0$ is the singular homoclinic orbit at $\epsilon=0$.

ref_dict.def:phi homogenization:
\begin{Definition}\label{def:phi homogenization}
Fix $\lambda = \lambda(n) > 0$ sufficiently small such that $\sigma = C_1(n)\lambda$ satisfies $4^{n+1}\sigma < c(n)$, where $C_1(n)$ is the one in Lemma \ref{lem:covering Lemma} and $c(n)$ is the one in Proposition \ref{prop:basic}. For $\Lambda\ge \max\{\Lambda_0,\Lambda_1,\Lambda_2\}$, and any nonnegative functions $v \in C(\Omega)$, we define its $\phi$-homogenization $M_{\phi,\Lambda}v(x):=M_{\phi,\lambda,\Lambda}v(x)$ in $\frac{7}{8}\Omega$ through the following maximal averaging type operator:
\begin{equation}\label{eq:phi homogenization}
\begin{split}
M_{\phi,\Lambda}v(x)=  \sup\left\{ t\in\R:\; \exists \ \check{h}(x)<h<  \hat{h}(x),\ s.t., \
\frac{\mu ( \{v> t\} \cap S_h (x)  )}{\mu(S_h (x))} > \lambda \right\}.
\end{split}
\end{equation}  
\end{Definition}

ref_dict.thm:solutions are periodic:
\begin{Theorem}\label{thm:solutions are periodic}
Let $\mu \not\equiv 0$ be a nonnegative locally finite Borel measure satisfying \eqref{eq:periodic f}, and let $u$ be a convex solution of \eqref{eq:periodic equation ma}. Then $u$ is a periodic solution in the sense of Definition \ref{def:periodic solution}.
\end{Theorem}

ref_dict.thm:uniqueness within periodic:
\begin{Theorem}\label{thm:uniqueness within periodic}
Let $\mu \not\equiv 0$ be a nonnegative locally finite Borel measure satisfying \eqref{eq:periodic f}, and let $P(x)=\frac{1}{2}x^{\top}Ax+b\cdot x+c$ be a quadratic function with $A\in \mathcal{S}_+^{n\times n}$ satisfying \eqref{eq:A compatible}. Then there exists a unique periodic solution (up to addition of constants) to \eqref{eq:periodic equation ma} with quadratic component $P$.  
\end{Theorem}

ref_dict.def:periodic solution:
\begin{Definition}[Periodic solution]\label{def:periodic solution}
A \emph{periodic solution} to \eqref{eq:periodic equation ma} is a convex function $u \in C(\mathbb{R}^n)$ satisfying \eqref{eq:periodic equation ma} in the Alexandrov sense, and can be decomposed as
\begin{equation}\label{eq:periodic solution}
u(x) = v(x) +P(x),
\end{equation}
where $v$ is periodic  with respect to  $\mathbb{Z}^n$ and  $P(x)=\frac{1}{2}x^{\top}Ax+b\cdot x+c$ is a quadratic function with $A\in \mathcal{S}_+^{n\times n}$, $b\in\R^n$ and $c\in\R$.  
\end{Definition}

ref_dict.thm:harnack super:
\begin{Theorem}\label{thm:harnack super} 
Assume that $v \in C^2(\Omega)$ is a nonnegative supersolution of \eqref{eq:linearized ma phi} in $\Omega$.
Then there exist positive constants  $\Lambda_6(n)$, $\epsilon(n) $ and $C(n) $ such that if 
\[
\inf_{B_{1/4}} v \leq 1,
\]
then for $\Lambda\ge \Lambda_6(n)$, we have
\begin{equation}\label{eq:harnack super} 
\mu(\{M_{\phi,\Lambda}v >  t\} \cap B_{1/2})< Ct^{-\epsilon} .
\end{equation} 
\end{Theorem}

ref_dict.prop:semiconcave:
\begin{Proposition}\label{prop:semiconcave}
Let $u$ be a convex solution to \eqref{eq:periodic equation ma} with $\mu$ being a $\mathbb{Z}^n/8n$-periodic measure (where $\mathbb{Z}^n := \Gamma_{\{e_1,\cdots,e_n\}}$) satisfying $\mu(\mathbb{Z}^n) = 1$. 
Under the nondegeneracy condition
\begin{equation}\label{eq:nondegenerate}
\Delta^2_{i} u(0):=\Delta^2_{e_i} u(0) > 0 \quad \text{for all } 1 \leq i \leq n,
\end{equation}
there exists a unique compatible matrix $A$ satisfying:
\[
\sup_{ \R^n}\Delta_z^2  u=z^{\top}Az ,\quad \forall z \in \mathbb{Z}^n.
\]
\end{Proposition}

pre_theorem_intro_text:
In this paper, we study convex solutions to the  Monge-Amp\`ere equation
\begin{equation}\label{eq:periodic equation ma}
\det D^2 u = \mu \quad \text{in } \mathbb{R}^n,
\end{equation}
where $\mu\not\equiv 0$ is a nonnegative locally finite  Borel measure on $\mathbb{R}^n$ and is periodic in  $n$ linearly independent directions. By exploiting the affine invariance of the equation, we may, without loss of generality, restrict our analysis to the case where $\mu $ is periodic with respect to the integer lattice $\mathbb{Z}^n := \{(k_1,\dots,k_n) \mid k_i \in \mathbb{Z}\} \subset \mathbb{R}^n$, i.e., for any Borel set $E \subset \mathbb{R}^n$,  
\begin{equation}\label{eq:periodic f}
\mu (E+z)=\mu (E),\quad \forall \ z \in \mathbb{Z}^n.
\end{equation}

Let $\mathcal{S}_+^{n\times n}$ denote the set of positive definite symmetric $n\times n$ matrices.
\begin{Definition}[Periodic solution]\label{def:periodic solution}
A \emph{periodic solution} to \eqref{eq:periodic equation ma} is a convex function $u \in C(\mathbb{R}^n)$ satisfying \eqref{eq:periodic equation ma} in the Alexandrov sense, and can be decomposed as
\begin{equation}\label{eq:periodic solution}
u(x) = v(x) +P(x),
\end{equation}
where $v$ is periodic  with respect to  $\mathbb{Z}^n$ and  $P(x)=\frac{1}{2}x^{\top}Ax+b\cdot x+c$ is a quadratic function with $A\in \mathcal{S}_+^{n\times n}$, $b\in\mathbb{R}^n$ and $c\in\mathbb{R}$.  
\end{Definition}

Note that if $u$ is a periodic solution to \eqref{eq:periodic equation ma} and is expressed as \eqref{eq:periodic solution}, then the quadratic component $P(x)$ always satisfies the compatibility condition
\begin{equation}\label{eq:A compatible}
 \det A =\mu (\mathbb{T}^n),
\end{equation} 
where $\mathbb{T}^n=\mathbb{R}^n/\mathbb{Z}^n$.

Our first result is the uniqueness of periodic solutions.

