        &\leq j\ \p(X_i\geq j^{1+\epsilon})+\frac{j\ \e(X_i\cdot1_{X_i\leq j^{1+\epsilon}})}{Cj^{1+\epsilon}}\nonumber\\
        &\leq j^{-\epsilon}(1+C^{-1}(1+\epsilon)\log j).\label{eq:1.3}
    \end{align}

