\subsection{The Upper Bound}\label{se:4}
In this subsection, we prove the upper bound of Proposition \ref{prop 1.3}, namely:
\begin{proposition}\label{prop4.1}
\begin{equation*}
 \limsup_{M\to\infty} \frac{\log\left(\p\left(\max\limits_{1\leq m\leq \sigma-1}\curvevisitonenumber{m}\geq M\right)\right)}{2\sqrt{M}}= -1.
\end{equation*}
\end{proposition}
The upper bound is established through a delicate bootstrapping (self-improving) iterative framework. Within this framework, the proofs of the following three lemmas are postponed, as they are technical yet essential for deriving Proposition \ref{prop4.1}. Define, for any $c>0$,
\begin{equation}
 h(c):=\limsup_{M\to\infty} \frac{\log\left(\p\left(\max\limits_{1\leq s\leq \text{e}^{c\sqrt{M}}}g(s)\geq M\right)\right)}{2\sqrt{M}}.\label{eq:4.0}
\end{equation}
\begin{lemma}\label{lem4.2}
 For any $0<N_1<N_2$ such that $\p\left(\max\limits_{1\leq s\leq N_2}g(s)\geq M\right)\leq 0.1$, we have
 \begin{equation}
 \p\left(\max\limits_{1\leq s\leq N_2}g(s)\geq M\right)\geq \frac{N_2-N_1}{8N_1(\log N_1+1)}\p\left(\max\limits_{1\leq s\leq N_1}g(s)\geq M\right).\label{eq:lem4.2}
 \end{equation}
\end{lemma}
Suppose
\begin{equation}\label{eq:3.1}
 \Theta:=\limsup_{M\to\infty} \frac{\log\left(\p\left(\max\limits_{1\leq m\leq \sigma-1}\curvevisitonenumber{m}\geq M\right)\right)}{2\sqrt{M}}.
\end{equation}
\begin{lemma}\label{lem4.3}
 For any $0<c<-2\Theta+\frac{(1+\Theta)^{2}}{2}$,
 \footnote{The motivation for writing the expression as $-2\Theta+\frac{(1+\Theta)^2}{2}$ is to clearly show that it exceeds $-2\Theta$ by precisely $\frac{(1+\Theta)^2}{2}$. The same logic applies to the analogous expressions that follow.}
 \begin{equation}
 h(c)\leq \frac{c}{2}+\Theta-\frac{(1+\Theta)^2}{4}.\label{eq:lem4.3}
 \end{equation}
\end{lemma}
\begin{lemma}\label{lem4.4}
 If \eqref{eq:lem4.3} holds for $c\leq c_1$, then it holds for any
 $$c=c_2<\min\left(1+\frac{1-\Theta}{4}c_1,-2\Theta+\frac{(1+\Theta)^{2}}{2}\right).$$
\end{lemma}
We now proceed to prove Proposition \ref{prop4.1} on the basis of the three lemmas established above.

Since the proof of Lemma \ref{lem4.3} relies on Lemma \ref{lem4.4}, we first prove the latter.
\begin{proof}[Proof of Lemma \ref{lem4.4}]
 Define event
 \begin{equation*}
 \mathcal{G}_{s_1,s_2}:=\left\{ s_1<s\leq s_2 : \exists \ k,\ 1 \leq k \leq \tau^G_{s_2}, \text{ such that } G_k = s, \text{ and } G_l \neq s \text{ for } 1 \leq l \leq \tau^G_{s_1},\ l \neq k \right\}
 \end{equation*}
Then, $\mathcal{G}_{s_2} \subset \mathcal{G}_{s_1} \cup \mathcal{G}_{s_1,s_2}$ for all $s_1<s_2$.
Assume $c_2 > 1$ and let $N_1 = \lfloor e^{(2c_2 - 2)\sqrt{M}} \rfloor$. With this, define$\tilde{\beta}_{1,k}:=\tau_{kN_1+1}^{G}$. Then, for $i \geq 1$, we define the following stopping times:
 \begin{align*}
 &\tilde\gamma_{i,k}:=\inf\{n>\tilde\beta_{i,k}:\ G_n\in \{G_{\tilde\beta_{i,k}}-1,(k+1)N_1\}\};\\ &\tilde\beta_{i+1,k}:=\inf\{n>\gamma_{i,k}':\ G_n=M^G_{\gamma_{i,k}'}+1\}.
 \end{align*}
 Under the condition that $M^G_{\tilde\gamma_{i,k}}-G_{\tilde\beta_{i,k}}=l-1$, we have
 $$(G_{n+{\tilde\beta_{i,k}}-1}-G_{{\tilde\beta_{i,k}}})_{1\leq n\leq \tau^G_{{G_{\tilde\beta_{i,k}}+l-1}}} \stackrel{d}{=}(G_n)_{1\leq n\leq \tau^G_{l}}.$$
 Then for any $M'>0$ and $k\le a_k$ such that $G_{\tilde\gamma_{a_k,k}}=(k+1)N_1$, we have
 \begin{equation}
 \p\left(\left.\max_{G_{\tilde\beta_{i,k}}\leq s<G_{\tilde\beta_{i+1,k}}}|\mathcal{G}_{kN_1,s}|\geq M'\right| M^G_{\tilde\gamma_{i,k}}-G_{\tilde\beta_{i,k}}=l-1,\mathcal{F}^G_{\tilde\beta_{i,k}}\right)=\p\left(\max\limits_{1\le s\le l}g(s)\geq M'\right).\label{eq:4.4}
 \end{equation}
 By Lemma \ref{lem4.2}, for $\p\left(\max\limits_{1\leq s\leq N_1}g(s)\geq M'\right)\leq 0.1$,
 \begin{equation}
 \p(g(l)\geq M')\leq 16(\log N_1+1)lN_1^{-1}\p\left(\max_{1\leq s\leq N_1}g(s)\geq M'\right).\label{eq:4.5}
 \end{equation}
Sum up \eqref{eq:4.4} for $1\leq i\leq a_k$, combining with \eqref{eq:4.5} gives
 \begin{align}\label{mathcal-G-calculate}
 &\p\left(\max_{kN_1+1\leq n\leq (k+1)N_1}\mathcal{G}_{kN_1,n}\geq M'\,\Big|\,\mathcal{F}^G_{\tau^G_{kN_1}}\right)\notag\\
 \leq& \sum_{i=1}^{a_k}\p\left(g(M^G_{\tilde\gamma_{i,k}}-G_{\tilde\beta_{i,k}}+1)\geq M'\Big|\mathcal{F}^G_{\tilde\beta_{i,k}}\right)\notag\\
