 \begin{eqnarray}\label{liminf-cal01}
 &&\p\left(\max_{kN_1+1\leq s\leq (k+1)N_1}g(s)\geq M\right)\notag\\
 &\leq& \sum_{i=0}^{\lfloor \epsilon^{-1}\rfloor} \p(g(kN_1)\geq \epsilon iM)\cdot\p\left(\max_{kN_1+1\leq s\leq (k+1)N_1}\mathcal{G}_{kN_1,s}\geq (1-\epsilon(i+1))M\,\Big|\,\mathcal{F}^G_{\tau^G_{kN_1}}\right)\notag\\
 &\overset{\eqref{mathcal-G-calculate}}{\le} & M\cdot\sum_{i=0}^{\lfloor \epsilon^{-1}\rfloor} \p(g(kN_1)\geq \epsilon iM)\cdot\p\left(\max_{1\leq s\leq N_1}g(s)\geq (1-\epsilon(i+1))M\right).
 \end{eqnarray}
 By Proposition \ref{prop1.5}, for any $0\leq k\leq N_1^{-1}e^{c_2\sqrt{M}}$ and any $\epsilon'>0$,
 \begin{equation}\label{liminf-cal02}
