 \end{equation}
 Putting together \eqref{liminf-cal01} and \eqref{liminf-cal02}, we obtain
 \begin{align}
&\limsup_{M\to\infty}\frac{\log\left(\p\left(\max\limits_{kN_1+1\leq s\leq (k+1)N_1}g(s)\geq M\right)\right)}{2\sqrt{M}}\notag\\
\leq& \max\limits_{c\in [0,1]}\left\{-cc_2^{-1}+\limsup_{M\to\infty}\frac{\log\left(\p\left(\max\limits_{1\leq s\leq N_1}g(s)\geq (1-c)M\right)\right)}{2\sqrt{M}}\right\}.\label{eq:4.7}
 \end{align}

