ref_dict.alg:basic:
\begin{algorithm}[H]
  \caption{Naive Pebble Game for $0 \leq \ell < 2k$}\label{alg:basic}
  \begin{algorithmic}[1]
    \Input An undirected graph $G = (V, E)$.
    \Require The edges $e_1, \dots, e_m$ of $G$ are sorted in non-increasing order of weight.
    \Output The edge set of a maximum-weight $(k, \ell)$-sparse subgraph.
    \vspace{0.2em}
    \hrule
    \vspace{0.2em}
    \Procedure{PebbleGame$_{k,\ell}$}{$G = (V, E)$}
      \State $F \gets \emptyset$ \Comment{Initialize the edge set of the optimal subgraph}
      \State $D \gets (V, \emptyset)$ \Comment{Initialize a directed graph on $V$ without arcs}
      \For{$e \gets e_1, \dots, e_m$} \Comment{Process the edges in non-increasing order of weight}\label{alg:basic:for}
        \State $u, v \gets \operatorname{endpoints}(e)$
      	\While{$\varrho_D(u) + \varrho_D(v) \geq 2k - \ell$}\label{alg:basic:while}
      	  \State find a path $P$ in $D$ from $\{w \in V \setminus \{u, v\} : \varrho_D(w) < k\}$ to $\{u, v\}$\label{alg:basic:findPath}
      	  \If{no such path exists}
      	    \State \Break \Comment{Exit the \texttt{while} loop}\label{alg:basic:reject}
      	  \EndIf
      	  \State reverse the arcs of $P$ in $D$ \Comment{Decrease the indegree of $u$ or $v$}\label{alg:basic:reverse}
      	\EndWhile
      	\If{$\varrho_D(u) + \varrho_D(v) < 2k - \ell$}\label{alg:basic:acceptIf}
          \State $F \gets F \cup \{e\}$ \Comment{Accept edge $e$}
      	  \If{$\varrho_D(v) < k$}
      	    \State $D \gets D \cup \{uv\}$ \Comment{Insert an arc from $u$ to $v$ in $D$}
      	  \Else
      	    \State $D \gets D \cup \{vu\}$ \Comment{Insert an arc from $v$ to $u$ in $D$}
      	  \EndIf
      	\EndIf\label{alg:basic:acceptEndIf}
      \EndFor
      \State \Return $F$ \Comment{Return the edge set of the optimal subgraph}
    \EndProcedure
  \end{algorithmic}
\end{algorithm}

