\begin{proposition}\label{ChInequalityOnSurface}
    Let $S_5\subset \mathbb{P}^3$ be a smooth irreducible quintic surface, $H = c_1(\mathcal{O}_{S_5}(1))$, and let $F$ be an object in $\Db(S_5)$ such that $\mu_H(F)\in (0,1)$. Suppose $F$ is $\nu_{\alpha,0,H}$-tilt-stable (or $\nu_{\alpha',1,H}$-tilt-stable) for some $\alpha > 0$ (resp. or $\alpha' > \frac{1}{2}$), then
    \begin{equation}\label{Ch1Ch2Inequal}
        \xi_H(F)\leq 
    \begin{cases}
    \frac{17}{26}\mu_H(F) - \frac{2}{13} & \text{when } 0 < \mu_H(F) \leq \frac{7}{46}; \\[0ex]
    -\frac{5}{14}\mu_H(F)  & \text{when } \frac{7}{46} \leq  \mu_H(F)\leq \frac{7}{20}; \\[0ex]
    \frac{1}{2}\mu_H(F)-\frac{3}{10} & \text{when } \frac{7}{20}\leq \mu_H(F) \leq \frac{13}{20}; \\[0ex]
    \frac{19}{14}\mu_H(F) - \frac{6}{7} & \text{when } \frac{13}{20}\leq \mu_H(F)< \frac{39}{46}; \\[0ex]
    \frac{9}{26}\mu_H(F) & \text{when } \frac{39}{46}\leq \mu_H(F)< 1.
\end{cases}
    \end{equation}
\end{proposition}

