\end{cases}
\end{equation}
where $\partial_n$ denotes the directional derivative with respect to $n$, the outward unit normal vector to $\partial\Omega$.
In this situation it is known the compactness of the embedding $H^1(\Omega)$ to $L^2(\Omega)$ and it gives that the eigenvalues of (\ref{Neumann eigenvalue problem}) can be listed with multiplicity as follows: 
\begin{align*}
 0=\mu_0(\Omega)<\mu_1(\Omega)\le\mu_2(\Omega)\le \dots \le \mu_k(\Omega)\le \mu_{k+1}(\Omega)\le \dots \to\infty.
\end{align*}

Our main concern in this paper is the relation between those eigenvalues. One of the main theorems in this paper is the following. We denote by $\alpha\lesssim \beta$ if $\alpha\leq c\beta$ for some universal concrete constant $c>0$ (which means $c$ does not depend on any parameters such as dimension and $k$ etc).

\section{Introduction}
Let $\Omega$ be a bounded domain in $\mathbb{R}^n$ with Lipschitz boundary. We consider the following Neumann eigenvalue problem of the Laplacian: 
\begin{equation}\label{Neumann eigenvalue problem}
\begin{cases}
-\Delta u = \mu u \quad \text{in } \Omega,\\
\partial_n u=0\quad \text{on }\partial \Omega,
\end{cases}
\end{equation}
where $\partial_n$ denotes the directional derivative with respect to $n$, the outward unit normal vector to $\partial\Omega$.
In this situation it is known the compactness of the embedding $H^1(\Omega)$ to $L^2(\Omega)$ and it gives that the eigenvalues of (\ref{Neumann eigenvalue problem}) can be listed with multiplicity as follows: 
\begin{align*}
 0=\mu_0(\Omega)<\mu_1(\Omega)\le\mu_2(\Omega)\le \dots \le \mu_k(\Omega)\le \mu_{k+1}(\Omega)\le \dots \to\infty.
\end{align*}

Let us mention the related known inequalities between the eigenvalues.
In \cite[Theorem 1.1]{Liu}, Liu showed the sharp dimension-free universal inequality $\mu_k(\Omega)\lesssim k^2\mu_1(\Omega)$ for any bounded convex domain $\Omega$ in $\mathbb{R}^n$.
In \cite[Theorem 1.2]{F2} the author proved that 
\begin{align}\label{univ}
 \mu_{k+1}(\Omega)\lesssim n^4\mu_k(\Omega)
\end{align}under the same situation of that of Liu's. The above theorem unifies the Liu inequality and the inequality (\ref{univ}) in the planar case.

We also obtain the opposite inequality: 
\begin{thm}\label{MTHM2}
 Let $\Omega$ be a planar bounded convex domain. Then for any $k\geq l$ we have
 \begin{align*}
 \mu_k(\Omega)\gtrsim \frac{k}{l} \mu_l(\Omega).
 \end{align*}
\end{thm}

\begin{prop}[{\cite[Proposition 2.3]{H}}]\label{Hacher lem} Let $\Omega$ be a bounded convex domain in $\mathbb{R}^n$. Tlanslating $\Omega$ if necessary we can find a sequence $a_1,a_2,\cdots, a_n$ of positive real numbers such that 
 \begin{align*}
 \Big[-\frac{a_1}{\sqrt{n}},\frac{a_1}{\sqrt{n}}\Big]\times \cdots \times \Big[-\frac{a_n}{\sqrt{n}},\frac{a_n}{\sqrt{n}}\Big]\subseteq \Omega\subseteq [-a_1 n, a_1 n]\times \cdots [-a_n n, a_n n].
 \end{align*}
\end{prop}

For a convex domain Neumann eigenvalues of the Laplacian are related with diameter as follows:
\begin{thm}[{Payne–Weinberger, \cite[(1.9)]{PW}}]\label{Diamthm}Suppose that $\Omega$ is a bounded convex domain in $\mathbb{R}^n$. Then we have $\mu_1(\Omega)\geq \frac{\pi^2}{(\diam \Omega)^2}$.
\end{thm}

In the following theorem $j_{\nu,k}$ denotes the $k$-th positive zero of the Bessel function $J_{\nu}$ of order $\nu$.
\begin{thm}[{Kr\"oger, \cite[Theorem 1]{Kr}}]\label{Kr ineq}
 Let $\Omega$ be a bounded convex domain in $\mathbb{R}^n$. Assume that $n>2$. Then we have
 \begin{enumerate}
 \item $(\diam \Omega)^2\mu_k(\Omega)\leq 4j_{\frac{n-2}{2},\frac{k+1}{2}}^2 $ if $k$ is odd, and
 \item $(\diam \Omega)^2\mu_k(\Omega)\leq (j_{\frac{n-2}{2},\frac{k}{2}}+j_{\frac{n-2}{2},\frac{k+2}{2}})^2 $ if $k$ is even.
 \end{enumerate}
 Now assume that $n=2$. Then we have
 \begin{align*}
 (\diam \Omega)^2\mu_k(\Omega)\leq (2j_{0,1}+(k-1)\pi)^2\lesssim k^2.
 \end{align*}
\end{thm}
Kr\"{o}ger proved the following upper bound for Neumann eigenvalues in terms of volume using harmonic analysis. 
\begin{thm}[{Kr\"{o}ger, \cite[Corollary 2]{Kr2}}]\label{Kr ineq2}Let $\Omega$ be a (not necessarily convex) bounded domain in $\mathbb{R}^n$ with Lipschitz boundary. Then for any natural number $k$ we have
\begin{align*}
 \mu_k(\Omega)\leq (2\pi)^2\Big(\frac{n+2}{2}\Big)^{\frac{2}{n}}\Big(\frac{k}{\omega_n \vol \Omega}\Big)^{\frac{2}{n}}\lesssim \Big(\frac{k}{\omega_n \vol \Omega}\Big)^{\frac{2}{n}},
\end{align*}where $\omega_n$ is the volume of a unit ball in $\mathbb{R}^n$.
\end{thm}

Put $R:=\frac{Ck}{l\sqrt{\mu_k(\Omega)}}$, where $C>0$ is a sufficiently large constant which will be specified later. We want to show that $\Omega$ can be decomposed into $l'$ convex subdomains $\{\Omega_i\}_{i=1}^{l'}$ such that $\diam \Omega_i'\lesssim R$ and $l'\leq l$. If this holds, then using Buser's theorem (Theorem \ref{Buserthm}) and the Payne-Weinberger inequality (Theorem \ref{Diamthm}) we obtain
 \begin{align*}
 \mu_l(\Omega)\geq \mu_{l'}(\Omega)\geq \min_i\mu_1(\Omega_i)\gtrsim \frac{1}{R^2} = \frac{l^2\mu_k(\Omega)}{C^2k^2},
 \end{align*}which completes the proof of the theorem.

The second case is the case where $a>2R$. In this case as in the proof of Theorem \ref{MTHM} we consider the rectangular subdomain
\begin{align*}
 \Omega':=\{x\in \Omega \mid d(x,\partial\Omega)\geq R\}
\end{align*}and take a maximal $2R$-separated points $\{x_i\}_{i=1}^{k'}$ in $\Omega'$. If we show $k'\leq k$ then as in the proof of Theorem \ref{MTHM} we get the desired convex partition $\{\Omega_i\}_{i=1}^{k'}$. Since $\{B(x_i,R)\}_{i=1}^{k'}$ are disjoint balls in $\Omega$, we have
\begin{align*}
k'\omega_2R^2=\sum_{i=1}^{k'}\vol B(x_i,R)\leq \vol \Omega. 
\end{align*}Applying Kr\"{o}ger's inequality (Theorem \ref{Kr ineq2}) to the above inequality we obtain
\begin{align*}
 k'\leq \frac{\vol \Omega}{w_2 R^2}=\frac{k\mu_l(\Omega) \vol \Omega}{C^2\omega_2 l}\lesssim \frac{k}{C^2}.
\end{align*}For sufficiently large $C$ we thereby obtain $k'\leq k$. This completes the proof.
\end{proof}
\section{An weaker inequality of (\ref{univ})}
In this section we give a short proof of the following:
\begin{thm}\label{Weaker ineq}Let $\Omega$ be a bounded convex domain in $\mathbb{R}^n$. Then we have
\begin{align*}
 \mu_{k+1}(\Omega)\lesssim n^7\mu_k(\Omega)
\end{align*}for any natural number $k$.
\begin{proof}Proposition \ref{Hacher lem} gives the existence of a rectangular domain $R$ such that
 \begin{align*}
 \frac{1}{\sqrt{n}}R\subseteq \Omega\subseteq nR.
 \end{align*}Let $\widetilde{R}$ be the flat torus whose fundamental domain is $R$. Observe that the $k$-the eigenvalue $\lambda_k(\widetilde{R})$ of the Laplacian on $\widetilde{R}$ is equal to $\mu_k(R)$ (\cite[Section II.2]{Ch}). Also since $\widetilde{R}$ is a homogeneous manifold, we use P.~Li's theorem (\cite[Theorem 11]{Li}) to get $\lambda_{k+1}(\widetilde{R})\lesssim \lambda_k(\widetilde{R})$, yielding that 
 \begin{align*}
 \mu_{k+1}(R)\lesssim \mu_k(R).
 \end{align*}Applying Theorem \ref{domain monotonicity} twice we thus obtain
 \begin{align*}
 \mu_{k+1}(\Omega)\lesssim n^2\mu_{k+1}\Big(\frac{1}{\sqrt{n}}R\Big)=n^3\mu_{k+1}(R)\lesssim n^3\mu_k(R)=\ &n^5\mu_k(n R)\\ \lesssim \ & n^7\mu_k(\Omega).
 \end{align*}This completes the proof.
\end{proof}
\end{thm}
