ref_dict.thMain:
\begin{theorem} \label{thMain}
  Let $(G_n)_{n \geq 1}$ be a sequence of finite solvable groups of bounded derived length.
  Then any sequence of actions $(G_n \circlearrowright \Omega_n)_{n \geq 1}$ is not expanding.
\end{theorem}

ref_dict.thHRV:
\begin{theorem}[Prop. 4 in \cite{HRV93}] \label{thHRV}
Let $(G_n)_{n \geq 1}$ be an expanding sequence of groups.
Then there exists a constant $c$ such that for every $n$ we have
$$ Rep_k(G_n) \> \leq \> c^{\, k^2} $$
for all $k \geq 1$.
\end{theorem}

ref_dict.corBDL:
\begin{corollary} \label{corBDL}
Let $(G_n)_{n \geq 1}$ be a sequence of finite solvable groups of bounded derived length.
Then $(G_n)_{n \geq 1}$ does not have BAb, and in particular is not an expanding sequence.
\end{corollary}

ref_dict.thLWineq:
\begin{theorem}[Th. 3.6 in \cite{LW93}] \label{thLWineq}
Let $(G_n)_{n \geq 1}$ be an expanding sequence of groups.
Then there exists a constant $c$ such that for every $n$ and $H \leqslant G_n$ we have
$$ |H:H'| \> \leq \> c^{\, |G_n:H|} . $$
\end{theorem}

ref_dict.thAmenableSG:
