\subsection{Poincar\'e series}\label{Poincare series}
In \cite[for $n=1$]{O16} and \cite[pp. 1265--1266 for $n\geq 2$]{LS1}, it is proved that the Poincar\'e series defined by
\begin{equation}\nonumber
	\sum_{\gamma\in \Gamma}  (\gamma_j(z)-\gamma_j(w))^{N}
\end{equation}
is a $\Gamma$-invariant holomorphic function on $\mathbb B^n\times\mathbb B^n$ for any $N\geq n+1$
with respect to the diagonal action, i.e.
this series converges when $N\geq n+1$.
Now, we consider a holomorphic coordinate system $(\widetilde z, \widetilde w)$ on $\mathbb{B}^n \times \mathbb{B}^n$ which is given by $\widetilde z := z$ and $\widetilde w := w-z$.  By the Taylor expansion of $\gamma_j (\tilde z + \tilde w)$ at $\tilde w=0$, we have
\begin{equation*}
\begin{aligned}
&\sum_{\gamma \in \Gamma} (\gamma_j (z) - \gamma_j (w))^N 
= \sum_{\gamma \in \Gamma} (\gamma_j (\tilde z ) - \gamma_j (\tilde z + \tilde w) )^N \\
&= (-1)^N \sum_{|I|=N}\frac{N!}{I!} \bigg(  \sum_{\gamma \in \Gamma} \bigg( \frac{\partial \gamma_j (z) } {\partial z_1} \bigg)^{i_1} \cdots \bigg( \frac{\partial \gamma_j (z) } {\partial z_n} \bigg)^{i_n} \bigg)  {\tilde w}^{i_1} \cdots {\tilde w}^{i_n} + O( {| \tilde{w} |}^{N+1} ).
\end{aligned}

theorem.content:
\label{thm: prod}
Let $S$ be a $k$-dimensional submanifold of a maximal flat of $M$, $k=0,1,\ldots,r$. 
Suppose without loss of generality that $d_1\leq d_2\leq\cdots\leq d_r$. 
Let 
$$\tau(d,p):=\left\{\begin{array}{ll}
-\frac1p, & p\geq\frac{4}{d-1},\\
-\frac{d-1}{4}, & 0<p\leq\frac{4}{d-1}.
\end{array}\right.$$
Let $f$ be an eigenfunction of $\Delta$ such that $\Delta f=-N^2f$, $N>1$. Then
\begin{align}\label{eq: general}
    \|f\|_{L^p(S)}\lesssim_\varepsilon N^{\frac{d-2}{2}+\sum_{i=1}^k\tau(d_i,p)+\varepsilon} \|f\|_{L^2(M)}, \qquad\text{for all }p\geq 2.
\end{align}
Moreover, when $r \ge 5$, the $\varepsilon$-loss in \eqref{eq: general} can be removed.
In particular, if $\dim M_i\geq 3$ for all $i$ and $r\geq 5$,  
then
\begin{align}\label{eq: no loss}
    \|f\|_{L^p(S)}\lesssim N^{\frac{d-2}{2}-\frac{k}{p}}\|f\|_{L^2(M)}, \qquad\text{for all }p\geq 2, 
\end{align}
and the above estimate is sharp.

