ref_dict.thm: jac:
\begin{theorem}\label{thm: jac}
Assume that $0\leq\beta\leq \alpha$. For $n\in\mathbb{Z}_{\geq 0}$, let $T_{n}^{\alpha,\beta}$
   denote the convolution operator on $\mathbb{T}=\mathbb{R}/2\pi\mathbb{Z}$ with kernel $P_{n}^{(\alpha,\beta)}(\cos\theta)$, 
   where $\theta\in \mathbb{T}$.  
Then for the following cases:
\begin{enumerate}
    \item $\alpha > \frac{1}{2}$,
    \item $0 \le \alpha < \frac{1}{2}$,
    \item $\alpha = \beta = \frac{1}{2}$,
\end{enumerate}
the operator $T_n^{\alpha,\beta}$ satisfies
\begin{align}\label{eq: Tn sharp bound}
    \|T_n^{\alpha,\beta}\|_{L^{p'}(\mathbb{T}) \to L^p(\mathbb{T})} \lesssim A(\alpha, p/2, n), \quad \text{for all } p \ge 2.
\end{align}

\end{theorem}

ref_dict.lem: Phi_n=sum:
\begin{lemma}[Proposition 9.4 of Chapter III of \cite{Hel08}]\label{lem: Phi_n=sum}
For $n\in\mathbb{Z}_{\geq 0}$, we have 
    $$\Phi_n(\theta)=\sum_{j=0}^{q_n} c_{n,j} e^{im_{n,j}\theta},\qquad \theta\in\mathbb{T},$$
    where $c_{n,j}\geq 0$ and $m_{n,j}\in\mathbb{Z}$. In particular, $\sum_{j=0}^{q_n} c_{n,j}=\Phi_n(0)=1$. 
\end{lemma}

pre_theorem_intro_text:
Let $M$ be a compact Riemannian manifold of dimension $d$. Let $\Delta$ be the Laplace--Beltrami operator on $M$, and let $f$ be its eigenfunctions such that $\Delta f=-N^2f$, $N>1$. The study of concentration of $f$ has become a popular subject \cite{Zel17}, and one of the approaches is to bound its restriction to submanifolds of $M$, as initiated by Tataru \cite{Tat98}  and Reznikov \cite{Rez04}. Let $S$ be a submanifold of dimension $k$. Let $L^p(M)$, $L^p(S)$ be the Lebesgue spaces associated to the Riemannian volume measure on $M$ and $S$ respectively. The following fundamental restriction bounds for general $M$ were established by Burq--G\'erard--Tzvetkov \cite{BGT07} and Hu \cite{Hu09}: it holds
\begin{align}\label{eq: BGT}
    \|f\|_{L^p(S)}\lesssim N^{\rho(k,d,p)}\|f\|_{L^2(M)},
\end{align}
where 
\begin{align*}
\rho(d-1,d,p)&=\left\{\begin{array}{ll}
\frac{d-1}{2}-\frac{d-1}{p}, \qquad \text{if }\frac{2d}{d-1}\leq p\leq\infty,\\
\frac{d-1}{4}-\frac{d-2}{2p}, \qquad \text{if }2\leq p\leq \frac{2d}{d-1},
\end{array}\right.\\
\rho(d-2,d,p)&=\frac{d-1}{2}-\frac{d-2}{p},  \qquad  \text{if }2<p\leq \infty, \\
\rho(k,d,p)&=\frac{d-1}{2}-\frac{k}{p}, \qquad  \text{if }1\leq k\leq d-3\text{ and }2\leq p\leq \infty;
\end{align*}
and for the case $p=2$ and $k=d-2$, it holds 
\begin{align}\label{eq: logloss}
\|f\|_{L^2(S)}\lesssim N^{\frac{1}{2}}(\log N)^{\frac{1}{2}}\|f\|_{L^2(M)}.
\end{align}
All the above estimates are sharp on spheres, except for the logarithmic loss, which however has been eliminated by Chen--Sogge \cite{CS14} and Wang--Zhang \cite{WZ21} for totally geodesic submanifolds. 

