The goal of this note is to record an instance of \textit{sharp polynomial improvement} over the above results of Burq--G\'erard--Tzvetkov and Hu, on products of compact rank-one symmetric spaces, for all $p\geq 2$: namely, the estimate \eqref{eq: no loss} below. For each $i=1,\ldots,r$ ($r\geq 2$), let $M_i$ be a compact rank-one symmetric space (CROSS) (of compact type) of dimension $d_i$; this family includes the standard spheres. Let $M=M_1\times \cdots \times M_r$ be their product. A maximal flat of $M$ is a maximally embedded flat, totally geodesic submanifold, which is isomorphic to $\mathbb{T}^r$. We establish:

\begin{align}\label{eq: general}
    \|f\|_{L^p(S)}\lesssim_\varepsilon N^{\frac{d-2}{2}+\sum_{i=1}^k\tau(d_i,p)+\varepsilon} \|f\|_{L^2(M)}, \qquad\text{for all }p\geq 2.
\end{align}

\begin{align}\label{eq: no loss}
    \|f\|_{L^p(S)}\lesssim N^{\frac{d-2}{2}-\frac{k}{p}}\|f\|_{L^2(M)}, \qquad\text{for all }p\geq 2, 
\end{align}

The goal of this note is to record an instance of \textit{sharp polynomial improvement} over the above results of Burq--G\'erard--Tzvetkov and Hu, on products of compact rank-one symmetric spaces, for all $p\geq 2$: namely, the estimate \eqref{eq: no loss} below. For each $i=1,\ldots,r$ ($r\geq 2$), let $M_i$ be a compact rank-one symmetric space (CROSS) (of compact type) of dimension $d_i$; this family includes the standard spheres. Let $M=M_1\times \cdots \times M_r$ be their product. A maximal flat of $M$ is a maximally embedded flat, totally geodesic submanifold, which is isomorphic to $\mathbb{T}^r$. We establish:

\begin{remark}
 In the setting of compact Lie groups, the author established the same sharp estimate as \eqref{eq: no loss} for eigenfunctions restricted to submanifolds of maximal flats \cite{Zha26}. 
\end{remark}

Applying \eqref{eq: c_i}, \eqref{eq: K=sum}, and $|J(\underline{\theta}')|\simeq 1$, it suffices to get the same bound for the $L^{p'}(V,\ d\underline{\theta})\to L^p(V,\ d\underline{\theta})$ norm of the operator 
\begin{align}\label{eq: operator A}
 \mathcal{A}: g\mapsto \int_V g(\underline{\theta}')\widetilde{\mathscr{K}}(\underline{\theta}',\underline{\theta})\ d\underline{\theta}'.
\end{align}
Furthermore, we may now assume $V=\mathbb{T}^k$ without loss of generality, and then the above operator is convolution on $\mathbb{T}^k$ with a product of Jacobi polynomials. 
We may apply Theorem \ref{thm: jac} along with the Minkowski inequality (using $p\geq 2\Leftrightarrow p\geq p'$) to bound such a convolution operator, as well as apply the standard asymptotics 
\begin{align}\label{eq: binom asymp}
 \binom{n+\alpha}{n} \sim \frac{n^{\alpha}}{\Gamma(\alpha+1)}, \qquad n \to \infty,
\end{align}
and Lemma \ref{lem: k(n) bound} to bound the coefficients, to obtain 
$$\|\mathcal{A}\|_{L^{p'}(S)\to L^{p}(S)}\lesssim N^{{d-r}+2\sum_{l=1}^k\tau(d_{i_l},p)}\leq N^{{d-r}+2\sum_{i=1}^k\tau(d_{i},p)}.$$
Here in the last inequality we applied $d_1\leq \cdots\leq d_r$. The proof is now complete.

\begin{proof}[Proof of Theorem \ref{thm: prod}]
Suppose $\Delta f=-N^2f$, $N>1$. 
By \eqref{eq: f=sum}, and a standard counting estimate \cite{Gro85}, we get
\begin{align*}
 |f|&\leq \left|\left\{(n_1,\ldots,n_r)\in\mathbb{Z}^r_{\geq 0}: \sum_{i=1}^r n_i^2+a_in_i=N^2\right\}\right|^{\frac{1}{2}}\|P_{n_1,\ldots,n_r}f\|_{l^2_{n_1,\ldots,n_r}}\\
 &\lesssim N^{\frac{r}{2}-1+\varepsilon}\|P_{n_1,\ldots,n_r}f\|_{l^2_{n_1,\ldots,n_r}},
\end{align*}
which implies by an application of the Minkowski inequality, that for $p\geq 2$, 
$$\|f\|_{L^p(M)}\lesssim N^{\frac{r}{2}-1+\varepsilon}\|\|P_{n_1,\ldots,n_r}f\|_{L^p(M)}\|_{l^2_{n_1,\ldots,n_r}},$$
and the $\varepsilon$-loss may be removed when $r\geq 5$.

\textbf{Case 2.} $0<\theta\leq c(n+1)^{-1}$ or $\pi-c(n+1)^{-1}\leq\theta<\pi$. For the former, we use (8.21.17) of \cite{Sze75} as follows: 
\begin{align}
 &\left(\sin\frac{\theta}{2}\right)^{\alpha}\left(\cos\frac{\theta}{2}\right)^{\beta}P_n^{(\alpha,\beta)}(\cos\theta)\nonumber \\
=&\widetilde{n}^{-\alpha}\frac{\Gamma(n+\alpha+1)}{n!}\left(\frac{\theta}{\sin\theta}\right)^\frac12 J_\alpha(\widetilde{n}\theta)+ \theta^{\alpha+2}O(n^\alpha), \qquad n\to\infty.\label{eq: small theta}
\end{align}
Here $J_\alpha$ stands for the Bessel function of the first kind of order $\alpha$, as defined in (1.71.1) of \cite{Sze75}. By (1.71.10) of \cite{Sze75}, we have the asymptotics, 
$$J_\alpha(x)\sim x^\alpha, \qquad x\to 0+.$$
We also need the classical asymptotics for Gamma functions:
$$\frac{\Gamma(n+\alpha+1)}{n!}\sim n^{\alpha}, \qquad n\to\infty.$$
Apply the above two asymptotics to \eqref{eq: small theta}, we get 
$$|P_{n}^{(\alpha,\beta)}(\cos\theta)|\lesssim (n+1)^\alpha,\qquad 0<\theta<c(n+1)^{-1}.$$
This implies 
\begin{align}\label{eq: alpha-1/p}
 \|P_{n}^{(\alpha,\beta)}(\cos\theta)\|_{L^p_\theta((0,c(n+1)^{-1}])}
 \lesssim (n+1)^{\alpha-\frac1p},\qquad \text{for all }p>0.
\end{align}
A similar approach works for the other case $\pi-c(n+1)^{-1}\leq\theta<\pi$: combining (8.21.17) and (4.1.3) of \cite{Sze75}, we get 
\begin{align*}
 &\left(\sin\frac{\theta}{2}\right)^{\alpha}\left(\cos\frac{\theta}{2}\right)^{\beta}P_n^{(\alpha,\beta)}(\cos\theta)\\
=&(-1)^n \widetilde{n}^{-\beta}\frac{\Gamma(n+\beta+1)}{n!}\left(\frac{\pi-\theta}{\sin\theta}\right)^{\frac12} J_\beta(\widetilde{n}(\pi-\theta))+ (\pi-\theta)^{\beta+2}O(n^\beta),\qquad n\to\infty,
\end{align*}
which implies, in a similar manner as above, that 
\begin{align}\label{eq: beta - 1/p}
 \|P_{n}^{(\alpha,\beta)}(\cos\theta)\|_{L^p_\theta([\pi-c(n+1)^{-1},\pi))}
 \lesssim (n+1)^{\beta-\frac1p}\leq (n+1)^{\alpha-\frac1p}, \qquad \text{for all }p>0. 
\end{align}
Again by an application of Young's inequality, \eqref{eq: alpha-1/p} and \eqref{eq: beta - 1/p} together yield the desired bound of the convolution operator with the kernel $P_{n}^{(\alpha,\beta)}(\cos\theta)$ restricted to the intervals $(0,c(n+1)^{-1}]$ and $[\pi-c(n+1)^{-1},\pi)$. This completes the proof. 
\end{proof}
\begin{remark}
 The above proof yields the sharp $L^p$ estimates of Jacobi polynomials: for $0\leq\beta\leq\alpha$, we have 
 $$\|P_{n}^{(\alpha,\beta)}(\cos\theta)\|_{L^p_\theta([0,2\pi])}\lesssim\widetilde{A}(\alpha,p,n).$$
 In particular, 
 \begin{align}\label{eq: Linfty of Jacobi}
 \|P_{n}^{(\alpha,\beta)}\|_{L^\infty([-1,1])}\lesssim (n+1)^\alpha. 
 \end{align}
\end{remark}

\section{Sharpness of \eqref{eq: no loss}}\label{sec: sharpness}
Fix an origin $e=(e_1,\ldots,e_r)$ of $M=M_1\times\cdots\times M_r$, and take $S$ to be any open subset of $\mathbb{T}_1 \times \cdots \times \mathbb{T}_k\times\{e_{k+1}\}\times\cdots\times \{e_{r}\}$ containing $e$. 
For $N>1$, take 
$$\Lambda:=\{(n_1,\ldots,n_r)\in\mathbb{Z}_{\geq 0}^r: n_1\geq \cdots\geq n_r\geq \frac{n_1}{2},\ \sum_{i=1}^rn_i^2+a_in_i=N^2\},$$
and then take 
\begin{align}\label{eq: maximizer}
 f(\theta_1,\ldots,\theta_r)=\sum_{(n_1,\ldots,n_r)\in \Lambda}\prod_{i=1}^r\sqrt{k_i(n_i)}\, \Phi_{i,n_i}(\theta_i).
\end{align}
As the spherical functions $\Phi_{i,n_i}$ are matrix entries of the associated irreducible spherical representations expressed via unit vectors (see Theorem 4.3 of Chapter V of \cite{Hel00}), the Schur orthogonality relations yield orthogonality between $\Phi_{i,n_i}$ for different $n_i$, and 
$$\|\sqrt{k_i(n_i)}\, \Phi_{i,n_i}\|_{L^2(M_i)}=1,$$
which together imply 
\begin{align}\label{eq: f L2}
 \|f\|_{L^2(M)}=|\Lambda|^{\frac12}.
\end{align}
We need the following derivative estimate for spherical functions. 
\begin{lemma}
 For spherical functions $\Phi_n(\theta)$ ($n\in\mathbb{Z}_{\geq 0}$) on a CROSS, we have the pointwise estimate 
 $$|\Phi_{n}'(\theta)|\lesssim (n+1)^2\sin\theta, \qquad\theta\in\mathbb{T}.$$
 In particular, this implies that 
 \begin{align}\label{eq: Phi_n close to 1}
 |\Phi_n(\theta)-1|\ll 1,\qquad\text{if } |\theta|\ll \frac{1}{n+1}. 
 \end{align}
\end{lemma}
