\begin{theorem}\label{theorem on resonance method}
	Let $q \ge 3$ and for every $\beta > 0$, define $\tau_{\beta, n}
	= e^{\gamma}\!\left(\log n + \log_2 n + C_2(q) - \beta\right),$ where
	\[
	C_2(q)
	= \frac{1}{2}
	- \left(\frac{\pi}{4} - \frac{\ln 2}{2}\right)\frac{q}{q-1}
	+ \log\!\left(
	\frac{(q-1)\ln q}{2q(3\ln 2 - \pi/2)}
	\right).
	\]
	Then we have
	\[
\phi_n(\beta)
:= \frac{1}{|\mathcal{H}_n|}
\sum_{\substack{D \in \mathcal{H}_n \\ L(1, \chi_D) \ge \tau_{\beta, n}}} 1
	\ge \exp\!\left(
	-\frac{q^{-\beta}\ln q}{2}
	\left(1 + o(1)\right)
	\right).
	\]
\end{theorem}

