The question of algorithmic decidability of a given first-order theory is a classical theme of mathematical logic. Starting from the undecidability of $\mathrm{Th}((\mathbb{N}, +, \cdot))$, the field is riddled with (un)decidability results of first-order theories. Famous examples are the undecidability of $\mathrm{Th}((\mathbb{Z}, +, \cdot))$, of the theory of groups, and of $\mathrm{Th}((\mathbb{Q}, +, \cdot))$. For an example on the positive side, Tarski proved in \cite{tarski} that the theory $\mathrm{Th}((\mathbb{R}, +, \cdot, <))$ is decidable. It is still an open problem (posed by Tarski) whether the theory $\mathrm{Th}((\mathbb{R}, +, \cdot, <, \mathrm{exp}))$ is decidable. In another direction, Quine proved in~\cite{quine} that the first-order theory of a non-cyclic free semigroup is undecidable.

\medskip 
 In \cite{NaPaI} we began the study of the model theory of free lattices, proving several fundamental results. This was continued in \cite{NaPaII}, where we proved that the universal (equiv.~existential) theory of infinite free lattices is decidable. One of the main open questions left in \cite{NaPaII} was the question of decidability of the (full) first-order theory of a given finitely generated free lattice $\mathbf F_n$ ($n \geqslant 3$). In this paper we resolve this problem, proving, more strongly, the following three undecidability results:

\begin{abstract} In \cite{NaPaII} we proved that the universal theory of infinite free lattices is (algorithmically) decidable, leaving open the problem of decidability of the full theory of an (infinite) free lattice. We solve this problem by proving that, for every cardinal $\kappa \geq 3$, the first-order theory of the free lattice $\mbf F_\kappa$ is undecidable.
\end{abstract}

\medskip 
 In \cite{NaPaI} we began the study of the model theory of free lattices, proving several fundamental results. This was continued in \cite{NaPaII}, where we proved that the universal (equiv.~existential) theory of infinite free lattices is decidable. One of the main open questions left in \cite{NaPaII} was the question of decidability of the (full) first-order theory of a given finitely generated free lattice $\mbf F_n$ ($n \geq 3$). In this paper we resolve this problem, proving, more strongly, the following three undecidability results:

Concerning Theorem~\ref{main_th}(2), we observe that the question of decidability of the finitely generated free structures in a given variety of algebras has a long tradition, on this question see e.g. \cite{Ershov1966, Idziak1987, Lavrov1962, Malcev1962} and references therein.

\begin{lm} \label{lm:118} Let $\mbf F$ be a free lattice. Then an element of the form
$$t = \prod_{i \in [1, k]} \sum_{j \in [1, m_j]} t_{ij} \in F$$
with $k > 1$ and, for every $j \in [1, k]$, $m_j > 1$, is in canonical form iff:
 \begin{enumerate}[(1)]
 \item each $t_i$ is a generator or a join; \item each $t_i$ is in canonical form;
 \item $t_i \nleq t_j$ for $i \ne j$;
 \item all $t_{ij} \ngeq t$.
 \end{enumerate}
\end{lm}

\begin{lm}\label{lemma_wQ} Let $Q = A \dot{\cup} B$ be a finite nice bipartite poset. In the context of Notation~\ref{notation_wQ} and recalling the embedding $\xi$ from \ref{fact_emb_xi}. Let $\kappa \geq m = |Q|$ be a cardinal. Then the following hold:
 \begin{enumerate}[(1)]
 \item $w_Q$ as given in \ref{notation_wQ} is in canonical form (and so it is a proper meet);
 \item $\{ u \in F_\kappa : w_Q \,E\, u \} = \xi(Q)$;
 \item $\mbf F_\kappa \models \Psi(w_Q)$.
 \end{enumerate}
\end{lm}

\begin{lm}\label{lm:translate} 
\begin{enumerate}[(1)]
 \item If every finite nice bipartite poset (cf.~\ref{def_bi_poset_nice}) satisfies $\varphi$, then, for every free lattice $\mbf F$, we have that $\mbf F \models \varphi_*$.
 \item If $\varphi$ fails in a finite nice bipartite poset $Q$, then, for every cardinal $\kappa \geq |Q|$ we have that $\mbf F_{\kappa}$ fails $\varphi_*$ at $w_Q$.
\end{enumerate}
\end{lm}

\begin{thm} \begin{enumerate}[(1)]
 \item The first-order theory of free lattices is undecidable.
 \item The first-order theory of finitely generated free lattices is undecidable.
\end{enumerate} 
 \end{thm}

\begin{lm}\label{crucial_F3_lemma} In the context of Notation~\ref{the_zeta_notation}, assume $Q$ is a finite nice bipartite poset with $|Q| = m$. Then we have:
 \begin{enumerate}[(1)]
 \item $\zeta(w_Q)$ (for $w_Q(x_1, ..., x_m)$ as in Notation \ref{notation_wQ}) is in canonical form;
 \item $\{ u \in F_\kappa: \zeta(w_Q) \,E\, u \} = \{ \zeta \circ \xi(q) : q \in Q \}$; \item $\mbf F_\kappa \mbf \models \Psi(\zeta (w_Q))$ holds.
 \end{enumerate} 
\end{lm}

\begin{thm}\label{main_th} \begin{enumerate}[(1)]
    \item The first-order theory of free lattices is undecidable.
    \item The first-order theory of finitely generated free lattices is undecidable.
    \item For every cardinal $\kappa \geq 3$, the first-order theory of $\mbf F_\kappa$ is undecidable.
\end{enumerate}        
\end{thm}

expanded_sketch:
We rely on the undecidability of the $\forall\exists$-theory of nice finite bipartite graphs (cf.
\begin{definition}\label{def_bi_graph_nice} We say that a bipartite graph $C = A \dot{\cup} B$ is {\em nice} when:
\begin{enumerate}[(1)]
        \item $|A| \geq 3$,
        \item $|B| \geq 3$,
        \item $\forall a \in A$, there are at least two elements of $B$ which are adjacent to $a$, and there is at least one element of $B$ which is not adjacent to~$a$;
        \item $\forall b \in B$, there are at least two elements of $A$ which are adjacent to $b$, and there is at least one element of $A$ which is not adjacent to~$b$.
    \end{enumerate}  
\end{definition}
) proved by Nies in \cite[Theorem~4.7]{Nies1996}. First we observe that also the $\forall\exists$-theory of nice finite bipartite posets is undecidable and then, given a $\forall\exists$-sentence $\varphi$ in the language of posets, we construct a sentence $\varphi_*$ in the same language (which is also the language of lattices) such that $\varphi$ is true in all finite lattices if and only if $\varphi_*$ is true in $\mathbf{F}_\kappa$ (where $\kappa \geqslant 3$ is fixed).,

ref_dict.closed:
\begin{theorem}\label{closed}
For the stratum $\H(2^{g-1})$ and disjoint intervals $[a_1,b_1],\cdots,[a_k,b_k]$, when $g\to \infty$, the random variable sequence
$$(L_{g,[a_1,b_1]},\cdots,L_{g,[a_k,b_k]}):\H(2^{g-1}) \to \mathbb{N}^k_0$$
converges jointly in distribution to a vector of random variables with Poisson distributions of means $\lambda_{[a_i,b_i]}$, where
$$\lambda_{[a_i,b_i]}=3\pi(b_i^2-a_i^2).$$
\end{theorem}

