ref_dict.dir-neu-lp:
\begin{lem}
\label{dir-neu-lp}
Let $O\subseteq \mathbb{R}^d$ be an open set and consider the sesquilinear forms $h^N_{A, O}(\cdot, \cdot)$ and $h^D_{A, O}(\cdot, \cdot)$ as defined in (\ref{ses-neu}) and (\ref{ses-dir}),  respectively.
\begin{enumerate}
\item[(i)] These two sesquilinear forms are positive, symmetric, and closed. Therefore, they each uniquely define a positive self-adjoint operator denoted $H^N_{A, O}$ and $H^D_{A, O}$, respectively.
\item[(ii)] The restricted Neumann magnetic Laplacian $H^N_{A, O}$ is given by
 \begin{equation}
\label{neu-lapla}
h^N_{A,O}(\psi, u)=\big\langle \psi, H^N_{A, O}u\big\rangle,~\forall~\psi\in W^{1,2}_A(O),~u\in 
D(H^N_{A,O}).
\end{equation}
Here the domain of the operator $H^N_{A,O}$ is described by
\begin{align}
\label{neu-dom}
D(H^N_{A,O})&=\bigg\{u\in W^{1,2}_A(O): \text{there~exists}~\tilde{u}\in L^2(O),~\text{such that}\nonumber\\
&\qquad \qquad \qquad h^N_{A, O}(\psi,u)=\langle \psi, \tilde{u}\rangle~\forall~\psi\in W^{1,2}_A(O)  \bigg\},
\end{align}
and for $u\in D(H^N_{A, O})$ we write $H^N_{A, O}u=\tilde{u}$.
\item[(iii)] The restricted Dirichlet magnetic Laplacian $H^D_{A, O}$ is given by
 \begin{equation}
\label{dir-lapla}
h^D_{A,O}(\psi, u)=\big\langle \psi, H^D_{A, O}u\big\rangle,~\forall~\psi\in W^{1,2}_{A,cl}(O),~u\in 
D(H^D_{A,O}).
\end{equation}
Here the domain of the operator $H^D_{A,O}$ is described by
\begin{align}
\label{dir-dom}
D(H^D_{A,O})&=\bigg\{u\in W^{1,2}_{A,cl}(O): \text{there~exists}~\tilde{u}\in L^2(O),~\text{such that}\nonumber\\
&\qquad \qquad \qquad h^D_{A, O}(\psi,u)=\langle \psi, \tilde{u}\rangle~\forall~\psi\in W^{1,2}_{A,cl}(O)  \bigg\},
\end{align}
and for $u\in D(H^D_{A, O})$ we write $H^D_{A, O}u=\tilde{u}$.
\end{enumerate}
\end{lem}

ref_dict.fl-d-lp:
\begin{rem}
\label{fl-d-lp}
We define $H_A$ to be the operator $H^N_{A,\mathbb{R}^d}$ \big(or $H^D_{A, \mathbb{R}^d}$\big) and denote it by $H_A=(i\nabla+A)^2$. The domain of $H_A$ is given by
\begin{align}
D(H_A)&=\bigg\{\psi\in W^{1,2}_{A, cl}(\mathbb{R}^d)=
 W^{1,2}_{A}(\mathbb{R}^d): \text{there~exists}~\tilde{\psi}\in L^2(\mathbb{R}^d)~\text{such that}\nonumber\\
&\qquad \qquad\qquad \qquad h^D_{A,\mathbb{R}^d}(\varphi,\psi)=h^N_{A,\mathbb{R}^d}(\varphi,\psi)=\langle \varphi, \tilde{\psi}\rangle~
\nonumber\\
&\qquad \qquad\qquad \qquad \qquad \qquad \forall~\varphi\in W^{1,2}_{A, cl}(\mathbb{R}^d)=W^{1,2}_A(\mathbb{R}^d)  \bigg\},
\end{align}
and for $\psi\in D(H_A)$ we have $H_A\psi=\tilde{\psi}$.
\end{rem}

ref_dict.mnthm:
\begin{thm}
\label{mnthm}
Let $H^\omega$ be as in \eqref{model} and assume Hypothesis~\ref{hypo}. 
Then, for each $f \in C^1_{d,0}\big[-\|V\|_\infty,\infty\big)$, we have the following convergence of random variables:
\begin{equation}
\label{clt-cn}
\frac{1}{|\Lambda_L|^{\frac{1}{2}}}
\bigg(
  \operatorname{Tr}\!\big( f(H^\omega_{\Lambda_L,X}) \big)
  - \mathbb{E}\!\big[\operatorname{Tr}\!\big( f(H^\omega_{\Lambda_L,X}) \big)\big]
\bigg)
\xrightarrow[L\to\infty]{\;\;\text{distribution}\;\;}
\mathcal{N}\!\big(0,\sigma^2_{f,X}\big),
\end{equation}
where $X \in \{D,N\}$ and $\mathcal{N}\!\big(0,\sigma^2_{f,X}\big)$ denotes the normal distribution with mean $0$ and variance $\sigma^2_{f,X}$, as defined in \eqref{lim-vr}. \\~\\
Moreover, for any $f \in C^1_{d,0}\big[-\|V\|_\infty,\infty\big)$, the limiting variance $\sigma^2_{f,X}$ is finite and independent of the boundary condition $X \in \{D,N\}$. In particular,
$\sigma^2_f := \sigma^2_{f,N} = \sigma^2_{f,D} < \infty$,
and its exact expression is given by
\begin{align}
\label{extlmv}
\sigma^2_f
&= \mathbb{E}\!\Bigg[\omega_{\vec{1}_d}\,
  \mathbb{E}\!\bigg(
    \int_0^1 
    \operatorname{Tr}\!\Big( u_{\vec{1}_d}(x)\,
    f'(H^\omega)_{(\omega_{\vec{1}_d}\to t\omega_{\vec{1}_d})} \Big)\,dt
  \;\Big|\; \mathcal{F}^d_{\vec{1}_d}  \bigg) \nonumber\\
&\qquad
- \mathbb{E}\!\bigg(
    \int_0^1 \omega_{\vec{1}_d}\,
    \operatorname{Tr}\!\Big( u_{\vec{1}_d}(x)\,
    f'(H^\omega)_{(\omega_{\vec{1}_d}\to t\omega_{\vec{1}_d})} \Big)\,dt
    \;\Big|\; \mathcal{F}^d_{\vec{1}_{d-1,0}}
  \bigg)
\Bigg]^2.
\end{align}
Finally, if $f \in C^1_{d,0}\big[-\|V\|_\infty, \infty\big)$ is strictly monotone and $u \ge 0$ or $u \le 0$ with $\|u\|_2 \neq 0$, then $\sigma_f^2 > 0$.
\end{thm}

