expanded_theorem:
\label{mnthm}
Let $H^\omega$ be as in
\begin{equation}
\label{model}
H^\omega = H_A + V^\omega, \quad \omega \in \Omega, \quad \text{where} \quad H_A := (i\nabla + A)^2.
\end{equation}
and assume
\begin{hyp}\indent
\label{hypo}
\begin{enumerate}
\item The single site distribution (SSD) $\mu$ is compactly supported.
\item The single site potential $u\in L^\infty(\mathbb{R}^d)$ is real-valued and compactly supported and denote $u_n(x)=u(x-n)$, $n\in\mathbb{Z}^d$.
\item  The vector potential $A(x)=\big(A_1(x),A_2(x),\cdots,A_d(x)\big):\mathbb{R}^d\to\mathbb{R}^d$ is Borel-measurable and it is given by 
$$A(x)=\frac{1}{2}Bx,~x=(x_1,x_2,\cdots,x_d)\in\mathbb{R}^d.$$
Here $B=\big[ B_{i,j} \big]_{1\leq i,j\leq d}$ is a real skew-symmetric $d\times d$ matrix
representing the constant magnetic field.
\end{enumerate}
\end{hyp}
Then, for each $f \in C^1_{d,0}\big[-\|V\|_\infty,\infty\big)$, we have the following convergence of random variables:
\begin{equation}
\label{clt-cn}
\frac{1}{|\Lambda_L|^{\frac{1}{2}}}
\bigg(
  \operatorname{Tr}\!\big( f(H^\omega_{\Lambda_L,X}) \big)
  - \mathbb{E}\!\big[\operatorname{Tr}\!\big( f(H^\omega_{\Lambda_L,X}) \big)\big]
\bigg)
\xrightarrow[L\to\infty]{\;\;\text{distribution}\;\;}
\mathcal{N}\!\big(0,\sigma^2_{f,X}\big),
\end{equation}
where $X \in \{D,N\}$ and $\mathcal{N}\!\big(0,\sigma^2_{f,X}\big)$ denotes the normal distribution with mean $0$ and variance $\sigma^2_{f,X}$, as defined in
\begin{align}
\label{lim-vr}
\sigma^2_{f,X}&=\lim_{L\to\infty}\frac{1}{|\Lambda_L|} \mathrm{Var}\big(Y_{f,X,L}  \big),~~~~X=D,N\nonumber\\
&=\lim_{L\to\infty}\frac{1}{|\Lambda_L|}\mathbb{E}\bigg[\operatorname{Tr}\!\big( f\big(H^\omega_{\Lambda_L,X}  \big) \big)-\mathbb{E}\big[\operatorname{Tr}\!\big( f\big(H^\omega_{\Lambda_L,X}  \big) \big) \big]\bigg]^2.
\end{align}
\\~\\
Moreover, for any $f \in C^1_{d,0}\big[-\|V\|_\infty,\infty\big)$, the limiting variance $\sigma^2_{f,X}$ is finite and independent of the boundary condition $X \in \{D,N\}$. In particular,
$\sigma^2_f := \sigma^2_{f,N} = \sigma^2_{f,D} < \infty$,
and its exact expression is given by
\begin{align}
\label{extlmv}
\sigma^2_f
&= \mathbb{E}\!\Bigg[\omega_{\vec{1}_d}\,
  \mathbb{E}\!\bigg(
    \int_0^1 
    \operatorname{Tr}\!\Big( u_{\vec{1}_d}(x)\,
    f'(H^\omega)_{(\omega_{\vec{1}_d}\to t\omega_{\vec{1}_d})} \Big)\,dt
  \;\Big|\; \mathcal{F}^d_{\vec{1}_d}  \bigg) \nonumber\\
&\qquad
- \mathbb{E}\!\bigg(
    \int_0^1 \omega_{\vec{1}_d}\,
    \operatorname{Tr}\!\Big( u_{\vec{1}_d}(x)\,
    f'(H^\omega)_{(\omega_{\vec{1}_d}\to t\omega_{\vec{1}_d})} \Big)\,dt
    \;\Big|\; \mathcal{F}^d_{\vec{1}_{d-1,0}}
  \bigg)
\Bigg]^2.
\end{align}
