In Theorem~\ref{thm2.2}, the case $k=0$ is given by \cite[Theorem 1.3.8]{morand2024galtonwatsonprocessesdynamicalenvironments}. We then proceed by induction on $k\in\mathbb{N}$. We know that the family of functions $\big(x\in\mathbb{\RZ}\mapsto\varphi^{(n)}(x,0)\big)_{n\in\mathbb{N}}$ converges uniformly to $q$ and is $(k+1)$-times differentiable. We then show that the sequence $\big(x\in\RZ\mapsto\partial_x^k\varphi^{(n)}(x,0)\big)_{n\in\mathbb{N}}$ converges uniformly to a function (whose Hölder regularity is controlled) which is therefore the $k$th derivative of $q$. To do this, we express \begin{align*}
 x\in\mathbb{\RZ}\mapsto\partial_x^k\varphi^{(n)}(x,0)
\end{align*} as a series of differentiable functions for which we control the uniform norm and the Hölder semi-norms as functions of the Lyapunov exponents.

\encad{For $k\in\mathbb{N}$, let:
\begin{hyp}[H\ref{hyp4}(k)]\label{hyp4}~
\begin{enumerate}[label=\alph*)]
 \item $T$ is a $\mathcal{C}^{k+1}$ uniformly expanding transformation of $\RZ$.
 \item For all $\nu\in\mathcal{E}_T(\RZ)$, $\mathbb{E}_\nu[\log m(\cdot)]>0$ (uniformly supercritical case).\label{US}
 \item $\varphi$ is $\mathcal{C}^{k+1}$ on $\RZ\times[0,1)$.
 \item $q(x)>0$ for all $x\in\RZ$.
\end{enumerate} 
\end{hyp}}\medskip

\begin{theorem}\cite[Theorem 1.3.8]{morand2024galtonwatsonprocessesdynamicalenvironments}\label{thm2.6}
 Let $\alpha\in(0,1]$. Assume (H\ref{hyp4}), and that $\alpha<\frac{|\lambda_F|}{\lambda_u}$. Then $q$ is $\alpha$-Hölder continuous.
\end{theorem}

\begin{prop}\cite[Corollary~5]{MR718829}
\label{prop2.1}
 Assume (H\ref{hyp4}). For all continuous functions $f:\RZ\to \mathbb{R}$, \begin{align*}
 \sup_{\nu\in\mathcal{P}_T(\rz)}\int_{\rz} f(x) \,\mathrm{d}\nu(x)=\sup_{k\in\mathbb{N}^*}\sup_{x\in \text{Per}_k(\rz)}\frac{1}{k}\sum_{i=0}^{k-1}f(T^ix).
 \end{align*}
In particular, \begin{align*}
 \lambda_F=\sup_{k\in\mathbb{N}^*}\sup_{x\in \text{Per}_k(\rz)}\frac{1}{k}\sum_{i=0}^{k-1}F(T^ix) \quad \text{and} \quad \lambda_u=\sup_{k\in\mathbb{N}^*}\sup_{x\in \text{Per}_k(\rz)}\frac{1}{k}\sum_{i=0}^{k-1}\log|T'(T^ix)|.
\end{align*}
\end{prop}

Let $N\geq 2$, $\omega\in\RZ$, and $\lambda,\varepsilon\in\mathbb{R}$ be such that $|\varepsilon|<\frac{N-1}{2\pi}$. To determine if we are in the uniformly supercritical case, we need to check if \begin{align}\label{cond}
 \uo{\nu\in\mathcal{P}_{T_{N,\varepsilon}}(\rz)}{}{\inf} \mathbb{E}_\nu[\log m_{\lambda,\omega}(\cdot)]>0.
 \end{align}
 For all $x\in\RZ$, \begin{align*}
 \log m_{\lambda,\omega}(x)=\lambda+\cos(2\pi(x+\omega)).
 \end{align*}
 Thus, Inequality~\eqref{cond} can be expressed as:\begin{align}\label{thie}
 \lambda> -\uo{\nu\in\mathcal{P}_{T_{N,\varepsilon}}(\rz)}{}{\inf} \mathbb{E}_\nu[\cos(2\pi(\cdot+\omega))].
 \end{align}
 In particular, \begin{itemize}
 \item if $\lambda>1$, we are in the uniformly supercritical case, and thus, Hypothesis~$H\ref{hyp4}(k)$ is satisfied for all $k\in\mathbb{N}$.
 \item if $N=2$ and $\varepsilon=0$, 
 Inequality~\eqref{thie} was studied in \cite{MR1785392}. The maximum of $\mathbb{E}_\nu[\cos 2\pi (\cdot+\omega)]$ is reached on a Sturm measure and is periodic for all $\omega\in\RZ$ outside a certain set of Hausdorff dimension zero. \cite[Annexe]{MR1785392} gives the corresponding maximising Sturm measure for some values of $\omega\in\RZ$.
 \end{itemize}

Let $k\geq1$. We suppose that the result holds for all $k'\leq k-1$. Let $\alpha\in(0,1]$. Assume $(H\ref{hyp4}(k))$, and that $k+\alpha <\frac{|\lambda_F|}{\lambda_u}$. By Proposition~\ref{prop_dq}, for all $x\in\RZ$, 
 \begin{align*}
 q^{(k)}(x)=\sum_{\ell=0}^{+\infty}f_{\ell}(x),
 \end{align*}
 with\begin{align*}
 f_{\ell}(x)=(T^\ell)'(x)^k\dsphn{ x}{q(T^{\ell+1}x)}{\ell}H_{k}(T^\ell x).
 \end{align*}
Moreover, for all $x\in\RZ$, \begin{align*}
 H_k(x)= P_k[ (T^{(z)}(x))_{ z\leq k}, (\dxsph{x}{q(Tx)}{z_1}{z_2})_{z_1+z_2\leq k}, (q^{(z)}(Tx))_{z<k}]. 
\end{align*}
