\begin{thm}[Main Result]\label{thm:main}
{\em (1)} The $h$-polynomial $h_R(t)$ of any cyclotomic standard graded $\kk$-algebra $R$ is of type CI if $h_R(1) \in \{1,4,6\}$ or $h_R(1)$ is prime. 

\noindent
{\em (2)} There exists a cyclotomic standard graded $\kk$-algebra $R$ whose $h$-polynomial $h_R(t)$ is not of type CI and satisfies $h_R(1)=n$ if $n$ is a non-prime number at least $8$.
\end{thm}

