\label{thm:main}
Let $(M,g)$ be a complete Riemannian manifold with 
$\mbox{Ric}\geq 0$. Then any biharmonic function $u \in C^4(M)$ of subquadratic growth must be harmonic. In particular, any biharmonic function of sublinear growth must be constant.

ref_dict.MarkoffMeasureDefinition:
\begin{corollary}\label{Verblunkyl2Condition}
    Let $\mu\in\Meas$. Then $\mu\in\Sz$ if and only if $(\alpha_n(\mu))_n\in\ell^2$.
\end{corollary}
In the following, we will write $\Phi_n, b_{n,i}$ and $\alpha_n$ instead of $\Phi_n(\mu;z), b_{n,i}(\mu)$ and $\alpha_n(\mu)$ whenever the measure $\mu$ is clear from the context.
\subsection*{Markoff measures}\label{MarkoffMeasureDefinition}
Let $\mu\in\Meas$.  For $\ell\in\N_0$ and $\varepsilon\in(0,1)$ define the class $\mathrm{Mar}_{\varepsilon,\ell}(\T)\subseteq \Meas$ via
\begin{equation}\label{markoffmeasure}
\mu\in\mathrm{Mar}_{\varepsilon,\ell}(\T)\Leftrightarrow \inf_{n\in\N_0}\max_{n\leq j\leq n+\ell} |\alpha_j|\geq \varepsilon.
\end{equation}
The class $\MMeas$ of \textit{Markoff measures}, which was introduced by Khrushchev in \cite{KhrushchevClassifictation}, is defined as follows
\[
\MMeas:=\bigcup_{\ell\in\N_0}\bigcup_{\varepsilon>0} \mathrm{Mar}_{\varepsilon,\ell}(\T).
\]
\begin{remark}
    This definition is in fact a characterization of the original definition \cite{KhrushchevClassifictation}*{Theorem~1.8}. Khrushchev defines $\MMeas$ as every $\mu\in\Meas$ such that $\dd m$ is not contained in the derived set of
    \[
    \{|\varphi_n|^2\dd \mu\mid n\in\N_0 \}
    \]
    where $\varphi_n$ is the $n$-th orthogonal polynomial in $L^2(\T,\mu)$ obtained by using the Gram-Schmidt algorithm on the monomials $z^n$ with $n\in\N_0$.
\end{remark}
Let us collect a few properties and examples of Markoff measures. 
\begin{lemma}[Properties of Markoff measures]\label{LemmaMarkoffMeasure}
Let $\mu\in\Meas$.
\begin{itemize}
\setlength{\itemsep}{1ex}
    \item[a)]  $\MMeas\subseteq \Sz^c$.
    \item[b)] $\mu\in\mathrm{Mar}_{\varepsilon,\ell}(\T)\Rightarrow \|\Phi_n\|^2_{L^2(\T,\mu)}\leq (1-\varepsilon^2)^{\frac{n-1}{\ell+1}-1}$.
    \item[c)] $\mu\in\MMeas\Rightarrow\mathrm{supp}(\mu_{ac})\neq \T$. 
    \item[d)] $\mathrm{supp}(\mu)\neq \T\Rightarrow \mu\in\MMeas$.
\end{itemize}
The converse implications in c) and d) are not true.
\end{lemma}
\begin{proof}
a) Let $\mu\in\MMeas$. Then, $(\alpha_n)_n$ does not converge to zero by definition of $\MMeas$. In particular, $(\alpha_n)_n\notin \ell^2$. Thus, by Corollary \ref{Verblunkyl2Condition}, $\mu\in \Sz^c$.

b)  Let $\mu\in\mathrm{Mar}_{\varepsilon,\ell}(\T)$. From \eqref{VerblunskyIdentity} it follows that
\[
\|\Phi_n\|^2_{L^2(\T,\mu)}=\prod_{i=0}^{n-1} (1-|\alpha_i|^2)\leq (1-\varepsilon^2)^{\lfloor\frac{n-1}{\ell+1}\rfloor}\leq(1-\varepsilon^2)^{\frac{n-1}{\ell+1}-1}.
\]

c) By Rakhmanov's theorem \cite{Rakhmanoc83}*{§3}, \cite{SimonOPUC2}*{Corollary~9.1.11}, for any $\mu\in\Meas$ with $\mathrm{supp}(\mu_{ac})=\T$ one has 
\[
\lim_{n\to\infty}\alpha_n(\mu)=0.
\]
Let $\mu\in\MMeas$. Then $(\alpha_n(\mu))_n$ does not converge to 0. Thus, by Rakhmanov's theorem, $\mathrm{supp}(\mu_{ac})\neq \T$. To see that the converse implication of c) doesn't hold true, consider a measure $\mu\in\Meas$ such that for all $n\in\N_0$
\[
\alpha_n(\mu)=
\begin{cases}
    \frac{1}{\sqrt{k}}, & n=k!, k\in\N_0\\
    0, &\text{else}.
\end{cases}
\]
By Corollary \ref{Verblunkyl2Condition} $\mu\in\Sz^c$. However, $\mu\notin\MMeas$ since ${a_n\to 0}$. Furthermore, $\mu$ is purely singular continuous (see \cite{SimonOPUC2}*{Theorem~12.5.2}). In particular, $\mu_{ac}=0$.

d) For a proof see \cite{KhrushchevClassifictation}*{Corollary~1.9}. We briefly present a counterexample to the converse implication due to Zhedanov \cite{Zhedanov20}. For $q\in\T$ which is not a root of unity and $0<p<1$ set
\[
\mu:=(1-p)\sum_{n=0}^\infty p^n\delta_{q^n}
\]
where $\delta_w$ is the Dirac measure with $\mathrm{supp}(\delta_w)=\{w\}$. Clearly, $\mu\in\Meas$. There is also a simple formula for $|\alpha_n|^2$ in terms of $p$ and $q$ (see \cite{Zhedanov20}*{p.5}). For all $n\in\N_0$
\[
|\alpha_n|^2=\frac{(1-p)^2}{1+p^2-2p\,\mathrm{Re}(q^{n+1})}.
\]
Thus, 
\[
\frac{1-p}{1+p}<|\alpha_n|<1
\]
for all $n\in\N_0$ which implies that $\mu\in\MMeas$. Furthermore, since $q$ is not a root of unity, 
\[
\mathrm{supp}(\mu)=\overline{\{q^n\mid n\in\N_0\}}=\T.\qedhere
\]
\end{proof}
\begin{remark}\label{RemarkMarkoffMeasures}
