\section{Main Theorem}
Recall that for $k,n\in\N_0$
\[
\beta_\mu(k,n)=\min_{\pi\in \PP_{\leq n}}\|z^{-k}-\pi(z)\|_{L^2(\T,\mu)}.
\]
\begin{definition}
    Let $\mu\in\Meas$. A strictly increasing function $f:\N\to\N$ is called $\beta$\textit{-approximating} for $\mu$ if 
    \begin{equation*}
        \lim_{k\to\infty} \beta_\mu(k,f(k))=0.
    \end{equation*}
\end{definition}
\begin{corollary}\label{CorollaryBetaApproximating}
    Let $\mu\in\Meas$. Then there exists a $\beta$-approximating $f$ if and only if $\mu\in\Sz^c$.
\end{corollary}

