    Let $\mu\in \Sz^c$. Then there exists a set $\Lambda\subseteq \N$ with $\underline{\dd}(\Lambda)=0$ such that $E(\Lambda)$ is dense in $L^2(\T,\mu)$.
\end{corollary}

ref_dict.LemmaMarkoffMeasure:
\begin{lemma}[Properties of Markoff measures]\label{LemmaMarkoffMeasure}
Let $\mu\in\Meas$.
\begin{itemize}
\setlength{\itemsep}{1ex}
    \item[a)]  $\MMeas\subseteq \Sz^c$.
    \item[b)] $\mu\in\mathrm{Mar}_{\varepsilon,\ell}(\T)\Rightarrow \|\Phi_n\|^2_{L^2(\T,\mu)}\leq (1-\varepsilon^2)^{\frac{n-1}{\ell+1}-1}$.
    \item[c)] $\mu\in\MMeas\Rightarrow\mathrm{supp}(\mu_{ac})\neq \T$. 
    \item[d)] $\mathrm{supp}(\mu)\neq \T\Rightarrow \mu\in\MMeas$.
\end{itemize}
The converse implications in c) and d) are not true.
\end{lemma}

expanded_sketch:
\begin{theorem}\label{Existence of infinite sets}
    Let $s>1$ and let $\mathbf{k}:=(k_j)_j\in\N^\N$ be strictly increasing. Set $\lfloor\mathbf{k}^s\rfloor:=(\lfloor k_j^s \rfloor)_j\in\N^\N$. Then, 
    \[
    \Big(\Lambda\big(\mathbf{k},\lfloor \mathbf{k}^s\rfloor\big),\,\MMeas\Big)\in\A.
    \]
    In particular, there exists a subset $\Lambda\subseteq \N$ with lower density $\underline{\dd}\big(\Lambda\big)=0$ such that \linebreak$(\Lambda,\MMeas)\in\A$. 
\end{theorem}

The theorem above is obtained as an application of the following main result:
\begin{theorem}\label{Theorem beta}
Let $\mu\in\Sz^c$ and $f$ be any $\beta$-approximating function for $\mu$. Let $\mathbf{k}:=(k_j)_j\in\N^\N$ be strictly increasing and $\bm{\ell}:=(\ell_j)_j\in\N_0^\N$ such that 
    \[
    \lim_{j\to\infty} \ell_j-f(k_j)=\infty.
    \]  
    Then $E(\Lambda(\mathbf{k},\bm{\ell}))$ is dense in $L^2(\T,\mu)$.
\end{theorem}
Moreover, we further show the following:
\begin{corollary}\label{MainCorollary}
    Let $\mu\in \Sz^c$. Then there exists a set $\Lambda\subseteq \N$ with $\underline{\dd}(\Lambda)=0$ such that $E(\Lambda)$ is dense in $L^2(\T,\mu)$.
\end{corollary}
Finally, later we prove the theorem above and show other applications of the main result.

theorem.content:
\label{thm:main}
Let $E_0\in \mathbb R$ be a fixed energy for which $L_d(\omega,E_0)>0$.
For any $\omega\in \mathrm{DC}$, the integrated density of states of $H_{\omega,\theta}$ satisfies
    \begin{align}
        |\mathcal{N}(\omega,E)-\mathcal{N}(\omega,E')|\leq |E-E'|^{\beta},
    \end{align}
    for any $E,E'\in I_{E_0}$, a neighborhood of $E_0$, and any H\"older exponent $0<\beta<1/(2\kappa^d(\omega,E_0))$.

