\begin{lemma}\label{Lemma:(i,j)th entry of Ak is the sum of weights of all closed walk lengh k from i to j}[Theorem 3.1.2, \cite{Brualdi-Cvetkovic-combinatorial-matrix-thy}]
Let $A=[a_{ij}]$ be a matrix of order $n.$ For each positive integer $k,$ the entry $a_{ij}^{(k)}$ of $A^k$ in the $i$th row and $j$th column equals the sum of the weights of all walks in $\mathcal{D}(A)$ of length $k$ from vertex $i$ to vertex $j.$    
 \end{lemma}

