Let $\Omega$ be an exterior domain, $u:\Rn\to (0, \infty)$ be lower semicontinuous that solve
\begin{equation}\label{L3.2B}
(-\Delta_p)^su \geq u^{t} |\na u|^{m}\quad
\text{in}\;\; \Omega.
\end{equation}
Then, for any $\theta \in \left( 0, \frac{N}{p-1} \right)$, there exists a constant $C(\theta, \Omega, u)$ such that 
\begin{equation}\label{eq1.2}
u(x) \geq C |x|^{-\theta}\quad  \text{ in }\;\; \bar \Omega \cap \{|x| \geq 1 \}.
\end{equation}
\end{lemma}

full_context:
This paper is devoted to establishing a Liouville theorem for inequalities involving the fractional $p$-Laplacian with a gradient-dependent nonlinearity. Our principal result is the following.

\begin{abstract}
We prove that any nonnegative viscosity solution of the inequality
$$(-\Delta_p)^s u(x) \geq u^{t} |\na u|^{m}\quad \text{ in }\; \Rn,\; N\geq 2,$$
must be constant. This result holds for parameters $p\in (1, \infty), s\in (0, 1)$, 
$t, m\geq 0$, satisfying
$$t (N-sp) + m(N-(sp-p+1)) < N(p-1),$$
with the additional condition that either $m\leq p-1$ if $p-1<sp$, or $m<sp$ if $p-1\geq sp$.

\noindent

\begin{rem}
 For $N\leq sp$, it is known from \cite[Theorem~1.2]{DPQ25} that any nonnegative viscosity solution to $(-\Delta_p)^s u\geq 0$ in $\Rn$ is constant. 
\end{rem}

\section{Preliminary}\label{S-prim}
In this section, we provide some preliminary estimates which will be used in the proof of Theorem~\ref{gradnon}. The solution to \eqref{E1.1A} is understood in the viscosity sense, which we recall from \cite{KKL19}. 
First, we recall some notation from 
\cite{KKL19}. Since, as noticed in \cite{KKL19}, the operator $(-\Delta_p)^s$ may not be classically defined for all $C^2$ functions, we must restrict our consideration to a suitable subclass of test functions when defining viscosity solutions.
Given an open set $D$, we denote by $C^2_\eta(D)$, a subset of $C^2(D)$, defined as
\begin{equation}\label{Ceta}
C^2_\eta(D)=\left\{\phi\in C^2(D)\; :\; \sup_{x\in D\setminus N_\phi}\left[\frac{\min\{d_\phi(x), 1\}^{\eta-1}}{|\nabla\phi(x)|} +
\frac{|D^2\phi(x)|}{(d_\phi(x))^{\eta-2}}\right]<\infty\right\},
\end{equation}
where
$$ 
d_\phi(x)={\dist}(x, N_\phi)\quad \text{and}\quad N_\phi=\{x\in D\; :\; \nabla\phi(x)=0\}.$$

Let us now recall the following result from \cite[Theorem~1.1]{DPQ25}.
\begin{thm}\label{DPQ1}
Let $N \geq 2$, $s\in (0, 1)$ and $p > 1$. Also, let $sp \neq N$. Then $\phi_{\theta} (x) = |x|^{-\theta}$, where $\theta \in \left( -\frac{sp}{p-1}, \frac{N}{p-1} \right)$, is a viscosity solution to
$$
(-\Delta_p)^{s} \phi_{\theta} (x) = C(\theta)\, |x|^{-\theta(p-1) -sp} \quad \text{in}\;\; \Rn \setminus \{0\},$$
where $C(\theta)$ is a constant satisfying
\[C(\theta)
\begin{cases}
=0 \quad\text{ if } \theta = 0 \text { or } \theta = \frac{N-sp}{p-1},
\\
> 0 \quad \text{ if } \min \left\{-\frac{N-sp}{p-1}, 0 \right\} < -\theta < \max \left\{ -\frac{N-sp}{p-1}, 0\right\},
\\
< 0 \quad \text{ otherwise. }
\end{cases}
\]
\end{thm}
We remark that the result \cite[Theorem~1.1]{DPQ25} is stated for weak solutions, but due to the equivalence between continuous weak solution and viscosity solution \cite[Theorem~1.3]{BM21}, the above result holds. Furthermore, since $\na \phi_\theta\neq 0$ in
$\Rn\setminus \{0\}$ and $\phi_\theta$ is $C^2$ for $x\neq 0$,
we see that $\phi_\theta$ is also a classical solution.

We also need the following result.
\begin{lemma}\label{DPQ3}
Let $N>sp$ and $\theta\in (0, \frac{N}{p-1})$. For 
$\varepsilon_0 \in (0,\frac{1}{2}]$, we define
$$\varphi_{\theta} (x) :=
\begin{cases}
|x|^{-\theta} \text{ if } |x| \geq \varepsilon_0,
\\[2mm]
\varepsilon_0^{-\theta} \text{\quad if } |x| < \varepsilon_0.
\end{cases}
$$
Then, for some $\varepsilon_0=\varepsilon_0(\theta)\in (0, \frac{1}{2}]$, we have the following: 
\begin{itemize}
\item[(i)] For $\theta \in \left(0, \frac{N-sp}{p-1} \right]$,
we have
$\varphi_\theta$ a classical solution to 
$$
(-\Delta_p)^s \varphi_{\theta} (x) \leq C(\theta, \varepsilon_0)\, |x|^{-\theta(p-1) -sp}\quad \text{ in }\;\; \Rn \setminus B_1,$$ and $C(\theta, \varepsilon_0) >0$.

Next key lemma improves the lower bound of $u$.
\begin{lemma}\label{L1.3}
Suppose that $t, m \geq 0$, $N>sp$ and $m$ satisfies \eqref{ineq:m}.
 In addition, let
\begin{equation}\label{L3.2A}
t (N-sp) + m(N-(sp-p+1)) < N(p-1).
\end{equation}
Let $\Omega$ be an exterior domain, $u:\Rn\to (0, \infty)$ be lower semicontinuous that solve
\begin{equation}\label{L3.2B}
(-\Delta_p)^su \geq u^{t} |\na u|^{m}\quad
\text{in}\;\; \Omega.
\end{equation}
Then, for any $\theta \in \left( 0, \frac{N}{p-1} \right)$, there exists a constant $C(\theta, \Omega, u)$ such that 
\begin{equation}\label{eq1.2}
u(x) \geq C |x|^{-\theta}\quad \text{ in }\;\; \bar \Omega \cap \{|x| \geq 1 \}.
\end{equation}
\end{lemma}

Let $0<\sigma<\frac{N}{p-1}$ and suppose that
for some constant $C_{\sigma}$
we have
\begin{align}\label{L3.2D0}
u(x) &\geq C_{\sigma} |x|^{-\sigma}\quad \text{in}\; \bar\Omega\cap\{|x|\geq 1\}.
\end{align}
This clearly holds for $\sigma\in\left( \frac{N-sp}{p-1} , \frac{N}{p-1} \right)$, by Lemma~\ref{L1.2}. Using \eqref{L3.2D0}, we then have from \eqref{L3.2B} that
\begin{equation}\label{L5.1D}
(-\Delta_p)^s u \geq C_\sigma^t |x|^{-t\sigma}|\nabla u|^m \quad \text{in}\;\; \Omega\cap\{|x|\geq 1\}.
\end{equation}
Now, consider $\sigma_1$ such that $0<\sigma_1<\sigma$.
We claim that, for $\tilde\varphi_{\sigma_1}(x):= c \varphi_{\sigma_1}(x)$, where $c$ is a positive constant and $\varphi_{\sigma_1}$ is defined as in Lemma~\ref{DPQ3}, if we have
\begin{align}\label{L3.2D}
(-\Delta_p)^s \tilde\varphi_{\sigma_1} (x) &< C_{\sigma}^t |x|^{-t \sigma} |\na \tilde\varphi_{\sigma_1}|^{m} \text{ for } |x| \geq r_{\sigma_1}
\end{align}
and some $r_{\sigma_1}>1$, then for some constant $C_{\sigma_1}$ we have
\begin{equation}\label{eqclaim2}
u(x) \geq C_{\sigma_1} |x|^{-\sigma_1} \text{ in } \bar \Omega \cap \{|x| \geq 1 \}.
\end{equation}

\begin{equation}\label{E1.1A}
(-\Delta_p)^s u(x) \geq u^{t} |\na u|^{m}\quad  \text{ in }\; \Rn
\end{equation}

\begin{thm}\label{gradnon} 
Suppose that $0<s<1<p<\infty$, $N\geq 2$, $t\geq 0$ and
\begin{align}\label{ineq:m}
 0\leq m\begin{cases}\leq p-1  \quad\mbox{if}\quad \frac{sp}{p-1} >1,\\
<sp \quad\mbox{if}\quad \frac{sp}{p-1} \leq 1.
\end{cases}
\end{align}
Moreover, let $N>sp$ and
\begin{equation}\label{algineq}
t (N-sp) + m(N-(sp-p+1)) < N(p-1).
\end{equation} 
Then, any nonnegative viscosity solution to
\begin{equation}\label{E1.1A}
(-\Delta_p)^s u(x) \geq u^{t} |\na u|^{m}\quad  \text{ in }\; \Rn
\end{equation}
is a constant. 
\end{thm}

