Now, we state the upper and lower estimates of the solutions and the upper one of their gradient, contained in \cite{KL20}, in our case.
\begin{thm} \label{thm:asymptEst}$($Theorem $1.1$, \cite{KL20}$)$
 Let $(u,v) \in \mathcal{D}^{1,p}(\R^n)\times \mathcal{D}^{1,p}(\R^n)$ be a weak solution of \eqref{P}
 with $1<p<n$, $0 \leq \gamma < \Lambda_{n,p}$, $\alpha+\beta=p^*$. Then there exist positive constants $0 < R_0< 1 < R_1$ depending on $n, p, \gamma, \nu, \alpha,\beta$, $u$ and $v$, such that
 \begin{equation}\label{eq:estat0}
 \frac{c_1^u}{|x|^{\mu_1}} \leq u(x) \leq \frac{C_1^u}{|x|^{\mu_1}},\quad \frac{c_1^v}{|x|^{\mu_1}} \leq v(x) \leq \frac{C_1^v}{|x|^{\mu_1}} \qquad x \in B_{R_0}\setminus\{0\},
 \end{equation}
 and
 \begin{equation}\label{eq:estatInf}
 \frac{c_2^u}{|x|^{\mu_2}} \leq u(x) \leq \frac{C_2^u}{|x|^{\mu_2}},\quad \frac{c_2^v}{|x|^{\mu_2}} \leq v(x) \leq \frac{C_2^v}{|x|^{\mu_2}} \qquad x \in (B_{R_1})^c,
 \end{equation}

\begin{thm}\label{stimagradiente1}$($Theorem $1.3$, \cite{KL20}$)$
 Let $(u,v) \in \mathcal{D}^{1,p}(\R^n)\times \mathcal{D}^{1,p}(\R^n)$ be a weak solution of \eqref{P}
 with $1<p<n$, $0 \leq \gamma < \Lambda_{n,p}$ and $\alpha+\beta=p^*$. Then there exist positive constants $\tilde C^u$, $\tilde C^v$ depending on $n,p, \gamma, \nu, \alpha,\beta$ and $u$ or $v$, respectively, such that
 \begin{equation}\label{eq:estat0grada}
 |\nabla u(x)| \leq \frac{\tilde C^u}{|x|^{\mu_1+1}}, \quad |\nabla v(x)| \leq \frac{\tilde C^v}{|x|^{\mu_1+1}} \qquad x \in B_{R_0},
 \end{equation}
 and
 \begin{equation}\label{eq:estatInfgrada}
 |\nabla u(x)| \leq \frac{\tilde C^u}{|x|^{\mu_2+1}}, \quad |\nabla v(x)| \leq \frac{\tilde C^v}{|x|^{\mu_2+1}} \qquad x \in (B_{R_1})^c,
 \end{equation}
where $\mu_1, \mu_2$ are roots of \eqref{eq:algebraicHardy} as in Theorem \ref{thm:asymptEst}, and $0 < R_0< 1 < R_1$ are constants depending on $n, p, \gamma,\nu, \alpha,\beta$, $u$ and $v$.
\end{thm}

\begin{thm}\label{stimagradiente2}
 Let $(u,v) \in \mathcal{D}^{1,p}(\R^n)\times \mathcal{D}^{1,p}(\R^n)$ be a weak solution of \eqref{P}
