u,v \in \mathcal D^{1,p}(\R^n),
\end{cases}
\end{equation}
Then $(u,v)$ is radially symmetric and radially decreasing around the origin.,

ref_dict.conj:strongly_q_logconcave:
\begin{conjecture}\label{conj:strongly_q_logconcave}
Let $S$ be an $\hfam$-admissible set and $m =\bm(S)$. The polynomial sequence $(b_k(S;q))_{k=\hfam(m)-m}^{\hfam(m)}$ is strongly $q$-log concave.
\end{conjecture}

ref_dict.thm.a-expansion:
\begin{thm}\label{thm.a-expansion} Let $\hfam$ be a weakly increasing sequence of positive integers such that $\hfam(i)\geq i$ for all $i$. Let $S$ is a nonempty $\hfam$-admissible set and $m=\bm(S)$. Then 
\begin{eqnarray}\label{eqn.a-expansion}
\hinv(S;n) = \sum_{k=0}^m a_k(S) {n-\hfam(m)+1\choose k}
\end{eqnarray}
where 
\[
a_k(S):= \#\{ \pi \in \Hinv(S,m+\hfam(m) -1) \mid \pi[m] = [\hfam(m), \hfam(m)+k-1]\}
\]
with $\pi[m]:= \{ \pi_1, \pi_2, \ldots, \pi_m\} \cap [\hfam(m), n]$.
\end{thm}

ref_dict.intthm:expansion:
\begin{thm}\label{intthm:expansion}
Let $\hfam = (\hfam(1), \hfam(2), \ldots)$ be a weakly increasing sequence of positive integers such that $\hfam(i)>i$ and $S$ be an $\hfam$-admissible subset. Let $m = \bm(S) := \max\{i \mid (i,i+1)\in S\}$ be the maximum descent in $S$. Then there exists sequences of non-negative integers $(a_k(S))_{k=0}^m$ and $(b_k(S))_{k=\hfam(m)-m}^{\hfam(m)}$ such that 
\begin{align*}
        \hinv(S;n) &=  \sum_{k=0}^m a_k(S) {n-\hfam(m)+1\choose k}\\
        &= \sum_{\ell =0}^{m} b_{\hfam(m)-\ell}(S) {n-\hfam(m)+\ell \choose \ell},
    \end{align*}
where the values $a_k(S)$ and $b_k(S)$ are each obtained by enumerating certain permutations with $\hfam$-inversions equal to $S$.
\end{thm}

ref_dict.intthm:poly:
\begin{thm}\label{intthm:poly}
Let $\hfam = (\hfam(1), \hfam(2), \ldots)$ be a weakly increasing sequence of positive integers such that $\hfam(i)>i$ and $S\subset \{(i,j) \mid i<j\leq \hfam(i)\}$. Let $\bj(S) := \max\{j \mid (i,j) \in S\}$. Then $\hinv(S;n)$ is given by a polynomial for all $n \geq \bj(S)$.
\end{thm}

ref_dict.cor.k-expansion:
\begin{cor} \label{cor.k-expansion}  Let $S$ be an $\hfam$-admissible set and $m= \bm(S)$. Then
\begin{align*}
\hinv(S;n) &= \sum_{k=\hfam(m)-m}^{\hfam(m)} b_k(S) {n-k \choose \hfam(m)-k} \\
&= \sum_{\ell =0}^m b_{\hfam(m)-\ell}(S) {n-\hfam(m)+\ell \choose \ell}.
\end{align*}
where $b_k(S):=  \# B_k(S;\hfam(m))$.
\end{cor}

ref_dict.prop.polynomial:
\begin{prop}\label{prop.polynomial} Let $S$ be an $\hfam$-admissible set. For each $n\geq \bj(S)$, we have
\begin{eqnarray}\label{eqn.polyproofexpansion}
\hinv(S;n) = \sum_{\sigma\in \Hinv(S,\,\bj(S))} {n-\bt(\sigma)\choose \bj(S)-\bt(\sigma)}
\end{eqnarray}
where for each $\sigma\in \Hinv(S,\,\bj(S))$ we define  $\bt(\sigma) := \max\{\sigma_k \mid 
(k, \bj(S)+1)\in \cp_\hfam\}$.
\end{prop}

